        conn.execute(
            """
            CREATE OR REPLACE FUNCTION
                serverware_guard_policy_checkpoint_head()
            RETURNS trigger
            LANGUAGE plpgsql
            AS $$
            BEGIN
                IF TG_OP = 'INSERT' THEN
                    IF NEW.checkpoint_sequence <> 1
                        OR NEW.sealed <> 0
                        OR NEW.sealed_at_epoch_ns IS NOT NULL
                    THEN
                        RAISE EXCEPTION
                            'checkpoint genesis head is not exact';
                    END IF;
                ELSIF NEW.canary_id <> OLD.canary_id
                    OR NEW.instance_id <> OLD.instance_id
                    OR NEW.boot_id <> OLD.boot_id
                    OR NEW.updated_at_epoch_ns < OLD.updated_at_epoch_ns
                THEN
                    RAISE EXCEPTION
                        'checkpoint head identity or time changed';
                ELSIF NEW.sealed = 1 THEN
                    IF OLD.sealed <> 0
                        OR NEW.checkpoint_sequence <>
                            OLD.checkpoint_sequence
                        OR NEW.checkpoint_envelope_digest <>
                            OLD.checkpoint_envelope_digest
                        OR NEW.checkpoint_payload_digest <>
                            OLD.checkpoint_payload_digest
                        OR NEW.observation_root_digest <>
                            OLD.observation_root_digest
                        OR NEW.request_sequence_end <>
                            OLD.request_sequence_end
                        OR NEW.observation_sequence_end <>
                            OLD.observation_sequence_end
                        OR NEW.sealed_at_epoch_ns IS NULL
                    THEN
                        RAISE EXCEPTION
                            'checkpoint head seal is not exact';
                    END IF;
                ELSIF OLD.sealed <> 0
                    OR NEW.sealed <> 0
                    OR NEW.sealed_at_epoch_ns IS NOT NULL
                    OR NEW.checkpoint_sequence <>
                        OLD.checkpoint_sequence + 1
                    OR NOT EXISTS (
                        SELECT 1
                        FROM policy_canary_checkpoints AS checkpoint
                        WHERE checkpoint.canary_id = NEW.canary_id
                          AND checkpoint.instance_id = NEW.instance_id
                          AND checkpoint.boot_id = NEW.boot_id
                          AND checkpoint.checkpoint_sequence =
                                NEW.checkpoint_sequence
                          AND checkpoint.checkpoint_envelope_digest =
                                NEW.checkpoint_envelope_digest
                          AND checkpoint.checkpoint_payload_digest =
                                NEW.checkpoint_payload_digest
                          AND checkpoint.observation_root_digest =
                                NEW.observation_root_digest
                          AND checkpoint.request_sequence_end =
                                NEW.request_sequence_end
                          AND checkpoint.observation_sequence_end =
                                NEW.observation_sequence_end
                          AND checkpoint.predecessor_checkpoint_sequence =
                                OLD.checkpoint_sequence
                          AND checkpoint.previous_checkpoint_digest =
                                OLD.checkpoint_envelope_digest
                          AND checkpoint.previous_observation_digest =
                                OLD.observation_root_digest
                          AND checkpoint.previous_request_sequence_end =
                                OLD.request_sequence_end
                          AND checkpoint.previous_observation_sequence_end =
                                OLD.observation_sequence_end
                    )
                THEN
                    RAISE EXCEPTION
                        'checkpoint head is not an exact successor';
                END IF;
                RETURN NEW;
            END;
            $$
            """
        )
