def stage_policy_candidate_artifact(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
) -> dict[str, Any]:
    item = _candidate_authority_record(
        "candidate artifact", record, _POLICY_CANDIDATE_ARTIFACT_FIELDS
    )
    if item["scope"] != "active":
        raise PolicyCandidateAuthorityError("candidate scope must be active")
    for field in (
        "artifact_envelope_digest",
        "artifact_payload_digest",
        "policy_hash",
        "predecessor_policy_hash",
        "compiler_digest",
        "compiler_config_digest",
        "policy_schema_digest",
        "semantic_model_digest",
        "evaluator_abi_digest",
        "policy_bundle_digest",
        "runtime_digest",
    ):
        item[field] = _candidate_authority_digest(field, item[field])
    _candidate_authority_json(
        "artifact_envelope_json",
        item["artifact_envelope_json"],
        item["artifact_envelope_digest"],
    )
    _candidate_authority_json(
        "artifact_payload_json",
        item["artifact_payload_json"],
        item["artifact_payload_digest"],
        maximum=8 * 1024 * 1024,
    )
    _candidate_authority_signature_fields(item)
    for field in (
        "policy_sequence",
        "rollback_epoch",
        "predecessor_policy_sequence",
        "predecessor_rollback_epoch",
    ):
        item[field] = _candidate_authority_int(field, item[field], minimum=1)
    if (
        item["policy_sequence"] <= item["predecessor_policy_sequence"]
        or item["rollback_epoch"] < item["predecessor_rollback_epoch"]
        or item["policy_hash"] == item["predecessor_policy_hash"]
    ):
        raise PolicyCandidateAuthorityError(
            "candidate artifact monotonic or timestamp binding is invalid"
        )
    _candidate_authority_text("candidate_id", item["candidate_id"], maximum=256)
    _candidate_authority_text("policy_id", item["policy_id"], maximum=256)
    _candidate_authority_text("staged_by", item["staged_by"], maximum=1024)

    connection_scope = (
        connect() if _connection is None else contextlib.nullcontext(_connection)
    )
    with connection_scope as conn:
        _lock_policy_candidate_authority(conn)
        _lock_policy_high_water(conn)
        existing_rows = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_CANDIDATE_ARTIFACT_READ_COLUMNS
            )
            + " FROM policy_candidate_artifacts "
            "WHERE artifact_envelope_digest = ? OR candidate_id = ? LIMIT 2",
            (item["artifact_envelope_digest"], item["candidate_id"]),
        ).fetchall()
        if existing_rows:
            if (
                len(existing_rows) != 1
                or any(
                    existing_rows[0][field] != item[field]
                    for field in _POLICY_CANDIDATE_ARTIFACT_FIELDS
                )
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "candidate artifact replay changed immutable evidence"
                )
            return {
                **dict(existing_rows[0]),
                "idempotent_replay": True,
            }
        verified = _verify_policy_authority_evidence(
            conn,
            evidence_kind="candidate_artifact",
            envelope_json=item["artifact_envelope_json"],
            envelope_digest=item["artifact_envelope_digest"],
            payload_json=item["artifact_payload_json"],
            payload_digest=item["artifact_payload_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                item, current_prefix="artifact"
            ),
        )
        _apply_policy_authority_verification(
            item, verified, include_verified_at=True
        )
        item["staged_at_epoch_ns"] = verified.values["verified_at_epoch_ns"]
        current = _committed_policy_authority_row(conn)
        if not _policy_row_matches(
            current,
            policy_id=item["policy_id"],
            sequence=item["predecessor_policy_sequence"],
            rollback_epoch=item["predecessor_rollback_epoch"],
            policy_hash=item["predecessor_policy_hash"],
        ):
            raise PolicyCandidateAuthorityConflictError(
                "candidate predecessor is not the exact active high-water state"
            )
        transition_digest = _stage_policy_authority_transition(
            conn,
            event_type="policy.candidate_artifact.staged",
            entity_kind="candidate_artifact",
            entity_id=item["candidate_id"],
            entity_revision=1,
            state_digest=item["artifact_payload_digest"],
            previous_state_digest=None,
            actor_id=item["staged_by"],
            evidence={
                "artifactEnvelopeDigest": item["artifact_envelope_digest"],
                "artifactPayloadDigest": item["artifact_payload_digest"],
                "policyHash": item["policy_hash"],
                "predecessorPolicyHash": item["predecessor_policy_hash"],
            },
            created_at_epoch_ns=item["staged_at_epoch_ns"],
        )
        stored = {
            **item,
            "created_transition_digest": transition_digest,
        }
        _insert_immutable_candidate_row(
            conn,
            table="policy_candidate_artifacts",
            columns=tuple(stored),
            values=stored,
            key_columns=("artifact_envelope_digest",),
        )
    return {**dict(stored), "idempotent_replay": False}


