def _policy_shadow_runtime_attestation_handoff_components(
    value: Any,
) -> Mapping[str, Any]:
    handoff_json = _candidate_authority_canonical_json(
        "policy-shadow runtime-attestation handoff",
        value,
        maximum=2 * 1024 * 1024,
    )
    handoff = _candidate_authority_strict_object(
        "policy-shadow runtime-attestation handoff",
        loads(handoff_json, None),
        _POLICY_SHADOW_GENERATION_REQUEST_ATTESTATION_FIELDS,
    )
    if (
        handoff["apiVersion"]
        != "serverware.policyShadowRuntimeAttestationHandoff/v2"
    ):
        raise PolicyCandidateAuthorityError(
            "runtime-attestation handoff API version is invalid"
        )
    receipt = _policy_shadow_direct_envelope_components(
        "startup runtime attestation", handoff["receipt"]
    )
    role_authorization = _policy_shadow_direct_envelope_components(
        "shadow role authorization", handoff["roleAuthorization"]
    )
    evidence = _candidate_authority_strict_object(
        "runtime-attestation evidence",
        handoff["evidence"],
        _POLICY_SHADOW_RUNTIME_ATTESTATION_EVIDENCE_FIELDS,
    )
    receipt_payload = _candidate_authority_strict_object(
        "startup runtime-attestation payload",
        receipt["payload"],
        frozenset({"issuedAtEpochNs", "expiresAtEpochNs", "record"}),
    )
    role_payload = _candidate_authority_strict_object(
        "shadow role-authorization payload",
        role_authorization["payload"],
        frozenset({"issuedAtEpochNs", "expiresAtEpochNs", "record"}),
    )
    role_record = _candidate_authority_strict_object(
        "shadow role-authorization record",
        role_payload["record"],
        _POLICY_SHADOW_ROLE_AUTHORIZATION_RECORD_FIELDS,
    )
    for field in (
        "receiptId",
        "receiptSha256",
        "receiptPayloadSha256",
        "roleAuthorizationId",
        "roleAuthorizationSha256",
        "roleAuthorizationPayloadSha256",
        "chainSha256",
    ):
        _candidate_authority_digest(
            "runtime-attestation handoff " + field,
            handoff[field],
        )
    for field in (
        "evidenceId",
        "evidenceSha256",
    ):
        _candidate_authority_digest(
            "runtime-attestation evidence " + field,
            evidence[field],
        )
    for field in _POLICY_SHADOW_ROLE_AUTHORIZATION_RECORD_FIELDS:
        if (
            field.endswith("Sha256")
            or field.endswith("Id") and field != "instanceId"
        ):
            _candidate_authority_digest(
                "shadow role authorization " + field,
                role_record[field],
            )
    for label, number in (
        ("receipt revision", handoff["receiptRevision"]),
        (
            "role authorization revision",
            handoff["roleAuthorizationRevision"],
        ),
        ("evidence revision", evidence["evidenceRevision"]),
        (
            "role payload authorization revision",
            role_record["authorizationRevision"],
        ),
        (
            "role payload assignment revision",
            role_record["assignmentRevision"],
        ),
        (
            "role payload receipt revision",
            role_record["runtimeAttestationReceiptRevision"],
        ),
        (
            "role payload evidence revision",
            role_record["attestationEvidenceRevision"],
        ),
        (
            "role payload membership revision",
            role_record["fleetMembershipRevision"],
        ),
        ("role payload member ordinal", role_record["memberOrdinal"]),
        (
            "role payload revocation generation",
            role_record["revocationGeneration"],
        ),
    ):
        _candidate_authority_int(label, number, minimum=1)
    receipt_issued = _candidate_authority_int(
        "startup attestation issuance",
        receipt_payload["issuedAtEpochNs"],
        minimum=1,
    )
    receipt_expires = _candidate_authority_int(
        "startup attestation expiry",
        receipt_payload["expiresAtEpochNs"],
        minimum=1,
    )
    role_issued = _candidate_authority_int(
        "shadow role authorization issuance",
        role_payload["issuedAtEpochNs"],
        minimum=1,
    )
    role_expires = _candidate_authority_int(
        "shadow role authorization expiry",
        role_payload["expiresAtEpochNs"],
        minimum=1,
    )
    evidence_json = dumps(evidence["evidence"])
    if (
        receipt["envelope_digest"] != handoff["receiptSha256"]
        or receipt["payload_digest"]
        != handoff["receiptPayloadSha256"]
        or role_authorization["envelope_digest"]
        != handoff["roleAuthorizationSha256"]
        or role_authorization["payload_digest"]
        != handoff["roleAuthorizationPayloadSha256"]
        or role_record["authorizationId"]
        != handoff["roleAuthorizationId"]
        or role_record["authorizationRevision"]
        != handoff["roleAuthorizationRevision"]
        or role_record["runtimeAttestationReceiptId"]
        != handoff["receiptId"]
        or role_record["runtimeAttestationReceiptRevision"]
        != handoff["receiptRevision"]
        or role_record["runtimeAttestationReceiptSha256"]
        != handoff["receiptSha256"]
        or role_record["runtimeAttestationPayloadSha256"]
        != handoff["receiptPayloadSha256"]
        or role_record["attestationEvidenceId"]
        != evidence["evidenceId"]
        or role_record["attestationEvidenceRevision"]
        != evidence["evidenceRevision"]
        or role_record["attestationEvidenceSha256"]
        != evidence["evidenceSha256"]
        or evidence["apiVersion"]
        != "serverware.policyShadowRuntimeAttestationEvidence/v1"
        or evidence["evidenceType"]
        not in {"aws-nitro-enclave", "amd-sev-snp", "intel-tdx"}
        or _candidate_authority_sha256(
            evidence_json.encode("ascii")
        )
        != evidence["evidenceSha256"]
        or receipt_expires <= receipt_issued
        or role_expires <= role_issued
        or role_record["role"] != "shadow"
    ):
        raise PolicyCandidateAuthorityConflictError(
            "runtime-attestation handoff signed artifacts are not exact"
        )
    return MappingProxyType(
        {
            "handoff": handoff,
            "handoff_json": handoff_json,
            "handoff_digest": _candidate_authority_sha256(
                handoff_json.encode("ascii")
            ),
            "receipt": receipt,
            "receipt_payload": receipt_payload,
            "role_authorization": role_authorization,
            "role_payload": role_payload,
            "role_record": role_record,
            "evidence": evidence,
            "evidence_json": dumps(evidence),
            "receipt_issued_at_epoch_ns": receipt_issued,
            "receipt_expires_at_epoch_ns": receipt_expires,
            "role_issued_at_epoch_ns": role_issued,
            "role_expires_at_epoch_ns": role_expires,
        }
    )


def _verify_policy_shadow_runtime_attestation_handoff(
    conn: Any,
    *,
    handoff_json: str,
    canary_id: str,
    instance_id: str,
    boot_id: str,
    candidate_id: str,
    stored: Mapping[str, Any] | None = None,
    require_current: bool,
) -> Mapping[str, Any]:
    parsed = _policy_shadow_runtime_attestation_handoff_components(
        handoff_json
    )
    handoff = parsed["handoff"]
    role = parsed["role_record"]
    evidence = parsed["evidence"]
    context = _policy_canary_runtime_context(
        conn,
        canary_id=canary_id,
        instance_id=instance_id,
        boot_id=boot_id,
    )
    attestation = conn.execute(
        "SELECT "
        + _policy_authority_projection(
            _POLICY_RUNTIME_ATTESTATION_READ_COLUMNS
        )
        + " FROM policy_runtime_attestations "
        "WHERE attestation_receipt_envelope_digest = ?",
        (context["attestation_receipt_envelope_digest"],),
    ).fetchone()
    shadow_key = conn.execute(
        "SELECT signing_key_id, public_key_base64url, public_key_digest, "
        "authorization_digest, attestation_receipt_envelope_digest "
        "FROM policy_runtime_role_keys "
        "WHERE assignment_envelope_digest = ? AND member_ordinal = ? "
        "AND role = 'shadow'",
        (
            context["assignment_envelope_digest"],
            context["member_ordinal"],
        ),
    ).fetchone()
    artifact = conn.execute(
        "SELECT candidate_id FROM policy_candidate_artifacts "
        "WHERE artifact_envelope_digest = ?",
        (context["artifact_envelope_digest"],),
    ).fetchone()
    if attestation is None or shadow_key is None or artifact is None:
        raise PolicyCandidateAuthorityConflictError(
            "runtime-attestation handoff predecessors are incomplete"
        )
    _reverify_policy_static_evidence(
        conn,
        evidence_kind="runtime_attestation",
        item=dict(attestation),
        current_prefix="attestation_receipt",
        historical=True,
    )
    if (
        parsed["receipt"]["envelope_json"]
        != attestation["attestation_receipt_envelope_json"]
        or parsed["receipt"]["payload_json"]
        != attestation["attestation_receipt_payload_json"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "runtime-attestation handoff receipt is not the persisted receipt"
        )
    load_payload = loads(context["load_receipt_payload_json"], None)
    if (
        not isinstance(load_payload, dict)
        or not isinstance(load_payload.get("runtimeIdentity"), dict)
    ):
        raise PolicyCandidateAuthorityConflictError(
            "load receipt has no exact runtime identity"
        )
    runtime_identity_digest = _candidate_authority_sha256(
        dumps(load_payload["runtimeIdentity"]).encode("ascii")
    )
    expected_chain_digest = _policy_shadow_generation_rust_domain_digest(
        b"serverware.policyShadowRuntimeAttestationEvidenceChain/v1",
        [
            "serverware.policyShadowRuntimeAttestationHandoff/v2",
            handoff["receiptId"],
            handoff["receiptRevision"],
            handoff["receiptSha256"],
            handoff["receiptPayloadSha256"],
            handoff["roleAuthorizationId"],
            handoff["roleAuthorizationRevision"],
            handoff["roleAuthorizationSha256"],
            handoff["roleAuthorizationPayloadSha256"],
            evidence,
            context["assignment_payload_digest"],
            context["load_receipt_payload_digest"],
            runtime_identity_digest,
            role["attestationPolicySha256"],
        ],
    )
    if stored is None:
        role_verified = _verify_policy_authority_evidence(
            conn,
            evidence_kind="shadow_role_authorization",
            envelope_json=parsed["role_authorization"]["envelope_json"],
            envelope_digest=
                parsed["role_authorization"]["envelope_digest"],
            payload_json=parsed["role_authorization"]["payload_json"],
            payload_digest=
                parsed["role_authorization"]["payload_digest"],
            signature_algorithm=
                parsed["role_authorization"]["signature_algorithm"],
            signing_key_id=
                parsed["role_authorization"]["signing_key_id"],
            signature=parsed["role_authorization"]["signature"],
            signature_digest=
                parsed["role_authorization"]["signature_digest"],
            record_binding=role,
        )
    else:
        role_verified = _reverify_historical_policy_static_evidence(
            conn,
            evidence_kind="shadow_role_authorization",
            envelope_json=parsed["role_authorization"]["envelope_json"],
            envelope_digest=
                parsed["role_authorization"]["envelope_digest"],
            payload_json=parsed["role_authorization"]["payload_json"],
            payload_digest=
                parsed["role_authorization"]["payload_digest"],
            signature_algorithm=
                parsed["role_authorization"]["signature_algorithm"],
            signing_key_id=
                parsed["role_authorization"]["signing_key_id"],
            signature=parsed["role_authorization"]["signature"],
            signature_digest=
                parsed["role_authorization"]["signature_digest"],
            record_binding=role,
            verification_receipt_digest=str(
                stored[
                    "role_authorization_verification_receipt_digest"
                ]
            ),
        )
    now_epoch_ns = int(
        _metadata_utcnow(conn).timestamp() * 1_000_000_000
    )
    if (
        artifact["candidate_id"] != candidate_id
        or role["candidateId"] != candidate_id
        or role["canaryId"] != canary_id
        or role["assignmentSha256"]
        != context["assignment_envelope_digest"]
        or role["assignmentPayloadSha256"]
        != context["assignment_payload_digest"]
        or role["assignmentRevision"]
        != context["assignment_revision"]
        or role["loadReceiptSha256"]
        != context["load_receipt_envelope_digest"]
        or role["loadReceiptPayloadSha256"]
        != context["load_receipt_payload_digest"]
        or role["fleetId"] != context["fleet_id"]
        or role["fleetMembershipRevision"]
        != context["membership_revision"]
        or role["membershipRootSha256"]
        != context["membership_root_digest"]
        or role["memberOrdinal"] != context["member_ordinal"]
        or role["memberId"] != context["member_id"]
        or role["instanceId"] != instance_id
        or role["bootIdSha256"] != boot_id
        or role["runtimeIdentitySha256"] != runtime_identity_digest
        or role["runtimeExecutableSha256"]
        != context["runtime_digest"]
        or role["shadowSigningKeyId"]
        != shadow_key["signing_key_id"]
        or role["shadowSigningKeySpkiSha256"]
        != shadow_key["public_key_digest"]
        or role["teeMeasurementSha256"]
        != attestation["tee_measurement_digest"]
        or evidence["evidenceSha256"]
        != attestation["tee_evidence_digest"]
        or evidence["evidenceType"] != attestation["tee_platform"]
        or handoff["chainSha256"] != expected_chain_digest
        or shadow_key["attestation_receipt_envelope_digest"]
        != handoff["receiptSha256"]
        or (
            require_current
            and (
                now_epoch_ns < parsed["receipt_issued_at_epoch_ns"]
                or now_epoch_ns >= parsed["receipt_expires_at_epoch_ns"]
                or now_epoch_ns < parsed["role_issued_at_epoch_ns"]
                or now_epoch_ns >= parsed["role_expires_at_epoch_ns"]
            )
        )
    ):
        raise PolicyCandidateAuthorityConflictError(
            "runtime-attestation handoff does not bind the exact assigned runtime"
        )
    if stored is not None:
        exact_stored = {
            "runtime_attestation_handoff_digest":
                parsed["handoff_digest"],
            "runtime_attestation_handoff_json":
                parsed["handoff_json"],
            "canary_id": canary_id,
            "instance_id": instance_id,
            "boot_id": boot_id,
            "candidate_id": candidate_id,
            "assignment_envelope_digest":
                context["assignment_envelope_digest"],
            "assignment_payload_digest":
                context["assignment_payload_digest"],
            "assignment_revision": context["assignment_revision"],
            "load_receipt_envelope_digest":
                context["load_receipt_envelope_digest"],
            "load_receipt_payload_digest":
                context["load_receipt_payload_digest"],
            "receipt_id": handoff["receiptId"],
            "receipt_revision": handoff["receiptRevision"],
            "receipt_envelope_digest": handoff["receiptSha256"],
            "receipt_payload_digest":
                handoff["receiptPayloadSha256"],
            "role_authorization_id":
                handoff["roleAuthorizationId"],
            "role_authorization_revision":
                handoff["roleAuthorizationRevision"],
            "role_authorization_envelope_digest":
                handoff["roleAuthorizationSha256"],
            "role_authorization_payload_digest":
                handoff["roleAuthorizationPayloadSha256"],
            "role_authorization_envelope_json":
                parsed["role_authorization"]["envelope_json"],
            "role_authorization_payload_json":
                parsed["role_authorization"]["payload_json"],
            "role_authorization_signature_algorithm":
                parsed["role_authorization"]["signature_algorithm"],
            "role_authorization_signing_key_id":
                parsed["role_authorization"]["signing_key_id"],
            "role_authorization_signature":
                parsed["role_authorization"]["signature"],
            "role_authorization_signature_digest":
                parsed["role_authorization"]["signature_digest"],
            "role_authorization_evidence_kind":
                "shadow_role_authorization",
            "role_authorization_record_binding_digest":
                role_verified.values["record_binding_digest"],
            "role_authorization_verification_receipt_digest":
                role_verified.values["verification_receipt_digest"],
            "attestation_evidence_id": evidence["evidenceId"],
            "attestation_evidence_revision":
                evidence["evidenceRevision"],
            "attestation_evidence_type": evidence["evidenceType"],
            "attestation_evidence_digest":
                evidence["evidenceSha256"],
            "attestation_evidence_json": parsed["evidence_json"],
            "attestation_chain_digest": handoff["chainSha256"],
            "runtime_identity_digest": runtime_identity_digest,
            "runtime_executable_digest":
                role["runtimeExecutableSha256"],
            "runtime_release_digest": role["runtimeReleaseSha256"],
            "runtime_config_digest": role["runtimeConfigSha256"],
            "runtime_policy_digest": role["runtimePolicySha256"],
            "attestation_policy_digest":
                role["attestationPolicySha256"],
            "attestation_trust_checkpoint_digest":
                role["attestationTrustCheckpointSha256"],
            "attestation_revocation_generation":
                role["revocationGeneration"],
            "attestation_revocation_root_digest":
                role["revocationRootSha256"],
            "shadow_signing_key_id": role["shadowSigningKeyId"],
            "shadow_signing_key_spki_digest":
                role["shadowSigningKeySpkiSha256"],
            "shadow_role_key_authorization_digest":
                shadow_key["authorization_digest"],
            "tee_measurement_digest":
                attestation["tee_measurement_digest"],
            "issued_at_epoch_ns":
                parsed["role_issued_at_epoch_ns"],
            "expires_at_epoch_ns": min(
                parsed["role_expires_at_epoch_ns"],
                parsed["receipt_expires_at_epoch_ns"],
            ),
        }
        if any(stored[field] != value for field, value in exact_stored.items()):
            raise PolicyCandidateAuthorityConflictError(
                "persisted runtime-attestation handoff projection changed"
            )
    return MappingProxyType(
        {
            **dict(parsed),
            "context": context,
            "attestation": dict(attestation),
            "shadow_key": dict(shadow_key),
            "runtime_identity_digest": runtime_identity_digest,
            "role_verification": role_verified,
        }
    )


def stage_policy_shadow_runtime_attestation_handoff(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
) -> Mapping[str, Any]:
    item = _candidate_authority_record(
        "policy-shadow runtime-attestation handoff",
        record,
        (
            "canary_id",
            "instance_id",
            "boot_id",
            "candidate_id",
            "runtime_attestation_json",
            "actor_id",
        ),
    )
    actor_id = _candidate_authority_text(
        "runtime-attestation handoff actor",
        item["actor_id"],
        maximum=1024,
    )
    for field in ("canary_id", "instance_id", "candidate_id"):
        item[field] = _candidate_authority_text(
            field, item[field], maximum=256
        )
    item["boot_id"] = _candidate_authority_digest(
        "runtime-attestation handoff boot ID", item["boot_id"]
    )
    connection_scope = (
        connect() if _connection is None else contextlib.nullcontext(_connection)
    )
    with connection_scope as conn:
        _lock_policy_candidate_authority(conn)
        verified = _verify_policy_shadow_runtime_attestation_handoff(
            conn,
            handoff_json=item["runtime_attestation_json"],
            canary_id=item["canary_id"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
            candidate_id=item["candidate_id"],
            stored=None,
            require_current=True,
        )
        parsed = verified
        handoff = parsed["handoff"]
        role = parsed["role_record"]
        role_envelope = parsed["role_authorization"]
        role_verification = parsed["role_verification"].values
        context = parsed["context"]
        attestation = parsed["attestation"]
        shadow_key = parsed["shadow_key"]
        existing = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_SHADOW_RUNTIME_ATTESTATION_HANDOFF_COLUMNS
            )
            + " FROM policy_shadow_runtime_attestation_handoffs "
            "WHERE canary_id = ? OR runtime_attestation_handoff_digest = ? "
            "OR role_authorization_envelope_digest = ? LIMIT 2",
            (
                item["canary_id"],
                parsed["handoff_digest"],
                handoff["roleAuthorizationSha256"],
            ),
        ).fetchall()
        if existing:
            if (
                len(existing) != 1
                or existing[0]["runtime_attestation_handoff_digest"]
                != parsed["handoff_digest"]
                or existing[0]["runtime_attestation_handoff_json"]
                != parsed["handoff_json"]
                or existing[0]["canary_id"] != item["canary_id"]
                or existing[0]["instance_id"] != item["instance_id"]
                or existing[0]["boot_id"] != item["boot_id"]
                or existing[0]["candidate_id"] != item["candidate_id"]
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "runtime-attestation handoff identity was reused"
                )
            _verify_policy_shadow_runtime_attestation_handoff(
                conn,
                handoff_json=existing[0][
                    "runtime_attestation_handoff_json"
                ],
                canary_id=item["canary_id"],
                instance_id=item["instance_id"],
                boot_id=item["boot_id"],
                candidate_id=item["candidate_id"],
                stored=dict(existing[0]),
                require_current=True,
            )
            return _policy_authority_freeze(dict(existing[0]))
        transition_digest = _stage_policy_authority_transition(
            conn,
            event_type="policy.shadow_runtime_attestation_handoff.staged",
            entity_kind="shadow_runtime_attestation_handoff",
            entity_id=parsed["handoff_digest"],
            entity_revision=handoff["roleAuthorizationRevision"],
            state_digest=parsed["handoff_digest"],
            previous_state_digest=
                context["load_receipt_payload_digest"],
            actor_id=actor_id,
            evidence={
                "attestationChainSha256": handoff["chainSha256"],
                "receiptSha256": handoff["receiptSha256"],
                "roleAuthorizationSha256":
                    handoff["roleAuthorizationSha256"],
            },
            created_at_epoch_ns=parsed["role_issued_at_epoch_ns"],
        )
        stored = {
            "runtime_attestation_handoff_digest":
                parsed["handoff_digest"],
            "runtime_attestation_handoff_json":
                parsed["handoff_json"],
            "canary_id": item["canary_id"],
            "instance_id": item["instance_id"],
            "boot_id": item["boot_id"],
            "candidate_id": item["candidate_id"],
            "assignment_envelope_digest":
                context["assignment_envelope_digest"],
            "assignment_payload_digest":
                context["assignment_payload_digest"],
            "assignment_revision": context["assignment_revision"],
            "load_receipt_envelope_digest":
                context["load_receipt_envelope_digest"],
            "load_receipt_payload_digest":
                context["load_receipt_payload_digest"],
            "receipt_id": handoff["receiptId"],
            "receipt_revision": handoff["receiptRevision"],
            "receipt_envelope_digest": handoff["receiptSha256"],
            "receipt_payload_digest":
                handoff["receiptPayloadSha256"],
            "role_authorization_id":
                handoff["roleAuthorizationId"],
            "role_authorization_revision":
                handoff["roleAuthorizationRevision"],
            "role_authorization_envelope_digest":
                handoff["roleAuthorizationSha256"],
            "role_authorization_payload_digest":
                handoff["roleAuthorizationPayloadSha256"],
            "role_authorization_envelope_json":
                role_envelope["envelope_json"],
            "role_authorization_payload_json":
                role_envelope["payload_json"],
            "role_authorization_signature_algorithm":
                role_envelope["signature_algorithm"],
            "role_authorization_signing_key_id":
                role_envelope["signing_key_id"],
            "role_authorization_signature":
                role_envelope["signature"],
            "role_authorization_signature_digest":
                role_envelope["signature_digest"],
            "role_authorization_evidence_kind":
                "shadow_role_authorization",
            "role_authorization_record_binding_digest":
                role_verification["record_binding_digest"],
            "role_authorization_verification_receipt_digest":
                role_verification["verification_receipt_digest"],
            "attestation_evidence_id":
                parsed["evidence"]["evidenceId"],
            "attestation_evidence_revision":
                parsed["evidence"]["evidenceRevision"],
            "attestation_evidence_type":
                parsed["evidence"]["evidenceType"],
            "attestation_evidence_digest":
                parsed["evidence"]["evidenceSha256"],
            "attestation_evidence_json": parsed["evidence_json"],
            "attestation_chain_digest": handoff["chainSha256"],
            "runtime_identity_digest":
                parsed["runtime_identity_digest"],
            "runtime_executable_digest":
                role["runtimeExecutableSha256"],
            "runtime_release_digest": role["runtimeReleaseSha256"],
            "runtime_config_digest": role["runtimeConfigSha256"],
            "runtime_policy_digest": role["runtimePolicySha256"],
            "attestation_policy_digest":
                role["attestationPolicySha256"],
            "attestation_trust_checkpoint_digest":
                role["attestationTrustCheckpointSha256"],
            "attestation_revocation_generation":
                role["revocationGeneration"],
            "attestation_revocation_root_digest":
                role["revocationRootSha256"],
            "shadow_signing_key_id":
                role["shadowSigningKeyId"],
            "shadow_signing_key_spki_digest":
                role["shadowSigningKeySpkiSha256"],
            "shadow_role_key_authorization_digest":
                shadow_key["authorization_digest"],
            "tee_measurement_digest":
                attestation["tee_measurement_digest"],
            "issued_at_epoch_ns":
                parsed["role_issued_at_epoch_ns"],
            "expires_at_epoch_ns":
                min(
                    parsed["role_expires_at_epoch_ns"],
                    parsed["receipt_expires_at_epoch_ns"],
                ),
            "created_transition_digest": transition_digest,
        }
        _insert_immutable_candidate_row(
            conn,
            table="policy_shadow_runtime_attestation_handoffs",
            columns=tuple(stored),
            values=stored,
            key_columns=("runtime_attestation_handoff_digest",),
        )
    return _policy_authority_freeze(stored)


def derive_policy_shadow_generation_request_identities(
    *,
    request_id: str,
    actor_id: str,
    candidate_id: str,
    canary_id: str,
    instance_id: str,
    boot_id: str,
    assignment_envelope_digest: str,
    load_receipt_envelope_digest: str,
    active_policy_hash: str,
    active_policy_bundle_digest: str,
    candidate_policy_hash: str,
    candidate_policy_bundle_digest: str,
    runtime_attestation_chain_digest: str,
    request_identity_digest: str,
) -> Mapping[str, str]:
    request_id = _candidate_authority_text(
        "generation request ID", request_id, maximum=36
    )
    candidate_id = _candidate_authority_text(
        "generation candidate ID", candidate_id, maximum=256
    )
    canary_id = _candidate_authority_text(
        "generation canary ID", canary_id, maximum=256
    )
    instance_id = _candidate_authority_text(
        "generation instance ID", instance_id, maximum=256
    )
    boot_id = _candidate_authority_digest(
        "generation boot ID", boot_id
    )
    assignment_envelope_digest = _candidate_authority_digest(
        "generation assignment envelope", assignment_envelope_digest
    )
    load_receipt_envelope_digest = _candidate_authority_digest(
        "generation load receipt envelope",
        load_receipt_envelope_digest,
    )
    active_policy_hash = _candidate_authority_digest(
        "generation active policy", active_policy_hash
    )
    active_policy_bundle_digest = _candidate_authority_digest(
        "generation active policy bundle", active_policy_bundle_digest
    )
    candidate_policy_hash = _candidate_authority_digest(
        "generation candidate policy", candidate_policy_hash
    )
    candidate_policy_bundle_digest = _candidate_authority_digest(
        "generation candidate policy bundle",
        candidate_policy_bundle_digest,
    )
    runtime_attestation_chain_digest = _candidate_authority_digest(
        "generation runtime attestation chain",
        runtime_attestation_chain_digest,
    )
    request_identity_digest = _candidate_authority_digest(
        "generation request identity", request_identity_digest
    )
    actor_id = _candidate_authority_text(
        "generation management actor", actor_id, maximum=1024
    )
    identity = {
        "activePolicyBundleSha256": active_policy_bundle_digest,
        "activePolicySha256": active_policy_hash,
        "actorId": actor_id,
        "assignmentSha256": assignment_envelope_digest,
        "bootIdSha256": boot_id,
        "candidateId": candidate_id,
        "candidatePolicyBundleSha256": candidate_policy_bundle_digest,
        "candidatePolicySha256": candidate_policy_hash,
        "canaryId": canary_id,
        "instanceId": instance_id,
        "loadReceiptSha256": load_receipt_envelope_digest,
        "requestId": request_id,
        "requestIdentitySha256": request_identity_digest,
        "runtimeAttestationChainSha256":
            runtime_attestation_chain_digest,
    }
    replay_digest = _policy_authority_domain_digest(
        b"serverware.policyShadowGenerationReplayIdentity/v1",
        dumps(identity).encode("ascii"),
    )
    replay_id = "replay:" + replay_digest.removeprefix("sha256:")
    if (
        not DATA_PLANE_MANAGEMENT_TOKEN
        or len(DATA_PLANE_MANAGEMENT_TOKEN.encode("utf-8")) > 4096
    ):
        raise PolicyCandidateAuthorityError(
            "decision-gate management authentication is unavailable"
        )
    handoff_material = dumps(
        {
            **identity,
            "replayId": replay_id,
            "route": "/v1/policy-shadow/generations",
        }
    ).encode("ascii")
    management_handoff_id = "handoff:" + hmac.new(
        DATA_PLANE_MANAGEMENT_TOKEN.encode("utf-8"),
        b"serverware.policyShadowGenerationManagementIdentity/v1\0"
        + handoff_material,
        hashlib.sha256,
    ).hexdigest()
    return MappingProxyType(
        {
            "replay_id": replay_id,
            "management_handoff_id": management_handoff_id,
        }
    )


def claim_policy_shadow_generation_request(
    *,
    request_id: str,
    replay_id: str,
    management_handoff_id: str,
    request_identity_digest: str,
    payload_digest: str,
    actor_id: str,
) -> Mapping[str, Any]:
    """Durably reserve the exact generation request before network I/O."""
    request_id = _candidate_authority_text(
        "generation request ID", request_id, maximum=36
    )
    replay_id = _candidate_authority_text(
        "generation replay ID", replay_id, maximum=256
    )
    management_handoff_id = _candidate_authority_text(
        "generation management handoff ID",
        management_handoff_id,
        maximum=256,
    )
    request_identity_digest = _candidate_authority_digest(
        "generation request identity", request_identity_digest
    )
    payload_digest = _candidate_authority_digest(
        "generation request payload", payload_digest
    )
    actor_id = _candidate_authority_text(
        "generation request actor", actor_id, maximum=1024
    )
    if (
        re.fullmatch(
            r"[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-"
            r"[89ab][0-9a-f]{3}-[0-9a-f]{12}",
            request_id,
        )
        is None
        or request_id in {replay_id, management_handoff_id}
        or replay_id == management_handoff_id
    ):
        raise PolicyCandidateAuthorityError(
            "generation request identities are invalid"
        )
    event = {
        "apiVersion":
            "serverware.policyShadowGenerationRequestReservation/v1",
        "managementHandoffId": management_handoff_id,
        "requestId": request_id,
        "requestIdentitySha256": request_identity_digest,
        "requestPayloadSha256": payload_digest,
        "replayId": replay_id,
    }
    try:
        receipt = record_audit_event(
            "policy.shadow_generation.request.reserved",
            event,
            actor_type="admin",
            actor_id=actor_id,
            idempotency_key=(
                "policy-shadow-generation-request:" + request_id
            ),
        )
    except AuditStoreError as exc:
        raise PolicyCandidateAuthorityConflictError(
            "generation request identity was already reserved differently"
        ) from exc
    return _policy_authority_freeze(
        {
            "request_id": request_id,
            "replay_id": replay_id,
            "management_handoff_id": management_handoff_id,
            "request_identity_digest": request_identity_digest,
            "payload_digest": payload_digest,
            "audit_event_id": receipt["id"],
            "audit_event_hash": receipt["event_hash"],
        }
    )


def _policy_shadow_generation_rust_domain_digest(
    domain: bytes,
    value: Any,
) -> str:
    canonical = dumps(value).encode("ascii")
    return _candidate_authority_sha256(domain + b"\0" + canonical)


def _policy_shadow_generation_publication_key_binding(
    conn: Any,
    *,
    assignment_envelope_digest: str,
    member_ordinal: int,
    signing_key_id: str,
    verified_public_key_digest: str,
) -> Mapping[str, Any]:
    shadow_key = conn.execute(
        "SELECT signing_key_id, public_key_base64url, public_key_digest, "
        "authorization_digest, attestation_receipt_envelope_digest "
        "FROM policy_runtime_role_keys "
        "WHERE assignment_envelope_digest = ? AND member_ordinal = ? "
        "AND role = 'shadow'",
        (assignment_envelope_digest, member_ordinal),
    ).fetchone()
    trusted_key = conn.execute(
        "SELECT key_revision, signing_key_id, public_key_base64url, "
        "public_key_digest "
        "FROM policy_authority_trusted_keys "
        "WHERE evidence_kind = 'generation_publication' "
        "AND signing_key_id = ? "
        "AND signature_domain = "
        "'serverware.policyShadowGenerationPublication/v2'",
        (signing_key_id,),
    ).fetchone()
    trusted_head = conn.execute(
        "SELECT head_key_revision, head_signing_key_id, "
        "head_public_key_digest "
        "FROM policy_authority_trusted_key_heads "
        "WHERE evidence_kind = 'generation_publication'",
    ).fetchone()
    trusted_revocation = conn.execute(
        "SELECT 1 FROM policy_authority_trusted_key_revocations "
        "WHERE evidence_kind = 'generation_publication' "
        "AND signing_key_id = ? LIMIT 1",
        (signing_key_id,),
    ).fetchone()
    revoked = (
        None
        if shadow_key is None
        else conn.execute(
            "SELECT 1 FROM policy_runtime_role_key_revocations "
            "WHERE assignment_envelope_digest = ? AND member_ordinal = ? "
            "AND role = 'shadow' AND public_key_digest = ? LIMIT 1",
            (
                assignment_envelope_digest,
                member_ordinal,
                shadow_key["public_key_digest"],
            ),
        ).fetchone()
    )
    if (
        shadow_key is None
        or trusted_key is None
        or trusted_head is None
        or revoked is not None
        or trusted_revocation is not None
        or int(trusted_key["key_revision"])
        != int(trusted_head["head_key_revision"])
        or trusted_key["signing_key_id"]
        != trusted_head["head_signing_key_id"]
        or trusted_key["public_key_digest"]
        != trusted_head["head_public_key_digest"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "generation publication shadow signer trust is unavailable"
        )

    def spki_digest(label: str, encoded: Any) -> str:
        public_key = Ed25519PublicKey.from_public_bytes(
            _candidate_authority_b64url(
                label, encoded, expected_bytes=32
            )
        )
        return _candidate_authority_sha256(
            public_key.public_bytes(
                serialization.Encoding.DER,
                serialization.PublicFormat.SubjectPublicKeyInfo,
            )
        )

    shadow_spki_digest = spki_digest(
        "attested shadow publication key",
        shadow_key["public_key_base64url"],
    )
    trusted_spki_digest = spki_digest(
        "trusted generation publication key",
        trusted_key["public_key_base64url"],
    )
    if not (
        signing_key_id
        == shadow_key["signing_key_id"]
        == shadow_key["public_key_digest"]
        == shadow_spki_digest
        == trusted_key["signing_key_id"]
        == trusted_key["public_key_digest"]
        == trusted_spki_digest
        == verified_public_key_digest
    ):
        raise PolicyCandidateAuthorityConflictError(
            "generation publication signer is not the exact attested shadow SPKI"
        )
    return MappingProxyType(
        {
            "signing_key_id": signing_key_id,
            "public_key_digest": shadow_spki_digest,
            "authorization_digest":
                shadow_key["authorization_digest"],
            "attestation_receipt_envelope_digest":
                shadow_key["attestation_receipt_envelope_digest"],
        }
    )


def _policy_shadow_generation_high_water_digests(
    item: Mapping[str, Any],
) -> tuple[str, str]:
    custody = _policy_authority_domain_digest(
        b"serverware.policyShadowCustodyPublicationHighWater/v1",
        dumps(
            {
                "assignmentSha256":
                    item["assignment_envelope_digest"],
                "bootIdSha256": item["boot_id"],
                "canaryId": item["canary_id"],
                "custodyPreparationReceiptSha256":
                    item["custody_preparation_receipt_digest"],
                "custodySequence": 0,
                "generationId": item["generation_id_digest"],
                "instanceId": item["instance_id"],
                "memberOrdinal": item["member_ordinal"],
            }
        ).encode("ascii"),
    )
    ingress = _policy_authority_domain_digest(
        b"serverware.policyShadowIngressPublicationHighWater/v1",
        dumps(
            {
                "assignmentSha256":
                    item["assignment_envelope_digest"],
                "bootIdSha256": item["boot_id"],
                "canaryId": item["canary_id"],
                "custodyHighWaterSha256": custody,
                "generationId": item["generation_id_digest"],
                "ingressSequence": 0,
                "instanceId": item["instance_id"],
                "memberOrdinal": item["member_ordinal"],
            }
        ).encode("ascii"),
    )
    return custody, ingress


