def _policy_shadow_generation_evidence(
    item: dict[str, Any],
) -> dict[str, Any]:
    generation_evidence_json = _candidate_authority_canonical_json(
        "generation evidence",
        item["generation_evidence_json"],
        maximum=2 * 1024 * 1024,
    )
    evidence = _candidate_authority_strict_object(
        "generation evidence",
        loads(generation_evidence_json, None),
        _POLICY_SHADOW_GENERATION_EVIDENCE_FIELDS,
    )
    request = _candidate_authority_strict_object(
        "generation evidence request",
        evidence["request"],
        _POLICY_SHADOW_GENERATION_EVIDENCE_REQUEST_FIELDS,
    )
    generation = _candidate_authority_strict_object(
        "generation evidence generation",
        evidence["generation"],
        _POLICY_SHADOW_GENERATION_EVIDENCE_GENERATION_FIELDS,
    )
    active = _candidate_authority_strict_object(
        "generation evidence active snapshot",
        generation["active"],
        _POLICY_SHADOW_GENERATION_EVIDENCE_SNAPSHOT_FIELDS,
    )
    candidate = _candidate_authority_strict_object(
        "generation evidence candidate snapshot",
        generation["candidate"],
        _POLICY_SHADOW_GENERATION_EVIDENCE_SNAPSHOT_FIELDS,
    )
    custody = _candidate_authority_strict_object(
        "generation evidence custody",
        evidence["custody"],
        _POLICY_SHADOW_GENERATION_EVIDENCE_CUSTODY_FIELDS,
    )
    runtime = _candidate_authority_strict_object(
        "generation evidence runtime",
        evidence["runtime"],
        _POLICY_SHADOW_GENERATION_EVIDENCE_RUNTIME_FIELDS,
    )
    trust = _candidate_authority_strict_object(
        "generation evidence trust",
        evidence["trust"],
        _POLICY_SHADOW_GENERATION_EVIDENCE_TRUST_FIELDS,
    )
    attestation_chain = _candidate_authority_strict_object(
        "generation evidence attestation chain",
        evidence["attestationChain"],
        _POLICY_SHADOW_GENERATION_ATTESTATION_CHAIN_FIELDS,
    )
    startup_attestation = _candidate_authority_strict_object(
        "generation startup runtime-attestation handoff",
        attestation_chain["startupAttestation"],
        _POLICY_SHADOW_GENERATION_REQUEST_ATTESTATION_FIELDS,
    )
    runtime_evidence = _candidate_authority_strict_object(
        "generation runtime attestation evidence",
        startup_attestation["evidence"],
        _POLICY_SHADOW_RUNTIME_ATTESTATION_EVIDENCE_FIELDS,
    )
    inner_envelope = attestation_chain[
        "runtimeAttestationVerification"
    ]
    inner = _policy_shadow_direct_envelope_components(
        "generation runtime attestation verification",
        inner_envelope,
    )
    inner_payload = _candidate_authority_strict_object(
        "generation runtime attestation verification payload",
        inner["payload"],
        _POLICY_SHADOW_DIRECT_PAYLOAD_FIELDS[
            "generation_runtime_attestation_verification"
        ],
    )
    digest_values = [
        evidence["preparationEnvelopeSha256"],
        evidence["externalRecordSha256"],
        evidence["durableCommitReceiptSha256"],
        request["managementHandoffSha256"],
        request["requestSha256"],
        generation["generationId"],
        generation["assignmentEnvelopeSha256"],
        generation["assignmentPayloadSha256"],
        generation["loadReceiptEnvelopeSha256"],
        generation["loadReceiptPayloadSha256"],
        generation["runtimeBootIdSha256"],
        generation["activePolicyBundleSha256"],
        generation["candidatePolicyBundleSha256"],
        generation["requestFactsSchemaSha256"],
        generation["ingressRangePredecessorHeadSha256"],
        generation["observationIntervalSha256"],
        generation["responseValidationObligationsRootSha256"],
        custody["custodyConfigurationSha256"],
        custody["preparationReceiptSha256"],
        custody["publicationReceiptSha256"],
        custody["publicationReconciliationReceiptSha256"],
        custody["authoritativeLedgerHeadSha256"],
        custody["authoritativeSpoolRootSha256"],
        *[
            active[field]
            for field in (
                "policySha256",
                "compiledSnapshotSha256",
                "compiledBehaviorSha256",
            )
        ],
        *[
            candidate[field]
            for field in (
                "policySha256",
                "compiledSnapshotSha256",
                "compiledBehaviorSha256",
            )
        ],
        *[
            runtime[field]
            for field in _POLICY_SHADOW_GENERATION_EVIDENCE_RUNTIME_FIELDS
            if field != "runtimeInstanceId"
        ],
        *[
            trust[field]
            for field in _POLICY_SHADOW_GENERATION_EVIDENCE_TRUST_FIELDS
            if field not in {"revocationGeneration", "replayStoreRevision"}
        ],
        runtime_evidence["evidenceSha256"],
        attestation_chain[
            "runtimeAttestationVerificationEnvelopeSha256"
        ],
    ]
    for value in digest_values:
        _candidate_authority_digest(
            "generation evidence digest", value
        )
    integer_values = (
        generation["generationEpoch"],
        generation["minimumGenerationTombstoneEpoch"],
        generation["generationTombstoneEpoch"],
        generation["assignmentRevision"],
        generation["requestCommitmentKeyEpoch"],
        generation["ingressRangeStartSequence"],
        generation["signedPublicationRevision"],
        custody["publicationRevision"],
        custody["authoritativeLedgerEventOrdinal"],
        active["policySequence"],
        active["rollbackEpoch"],
        active["runtimeSnapshotEpoch"],
        active["policyTrustGeneration"],
        candidate["policySequence"],
        candidate["rollbackEpoch"],
        candidate["runtimeSnapshotEpoch"],
        candidate["policyTrustGeneration"],
        trust["revocationGeneration"],
        trust["replayStoreRevision"],
        evidence["notBeforeUnixNanos"],
        evidence["issuedAtUnixNanos"],
        evidence["expiresAtUnixNanos"],
    )
    if any(
        _candidate_authority_int(
            "generation evidence integer",
            value,
            minimum=0,
        )
        != value
        for value in integer_values
    ):
        raise PolicyCandidateAuthorityError(
            "generation evidence integer is invalid"
        )
    expected_management_handoff_digest = (
        _policy_shadow_generation_rust_domain_digest(
            b"serverware.policyShadowGenerationManagementHandoff/v1",
            [
                request["requestId"],
                request["replayId"],
                request["managementHandoffId"],
                request["requestSha256"],
                runtime["runtimeIdentitySha256"],
            ],
        )
    )
    expected_runtime_evidence_chain_digest = (
        _policy_shadow_generation_rust_domain_digest(
            b"serverware.policyShadowRuntimeAttestationEvidenceChain/v1",
            [
                startup_attestation["apiVersion"],
                startup_attestation["receiptId"],
                startup_attestation["receiptRevision"],
                startup_attestation["receiptSha256"],
                startup_attestation["receiptPayloadSha256"],
                startup_attestation["roleAuthorizationId"],
                startup_attestation["roleAuthorizationRevision"],
                startup_attestation["roleAuthorizationSha256"],
                startup_attestation[
                    "roleAuthorizationPayloadSha256"
                ],
                runtime_evidence,
                generation["assignmentPayloadSha256"],
                generation["loadReceiptPayloadSha256"],
                runtime["runtimeIdentitySha256"],
                trust["runtimeAttestationPolicySha256"],
            ],
        )
    )
    expected_commit_digest = _policy_shadow_generation_rust_domain_digest(
        b"serverware.policyShadowGenerationDurableReplayCommit/v1",
        [
            request,
            evidence["preparationEnvelopeSha256"],
            generation["generationId"],
            generation["assignmentRevision"],
            custody,
            trust["publicationReplayStoreSha256"],
            trust["replayStoreRevision"],
        ],
    )
    expected_runtime_measurement = (
        _policy_shadow_generation_rust_domain_digest(
            b"serverware.policyShadowDecisionGateRuntimeMeasurement/v1",
            [
                runtime["decisionGateExecutableSha256"],
                runtime["releaseProvenanceSha256"],
                runtime["imageSignaturesSha256"],
                runtime["generationTrustManifestSha256"],
                custody["custodyConfigurationSha256"],
                runtime["runtimeIdentitySha256"],
                runtime["activePolicySigningKeyId"],
                runtime[
                    "runtimeAttestationVerifierExecutableSha256"
                ],
                runtime["publicationHandoffExecutableSha256"],
                active["policySequence"],
                active["rollbackEpoch"],
                active["policyTrustGeneration"],
                runtime["policyCompilerBinarySha256"],
                runtime["policyCompilerConfigurationSha256"],
            ],
        )
    )
    runtime_evidence_value_json = dumps(runtime_evidence["evidence"])
    external_record = _policy_shadow_generation_signed_record(item)
    external_record.pop("generationEvidence")
    expected_external_record_digest = _candidate_authority_sha256(
        dumps(external_record).encode("ascii")
    )
    if (
        evidence["schemaVersion"]
        != "serverware.policyShadowGenerationPublication/v2"
        or evidence["signatureDomain"]
        != "serverware.policyShadowGenerationPublication/v2"
        or evidence["signatureAlgorithm"] != "Ed25519"
        or evidence["canonicalizationProfile"]
        != _POLICY_AUTHORITY_CANONICAL_PROFILE
        or evidence["status"] != "published"
        or evidence["notBeforeUnixNanos"]
        != evidence["issuedAtUnixNanos"]
        or evidence["expiresAtUnixNanos"]
        <= evidence["issuedAtUnixNanos"]
        or evidence["expiresAtUnixNanos"]
        - evidence["issuedAtUnixNanos"]
        > 15 * 60 * 1_000_000_000
        or request["requestId"] != item["request_id"]
        or request["replayId"] != item["replay_id"]
        or request["managementHandoffId"]
        != item["management_handoff_id"]
        or request["requestSha256"] != item["request_payload_digest"]
        or request["managementHandoffSha256"]
        != expected_management_handoff_digest
        or generation["generationId"] != item["generation_id_digest"]
        or generation["generationEpoch"] != item["generation_epoch"]
        or generation["minimumGenerationTombstoneEpoch"]
        != item["minimum_generation_tombstone_epoch"]
        or generation["assignmentEnvelopeSha256"]
        != item["assignment_envelope_digest"]
        or generation["assignmentPayloadSha256"]
        != item["assignment_payload_digest"]
        or generation["assignmentRevision"] != item["assignment_revision"]
        or generation["loadReceiptEnvelopeSha256"]
        != item["load_receipt_envelope_digest"]
        or generation["loadReceiptPayloadSha256"]
        != item["load_receipt_payload_digest"]
        or generation["runtimeBootIdSha256"] != item["boot_id"]
        or generation["generationTombstoneEpoch"]
        > generation["generationEpoch"]
        or generation["generationTombstoneEpoch"]
        < generation["minimumGenerationTombstoneEpoch"]
        or generation["signedPublicationRevision"]
        != custody["publicationRevision"]
        or generation["requestFactsSchemaSha256"]
        != runtime["requestFactsSchemaSha256"]
        or active["policySha256"] != item["active_policy_hash"]
        or active["policySequence"] != item["active_policy_sequence"]
        or active["rollbackEpoch"] != item["active_rollback_epoch"]
        or generation["activePolicyBundleSha256"]
        != item["active_policy_bundle_digest"]
        or candidate["policySha256"] != item["candidate_policy_hash"]
        or candidate["policySequence"]
        != item["candidate_policy_sequence"]
        or candidate["rollbackEpoch"]
        != item["candidate_rollback_epoch"]
        or generation["candidatePolicyBundleSha256"]
        != item["candidate_policy_bundle_digest"]
        or candidate["policySequence"] <= active["policySequence"]
        or custody["preparationReceiptSha256"]
        != item["custody_preparation_receipt_digest"]
        or custody["publicationRevision"] != item["publication_revision"]
        or custody["authoritativeLedgerEventOrdinal"]
        != item["custody_sequence"]
        or custody["authoritativeLedgerHeadSha256"]
        != item["custody_high_water_digest"]
        or generation["ingressRangeStartSequence"] - 1
        != item["ingress_sequence"]
        or generation["ingressRangePredecessorHeadSha256"]
        != item["ingress_high_water_digest"]
        or runtime["decisionGateExecutableSha256"]
        != item["runtime_executable_digest"]
        or runtime["releaseProvenanceSha256"]
        != item["runtime_release_digest"]
        or runtime["runtimeConfigurationSha256"]
        != item["runtime_config_digest"]
        or runtime["runtimePolicySha256"]
        != item["runtime_policy_digest"]
        or runtime["runtimeInstanceId"] != item["instance_id"]
        or runtime["runtimeBootIdSha256"] != item["boot_id"]
        or runtime["runtimeTeeMeasurementSha256"]
        != item["tee_measurement_digest"]
        or runtime["generationTrustManifestSha256"]
        != trust["trustCheckpointSha256"]
        or trust["runtimeAttestationPolicySha256"]
        != item["attestation_policy_digest"]
        or trust["trustCheckpointSha256"]
        != item["attestation_trust_checkpoint_digest"]
        or trust["publicationSigningKeyId"] != item["signing_key_id"]
        or trust["publicationSigningKeySpkiSha256"]
        != item["signing_key_id"]
        or runtime_evidence["evidenceSha256"]
        != item["attestation_evidence_digest"]
        or startup_attestation["apiVersion"]
        != "serverware.policyShadowRuntimeAttestationHandoff/v2"
        or startup_attestation["receiptSha256"]
        != item["runtime_attestation_receipt_envelope_digest"]
        or startup_attestation["receiptPayloadSha256"]
        != item["runtime_attestation_receipt_payload_digest"]
        or startup_attestation["roleAuthorizationSha256"]
        != item["attestation_role_authorization_digest"]
        or startup_attestation["chainSha256"]
        != item["attestation_chain_digest"]
        or attestation_chain["attestationMode"]
        != item["attestation_mode"]
        or attestation_chain["hardwareAttested"]
        != item["hardware_attested"]
        or (
            attestation_chain["attestationMode"] == "trusted-host-no-tee"
            and attestation_chain["hardwareAttested"] is not False
        )
        or (
            attestation_chain["attestationMode"]
            in {"aws-nitro-enclave", "amd-sev-snp", "intel-tdx"}
            and attestation_chain["hardwareAttested"] is not True
        )
        or attestation_chain["attestationMode"] not in {
            "trusted-host-no-tee",
            "aws-nitro-enclave",
            "amd-sev-snp",
            "intel-tdx",
        }
        or inner["envelope_digest"]
        != attestation_chain[
            "runtimeAttestationVerificationEnvelopeSha256"
        ]
        or inner["envelope_digest"]
        != item["runtime_attestation_verification_envelope_digest"]
        or inner_envelope.get("apiVersion")
        != "serverware.policyShadowRuntimeAttestationVerification/v2"
        or inner_envelope.get("kind")
        != "PolicyShadowRuntimeAttestationVerification"
        or inner_envelope.get("signatureDomain")
        != "serverware.policyShadowRuntimeAttestationVerification/v2"
        or inner_envelope.get("canonicalProfile")
        != _POLICY_AUTHORITY_CANONICAL_PROFILE
        or inner_envelope.get("signingKeySpkiSha256")
        != inner["signing_key_id"]
        or inner["signing_key_id"]
        != trust["runtimeAttestationVerifierSigningKeyId"]
        or inner["signing_key_id"]
        != trust[
            "runtimeAttestationVerifierSigningKeySpkiSha256"
        ]
        or inner_payload["schemaVersion"]
        != "serverware.policyShadowRuntimeAttestationVerification/v2"
        or inner_payload["status"] != "verified"
        or inner_payload["attestationPolicySha256"]
        != trust["runtimeAttestationPolicySha256"]
        or inner_payload["assignmentPayloadSha256"]
        != generation["assignmentPayloadSha256"]
        or inner_payload["loadReceiptPayloadSha256"]
        != generation["loadReceiptPayloadSha256"]
        or inner_payload["runtimeIdentitySha256"]
        != runtime["runtimeIdentitySha256"]
        or inner_payload["runtimeAttestationReceiptSha256"]
        != startup_attestation["receiptSha256"]
        or inner_payload["runtimeAttestationPayloadSha256"]
        != startup_attestation["receiptPayloadSha256"]
        or inner_payload["roleAuthorizationSha256"]
        != startup_attestation["roleAuthorizationSha256"]
        or inner_payload["roleAuthorizationPayloadSha256"]
        != startup_attestation["roleAuthorizationPayloadSha256"]
        or inner_payload["attestationEvidenceId"]
        != runtime_evidence["evidenceId"]
        or inner_payload["attestationEvidenceRevision"]
        != runtime_evidence["evidenceRevision"]
        or inner_payload["teeEvidenceSha256"]
        != runtime_evidence["evidenceSha256"]
        or inner_payload["teeMeasurementSha256"]
        != item["tee_measurement_digest"]
        or inner_payload["runtimeExecutableSha256"]
        != item["runtime_executable_digest"]
        or inner_payload["runtimeReleaseSha256"]
        != item["runtime_release_digest"]
        or inner_payload["runtimeConfigSha256"]
        != item["runtime_config_digest"]
        or inner_payload["runtimePolicySha256"]
        != item["runtime_policy_digest"]
        or inner_payload["shadowSigningKeyId"]
        != item["signing_key_id"]
        or inner_payload["shadowSigningKeySpkiSha256"]
        != item["signing_key_id"]
        or inner_payload["trustCheckpointSha256"]
        != trust["trustCheckpointSha256"]
        or inner_payload["revocationGeneration"]
        != trust["revocationGeneration"]
        or inner_payload["revocationRootSha256"]
        != trust["revocationRootSha256"]
        or inner_payload["attestationMode"]
        != attestation_chain["attestationMode"]
        or inner_payload["hardwareAttested"]
        != attestation_chain["hardwareAttested"]
        or inner_payload["trustedNowUnixNanos"]
        < inner_payload["issuedAtUnixNanos"]
        or inner_payload["trustedNowUnixNanos"]
        >= inner_payload["expiresAtUnixNanos"]
        or inner_payload["expiresAtUnixNanos"]
        <= inner_payload["issuedAtUnixNanos"]
        or inner_payload["expiresAtUnixNanos"]
        - inner_payload["issuedAtUnixNanos"]
        > 15 * 60 * 1_000_000_000
        or trust["replayStoreRevision"]
        != generation["assignmentRevision"]
        or runtime_evidence["apiVersion"]
        != "serverware.policyShadowRuntimeAttestationEvidence/v1"
        or runtime_evidence["evidenceType"]
        != attestation_chain["attestationMode"]
        or _candidate_authority_sha256(
            runtime_evidence_value_json.encode("ascii")
        )
        != runtime_evidence["evidenceSha256"]
        or inner_payload["evidenceChainSha256"]
        != expected_runtime_evidence_chain_digest
        or evidence["externalRecordSha256"]
        != expected_external_record_digest
        or evidence["durableCommitReceiptSha256"]
        != expected_commit_digest
        or runtime["decisionGateRuntimeMeasurementSha256"]
        != expected_runtime_measurement
    ):
        raise PolicyCandidateAuthorityConflictError(
            "generation evidence does not bind the exact durable projection"
        )
    attestation_chain_json = dumps(attestation_chain)
    item.update(
        {
            "generation_preparation_envelope_digest":
                evidence["preparationEnvelopeSha256"],
            "custody_configuration_digest":
                custody["custodyConfigurationSha256"],
            "custody_publication_receipt_digest":
                custody["publicationReceiptSha256"],
            "publication_reconciliation_receipt_digest":
                custody["publicationReconciliationReceiptSha256"],
            "authoritative_spool_root_digest":
                custody["authoritativeSpoolRootSha256"],
            "ingress_range_start_sequence":
                generation["ingressRangeStartSequence"],
            "observation_interval_digest":
                generation["observationIntervalSha256"],
            "response_obligations_digest":
                generation[
                    "responseValidationObligationsRootSha256"
                ],
            "request_commitment_key_epoch":
                generation["requestCommitmentKeyEpoch"],
            "request_facts_schema_digest":
                generation["requestFactsSchemaSha256"],
            "active_compiled_snapshot_digest":
                active["compiledSnapshotSha256"],
            "active_compiled_behavior_digest":
                active["compiledBehaviorSha256"],
            "active_runtime_snapshot_epoch":
                active["runtimeSnapshotEpoch"],
            "active_policy_trust_generation":
                active["policyTrustGeneration"],
            "candidate_compiled_snapshot_digest":
                candidate["compiledSnapshotSha256"],
            "candidate_compiled_behavior_digest":
                candidate["compiledBehaviorSha256"],
            "candidate_runtime_snapshot_epoch":
                candidate["runtimeSnapshotEpoch"],
            "candidate_policy_trust_generation":
                candidate["policyTrustGeneration"],
            "runtime_measurement_digest":
                runtime["decisionGateRuntimeMeasurementSha256"],
            "image_signatures_digest":
                runtime["imageSignaturesSha256"],
            "generation_trust_manifest_digest":
                runtime["generationTrustManifestSha256"],
            "policy_compiler_binary_digest":
                runtime["policyCompilerBinarySha256"],
            "policy_schema_digest": runtime["policySchemaSha256"],
            "adapter_schema_digest": runtime["adapterSchemaSha256"],
            "policy_semantic_model_digest":
                runtime["policySemanticModelSha256"],
            "policy_plan_schema_digest":
                runtime["policyPlanSchemaSha256"],
            "runtime_attestation_verifier_executable_digest":
                runtime[
                    "runtimeAttestationVerifierExecutableSha256"
                ],
            "publication_handoff_executable_digest":
                runtime["publicationHandoffExecutableSha256"],
            "active_policy_signing_key_id":
                runtime["activePolicySigningKeyId"],
            "runtime_instance_id": runtime["runtimeInstanceId"],
            "runtime_identity_digest":
                runtime["runtimeIdentitySha256"],
            "attestation_revocation_generation":
                trust["revocationGeneration"],
            "attestation_revocation_root_digest":
                trust["revocationRootSha256"],
            "runtime_attestation_verifier_signing_key_id":
                trust[
                    "runtimeAttestationVerifierSigningKeyId"
                ],
            "runtime_attestation_verifier_signing_key_spki_digest":
                trust[
                    "runtimeAttestationVerifierSigningKeySpkiSha256"
                ],
            "publication_signing_key_id":
                trust["publicationSigningKeyId"],
            "publication_signing_key_spki_digest":
                trust["publicationSigningKeySpkiSha256"],
            "publication_replay_store_digest":
                trust["publicationReplayStoreSha256"],
            "replay_store_revision": trust["replayStoreRevision"],
            "runtime_attestation_evidence_json":
                dumps(runtime_evidence),
            "runtime_attestation_verification_envelope_json":
                inner["envelope_json"],
            "runtime_attestation_verification_payload_json":
                inner["payload_json"],
            "runtime_attestation_verifier_signature_algorithm":
                inner["signature_algorithm"],
            "runtime_attestation_verifier_signing_key_id":
                inner["signing_key_id"],
            "runtime_attestation_verifier_signature":
                inner["signature"],
            "runtime_attestation_verifier_signature_digest":
                inner["signature_digest"],
            "runtime_attestation_evidence_kind":
                "generation_runtime_attestation_verification",
            "attestation_chain_json": attestation_chain_json,
            "durable_commit_receipt_digest":
                evidence["durableCommitReceiptSha256"],
            "not_before_epoch_ns": evidence["notBeforeUnixNanos"],
            "runtime_attestation_trusted_at_epoch_ns":
                inner_payload["trustedNowUnixNanos"],
            "runtime_attestation_issued_at_epoch_ns":
                inner_payload["issuedAtUnixNanos"],
            "runtime_attestation_expires_at_epoch_ns":
                inner_payload["expiresAtUnixNanos"],
        }
    )
    return {
        "evidence": evidence,
        "request": request,
        "generation": generation,
        "custody": custody,
        "runtime": runtime,
        "trust": trust,
        "attestation_chain": attestation_chain,
        "startup_attestation": startup_attestation,
        "runtime_evidence": runtime_evidence,
        "inner": inner,
        "inner_payload": inner_payload,
    }


def stage_policy_shadow_generation_publication(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
) -> dict[str, Any]:
    """Verify and immutably stage one attested Rust generation publication."""
    item = _candidate_authority_record(
        "policy-shadow generation publication",
        record,
        _POLICY_SHADOW_GENERATION_PUBLICATION_FIELDS,
    )
    actor_id = _candidate_authority_text(
        "generation publication actor_id",
        item.pop("actor_id"),
        maximum=1024,
    )
    management_request_json = item.pop("management_request_json")
    for field, value in tuple(item.items()):
        if field.endswith("_digest") or field.endswith("_hash"):
            item[field] = _candidate_authority_digest(field, value)
    for field, minimum in (
        ("assignment_revision", 1),
        ("generation_epoch", 1),
        ("minimum_generation_tombstone_epoch", 1),
        ("membership_revision", 1),
        ("member_ordinal", 1),
        ("publication_revision", 1),
        ("custody_sequence", 0),
        ("ingress_sequence", 0),
        ("active_policy_sequence", 1),
        ("active_rollback_epoch", 1),
        ("candidate_policy_sequence", 1),
        ("candidate_rollback_epoch", 1),
    ):
        item[field] = _candidate_authority_int(
            field, item[field], minimum=minimum
        )
    if (
        item["publication_revision"] != 1
        or item["custody_sequence"] != 0
        or item["ingress_sequence"] != 0
        or (
            item["attestation_mode"] == "trusted-host-no-tee"
            and item["hardware_attested"] is not False
        )
        or (
            item["attestation_mode"]
            in {"aws-nitro-enclave", "amd-sev-snp", "intel-tdx"}
            and item["hardware_attested"] is not True
        )
        or item["attestation_mode"] not in {
            "trusted-host-no-tee",
            "aws-nitro-enclave",
            "amd-sev-snp",
            "intel-tdx",
        }
    ):
        raise PolicyCandidateAuthorityError(
            "generation publication revisions or attestation state are invalid"
        )
    if (
        not isinstance(item["request_id"], str)
        or re.fullmatch(
            r"[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-"
            r"[89ab][0-9a-f]{3}-[0-9a-f]{12}",
            item["request_id"],
        )
        is None
    ):
        raise PolicyCandidateAuthorityError(
            "generation publication request ID is not a lowercase UUIDv4"
        )
    for field in (
        "candidate_id",
        "canary_id",
        "member_id",
        "instance_id",
        "boot_id",
        "attestation_mode",
    ):
        _candidate_authority_text(field, item[field], maximum=256)
    management_request_json, request_payload_digest = (
        _candidate_authority_json(
            "policy-shadow management request",
            management_request_json,
            item["request_payload_digest"],
            maximum=8 * 1024 * 1024,
        )
    )
    item["request_payload_digest"] = request_payload_digest
    _candidate_authority_json(
        "generation_publication_envelope_json",
        item["generation_publication_envelope_json"],
        item["generation_publication_envelope_digest"],
        maximum=4 * 1024 * 1024,
    )
    _candidate_authority_json(
        "generation_publication_payload_json",
        item["generation_publication_payload_json"],
        item["generation_publication_payload_digest"],
        maximum=4 * 1024 * 1024,
    )
    _candidate_authority_signature_fields(item)

    request = loads(management_request_json, None)
    if (
        not isinstance(request, dict)
        or set(request) != _POLICY_SHADOW_GENERATION_REQUEST_FIELDS
        or request.get("apiVersion")
        != "serverware.policyShadowGenerationInstall/v2"
        or request.get("requestId") != item["request_id"]
        or request.get("replayId") != item["replay_id"]
        or request.get("managementHandoffId")
        != item["management_handoff_id"]
        or not isinstance(request.get("assignment"), dict)
        or not isinstance(request.get("loadReceipt"), dict)
        or not isinstance(request.get("activePolicyBundle"), dict)
        or not isinstance(request.get("candidatePolicyBundle"), dict)
        or not isinstance(request.get("runtimeAttestation"), dict)
        or set(request["runtimeAttestation"])
        != _POLICY_SHADOW_GENERATION_REQUEST_ATTESTATION_FIELDS
        or request["runtimeAttestation"].get("apiVersion")
        != "serverware.policyShadowRuntimeAttestationHandoff/v2"
    ):
        raise PolicyCandidateAuthorityError(
            "policy-shadow management request is not closed"
        )
    active_bundle_digest = _candidate_authority_sha256(
        dumps(request["activePolicyBundle"]).encode("ascii")
    )
    candidate_bundle_digest = _candidate_authority_sha256(
        dumps(request["candidatePolicyBundle"]).encode("ascii")
    )
    if (
        active_bundle_digest != item["active_policy_bundle_digest"]
        or candidate_bundle_digest
        != item["candidate_policy_bundle_digest"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "generation publication bundle bytes changed after handoff"
        )
    evidence_projection = _policy_shadow_generation_evidence(item)
    if (
        request["runtimeAttestation"]
        != evidence_projection["startup_attestation"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "generation publication changed its durable startup attestation"
        )
    identity_request = {
        key: value
        for key, value in request.items()
        if key not in {"replayId", "managementHandoffId"}
    }
    request_identity_digest = _candidate_authority_sha256(
        dumps(identity_request).encode("ascii")
    )
    identities = derive_policy_shadow_generation_request_identities(
        request_id=item["request_id"],
        actor_id=actor_id,
        candidate_id=item["candidate_id"],
        canary_id=item["canary_id"],
        instance_id=item["instance_id"],
        boot_id=item["boot_id"],
        assignment_envelope_digest=item["assignment_envelope_digest"],
        load_receipt_envelope_digest=
            item["load_receipt_envelope_digest"],
        active_policy_hash=item["active_policy_hash"],
        active_policy_bundle_digest=item["active_policy_bundle_digest"],
        candidate_policy_hash=item["candidate_policy_hash"],
        candidate_policy_bundle_digest=
            item["candidate_policy_bundle_digest"],
        runtime_attestation_chain_digest=
            item["attestation_chain_digest"],
        request_identity_digest=request_identity_digest,
    )
    if (
        identities["replay_id"] != item["replay_id"]
        or identities["management_handoff_id"]
        != item["management_handoff_id"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "generation request identities were not server-derived"
        )

    connection_scope = (
        connect() if _connection is None else contextlib.nullcontext(_connection)
    )
    with connection_scope as conn:
        _lock_policy_candidate_authority(conn)
        context = _policy_canary_runtime_context(
            conn,
            canary_id=item["canary_id"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
        )
        _require_policy_runtime_context(
            item,
            context,
            (
                "assignment_envelope_digest",
                "assignment_payload_digest",
                "assignment_revision",
                "generation_epoch",
                "minimum_generation_tombstone_epoch",
                "fleet_id",
                "membership_revision",
                "membership_root_digest",
                "member_ordinal",
                "member_id",
                "load_receipt_envelope_digest",
                "load_receipt_payload_digest",
                "candidate_policy_hash",
            ),
        )
        assignment = conn.execute(
            "SELECT candidate_policy_sequence, "
            "candidate_rollback_epoch, predecessor_policy_sequence, "
            "predecessor_rollback_epoch, predecessor_policy_hash, "
            "artifact_envelope_digest, artifact_payload_digest, "
            "assignment_envelope_json, assignment_payload_json "
            "FROM policy_canary_assignments WHERE canary_id = ?",
            (item["canary_id"],),
        ).fetchone()
        artifact = conn.execute(
            "SELECT candidate_id, policy_id, artifact_envelope_digest, "
            "artifact_payload_digest, policy_hash, policy_bundle_digest "
            "FROM policy_candidate_artifacts WHERE candidate_id = ?",
            (item["candidate_id"],),
        ).fetchone()
        load_receipt = conn.execute(
            "SELECT load_receipt_envelope_json "
            "FROM policy_canary_load_receipts "
            "WHERE load_receipt_envelope_digest = ?",
            (item["load_receipt_envelope_digest"],),
        ).fetchone()
        attestation = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_RUNTIME_ATTESTATION_READ_COLUMNS
            )
            + " FROM policy_runtime_attestations "
            "WHERE attestation_receipt_envelope_digest = ?",
            (context["attestation_receipt_envelope_digest"],),
        ).fetchone()
        shadow_key = conn.execute(
            "SELECT signing_key_id, public_key_digest, "
            "authorization_digest, attestation_receipt_envelope_digest "
            "FROM policy_runtime_role_keys "
            "WHERE assignment_envelope_digest = ? "
            "AND member_ordinal = ? AND role = 'shadow'",
            (
                item["assignment_envelope_digest"],
                item["member_ordinal"],
            ),
        ).fetchone()
        durable_handoff = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_SHADOW_RUNTIME_ATTESTATION_HANDOFF_COLUMNS
            )
            + " FROM policy_shadow_runtime_attestation_handoffs "
            "WHERE canary_id = ? AND instance_id = ? AND boot_id = ?",
            (
                item["canary_id"],
                item["instance_id"],
                item["boot_id"],
            ),
        ).fetchone()
        if (
            assignment is None
            or artifact is None
            or load_receipt is None
            or attestation is None
            or shadow_key is None
            or durable_handoff is None
        ):
            raise PolicyCandidateAuthorityConflictError(
                "generation publication trust predecessor is incomplete"
            )
        item["runtime_attestation_verification_receipt_digest"] = (
            attestation["verification_receipt_digest"]
        )
        durable_handoff = dict(durable_handoff)
        verified_handoff = (
            _verify_policy_shadow_runtime_attestation_handoff(
                conn,
                handoff_json=durable_handoff[
                    "runtime_attestation_handoff_json"
                ],
                canary_id=item["canary_id"],
                instance_id=item["instance_id"],
                boot_id=item["boot_id"],
                candidate_id=item["candidate_id"],
                stored=durable_handoff,
                require_current=True,
            )
        )
        if (
            request["runtimeAttestation"]
            != verified_handoff["handoff"]
            or request["assignment"]
            != loads(assignment["assignment_envelope_json"], None)
            or request["loadReceipt"]
            != loads(load_receipt["load_receipt_envelope_json"], None)
            or assignment["artifact_envelope_digest"]
            != artifact["artifact_envelope_digest"]
            or assignment["artifact_payload_digest"]
            != artifact["artifact_payload_digest"]
            or artifact["policy_hash"] != item["candidate_policy_hash"]
            or artifact["policy_bundle_digest"]
            != item["candidate_policy_bundle_digest"]
            or context["policy_bundle_digest"]
            != item["candidate_policy_bundle_digest"]
            or context["runtime_digest"]
            != item["runtime_executable_digest"]
            or int(assignment["candidate_policy_sequence"])
            != item["candidate_policy_sequence"]
            or int(assignment["candidate_rollback_epoch"])
            != item["candidate_rollback_epoch"]
            or assignment["predecessor_policy_hash"]
            != item["active_policy_hash"]
            or int(assignment["predecessor_policy_sequence"])
            != item["active_policy_sequence"]
            or int(assignment["predecessor_rollback_epoch"])
            != item["active_rollback_epoch"]
            or item["runtime_release_digest"]
            != durable_handoff["runtime_release_digest"]
            or item["runtime_config_digest"]
            != durable_handoff["runtime_config_digest"]
            or item["runtime_policy_digest"]
            != durable_handoff["runtime_policy_digest"]
            or item["attestation_policy_digest"]
            != durable_handoff["attestation_policy_digest"]
            or item["attestation_trust_checkpoint_digest"]
            != durable_handoff[
                "attestation_trust_checkpoint_digest"
            ]
            or item["attestation_mode"] != attestation["tee_platform"]
            or item["runtime_attestation_receipt_envelope_digest"]
            != attestation["attestation_receipt_envelope_digest"]
            or item["runtime_attestation_receipt_payload_digest"]
            != attestation["attestation_receipt_payload_digest"]
            or item["runtime_attestation_verification_receipt_digest"]
            != attestation["verification_receipt_digest"]
            or item["attestation_role_authorization_digest"]
            != durable_handoff["role_authorization_envelope_digest"]
            or item["attestation_evidence_digest"]
            != attestation["tee_evidence_digest"]
            or item["tee_measurement_digest"]
            != attestation["tee_measurement_digest"]
            or shadow_key["attestation_receipt_envelope_digest"]
            != item["runtime_attestation_receipt_envelope_digest"]
            or shadow_key["authorization_digest"]
            != durable_handoff[
                "shadow_role_key_authorization_digest"
            ]
            or item["signing_key_id"]
            != durable_handoff["shadow_signing_key_id"]
            or item["attestation_chain_digest"]
            != durable_handoff["attestation_chain_digest"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "generation publication attestation or policy binding changed"
            )
        custody_high_water, ingress_high_water = (
            _policy_shadow_generation_high_water_digests(item)
        )
        if (
            item["custody_high_water_digest"] != custody_high_water
            or item["ingress_high_water_digest"] != ingress_high_water
        ):
            raise PolicyCandidateAuthorityConflictError(
                "generation publication high-water or attestation chain is not exact"
            )
        inner_verified = _verify_policy_authority_evidence(
            conn,
            evidence_kind=
                "generation_runtime_attestation_verification",
            envelope_json=
                item["runtime_attestation_verification_envelope_json"],
            envelope_digest=evidence_projection["inner"][
                "envelope_digest"
            ],
            payload_json=
                item["runtime_attestation_verification_payload_json"],
            payload_digest=evidence_projection["inner"][
                "payload_digest"
            ],
            signature_algorithm=
                item["runtime_attestation_verifier_signature_algorithm"],
            signing_key_id=
                item["runtime_attestation_verifier_signing_key_id"],
            signature=item["runtime_attestation_verifier_signature"],
            signature_digest=
                item["runtime_attestation_verifier_signature_digest"],
            record_binding=evidence_projection["inner_payload"],
        )
        item["runtime_attestation_verifier_record_binding_digest"] = (
            inner_verified.values["record_binding_digest"]
        )
        item["rust_attestation_verification_receipt_digest"] = (
            inner_verified.values["verification_receipt_digest"]
        )
        item["management_actor_id"] = actor_id
        verified = _verify_policy_authority_evidence(
            conn,
            evidence_kind="generation_publication",
            envelope_json=
                item["generation_publication_envelope_json"],
            envelope_digest=
                item["generation_publication_envelope_digest"],
            payload_json=
                item["generation_publication_payload_json"],
            payload_digest=
                item["generation_publication_payload_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_policy_shadow_generation_signed_record(item),
        )
        _apply_policy_authority_verification(item, verified)
        key_binding = _policy_shadow_generation_publication_key_binding(
            conn,
            assignment_envelope_digest=
                item["assignment_envelope_digest"],
            member_ordinal=item["member_ordinal"],
            signing_key_id=item["signing_key_id"],
            verified_public_key_digest=
                verified.values["public_key_digest"],
        )
        if (
            key_binding["authorization_digest"]
            != shadow_key["authorization_digest"]
            or verified.values["issued_at_epoch_ns"]
            != evidence_projection["evidence"]["issuedAtUnixNanos"]
            or verified.values["expires_at_epoch_ns"]
            != evidence_projection["evidence"]["expiresAtUnixNanos"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "generation publication signer or envelope time changed"
            )
        existing_rows = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_SHADOW_GENERATION_PUBLICATION_COLUMNS
            )
            + " FROM policy_shadow_generation_publications "
            "WHERE request_id = ? OR replay_id = ? "
            "OR management_handoff_id = ? OR generation_id_digest = ? "
            "OR generation_publication_envelope_digest = ? "
            "OR generation_publication_payload_digest = ? LIMIT 2",
            (
                item["request_id"],
                item["replay_id"],
                item["management_handoff_id"],
                item["generation_id_digest"],
                item["generation_publication_envelope_digest"],
                item["generation_publication_payload_digest"],
            ),
        ).fetchall()
        if existing_rows:
            if len(existing_rows) != 1:
                raise PolicyCandidateAuthorityConflictError(
                    "generation publication identities resolve to multiple receipts"
                )
            existing = dict(existing_rows[0])
            _reverify_policy_shadow_generation_publication(
                conn, existing
            )
            exact_retry = (
                "request_id",
                "replay_id",
                "management_handoff_id",
                "request_payload_digest",
                "management_request_json",
                "generation_publication_envelope_digest",
                "generation_publication_payload_digest",
                "signature_digest",
                "signing_key_id",
                "generation_id_digest",
                "attestation_chain_digest",
            )
            if any(
                existing[field]
                != (
                    management_request_json
                    if field == "management_request_json"
                    else item[field]
                )
                for field in exact_retry
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "generation replay identity was reused for divergent bytes"
                )
            return existing
        high_water = _policy_high_water_row(conn)
        if (
            high_water is None
            or high_water["policy_id"] != artifact["policy_id"]
            or high_water["policy_hash"] != item["active_policy_hash"]
            or int(high_water["sequence"])
            != item["active_policy_sequence"]
            or int(high_water["rollback_epoch"])
            != item["active_rollback_epoch"]
            or assignment["predecessor_policy_hash"]
            != high_water["policy_hash"]
            or int(assignment["predecessor_policy_sequence"])
            != int(high_water["sequence"])
            or int(assignment["predecessor_rollback_epoch"])
            != int(high_water["rollback_epoch"])
        ):
            raise PolicyCandidateAuthorityConflictError(
                "generation publication predecessor is not current policy high-water"
            )
        transition_digest = _stage_policy_authority_transition(
            conn,
            event_type="policy.shadow_generation.published",
            entity_kind="shadow_generation_publication",
            entity_id=item["generation_id_digest"],
            entity_revision=item["publication_revision"],
            state_digest=
                item["generation_publication_payload_digest"],
            previous_state_digest=item["load_receipt_payload_digest"],
            actor_id=actor_id,
            evidence={
                "attestationChainDigest":
                    item["attestation_chain_digest"],
                "generationPublicationEnvelopeDigest":
                    item["generation_publication_envelope_digest"],
                "managementRequestDigest":
                    item["request_payload_digest"],
                "requestId": item["request_id"],
            },
            created_at_epoch_ns=
                verified.values["issued_at_epoch_ns"],
        )
        publication = {
            **{
                column: item[column]
                for column in _POLICY_SHADOW_GENERATION_PUBLICATION_COLUMNS
                if column
                not in {
                    "management_request_json",
                    "created_transition_digest",
                }
            },
            "management_request_json": management_request_json,
            "created_transition_digest": transition_digest,
        }
        _insert_immutable_candidate_row(
            conn,
            table="policy_shadow_generation_publications",
            columns=tuple(publication),
            values=publication,
            key_columns=("request_id",),
        )
    return dict(publication)


def _reverify_policy_shadow_generation_publication(
    conn: Any,
    publication: Mapping[str, Any],
) -> None:
    stored = dict(publication)
    request_json, request_digest = _candidate_authority_json(
        "persisted policy-shadow management request",
        stored["management_request_json"],
        stored["request_payload_digest"],
        maximum=8 * 1024 * 1024,
    )
    request = loads(request_json, None)
    projected = dict(stored)
    evidence = _policy_shadow_generation_evidence(projected)
    if (
        request_digest != stored["request_payload_digest"]
        or not isinstance(request, dict)
        or set(request) != _POLICY_SHADOW_GENERATION_REQUEST_FIELDS
        or request.get("apiVersion")
        != "serverware.policyShadowGenerationInstall/v2"
        or request.get("requestId") != stored["request_id"]
        or request.get("replayId") != stored["replay_id"]
        or request.get("managementHandoffId")
        != stored["management_handoff_id"]
        or not isinstance(request.get("runtimeAttestation"), dict)
        or set(request["runtimeAttestation"])
        != _POLICY_SHADOW_GENERATION_REQUEST_ATTESTATION_FIELDS
        or request["runtimeAttestation"]
        != evidence["startup_attestation"]
        or not isinstance(request.get("assignment"), dict)
        or not isinstance(request.get("loadReceipt"), dict)
        or not isinstance(request.get("activePolicyBundle"), dict)
        or not isinstance(request.get("candidatePolicyBundle"), dict)
        or _candidate_authority_sha256(
            dumps(request["activePolicyBundle"]).encode("ascii")
        )
        != stored["active_policy_bundle_digest"]
        or _candidate_authority_sha256(
            dumps(request["candidatePolicyBundle"]).encode("ascii")
        )
        != stored["candidate_policy_bundle_digest"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "persisted generation publication request is not exact"
        )
    identity_request = {
        key: value
        for key, value in request.items()
        if key not in {"replayId", "managementHandoffId"}
    }
    identities = derive_policy_shadow_generation_request_identities(
        request_id=stored["request_id"],
        actor_id=stored["management_actor_id"],
        candidate_id=stored["candidate_id"],
        canary_id=stored["canary_id"],
        instance_id=stored["instance_id"],
        boot_id=stored["boot_id"],
        assignment_envelope_digest=
            stored["assignment_envelope_digest"],
        load_receipt_envelope_digest=
            stored["load_receipt_envelope_digest"],
        active_policy_hash=stored["active_policy_hash"],
        active_policy_bundle_digest=
            stored["active_policy_bundle_digest"],
        candidate_policy_hash=stored["candidate_policy_hash"],
        candidate_policy_bundle_digest=
            stored["candidate_policy_bundle_digest"],
        runtime_attestation_chain_digest=
            stored["attestation_chain_digest"],
        request_identity_digest=_candidate_authority_sha256(
            dumps(identity_request).encode("ascii")
        ),
    )
    custody_high_water, ingress_high_water = (
        _policy_shadow_generation_high_water_digests(stored)
    )
    if (
        identities["replay_id"] != stored["replay_id"]
        or identities["management_handoff_id"]
        != stored["management_handoff_id"]
        or stored["custody_high_water_digest"]
        != custody_high_water
        or stored["ingress_high_water_digest"]
        != ingress_high_water
        or any(
            stored[column] != projected[column]
            for column in _POLICY_SHADOW_GENERATION_DERIVED_COLUMNS
            if column
            not in {
                "rust_attestation_verification_receipt_digest",
                "runtime_attestation_verifier_record_binding_digest",
            }
        )
    ):
        raise PolicyCandidateAuthorityConflictError(
            "persisted generation publication projection changed"
        )
    handoff = conn.execute(
        "SELECT "
        + _policy_authority_projection(
            _POLICY_SHADOW_RUNTIME_ATTESTATION_HANDOFF_COLUMNS
        )
        + " FROM policy_shadow_runtime_attestation_handoffs "
        "WHERE canary_id = ? AND instance_id = ? AND boot_id = ?",
        (
            stored["canary_id"],
            stored["instance_id"],
            stored["boot_id"],
        ),
    ).fetchone()
    if handoff is None:
        raise PolicyCandidateAuthorityConflictError(
            "persisted generation startup attestation is missing"
        )
    verified_handoff = _verify_policy_shadow_runtime_attestation_handoff(
        conn,
        handoff_json=handoff["runtime_attestation_handoff_json"],
        canary_id=stored["canary_id"],
        instance_id=stored["instance_id"],
        boot_id=stored["boot_id"],
        candidate_id=stored["candidate_id"],
        stored=dict(handoff),
        require_current=False,
    )
    if (
        request["runtimeAttestation"] != verified_handoff["handoff"]
        or stored["attestation_chain_digest"]
        != handoff["attestation_chain_digest"]
        or stored["runtime_attestation_verification_receipt_digest"]
        != verified_handoff["attestation"]["verification_receipt_digest"]
        or stored["runtime_attestation_verification_envelope_digest"]
        != evidence["inner"]["envelope_digest"]
        or stored["attestation_role_authorization_digest"]
        != handoff["role_authorization_envelope_digest"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "persisted generation startup attestation changed"
        )
    inner_verified = _reverify_historical_policy_static_evidence(
        conn,
        evidence_kind="generation_runtime_attestation_verification",
        envelope_json=str(
            stored["runtime_attestation_verification_envelope_json"]
        ),
        envelope_digest=evidence["inner"]["envelope_digest"],
        payload_json=str(
            stored["runtime_attestation_verification_payload_json"]
        ),
        payload_digest=evidence["inner"]["payload_digest"],
        signature_algorithm=str(
            stored[
                "runtime_attestation_verifier_signature_algorithm"
            ]
        ),
        signing_key_id=str(
            stored["runtime_attestation_verifier_signing_key_id"]
        ),
        signature=str(
            stored["runtime_attestation_verifier_signature"]
        ),
        signature_digest=str(
            stored["runtime_attestation_verifier_signature_digest"]
        ),
        record_binding=evidence["inner_payload"],
        verification_receipt_digest=str(
            stored["rust_attestation_verification_receipt_digest"]
        ),
    )
    outer_verified = _reverify_historical_policy_static_evidence(
        conn,
        evidence_kind="generation_publication",
        envelope_json=str(
            stored["generation_publication_envelope_json"]
        ),
        envelope_digest=str(
            stored["generation_publication_envelope_digest"]
        ),
        payload_json=str(
            stored["generation_publication_payload_json"]
        ),
        payload_digest=str(
            stored["generation_publication_payload_digest"]
        ),
        signature_algorithm=str(stored["signature_algorithm"]),
        signing_key_id=str(stored["signing_key_id"]),
        signature=str(stored["signature"]),
        signature_digest=str(stored["signature_digest"]),
        record_binding=
            _policy_shadow_generation_signed_record(stored),
        verification_receipt_digest=str(
            stored["verification_receipt_digest"]
        ),
    )
    key_binding = _policy_shadow_generation_publication_key_binding(
        conn,
        assignment_envelope_digest=
            stored["assignment_envelope_digest"],
        member_ordinal=int(stored["member_ordinal"]),
        signing_key_id=stored["signing_key_id"],
        verified_public_key_digest=
            outer_verified.values["public_key_digest"],
    )
    if (
        inner_verified.values["record_binding_digest"]
        != stored[
            "runtime_attestation_verifier_record_binding_digest"
        ]
        or key_binding["authorization_digest"]
        != handoff["shadow_role_key_authorization_digest"]
        or outer_verified.values["issued_at_epoch_ns"]
        != evidence["evidence"]["issuedAtUnixNanos"]
        or outer_verified.values["expires_at_epoch_ns"]
        != evidence["evidence"]["expiresAtUnixNanos"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "persisted generation signer or signed time changed"
        )


_POLICY_CANARY_CUSTODY_EVIDENCE_FIELDS = (
    "custody_evidence_envelope_digest",
    "custody_evidence_payload_digest",
    "custody_evidence_id",
    "assignment_envelope_digest",
    "assignment_payload_digest",
    "assignment_revision",
    "canary_id",
    "fleet_id",
    "membership_revision",
    "membership_root_digest",
    "member_ordinal",
    "member_id",
    "instance_id",
    "boot_id",
    "tee_measurement_digest",
    "runtime_identity_digest",
    "generation_id_digest",
    "custody_sequence",
    "previous_custody_sequence",
    "previous_custody_head_digest",
    "resulting_custody_head_digest",
    "ingress_sequence",
    "request_identity_digest",
    "request_binding_digest",
    "request_commitment_digest",
    "opening_spill_receipt_digest",
    "sampling_decision",
    "persistence_identity_digest",
    "persistence_receipt_digest",
    "immutable_retrieval_proof_digest",
    "trusted_time_epoch_ns",
    "trusted_time_checkpoint_digest",
    "custody_evidence_envelope_json",
    "custody_evidence_payload_json",
    "signature_algorithm",
    "signing_key_id",
    "signature",
    "signature_digest",
    "actor_id",
)

_POLICY_CANARY_CUSTODY_EVIDENCE_COLUMNS = tuple(
    field
    for field in _POLICY_CANARY_CUSTODY_EVIDENCE_FIELDS
    if field != "actor_id"
) + (
    "evidence_kind",
    "record_binding_digest",
    "verification_receipt_digest",
    "issued_at_epoch_ns",
    "expires_at_epoch_ns",
    "created_transition_digest",
)


def _policy_canary_custody_head_digest(
    item: Mapping[str, Any],
) -> str:
    return _policy_authority_domain_digest(
        b"serverware.policyShadowCustodyHead/v1",
        str(item["previous_custody_head_digest"]).encode("ascii"),
        dumps(
            {
                "custodyEvidenceId": item["custody_evidence_id"],
                "custodySequence": item["custody_sequence"],
                "immutableRetrievalProofSha256":
                    item["immutable_retrieval_proof_digest"],
                "ingressSequence": item["ingress_sequence"],
                "openingSpillReceiptSha256":
                    item["opening_spill_receipt_digest"],
                "persistenceIdentitySha256":
                    item["persistence_identity_digest"],
                "persistenceReceiptSha256":
                    item["persistence_receipt_digest"],
                "requestBindingSha256": item["request_binding_digest"],
                "requestCommitmentSha256":
                    item["request_commitment_digest"],
                "requestIdentitySha256": item["request_identity_digest"],
                "samplingDecision": item["sampling_decision"],
                "trustedTimeCheckpointSha256":
                    item["trusted_time_checkpoint_digest"],
                "trustedTimeUnixNanos": item["trusted_time_epoch_ns"],
            }
        ).encode("ascii"),
    )


def _reverify_policy_canary_custody_evidence(
    conn: Any,
    custody: Mapping[str, Any],
    *,
    require_current_head: bool,
) -> None:
    wire = _policy_shadow_direct_envelope_components(
        "custody evidence",
        loads(custody["custody_evidence_envelope_json"], None),
    )
    if (
        wire["envelope_digest"]
        != custody["custody_evidence_envelope_digest"]
        or wire["payload_digest"]
        != custody["custody_evidence_payload_digest"]
        or wire["payload_json"]
        != custody["custody_evidence_payload_json"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "custody evidence canonical bytes no longer match its identity"
        )
    persisted_receipt = conn.execute(
        "SELECT verification_receipt_digest, evidence_kind, "
        "assignment_envelope_digest, member_ordinal, signature_digest, "
        "record_binding_digest, envelope_digest, payload_digest "
        "FROM policy_runtime_evidence_verifications "
        "WHERE verification_receipt_digest = ? "
        "AND evidence_kind = 'custody_evidence'",
        (custody["verification_receipt_digest"],),
    ).fetchone()
    if (
        persisted_receipt is None
        or persisted_receipt["assignment_envelope_digest"]
        != custody["assignment_envelope_digest"]
        or int(persisted_receipt["member_ordinal"])
        != int(custody["member_ordinal"])
        or persisted_receipt["signature_digest"]
        != custody["signature_digest"]
        or persisted_receipt["record_binding_digest"]
        != custody["record_binding_digest"]
        or persisted_receipt["envelope_digest"]
        != custody["custody_evidence_envelope_digest"]
        or persisted_receipt["payload_digest"]
        != custody["custody_evidence_payload_digest"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "custody evidence has no exact immutable verification receipt"
        )
    signed_custody = dict(custody)
    signed_custody.pop("issued_at_epoch_ns", None)
    signed_custody.pop("expires_at_epoch_ns", None)
    signed_custody.pop("created_transition_digest", None)
    verifier = (
        _verify_policy_runtime_evidence
        if require_current_head
        else _reverify_historical_policy_runtime_evidence
    )
    verification_arguments = {
        "evidence_kind": "custody_evidence",
        "assignment_envelope_digest":
            custody["assignment_envelope_digest"],
        "member_ordinal": int(custody["member_ordinal"]),
        "canary_id": str(custody["canary_id"]),
        "fleet_id": str(custody["fleet_id"]),
        "membership_revision": int(custody["membership_revision"]),
        "instance_id": str(custody["instance_id"]),
        "boot_id": str(custody["boot_id"]),
        "envelope_json": wire["envelope_json"],
        "envelope_digest": wire["envelope_digest"],
        "payload_json": wire["payload_json"],
        "payload_digest": wire["payload_digest"],
        "signature_algorithm": wire["signature_algorithm"],
        "signing_key_id": wire["signing_key_id"],
        "signature": wire["signature"],
        "signature_digest": wire["signature_digest"],
        "record_binding": _candidate_authority_signed_record(
            signed_custody, current_prefix="custody_evidence"
        ),
    }
    if require_current_head:
        verification_arguments["persist_verification"] = False
    else:
        verification_arguments["verification_receipt_digest"] = (
            custody["verification_receipt_digest"]
        )
    verifier(
        conn,
        **verification_arguments,
    )
    if require_current_head:
        head = conn.execute(
            "SELECT custody_sequence, custody_head_digest, "
            "custody_evidence_envelope_digest, ingress_sequence "
            "FROM policy_canary_custody_heads "
            "WHERE assignment_envelope_digest = ? AND member_ordinal = ? "
            "AND canary_id = ? AND instance_id = ? AND boot_id = ? "
            "AND generation_id_digest = ?",
            (
                custody["assignment_envelope_digest"],
                custody["member_ordinal"],
                custody["canary_id"],
                custody["instance_id"],
                custody["boot_id"],
                custody["generation_id_digest"],
            ),
        ).fetchone()
        if (
            head is None
            or int(head["custody_sequence"])
            != int(custody["custody_sequence"])
            or head["custody_head_digest"]
            != custody["resulting_custody_head_digest"]
            or head["custody_evidence_envelope_digest"]
            != custody["custody_evidence_envelope_digest"]
            or int(head["ingress_sequence"])
            != int(custody["ingress_sequence"])
        ):
            raise PolicyCandidateAuthorityConflictError(
                "custody evidence is not the exact current monotonic head"
            )


def stage_policy_canary_custody_evidence(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
) -> dict[str, Any]:
    item = _candidate_authority_record(
        "canary custody evidence",
        record,
        _POLICY_CANARY_CUSTODY_EVIDENCE_FIELDS,
    )
    actor_id = _candidate_authority_text(
        "custody actor_id", item.pop("actor_id"), maximum=1024
    )
    item["custody_evidence_id"] = _candidate_authority_text(
        "custody_evidence_id", item["custody_evidence_id"], maximum=256
    )
    for field, value in tuple(item.items()):
        if field.endswith("_digest") or field.endswith("_hash"):
            item[field] = _candidate_authority_digest(field, value)
    for field, minimum in (
        ("assignment_revision", 1),
        ("membership_revision", 1),
        ("member_ordinal", 1),
        ("custody_sequence", 1),
        ("previous_custody_sequence", 0),
        ("ingress_sequence", 1),
        ("trusted_time_epoch_ns", 0),
    ):
        item[field] = _candidate_authority_int(
            field, item[field], minimum=minimum
        )
    for field in ("canary_id", "member_id", "instance_id", "boot_id"):
        _candidate_authority_text(field, item[field], maximum=256)
    if item["sampling_decision"] not in {
        "included",
        "excluded-by-assignment",
    }:
        raise PolicyCandidateAuthorityError(
            "custody sampling decision is outside the closed contract"
        )
    _candidate_authority_json(
        "custody_evidence_envelope_json",
        item["custody_evidence_envelope_json"],
        item["custody_evidence_envelope_digest"],
    )
    _candidate_authority_json(
        "custody_evidence_payload_json",
        item["custody_evidence_payload_json"],
        item["custody_evidence_payload_digest"],
    )
    _candidate_authority_signature_fields(item)
    connection_scope = (
        connect() if _connection is None else contextlib.nullcontext(_connection)
    )
    with connection_scope as conn:
        _lock_policy_candidate_authority(conn)
        context = _policy_canary_runtime_context(
            conn,
            canary_id=item["canary_id"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
        )
        _require_policy_runtime_context(
            item,
            context,
            (
                "assignment_envelope_digest",
                "assignment_payload_digest",
                "assignment_revision",
                "fleet_id",
                "membership_revision",
                "membership_root_digest",
                "member_ordinal",
                "member_id",
                "tee_measurement_digest",
                "runtime_identity_digest",
            ),
        )
        publication = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_SHADOW_GENERATION_PUBLICATION_COLUMNS
            )
            + " "
            "FROM policy_shadow_generation_publications "
            "WHERE canary_id = ? AND instance_id = ? AND boot_id = ? "
            "AND assignment_envelope_digest = ? AND member_ordinal = ?",
            (
                item["canary_id"],
                item["instance_id"],
                item["boot_id"],
                item["assignment_envelope_digest"],
                item["member_ordinal"],
            ),
        ).fetchone()
        if publication is not None:
            _reverify_policy_shadow_generation_publication(
                conn, dict(publication)
            )
        if (
            publication is None
            or publication["generation_id_digest"]
            != item["generation_id_digest"]
            or int(publication["custody_sequence"]) != 0
            or int(publication["ingress_sequence"]) != 0
        ):
            raise PolicyCandidateAuthorityConflictError(
                "custody evidence has no exact signed generation publication"
            )
        head = conn.execute(
            "SELECT custody_sequence, custody_head_digest, "
            "custody_evidence_envelope_digest, ingress_sequence "
            "FROM policy_canary_custody_heads "
            "WHERE assignment_envelope_digest = ? AND member_ordinal = ? "
            "AND canary_id = ? AND instance_id = ? AND boot_id = ? "
            "AND generation_id_digest = ?",
            (
                item["assignment_envelope_digest"],
                item["member_ordinal"],
                item["canary_id"],
                item["instance_id"],
                item["boot_id"],
                item["generation_id_digest"],
            ),
        ).fetchone()
        expected_sequence = (
            1 if head is None else int(head["custody_sequence"]) + 1
        )
        expected_previous_sequence = (
            0 if head is None else int(head["custody_sequence"])
        )
        expected_previous_head = (
            str(publication["custody_high_water_digest"])
            if head is None
            else str(head["custody_head_digest"])
        )
        if (
            item["custody_sequence"] != expected_sequence
            or item["previous_custody_sequence"]
            != expected_previous_sequence
            or item["previous_custody_head_digest"]
            != expected_previous_head
            or (
                head is not None
                and item["ingress_sequence"]
                <= int(head["ingress_sequence"])
            )
            or item["resulting_custody_head_digest"]
            != _policy_canary_custody_head_digest(item)
        ):
            raise PolicyCandidateAuthorityConflictError(
                "custody evidence is not the exact monotonic successor"
            )
        verified = _verify_policy_runtime_evidence(
            conn,
            evidence_kind="custody_evidence",
            assignment_envelope_digest=
                item["assignment_envelope_digest"],
            member_ordinal=item["member_ordinal"],
            canary_id=item["canary_id"],
            fleet_id=item["fleet_id"],
            membership_revision=item["membership_revision"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
            envelope_json=item["custody_evidence_envelope_json"],
            envelope_digest=item["custody_evidence_envelope_digest"],
            payload_json=item["custody_evidence_payload_json"],
            payload_digest=item["custody_evidence_payload_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                item, current_prefix="custody_evidence"
            ),
        )
        _apply_policy_authority_verification(item, verified)
        item["issued_at_epoch_ns"] = verified.values["issued_at_epoch_ns"]
        item["expires_at_epoch_ns"] = verified.values["expires_at_epoch_ns"]
        observation_window = loads(context["observation_window_json"], None)
        maximum_age = _candidate_authority_int(
            "custody maximum evidence age",
            observation_window["maximumEvidenceAgeNanos"],
            minimum=1,
        )
        if (
            item["trusted_time_epoch_ns"] > item["issued_at_epoch_ns"]
            or item["issued_at_epoch_ns"] - item["trusted_time_epoch_ns"]
            > maximum_age
        ):
            raise PolicyCandidateAuthorityConflictError(
                "custody trusted time is not within signed assignment bounds"
            )
        transition_digest = _stage_policy_authority_transition(
            conn,
            event_type="policy.custody_evidence.verified",
            entity_kind="custody_evidence",
            entity_id=item["custody_evidence_envelope_digest"],
            entity_revision=item["custody_sequence"],
            state_digest=item["resulting_custody_head_digest"],
            previous_state_digest=item["previous_custody_head_digest"],
            actor_id=actor_id,
            evidence={
                "immutableRetrievalProofDigest":
                    item["immutable_retrieval_proof_digest"],
                "ingressSequence": item["ingress_sequence"],
                "verificationReceiptDigest":
                    item["verification_receipt_digest"],
            },
            created_at_epoch_ns=item["issued_at_epoch_ns"],
        )
        item["created_transition_digest"] = transition_digest
        _insert_immutable_candidate_row(
            conn,
            table="policy_canary_custody_evidence",
            columns=tuple(item),
            values=item,
            key_columns=("custody_evidence_envelope_digest",),
        )
        head_values = (
            item["assignment_envelope_digest"],
            item["member_ordinal"],
            item["canary_id"],
            item["instance_id"],
            item["boot_id"],
            item["generation_id_digest"],
        )
        if head is None:
            conn.execute(
                "INSERT INTO policy_canary_custody_heads "
                "(assignment_envelope_digest, member_ordinal, canary_id, "
                "instance_id, boot_id, generation_id_digest, "
                "custody_sequence, custody_head_digest, "
                "custody_evidence_envelope_digest, ingress_sequence, "
                "updated_at_epoch_ns) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    *head_values,
                    item["custody_sequence"],
                    item["resulting_custody_head_digest"],
                    item["custody_evidence_envelope_digest"],
                    item["ingress_sequence"],
                    item["issued_at_epoch_ns"],
                ),
            )
        else:
            updated = conn.execute(
                "UPDATE policy_canary_custody_heads SET "
                "custody_sequence = ?, custody_head_digest = ?, "
                "custody_evidence_envelope_digest = ?, ingress_sequence = ?, "
                "updated_at_epoch_ns = ? "
                "WHERE assignment_envelope_digest = ? AND member_ordinal = ? "
                "AND canary_id = ? AND instance_id = ? AND boot_id = ? "
                "AND generation_id_digest = ? AND custody_sequence = ? "
                "AND custody_head_digest = ?",
                (
                    item["custody_sequence"],
                    item["resulting_custody_head_digest"],
                    item["custody_evidence_envelope_digest"],
                    item["ingress_sequence"],
                    item["issued_at_epoch_ns"],
                    *head_values,
                    head["custody_sequence"],
                    head["custody_head_digest"],
                ),
            )
            if updated.rowcount != 1:
                raise PolicyCandidateAuthorityConflictError(
                    "custody head changed during monotonic CAS append"
                )
    return dict(item)


_POLICY_CANARY_INGRESS_OBSERVATION_FIELDS = (
    "ingress_envelope_digest",
    "ingress_payload_digest",
    "assignment_envelope_digest",
    "assignment_payload_digest",
    "assignment_revision",
    "canary_id",
    "fleet_id",
    "membership_revision",
    "membership_root_digest",
    "member_ordinal",
    "member_id",
    "instance_id",
    "boot_id",
    "load_receipt_envelope_digest",
    "load_receipt_payload_digest",
    "policy_identity_digest",
    "runtime_identity_digest",
    "ingress_sequence",
    "observed_at_epoch_ns",
    "sampling_decision",
    "accounting_outcome",
    "request_commitment_digest",
    "unavailable_marker_digest",
    "custody_generation_id_digest",
    "custody_request_binding_digest",
    "custody_request_commitment_digest",
    "custody_opening_spill_receipt_digest",
    "custody_evidence_envelope_digest",
    "custody_evidence_payload_digest",
    "custody_verification_receipt_digest",
    "ingress_envelope_json",
    "ingress_payload_json",
    "signature_algorithm",
    "signing_key_id",
    "signature",
    "signature_digest",
    "actor_id",
)


def stage_policy_canary_ingress_observation(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
) -> dict[str, Any]:
    item = _candidate_authority_record(
        "canary ingress observation",
        record,
        _POLICY_CANARY_INGRESS_OBSERVATION_FIELDS,
    )
    _candidate_authority_text(
        "ingress actor_id", item.pop("actor_id"), maximum=1024
    )
    for field, value in tuple(item.items()):
        if (field.endswith("_digest") or field.endswith("_hash")) and value is not None:
            item[field] = _candidate_authority_digest(field, value)
    for field in (
        "assignment_revision",
        "membership_revision",
        "member_ordinal",
        "ingress_sequence",
    ):
        item[field] = _candidate_authority_int(field, item[field], minimum=1)
    item["observed_at_epoch_ns"] = _candidate_authority_int(
        "observed_at_epoch_ns", item["observed_at_epoch_ns"]
    )
    for field in ("canary_id", "member_id", "instance_id", "boot_id"):
        _candidate_authority_text(field, item[field], maximum=256)
    if item["sampling_decision"] not in {
        "included",
        "excluded-by-assignment",
    } or item["accounting_outcome"] not in {
        "evaluated",
        "dropped",
        "error",
        "excluded",
        "transport-excluded",
    }:
        raise PolicyCandidateAuthorityError(
            "ingress sampling or accounting class is invalid"
        )
    if (
        item["sampling_decision"] == "excluded-by-assignment"
        and (
            item["accounting_outcome"] != "excluded"
            or item["request_commitment_digest"] is None
            or item["unavailable_marker_digest"] is not None
        )
    ) or (
        item["sampling_decision"] == "included"
        and item["accounting_outcome"] == "excluded"
    ):
        raise PolicyCandidateAuthorityError(
            "ingress commitment and unavailable evidence is not exact"
        )
    _candidate_authority_json(
        "ingress_envelope_json",
        item["ingress_envelope_json"],
        item["ingress_envelope_digest"],
    )
    _candidate_authority_json(
        "ingress_payload_json",
        item["ingress_payload_json"],
        item["ingress_payload_digest"],
    )
    _candidate_authority_signature_fields(item)
    with (
        connect()
        if _connection is None
        else contextlib.nullcontext(_connection)
    ) as conn:
        _lock_policy_candidate_authority(conn)
        context = _policy_canary_runtime_context(
            conn,
            canary_id=item["canary_id"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
        )
        _require_policy_runtime_context(
            item,
            context,
            (
                "assignment_envelope_digest",
                "assignment_payload_digest",
                "assignment_revision",
                "fleet_id",
                "membership_revision",
                "membership_root_digest",
                "member_ordinal",
                "member_id",
                "load_receipt_envelope_digest",
                "load_receipt_payload_digest",
                "policy_identity_digest",
                "runtime_identity_digest",
            ),
        )
        assignment_window = conn.execute(
            "SELECT observation_window_json, observation_window_digest "
            "FROM policy_canary_assignments "
            "WHERE assignment_envelope_digest = ? "
            "AND assignment_payload_digest = ? AND canary_id = ?",
            (
                item["assignment_envelope_digest"],
                item["assignment_payload_digest"],
                item["canary_id"],
            ),
        ).fetchone()
        if assignment_window is None:
            raise PolicyCandidateAuthorityConflictError(
                "ingress observation has no exact assignment window"
            )
        _candidate_authority_json(
            "ingress assignment observation window",
            assignment_window["observation_window_json"],
            assignment_window["observation_window_digest"],
        )
        window = _candidate_authority_strict_object(
            "ingress assignment observation window",
            loads(assignment_window["observation_window_json"], None),
            frozenset(
                {
                    "startsAtUnixNanos",
                    "endsAtUnixNanos",
                    "sealDeadlineUnixNanos",
                    "minimumDurationNanos",
                    "firstIngressSequence",
                    "samplingBasisPoints",
                    "requestCommitmentKeyId",
                    "requestCommitmentKeyEpoch",
                    "maximumEvidenceAgeNanos",
                    "maximumHeartbeatGapNanos",
                }
            ),
        )
        ingress_wire = _policy_shadow_direct_envelope_components(
            "ingress observation",
            loads(item["ingress_envelope_json"], None),
        )
        if (
            ingress_wire["envelope_digest"]
            != item["ingress_envelope_digest"]
            or ingress_wire["payload_digest"]
            != item["ingress_payload_digest"]
            or ingress_wire["payload_json"] != item["ingress_payload_json"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "ingress wire and stored canonical payload are not identical"
            )
        ingress_payload = ingress_wire["payload"]
        ingress_facts = _policy_shadow_ingress_facts_state(
            "ingress observation",
            ingress_payload,
            assignment_payload_digest=item["assignment_payload_digest"],
            assignment_revision=item["assignment_revision"],
            ingress_sequence=item["ingress_sequence"],
            observed_at_epoch_ns=item["observed_at_epoch_ns"],
            observation_window=window,
        )
        payload_sampling = ingress_payload["samplingDecision"]
        accounting = ingress_payload["accountingOutcome"]
        if (
            payload_sampling not in {
                "included",
                "excluded-by-assignment",
            }
            or not isinstance(accounting, dict)
            or "status" not in accounting
        ):
            raise PolicyCandidateAuthorityConflictError(
                "ingress sampling or accounting payload is not exact"
            )
        accounting_status = accounting["status"]
        if accounting_status == "evaluated":
            accounting_exact = set(accounting) == {"status"}
            projected_accounting = "evaluated"
            accounting_unavailable = None
        elif accounting_status in {"dropped", "error"}:
            accounting_exact = (
                set(accounting)
                == {"status", "reason", "unavailableMarkerSha256"}
            )
            projected_accounting = accounting_status
            accounting_unavailable = _candidate_authority_digest(
                "ingress accounting unavailable marker",
                accounting.get("unavailableMarkerSha256"),
            )
        elif accounting_status == "excluded":
            accounting_exact = (
                set(accounting) == {"status", "reason"}
                and accounting.get("reason")
                == "deterministic-assignment-sampling"
            )
            projected_accounting = "excluded"
            accounting_unavailable = None
        elif accounting_status == "transport-excluded":
            accounting_exact = set(accounting) == {"status"}
            projected_accounting = "transport-excluded"
            accounting_unavailable = None
        else:
            accounting_exact = False
            projected_accounting = ""
            accounting_unavailable = None
        facts_unavailable = ingress_facts["unavailable_marker_digest"]
        if (
            not accounting_exact
            or item["sampling_decision"] != payload_sampling
            or item["accounting_outcome"] != projected_accounting
            or item["request_commitment_digest"]
            != ingress_facts["request_commitment_digest"]
            or item["unavailable_marker_digest"]
            != (accounting_unavailable or facts_unavailable)
            or (
                accounting_unavailable is not None
                and facts_unavailable is not None
                and accounting_unavailable != facts_unavailable
            )
            or (
                ingress_facts["state"] == "captured"
                and payload_sampling
                != ingress_facts["sampling_decision"]
            )
            or (
                payload_sampling == "excluded-by-assignment"
                and projected_accounting != "excluded"
            )
            or (
                projected_accounting == "excluded"
                and payload_sampling != "excluded-by-assignment"
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "ingress projections differ from the signed policy-shadow "
                "request commitment"
            )
        custody_reference_fields = (
            "custody_generation_id_digest",
            "custody_request_binding_digest",
            "custody_request_commitment_digest",
            "custody_opening_spill_receipt_digest",
            "custody_evidence_envelope_digest",
            "custody_evidence_payload_digest",
            "custody_verification_receipt_digest",
        )
        if ingress_facts["state"] == "captured":
            if any(
                item[field] is None for field in custody_reference_fields
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "captured ingress facts require direct verified custody "
                    "evidence"
                )
            custody = conn.execute(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_CANARY_CUSTODY_EVIDENCE_COLUMNS
                )
                + " FROM policy_canary_custody_evidence "
                "WHERE custody_evidence_envelope_digest = ? "
                "AND custody_evidence_payload_digest = ? "
                "AND verification_receipt_digest = ?",
                (
                    item["custody_evidence_envelope_digest"],
                    item["custody_evidence_payload_digest"],
                    item["custody_verification_receipt_digest"],
                ),
            ).fetchone()
            custody_exact = {
                "assignment_envelope_digest":
                    item["assignment_envelope_digest"],
                "assignment_payload_digest":
                    item["assignment_payload_digest"],
                "assignment_revision": item["assignment_revision"],
                "canary_id": item["canary_id"],
                "fleet_id": item["fleet_id"],
                "membership_revision": item["membership_revision"],
                "membership_root_digest":
                    item["membership_root_digest"],
                "member_ordinal": item["member_ordinal"],
                "member_id": item["member_id"],
                "instance_id": item["instance_id"],
                "boot_id": item["boot_id"],
                "runtime_identity_digest":
                    item["runtime_identity_digest"],
                "generation_id_digest":
                    item["custody_generation_id_digest"],
                "ingress_sequence": item["ingress_sequence"],
                "request_binding_digest":
                    item["custody_request_binding_digest"],
                "request_commitment_digest":
                    item["request_commitment_digest"],
                "opening_spill_receipt_digest":
                    item["custody_opening_spill_receipt_digest"],
                "sampling_decision": item["sampling_decision"],
                "trusted_time_epoch_ns": item["observed_at_epoch_ns"],
            }
            if (
                custody is None
                or item["custody_request_commitment_digest"]
                != item["request_commitment_digest"]
                or any(
                    custody[field] != value
                    for field, value in custody_exact.items()
                )
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "custody evidence does not bind the exact signed ingress "
                    "request, sampling decision, and immutable retrieval proof"
                )
            _reverify_policy_canary_custody_evidence(
                conn, dict(custody), require_current_head=True
            )
        else:
            if any(
                item[field] is not None for field in custody_reference_fields
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "unavailable ingress facts cannot carry custody authority"
                )
        first_ingress_sequence = _candidate_authority_int(
            "ingress assignment first sequence",
            window["firstIngressSequence"],
            minimum=1,
        )
        if not (
            int(window["startsAtUnixNanos"])
            <= item["observed_at_epoch_ns"]
            < int(window["endsAtUnixNanos"])
        ):
            raise PolicyCandidateAuthorityConflictError(
                "ingress observation is outside the signed assignment window"
            )
        instance_head = conn.execute(
            "SELECT status FROM policy_canary_instance_heads "
            "WHERE canary_id = ? AND instance_id = ? AND boot_id = ?",
            (item["canary_id"], item["instance_id"], item["boot_id"]),
        ).fetchone()
        if (
            instance_head is None
            or instance_head["status"] != "observing"
        ):
            raise PolicyCandidateAuthorityConflictError(
                "ingress observation requires an observing instance"
            )
        previous = conn.execute(
            "SELECT ingress_sequence, observed_at_epoch_ns "
            "FROM policy_canary_ingress_observations "
            "WHERE canary_id = ? AND instance_id = ? AND boot_id = ? "
            "ORDER BY ingress_sequence DESC LIMIT 1",
            (item["canary_id"], item["instance_id"], item["boot_id"]),
        ).fetchone()
        expected_sequence = (
            first_ingress_sequence
            if previous is None
            else int(previous["ingress_sequence"]) + 1
        )
        if (
            item["ingress_sequence"] != expected_sequence
            or (
                previous is not None
                and item["observed_at_epoch_ns"]
                < int(previous["observed_at_epoch_ns"])
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "ingress observation is not the exact next sequence"
            )
        verified = _verify_policy_runtime_evidence(
            conn,
            evidence_kind="ingress_observation",
            assignment_envelope_digest=item["assignment_envelope_digest"],
            member_ordinal=item["member_ordinal"],
            canary_id=item["canary_id"],
            fleet_id=item["fleet_id"],
            membership_revision=item["membership_revision"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
            envelope_json=item["ingress_envelope_json"],
            envelope_digest=item["ingress_envelope_digest"],
            payload_json=item["ingress_payload_json"],
            payload_digest=item["ingress_payload_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                item, current_prefix="ingress"
            ),
        )
        _apply_policy_authority_verification(item, verified)
        item["issued_at_epoch_ns"] = verified.values["issued_at_epoch_ns"]
        item["expires_at_epoch_ns"] = verified.values["expires_at_epoch_ns"]
        if item["observed_at_epoch_ns"] > item["issued_at_epoch_ns"]:
            raise PolicyCandidateAuthorityConflictError(
                "ingress observation was signed before it was observed"
            )
        _insert_immutable_candidate_row(
            conn,
            table="policy_canary_ingress_observations",
            columns=tuple(item),
            values=item,
            key_columns=("ingress_envelope_digest",),
        )
    return dict(item)


