def stage_policy_canary_active_decision(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
) -> dict[str, Any]:
    item = _candidate_authority_record(
        "canary active decision",
        record,
        _POLICY_CANARY_ACTIVE_DECISION_FIELDS,
    )
    _candidate_authority_text(
        "active-decision actor_id", item.pop("actor_id"), maximum=1024
    )
    for field, value in tuple(item.items()):
        if (field.endswith("_digest") or field.endswith("_hash")) and value is not None:
            item[field] = _candidate_authority_digest(field, value)
    for field in (
        "assignment_revision",
        "membership_revision",
        "member_ordinal",
        "ingress_sequence",
    ):
        item[field] = _candidate_authority_int(field, item[field], minimum=1)
    item["captured_at_epoch_ns"] = _candidate_authority_int(
        "captured_at_epoch_ns", item["captured_at_epoch_ns"]
    )
    item["decision_at_epoch_ns"] = _candidate_authority_int(
        "decision_at_epoch_ns", item["decision_at_epoch_ns"]
    )
    if item["returned_http_status"] is not None:
        item["returned_http_status"] = _candidate_authority_int(
            "returned_http_status",
            item["returned_http_status"],
            minimum=100,
            maximum=599,
        )
    if item["decision_status"] not in {"evaluated", "unavailable"}:
        raise PolicyCandidateAuthorityError(
            "active decision status is invalid"
        )
    if item["active_outcome"] not in _POLICY_AUTHORITY_OUTCOMES:
        raise PolicyCandidateAuthorityError(
            "active decision outcome is invalid"
        )
    if item["final_active_outcome"] not in {
        "allow",
        "deny",
        "conditional",
        "error",
    }:
        raise PolicyCandidateAuthorityError(
            "final active enforcement outcome is invalid"
        )
    item["upstream_dispatch_authorized"] = _candidate_authority_int(
        "upstream_dispatch_authorized",
        item["upstream_dispatch_authorized"],
        maximum=1,
    )
    if (
        item["decision_status"] == "evaluated"
        and (
            item["active_evaluation_digest"] is None
            or item["active_unavailable_reason"] is not None
            or item["active_unavailable_marker_digest"] is not None
            or item["returned_http_status"] is None
            or item["active_dispatch_commitment_digest"] is None
        )
    ) or (
        item["decision_status"] == "unavailable"
        and (
            item["active_outcome"] != "indeterminate"
            or item["active_evaluation_digest"] is not None
            or item["active_unavailable_reason"]
            not in _POLICY_AUTHORITY_ERROR_REASONS
            or item["active_unavailable_marker_digest"] is None
            or item["final_active_outcome"] != "error"
            or item["returned_http_status"] is not None
            or item["upstream_dispatch_authorized"] != 0
            or item["active_dispatch_commitment_digest"] is not None
        )
    ) or (
        item["final_active_outcome"] != "allow"
        and item["upstream_dispatch_authorized"] != 0
    ):
        raise PolicyCandidateAuthorityError(
            "active decision evaluation evidence is not exact"
        )
    _candidate_authority_json(
        "active_decision_envelope_json",
        item["active_decision_envelope_json"],
        item["active_decision_envelope_digest"],
    )
    _candidate_authority_json(
        "active_decision_payload_json",
        item["active_decision_payload_json"],
        item["active_decision_payload_digest"],
    )
    _candidate_authority_signature_fields(item)
    active_wire = _policy_shadow_direct_envelope_components(
        "active decision",
        loads(item["active_decision_envelope_json"], None),
    )
    active_payload = active_wire["payload"]
    active_result = active_payload["result"]
    if (
        active_wire["envelope_digest"]
        != item["active_decision_envelope_digest"]
        or active_wire["payload_digest"]
        != item["active_decision_payload_digest"]
        or active_wire["payload_json"] != item["active_decision_payload_json"]
        or active_payload["generationId"] != item["generation_id_digest"]
        or active_payload["capturedAtUnixNanos"]
        != item["captured_at_epoch_ns"]
        or active_payload["decisionAtUnixNanos"]
        != item["decision_at_epoch_ns"]
        or not isinstance(active_result, dict)
    ):
        raise PolicyCandidateAuthorityConflictError(
            "active-decision wire and stored projection are not identical"
        )
    if active_result.get("status") == "finalized":
        pure_evaluation = _candidate_authority_strict_object(
            "active pure evaluation",
            active_result["pureActiveEvaluation"],
            frozenset(
                {
                    "outcome",
                    "policyPlan",
                    "policyPlanSha256",
                    "reasonSetSha256",
                    "obligationsSha256",
                    "effectIntentsSha256",
                    "dispatchCommitmentSha256",
                    "effectRequirements",
                    "evaluationNanos",
                }
            ),
        )
        effect_resolution = _candidate_authority_strict_object(
            "active effect resolution",
            active_result["effectResolution"],
            frozenset(
                {
                    "finalizationBindingSha256",
                    "resolvedEffectIntentsSha256",
                    "effectRequirements",
                    "terminalEvidence",
                    "effectResultCommitmentsRootSha256",
                    "finalOutcome",
                    "returnedHttpStatus",
                    "upstreamDispatchAuthorized",
                    "finalizedAtUnixNanos",
                }
            ),
        )
        expected_evaluation_digest = _candidate_authority_sha256(
            dumps(pure_evaluation).encode("ascii")
        )
        active_result_exact = (
            set(active_result)
            == {"status", "pureActiveEvaluation", "effectResolution"}
            and item["decision_status"] == "evaluated"
            and pure_evaluation["outcome"] == item["active_outcome"]
            and expected_evaluation_digest
            == item["active_evaluation_digest"]
            and pure_evaluation["dispatchCommitmentSha256"]
            == item["active_dispatch_commitment_digest"]
            and effect_resolution["finalOutcome"]
            == item["final_active_outcome"]
            and effect_resolution["returnedHttpStatus"]
            == item["returned_http_status"]
            and int(bool(
                effect_resolution["upstreamDispatchAuthorized"]
            )) == item["upstream_dispatch_authorized"]
            and effect_resolution["finalizedAtUnixNanos"]
            == item["decision_at_epoch_ns"]
        )
    elif active_result.get("status") == "unavailable":
        active_result_exact = (
            set(active_result)
            == {"status", "reason", "unavailableMarkerSha256"}
            and item["decision_status"] == "unavailable"
            and active_result["reason"]
            == item["active_unavailable_reason"]
            and active_result["unavailableMarkerSha256"]
            == item["active_unavailable_marker_digest"]
        )
    else:
        active_result_exact = False
    if not active_result_exact:
        raise PolicyCandidateAuthorityConflictError(
            "active-decision result differs from the signed direct result"
        )
    with (
        connect()
        if _connection is None
        else contextlib.nullcontext(_connection)
    ) as conn:
        _lock_policy_candidate_authority(conn)
        context = _policy_canary_runtime_context(
            conn,
            canary_id=item["canary_id"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
        )
        _require_policy_runtime_context(
            item,
            context,
            (
                "assignment_envelope_digest",
                "assignment_payload_digest",
                "assignment_revision",
                "fleet_id",
                "membership_revision",
                "membership_root_digest",
                "member_ordinal",
                "member_id",
                "load_receipt_envelope_digest",
                "load_receipt_payload_digest",
                "policy_identity_digest",
                "runtime_identity_digest",
            ),
        )
        instance_head = conn.execute(
            "SELECT status FROM policy_canary_instance_heads "
            "WHERE canary_id = ? AND instance_id = ? AND boot_id = ?",
            (item["canary_id"], item["instance_id"], item["boot_id"]),
        ).fetchone()
        if (
            instance_head is None
            or instance_head["status"] != "observing"
        ):
            raise PolicyCandidateAuthorityConflictError(
                "active decision requires an observing instance"
            )
        ingress = conn.execute(
            "SELECT ingress_envelope_digest, ingress_payload_digest, "
            "ingress_sequence, accounting_outcome, "
            "custody_evidence_envelope_digest, "
            "custody_verification_receipt_digest "
            "FROM policy_canary_ingress_observations "
            "WHERE canary_id = ? AND instance_id = ? AND boot_id = ? "
            "AND ingress_sequence = ?",
            (
                item["canary_id"],
                item["instance_id"],
                item["boot_id"],
                item["ingress_sequence"],
            ),
        ).fetchone()
        if (
            ingress is None
            or ingress["ingress_envelope_digest"]
            != item["ingress_envelope_digest"]
            or ingress["ingress_payload_digest"]
            != item["ingress_payload_digest"]
            or ingress["custody_evidence_envelope_digest"]
            != item["custody_evidence_envelope_digest"]
            or ingress["custody_verification_receipt_digest"]
            != item["custody_verification_receipt_digest"]
            or (
                ingress["accounting_outcome"] == "evaluated"
            ) != (item["decision_status"] == "evaluated")
        ):
            raise PolicyCandidateAuthorityConflictError(
                "active decision does not bind the exact ingress outcome"
            )
        if item["custody_evidence_envelope_digest"] is not None:
            custody = conn.execute(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_CANARY_CUSTODY_EVIDENCE_COLUMNS
                )
                + " FROM policy_canary_custody_evidence "
                "WHERE custody_evidence_envelope_digest = ? "
                "AND verification_receipt_digest = ?",
                (
                    item["custody_evidence_envelope_digest"],
                    item["custody_verification_receipt_digest"],
                ),
            ).fetchone()
            if custody is None:
                raise PolicyCandidateAuthorityConflictError(
                    "active decision has no exact custody authority"
                )
            _reverify_policy_canary_custody_evidence(
                conn, dict(custody), require_current_head=False
            )
        elif item["custody_verification_receipt_digest"] is not None:
            raise PolicyCandidateAuthorityConflictError(
                "active decision custody reference is incomplete"
            )
        verified = _verify_policy_runtime_evidence(
            conn,
            evidence_kind="active_decision",
            assignment_envelope_digest=item["assignment_envelope_digest"],
            member_ordinal=item["member_ordinal"],
            canary_id=item["canary_id"],
            fleet_id=item["fleet_id"],
            membership_revision=item["membership_revision"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
            envelope_json=item["active_decision_envelope_json"],
            envelope_digest=item["active_decision_envelope_digest"],
            payload_json=item["active_decision_payload_json"],
            payload_digest=item["active_decision_payload_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                item, current_prefix="active_decision"
            ),
        )
        _apply_policy_authority_verification(item, verified)
        item["issued_at_epoch_ns"] = verified.values["issued_at_epoch_ns"]
        item["expires_at_epoch_ns"] = verified.values["expires_at_epoch_ns"]
        _insert_immutable_candidate_row(
            conn,
            table="policy_canary_active_decisions",
            columns=tuple(item),
            values=item,
            key_columns=("active_decision_envelope_digest",),
        )
    return dict(item)


