def stage_policy_canary_shadow_observation(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
) -> dict[str, Any]:
    item = _candidate_authority_record(
        "canary shadow observation",
        record,
        _POLICY_CANARY_SHADOW_OBSERVATION_FIELDS,
    )
    _candidate_authority_text(
        "shadow actor_id", item.pop("actor_id"), maximum=1024
    )
    for field, value in tuple(item.items()):
        if (field.endswith("_digest") or field.endswith("_hash")) and value is not None:
            item[field] = _candidate_authority_digest(field, value)
    for field in (
        "assignment_revision",
        "membership_revision",
        "member_ordinal",
        "observation_sequence",
        "ingress_sequence",
    ):
        item[field] = _candidate_authority_int(field, item[field], minimum=1)
    if (
        item["observation_status"]
        not in {
            "evaluated",
            "dropped",
            "error",
            "excluded",
            "transport-excluded",
        }
        or item["active_outcome"] not in _POLICY_AUTHORITY_OUTCOMES
        or item["candidate_outcome"] not in _POLICY_AUTHORITY_OUTCOMES
    ):
        raise PolicyCandidateAuthorityError(
            "shadow observation classification is invalid"
        )
    for json_field, digest_field, maximum in (
        ("authority_binding_json", "authority_binding_digest", 1024 * 1024),
        (
            "expansion_cells_json",
            "expansion_cells_digest",
            _POLICY_AUTHORITY_MAX_CANONICAL_AGGREGATE_BYTES,
        ),
        ("pilot_membership_json", "pilot_membership_digest", 1024 * 1024),
        (
            "response_obligation_json",
            "response_obligation_digest",
            1024 * 1024,
        ),
        (
            "response_comparison_json",
            "response_comparison_digest",
            _POLICY_AUTHORITY_MAX_CANONICAL_AGGREGATE_BYTES,
        ),
        ("latency_samples_json", "latency_samples_digest", 1024 * 1024),
    ):
        _candidate_authority_json(
            json_field,
            item[json_field],
            item[digest_field],
            maximum=maximum,
        )
    authority_value = loads(item["authority_binding_json"], None)
    authority_binding = (
        None
        if authority_value is None
        else _policy_authority_observed_binding(
            "observed authority binding", authority_value
        )
    )
    expansion_cells = _policy_authority_semantic_expansion_cells(
        "observed expansion cells",
        loads(item["expansion_cells_json"], None),
        maximum=128,
        allow_empty=True,
    )
    pilot_membership = _policy_authority_pilot_membership(
        "observed pilot membership",
        loads(item["pilot_membership_json"], None),
        authority_binding=authority_binding,
        expansion_cells=expansion_cells,
    )
    response_obligation = _policy_authority_response_obligation(
        "observed response obligation",
        loads(item["response_obligation_json"], None),
    )
    response_comparison = loads(item["response_comparison_json"], None)
    latency_wire = _candidate_authority_strict_object(
        "latency samples",
        loads(item["latency_samples_json"], None),
        frozenset(_POLICY_AUTHORITY_LATENCY_SAMPLE_FIELDS.values()),
    )
    latency_samples = {
        series: latency_wire[field]
        for series, field
        in _POLICY_AUTHORITY_LATENCY_SAMPLE_FIELDS.items()
    }
    for series in _POLICY_AUTHORITY_LATENCY_SERIES:
        sample = latency_samples[series]
        if sample is not None:
            _candidate_authority_int(f"{series} latency", sample)
    evaluated = item["observation_status"] == "evaluated"
    if evaluated:
        if (
            authority_binding is None
            or response_comparison is None
            or item["candidate_dispatch_commitment_digest"] is None
            or any(
                latency_samples[series] is None
                for series in (
                    "factsCapture",
                    "activeEvaluation",
                    "candidateEvaluation",
                    "shadowTotal",
                )
            )
            or any(
                sample is not None
                and sample > latency_samples["shadowTotal"]
                for sample in latency_samples.values()
            )
        ):
            raise PolicyCandidateAuthorityError(
                "evaluated shadow latency and authority evidence is incomplete"
            )
        if any(
            cell["routeSha256"] != authority_binding["routeSha256"]
            or cell["operation"] != authority_binding["operation"]
            or cell["compiledSemanticProfileSha256"]
            != authority_binding["compiledSemanticProfileSha256"]
            or cell["requestAuthorityClass"]
            != authority_binding["requestAuthorityClass"]
            or cell["activeOutcome"] != item["active_outcome"]
            or cell["candidateOutcome"] != item["candidate_outcome"]
            for cell in expansion_cells
        ):
            raise PolicyCandidateAuthorityError(
                "observed expansion cells do not bind exact request semantics"
            )
        if (
            response_obligation is not None
            and response_obligation["routeSha256"]
            != authority_binding["routeSha256"]
        ):
            raise PolicyCandidateAuthorityError(
                "response obligation does not bind the observed route"
            )
    elif (
        authority_binding is not None
        or expansion_cells
        or pilot_membership is not None
        or response_obligation is not None
        or response_comparison is not None
        or item["candidate_dispatch_commitment_digest"] is not None
        or item["candidate_outcome"] != "indeterminate"
    ):
        raise PolicyCandidateAuthorityError(
            "non-evaluated shadow evidence carries evaluated authority"
        )
    if (
        item["observation_status"] in {"excluded", "transport-excluded"}
        and any(sample is not None for sample in latency_samples.values())
    ) or (
        item["observation_status"] in {"dropped", "error"}
        and (
            (
                latency_samples["shadowTotal"] is None
                and any(
                    sample is not None
                    for series, sample in latency_samples.items()
                    if series != "shadowTotal"
                )
            )
            or (
                latency_samples["shadowTotal"] is not None
                and any(
                    sample is not None
                    and sample > latency_samples["shadowTotal"]
                    for sample in latency_samples.values()
                )
            )
        )
    ):
        raise PolicyCandidateAuthorityError(
            "failure latency availability is not exact"
        )
    if (
        evaluated
        and (
            item["drop_reason"] is not None
            or item["error_reason"] is not None
        )
    ) or (
        item["observation_status"] == "dropped"
        and (
            item["drop_reason"] is None
            or item["error_reason"] is not None
            or item["candidate_outcome"] != "indeterminate"
        )
    ) or (
        item["observation_status"] == "error"
        and (
            item["error_reason"] is None
            or item["drop_reason"] is not None
            or item["candidate_outcome"] != "indeterminate"
        )
    ) or (
        item["observation_status"] in {"excluded", "transport-excluded"}
        and (
            item["drop_reason"] is not None
            or item["error_reason"] is not None
            or item["candidate_outcome"] != "indeterminate"
        )
    ):
        raise PolicyCandidateAuthorityError(
            "shadow failure and evaluation fields are not exact"
        )
    item["route_id"] = (
        None
        if authority_binding is None
        else authority_binding["routeSha256"]
    )
    item["operation_class"] = (
        None if authority_binding is None else authority_binding["operation"]
    )
    item["request_authority_class"] = (
        None
        if authority_binding is None
        else authority_binding["requestAuthorityClass"]
    )
    item["response_obligation_route_id"] = (
        None
        if response_obligation is None
        else response_obligation["routeSha256"]
    )
    item["response_obligation_root_digest"] = (
        None
        if response_obligation is None
        else response_obligation["obligationRootSha256"]
    )
    for reason_field in ("drop_reason", "error_reason"):
        if item[reason_field] is not None:
            item[reason_field] = _candidate_authority_text(
                reason_field, item[reason_field], maximum=1024
            )
    if (
        item["drop_reason"] is not None
        and item["drop_reason"] not in _POLICY_AUTHORITY_DROP_REASONS
    ) or (
        item["error_reason"] is not None
        and item["error_reason"] not in _POLICY_AUTHORITY_ERROR_REASONS
    ):
        raise PolicyCandidateAuthorityError(
            "shadow failure reason is outside the closed contract"
        )
    _candidate_authority_json(
        "shadow_observation_envelope_json",
        item["shadow_observation_envelope_json"],
        item["shadow_observation_envelope_digest"],
    )
    _candidate_authority_json(
        "shadow_observation_payload_json",
        item["shadow_observation_payload_json"],
        item["shadow_observation_payload_digest"],
        maximum=4 * 1024 * 1024,
    )
    _candidate_authority_signature_fields(item)
    with (
        connect()
        if _connection is None
        else contextlib.nullcontext(_connection)
    ) as conn:
        _lock_policy_candidate_authority(conn)
        context = _policy_canary_runtime_context(
            conn,
            canary_id=item["canary_id"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
        )
        _require_policy_runtime_context(
            item,
            context,
            (
                "assignment_envelope_digest",
                "assignment_payload_digest",
                "assignment_revision",
                "fleet_id",
                "membership_revision",
                "membership_root_digest",
                "member_ordinal",
                "member_id",
                "load_receipt_envelope_digest",
                "load_receipt_payload_digest",
                "policy_identity_digest",
                "runtime_identity_digest",
            ),
        )
        ingress = conn.execute(
            "SELECT ingress_envelope_digest, ingress_payload_digest, "
            "ingress_envelope_json, ingress_payload_json, "
            "observed_at_epoch_ns, accounting_outcome, "
            "request_commitment_digest, "
            "custody_generation_id_digest, "
            "custody_request_binding_digest, "
            "custody_request_commitment_digest, "
            "custody_opening_spill_receipt_digest, "
            "custody_evidence_envelope_digest, "
            "custody_verification_receipt_digest "
            "FROM policy_canary_ingress_observations "
            "WHERE canary_id = ? AND instance_id = ? AND boot_id = ? "
            "AND ingress_sequence = ?",
            (
                item["canary_id"],
                item["instance_id"],
                item["boot_id"],
                item["ingress_sequence"],
            ),
        ).fetchone()
        active = conn.execute(
            "SELECT active_decision_envelope_digest, "
            "active_decision_payload_digest, decision_status, active_outcome, "
            "final_active_outcome, upstream_dispatch_authorized, "
            "active_dispatch_commitment_digest, "
            "generation_id_digest, custody_evidence_envelope_digest, "
            "custody_verification_receipt_digest, "
            "active_decision_envelope_json, active_decision_payload_json "
            "FROM policy_canary_active_decisions WHERE canary_id = ? "
            "AND instance_id = ? AND boot_id = ? AND ingress_sequence = ?",
            (
                item["canary_id"],
                item["instance_id"],
                item["boot_id"],
                item["ingress_sequence"],
            ),
        ).fetchone()
        assignment_contract = conn.execute(
            "SELECT expected_snapshots_json, expected_snapshots_digest, "
            "response_obligations_json, "
            "response_obligations_json_digest, "
            "response_obligations_digest, "
            "observation_window_json, observation_window_digest "
            "FROM policy_canary_assignments "
            "WHERE assignment_envelope_digest = ? "
            "AND assignment_payload_digest = ? AND canary_id = ?",
            (
                item["assignment_envelope_digest"],
                item["assignment_payload_digest"],
                item["canary_id"],
            ),
        ).fetchone()
        compiler = conn.execute(
            "SELECT analysis_envelope_digest, analysis_payload_digest, "
            "assignment_envelope_digest, assignment_payload_digest, "
            "canary_id, route_authority_root_digest, "
            "operation_authority_root_digest, analysis_mode, "
            "expansion_cells_json, expansion_cells_digest, "
            "pilot_restrictions_json, pilot_restrictions_digest, "
            "issued_at_epoch_ns, expires_at_epoch_ns "
            "FROM policy_compiler_authority_analyses "
            "WHERE analysis_envelope_digest = ? "
            "AND analysis_payload_digest = ?",
            (
                item["compiler_analysis_envelope_digest"],
                item["compiler_analysis_payload_digest"],
            ),
        ).fetchone()
        if assignment_contract is None:
            raise PolicyCandidateAuthorityConflictError(
                "shadow observation has no exact assignment contract"
            )
        _candidate_authority_json(
            "shadow assignment observation window",
            assignment_contract["observation_window_json"],
            assignment_contract["observation_window_digest"],
        )
        observation_window = _candidate_authority_strict_object(
            "shadow assignment observation window",
            loads(assignment_contract["observation_window_json"], None),
            frozenset(
                {
                    "startsAtUnixNanos",
                    "endsAtUnixNanos",
                    "sealDeadlineUnixNanos",
                    "minimumDurationNanos",
                    "firstIngressSequence",
                    "samplingBasisPoints",
                    "requestCommitmentKeyId",
                    "requestCommitmentKeyEpoch",
                    "maximumEvidenceAgeNanos",
                    "maximumHeartbeatGapNanos",
                }
            ),
        )
        first_ingress_sequence = _candidate_authority_int(
            "shadow assignment first ingress sequence",
            observation_window["firstIngressSequence"],
            minimum=1,
        )
        instance_head = conn.execute(
            "SELECT status FROM policy_canary_instance_heads "
            "WHERE canary_id = ? AND instance_id = ? AND boot_id = ?",
            (item["canary_id"], item["instance_id"], item["boot_id"]),
        ).fetchone()
        previous = conn.execute(
            "SELECT shadow.observation_sequence, "
            "shadow.ingress_sequence, "
            "shadow.shadow_observation_envelope_digest, "
            "ingress.observed_at_epoch_ns "
            "FROM policy_canary_shadow_observations AS shadow "
            "JOIN policy_canary_ingress_observations AS ingress "
            "ON ingress.ingress_envelope_digest = "
            "shadow.ingress_envelope_digest "
            "AND ingress.ingress_payload_digest = "
            "shadow.ingress_payload_digest "
            "WHERE shadow.canary_id = ? "
            "AND shadow.instance_id = ? AND shadow.boot_id = ? "
            "ORDER BY shadow.observation_sequence DESC LIMIT 1",
            (item["canary_id"], item["instance_id"], item["boot_id"]),
        ).fetchone()
        expected_sequence = 1 if previous is None else int(
            previous["observation_sequence"]
        ) + 1
        expected_previous = (
            None
            if previous is None
            else previous["shadow_observation_envelope_digest"]
        )
        expected_ingress_sequence = (
            first_ingress_sequence
            if previous is None
            else int(previous["ingress_sequence"]) + 1
        )
        if (
            ingress is None
            or active is None
            or compiler is None
            or instance_head is None
            or instance_head["status"] != "observing"
            or item["observation_sequence"] != expected_sequence
            or item["ingress_sequence"] != expected_ingress_sequence
            or (
                previous is not None
                and int(ingress["observed_at_epoch_ns"])
                < int(previous["observed_at_epoch_ns"])
            )
            or item["previous_observation_envelope_digest"]
            != expected_previous
            or item["ingress_envelope_digest"]
            != ingress["ingress_envelope_digest"]
            or item["ingress_payload_digest"]
            != ingress["ingress_payload_digest"]
            or item["active_decision_envelope_digest"]
            != active["active_decision_envelope_digest"]
            or item["active_decision_payload_digest"]
            != active["active_decision_payload_digest"]
            or item["custody_evidence_envelope_digest"]
            != ingress["custody_evidence_envelope_digest"]
            or item["custody_verification_receipt_digest"]
            != ingress["custody_verification_receipt_digest"]
            or item["custody_evidence_envelope_digest"]
            != active["custody_evidence_envelope_digest"]
            or item["custody_verification_receipt_digest"]
            != active["custody_verification_receipt_digest"]
            or item["observation_status"] != ingress["accounting_outcome"]
            or item["active_outcome"] != active["active_outcome"]
            or (
                item["observation_status"] == "evaluated"
            ) != (active["decision_status"] == "evaluated")
            or compiler["assignment_envelope_digest"]
            != item["assignment_envelope_digest"]
            or compiler["assignment_payload_digest"]
            != item["assignment_payload_digest"]
            or compiler["canary_id"] != item["canary_id"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "shadow observation does not bind its exact independent prefix"
            )
        shadow_wire = _policy_shadow_direct_envelope_components(
            "shadow observation",
            loads(item["shadow_observation_envelope_json"], None),
        )
        if (
            shadow_wire["envelope_digest"]
            != item["shadow_observation_envelope_digest"]
            or shadow_wire["payload_digest"]
            != item["shadow_observation_payload_digest"]
            or shadow_wire["payload_json"]
            != item["shadow_observation_payload_json"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "shadow observation wire and stored payload are not identical"
            )
        shadow_payload = shadow_wire["payload"]
        nested_ingress = _policy_shadow_direct_envelope_components(
            "shadow nested ingress", shadow_payload["ingressEvidence"]
        )
        nested_active = _policy_shadow_direct_envelope_components(
            "shadow nested active decision",
            shadow_payload["activeDecision"],
        )
        if (
            shadow_payload["ingressEvidenceSha256"]
            != item["ingress_envelope_digest"]
            or shadow_payload["activeDecisionSha256"]
            != item["active_decision_envelope_digest"]
            or nested_ingress["envelope_digest"]
            != ingress["ingress_envelope_digest"]
            or nested_ingress["payload_digest"]
            != ingress["ingress_payload_digest"]
            or nested_ingress["envelope_json"]
            != ingress["ingress_envelope_json"]
            or nested_ingress["payload_json"]
            != ingress["ingress_payload_json"]
            or nested_active["envelope_digest"]
            != active["active_decision_envelope_digest"]
            or nested_active["payload_digest"]
            != active["active_decision_payload_digest"]
            or nested_active["envelope_json"]
            != active["active_decision_envelope_json"]
            or nested_active["payload_json"]
            != active["active_decision_payload_json"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "shadow observation embeds different ingress or active evidence"
            )
        result = shadow_payload["result"]
        if not isinstance(result, dict) or result.get("status") is None:
            raise PolicyCandidateAuthorityConflictError(
                "shadow observation result is not an exact tagged object"
            )
        result_status = result["status"]
        if result_status == "evaluated":
            expected_result_fields = {
                "status",
                "pureActiveEvaluation",
                "finalActiveEnforcement",
                "candidateEvaluation",
                "authorityBinding",
                "derivedExpansion",
                "pilotMembership",
                "responseObligation",
                "responseComparison",
                "latencySamples",
            }
            active_evaluation = result["pureActiveEvaluation"]
            final_enforcement = result["finalActiveEnforcement"]
            candidate_evaluation = result["candidateEvaluation"]
            derived_expansion = _candidate_authority_strict_object(
                "shadow direct derived expansion",
                result["derivedExpansion"],
                frozenset({"cells", "cellsRootSha256"}),
            )
            direct_cells = _policy_authority_semantic_expansion_cells(
                "shadow direct derived expansion cells",
                derived_expansion["cells"],
                maximum=_POLICY_AUTHORITY_MAX_EXPANSION_CELLS,
                allow_empty=True,
            )
            direct_cell_root = _policy_shadow_merkle_root(
                [
                    (index, cell["cellSha256"])
                    for index, cell in enumerate(direct_cells, start=1)
                ]
            )
            direct_material_exact = (
                set(result) == expected_result_fields
                and isinstance(active_evaluation, dict)
                and isinstance(final_enforcement, dict)
                and isinstance(candidate_evaluation, dict)
                and active_evaluation.get("outcome")
                == item["active_outcome"]
                and candidate_evaluation.get("outcome")
                == item["candidate_outcome"]
                and active_evaluation.get("dispatchCommitmentSha256")
                == active["active_dispatch_commitment_digest"]
                and candidate_evaluation.get("dispatchCommitmentSha256")
                == item["candidate_dispatch_commitment_digest"]
                and final_enforcement.get("finalOutcome")
                == active["final_active_outcome"]
                and int(bool(
                    final_enforcement.get("upstreamDispatchAuthorized")
                ))
                == int(active["upstream_dispatch_authorized"])
                and derived_expansion["cellsRootSha256"]
                == direct_cell_root
                and dumps(result["authorityBinding"])
                == item["authority_binding_json"]
                and dumps(direct_cells) == item["expansion_cells_json"]
                and dumps(result["pilotMembership"])
                == item["pilot_membership_json"]
                and dumps(result["responseObligation"])
                == item["response_obligation_json"]
                and dumps(result["responseComparison"])
                == item["response_comparison_json"]
                and dumps(result["latencySamples"])
                == item["latency_samples_json"]
            )
        elif result_status in {"dropped", "error"}:
            expected_result_fields = {
                "status",
                "reason",
                "unavailableMarkerSha256",
                "latencySamples",
            }
            direct_material_exact = (
                set(result) == expected_result_fields
                and result_status == item["observation_status"]
                and result["reason"]
                == item[
                    "drop_reason"
                    if result_status == "dropped"
                    else "error_reason"
                ]
                and dumps(result["latencySamples"])
                == item["latency_samples_json"]
            )
        elif result_status == "excluded":
            direct_material_exact = (
                set(result) == {"status", "reason"}
                and result["reason"]
                == "deterministic-assignment-sampling"
                and item["observation_status"] == "excluded"
            )
        elif result_status == "transport-excluded":
            direct_material_exact = (
                set(result) == {"status"}
                and item["observation_status"] == "transport-excluded"
            )
        else:
            direct_material_exact = False
        if not direct_material_exact:
            raise PolicyCandidateAuthorityConflictError(
                "shadow DB projections differ from the direct signed result"
            )
        if ingress["request_commitment_digest"] is not None:
            if (
                ingress["custody_generation_id_digest"]
                != active["generation_id_digest"]
                or ingress["custody_request_binding_digest"] is None
                or ingress["custody_request_commitment_digest"]
                != ingress["request_commitment_digest"]
                or ingress["custody_opening_spill_receipt_digest"] is None
                or ingress["custody_evidence_envelope_digest"] is None
                or ingress["custody_verification_receipt_digest"] is None
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "shadow observation does not bind exact verified custody"
                )
            custody = conn.execute(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_CANARY_CUSTODY_EVIDENCE_COLUMNS
                )
                + " FROM policy_canary_custody_evidence "
                "WHERE custody_evidence_envelope_digest = ? "
                "AND verification_receipt_digest = ?",
                (
                    ingress["custody_evidence_envelope_digest"],
                    ingress["custody_verification_receipt_digest"],
                ),
            ).fetchone()
            if (
                custody is None
                or custody["generation_id_digest"]
                != active["generation_id_digest"]
                or custody["request_commitment_digest"]
                != ingress["request_commitment_digest"]
                or custody["request_binding_digest"]
                != ingress["custody_request_binding_digest"]
                or custody["opening_spill_receipt_digest"]
                != ingress["custody_opening_spill_receipt_digest"]
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "shadow observation resolved different custody authority"
                )
            _reverify_policy_canary_custody_evidence(
                conn, dict(custody), require_current_head=False
            )
        elif any(
            ingress[field] is not None
            for field in (
                "custody_generation_id_digest",
                "custody_request_binding_digest",
                "custody_request_commitment_digest",
                "custody_opening_spill_receipt_digest",
                "custody_evidence_envelope_digest",
                "custody_verification_receipt_digest",
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "unavailable shadow ingress carries custody authority"
            )
        for json_field, digest_field in (
            ("expected_snapshots_json", "expected_snapshots_digest"),
            (
                "response_obligations_json",
                "response_obligations_json_digest",
            ),
        ):
            _candidate_authority_json(
                f"assigned {json_field}",
                assignment_contract[json_field],
                assignment_contract[digest_field],
            )
        snapshots = loads(
            assignment_contract["expected_snapshots_json"], None
        )
        _candidate_authority_strict_object(
            "assigned snapshots",
            snapshots,
            frozenset({"active", "candidate", "requestFactsSchemaSha256"}),
        )
        for snapshot_name in ("active", "candidate"):
            if not isinstance(snapshots[snapshot_name], dict):
                raise PolicyCandidateAuthorityConflictError(
                    "assigned policy snapshot is not an exact object"
                )
        _candidate_authority_json(
            "compiler expansion cells",
            compiler["expansion_cells_json"],
            compiler["expansion_cells_digest"],
            maximum=_POLICY_AUTHORITY_MAX_CANONICAL_AGGREGATE_BYTES,
        )
        compiler_entries = loads(compiler["expansion_cells_json"], None)
        if not isinstance(compiler_entries, list):
            raise PolicyCandidateAuthorityConflictError(
                "compiler expansion authority is not a bounded list"
            )
        authorized_cells: dict[str, dict[str, Any]] = {}
        previous_compiler_cell = ""
        for compiler_index, raw_entry in enumerate(compiler_entries):
            cell = _policy_authority_semantic_expansion_cell(
                f"compiler expansion entry {compiler_index}",
                raw_entry,
            )
            digest = cell["cellSha256"]
            if (
                digest <= previous_compiler_cell
                or cell["routeAuthorityRootSha256"]
                != compiler["route_authority_root_digest"]
                or cell["operationAuthorityRootSha256"]
                != compiler["operation_authority_root_digest"]
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "compiler expansion entry is not exact authority"
                )
            previous_compiler_cell = digest
            authorized_cells[digest] = cell
        observed_transition = (
            item["active_outcome"],
            item["candidate_outcome"],
        )
        if compiler["analysis_mode"] == "no-expansion":
            if (
                expansion_cells
                or authorized_cells
                or (
                    evaluated
                    and observed_transition
                    in _POLICY_AUTHORITY_EXPANDING_TRANSITIONS
                )
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "NoExpansion compiler authority cannot stage expansion"
                )
        elif compiler["analysis_mode"] == "approved-expansion":
            for cell in expansion_cells:
                authorized = authorized_cells.get(cell["cellSha256"])
                if authorized is None or authorized != cell:
                    raise PolicyCandidateAuthorityConflictError(
                        "observed expansion is outside exact compiler authority"
                    )
            if (
                evaluated
                and observed_transition
                in _POLICY_AUTHORITY_EXPANDING_TRANSITIONS
                and not expansion_cells
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "expanding observation has no exact compiler-signed cell"
                )
        else:
            raise PolicyCandidateAuthorityConflictError(
                "compiler analysis mode is invalid"
            )
        expected_observed_cells = (
            []
            if authority_binding is None
            else [
                authorized_cells[digest]
                for digest in sorted(authorized_cells)
                if authorized_cells[digest]["routeSha256"]
                == authority_binding["routeSha256"]
                and authorized_cells[digest]["operation"]
                == authority_binding["operation"]
                and authorized_cells[digest][
                    "compiledSemanticProfileSha256"
                ]
                == authority_binding["compiledSemanticProfileSha256"]
                and authorized_cells[digest][
                    "requestAuthorityClass"
                ]
                == authority_binding["requestAuthorityClass"]
                and authorized_cells[digest]["activeOutcome"]
                == item["active_outcome"]
                and authorized_cells[digest]["candidateOutcome"]
                == item["candidate_outcome"]
            ]
        )
        if expansion_cells != expected_observed_cells:
            raise PolicyCandidateAuthorityConflictError(
                "observed expansion set is not the exact compiler-derived set"
            )
        obligations = loads(
            assignment_contract["response_obligations_json"], None
        )
        if not isinstance(obligations, list):
            raise PolicyCandidateAuthorityConflictError(
                "assigned response obligations are not a list"
            )
        obligation_by_route = {
            obligation["routeSha256"]: obligation
            for obligation in obligations
        }
        assigned_obligation = (
            None
            if authority_binding is None
            else obligation_by_route.get(authority_binding["routeSha256"])
        )
        if (
            assigned_obligation is None
            and response_obligation is not None
        ) or (
            assigned_obligation is not None
            and (
                response_obligation is None
                or response_obligation["obligationRootSha256"]
                != assigned_obligation["obligationRootSha256"]
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "response obligation is not the exact assigned route contract"
            )
        if evaluated:
            response_comparison = _policy_authority_response_comparison(
                "observed response comparison",
                response_comparison,
                obligation=response_obligation,
                active_snapshot_digest=
                    snapshots["active"]["compiledSnapshotSha256"],
                candidate_snapshot_digest=
                    snapshots["candidate"]["compiledSnapshotSha256"],
                final_active_outcome=active["final_active_outcome"],
                upstream_dispatch_authorized=int(
                    active["upstream_dispatch_authorized"]
                ),
                active_dispatch_commitment_digest=
                    active["active_dispatch_commitment_digest"],
                candidate_dispatch_commitment_digest=
                    item["candidate_dispatch_commitment_digest"],
                candidate_outcome=item["candidate_outcome"],
            )
            item["response_comparison_class"] = response_comparison[
                "classification"
            ]
            item["response_capture_mode"] = response_comparison[
                "captureMode"
            ]
        else:
            item["response_comparison_class"] = None
            item["response_capture_mode"] = None
        verified = _verify_policy_runtime_evidence(
            conn,
            evidence_kind="shadow_observation",
            assignment_envelope_digest=item["assignment_envelope_digest"],
            member_ordinal=item["member_ordinal"],
            canary_id=item["canary_id"],
            fleet_id=item["fleet_id"],
            membership_revision=item["membership_revision"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
            envelope_json=item["shadow_observation_envelope_json"],
            envelope_digest=item["shadow_observation_envelope_digest"],
            payload_json=item["shadow_observation_payload_json"],
            payload_digest=item["shadow_observation_payload_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                item, current_prefix="shadow_observation"
            ),
        )
        _apply_policy_authority_verification(item, verified)
        item["issued_at_epoch_ns"] = verified.values["issued_at_epoch_ns"]
        item["expires_at_epoch_ns"] = verified.values["expires_at_epoch_ns"]
        _candidate_authority_json(
            "compiler pilot restrictions",
            compiler["pilot_restrictions_json"],
            compiler["pilot_restrictions_digest"],
        )
        pilot_restrictions = _candidate_authority_strict_object(
            "compiler pilot restrictions",
            loads(compiler["pilot_restrictions_json"], None),
            (
                frozenset({"mode"})
                if compiler["analysis_mode"] == "no-expansion"
                else frozenset(
                    {
                        "mode",
                        "principalSetRootSha256",
                        "routeSetRootSha256",
                        "maximumRequests",
                        "maximumDurationNanos",
                        "maximumWriteRequests",
                        "cells",
                    }
                )
            ),
        )
        if (
            (
                compiler["analysis_mode"] == "no-expansion"
                and pilot_restrictions != {"mode": "not-applicable"}
            )
            or (
                compiler["analysis_mode"] == "approved-expansion"
                and (
                    pilot_restrictions["mode"] != "constrained"
                    or pilot_restrictions["cells"]
                    != [
                        authorized_cells[digest]
                        for digest in sorted(authorized_cells)
                    ]
                )
            )
            or
            item["issued_at_epoch_ns"] < int(compiler["issued_at_epoch_ns"])
            or item["expires_at_epoch_ns"]
            > int(compiler["expires_at_epoch_ns"])
        ):
            raise PolicyCandidateAuthorityConflictError(
                "shadow evidence is outside current signed compiler authority"
            )
        _insert_immutable_candidate_row(
            conn,
            table="policy_canary_shadow_observations",
            columns=tuple(item),
            values=item,
            key_columns=("shadow_observation_envelope_digest",),
        )
    return dict(item)


_POLICY_CANARY_INSTANCE_REVISION_FIELDS = (
    "canary_id",
    "fleet_id",
    "membership_revision",
    "membership_root_digest",
    "member_ordinal",
    "member_id",
    "instance_id",
    "boot_id",
    "assignment_envelope_digest",
    "assignment_payload_digest",
    "revision",
    "status",
    "previous_revision",
    "previous_status",
    "previous_state_digest",
    "load_receipt_envelope_digest",
    "load_receipt_payload_digest",
    "checkpoint_sequence",
    "checkpoint_envelope_digest",
    "checkpoint_payload_digest",
    "state_envelope_json",
    "state_payload_json",
    "state_digest",
    "signature_algorithm",
    "signing_key_id",
    "signature",
    "signature_digest",
    "created_at_epoch_ns",
    "sealed_at_epoch_ns",
    "terminal_from_status",
    "terminal_at_epoch_ns",
    "actor_id",
    "event_type",
)


def append_policy_canary_instance_revision(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
) -> dict[str, Any]:
    item = _candidate_authority_record(
        "canary instance revision",
        record,
        _POLICY_CANARY_INSTANCE_REVISION_FIELDS,
    )
    actor_id = _candidate_authority_text(
        "actor_id", item.pop("actor_id"), maximum=1024
    )
    event_type = _candidate_authority_text(
        "event_type", item.pop("event_type"), maximum=256
    )
    for field in ("canary_id", "member_id", "instance_id", "boot_id"):
        _candidate_authority_text(field, item[field], maximum=256)
    for field in ("revision", "membership_revision", "member_ordinal"):
        item[field] = _candidate_authority_int(
            field, item[field], minimum=1
        )
    status = _candidate_authority_text("status", item["status"], maximum=32)
    if (
        status
        not in set(_POLICY_CANARY_INSTANCE_TRANSITIONS)
        | _POLICY_CANARY_INSTANCE_TERMINAL_STATUSES
    ):
        raise PolicyCandidateAuthorityError(
            "canary instance revision status is invalid"
        )
    for field in (
        "previous_state_digest",
        "load_receipt_envelope_digest",
        "load_receipt_payload_digest",
        "checkpoint_envelope_digest",
        "checkpoint_payload_digest",
    ):
        if item[field] is not None:
            item[field] = _candidate_authority_digest(field, item[field])
    item["state_digest"] = _candidate_authority_digest(
        "state_digest", item["state_digest"]
    )
    _candidate_authority_json(
        "state_payload_json", item["state_payload_json"], item["state_digest"]
    )
    _candidate_authority_canonical_json(
        "state_envelope_json", item["state_envelope_json"]
    )
    _candidate_authority_signature_fields(item)
    for field in (
        "created_at_epoch_ns",
        "sealed_at_epoch_ns",
        "terminal_at_epoch_ns",
    ):
        if item[field] is not None:
            item[field] = _candidate_authority_int(field, item[field])
    if item["checkpoint_sequence"] is not None:
        item["checkpoint_sequence"] = _candidate_authority_int(
            "checkpoint_sequence", item["checkpoint_sequence"], minimum=1
        )

    identity = (item["canary_id"], item["instance_id"], item["boot_id"])
    entity_id = "/".join(identity)
    connection_scope = (
        connect() if _connection is None else contextlib.nullcontext(_connection)
    )
    with connection_scope as conn:
        _lock_policy_candidate_authority(conn)
        context = _policy_canary_runtime_context(
            conn,
            canary_id=item["canary_id"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
            require_load_receipt=status != "assigned",
        )
        _require_policy_runtime_context(
            item,
            context,
            (
                "fleet_id",
                "membership_revision",
                "membership_root_digest",
                "member_ordinal",
                "member_id",
                "assignment_envelope_digest",
                "assignment_payload_digest",
            ),
        )
        instance = conn.execute(
            "SELECT instance.canary_id, instance.instance_id, "
            "instance.boot_id, receipt.load_receipt_envelope_digest, "
            "receipt.load_receipt_payload_digest "
            "FROM policy_canary_instances AS instance "
            "LEFT JOIN policy_canary_load_receipts AS receipt "
            "ON receipt.canary_id = instance.canary_id "
            "AND receipt.instance_id = instance.instance_id "
            "AND receipt.boot_id = instance.boot_id "
            "WHERE instance.canary_id = ? AND instance.instance_id = ? "
            "AND instance.boot_id = ?",
            identity,
        ).fetchone()
        if instance is None or (
            item["load_receipt_envelope_digest"] is not None
            and (
                instance["load_receipt_envelope_digest"]
                != item["load_receipt_envelope_digest"]
                or instance["load_receipt_payload_digest"]
                != item["load_receipt_payload_digest"]
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "instance revision does not bind the immutable instance/load receipt"
            )
        state_envelope_digest = _candidate_authority_sha256(
            item["state_envelope_json"].encode("ascii")
        )
        verified = _verify_policy_runtime_evidence(
            conn,
            evidence_kind="canary_instance_state",
            assignment_envelope_digest=item["assignment_envelope_digest"],
            member_ordinal=item["member_ordinal"],
            canary_id=item["canary_id"],
            fleet_id=item["fleet_id"],
            membership_revision=item["membership_revision"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
            envelope_json=item["state_envelope_json"],
            envelope_digest=state_envelope_digest,
            payload_json=item["state_payload_json"],
            payload_digest=item["state_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                {**item, "actor_id": actor_id, "event_type": event_type},
                current_prefix="state",
            ),
        )
        _apply_policy_authority_verification(item, verified)
        head = conn.execute(
            "SELECT canary_id, instance_id, boot_id, head_revision, "
            "head_state_digest, status, updated_at_epoch_ns "
            "FROM policy_canary_instance_heads "
            "WHERE canary_id = ? AND instance_id = ? AND boot_id = ?",
            identity,
        ).fetchone()
        if head is None:
            if (
                item["revision"] != 1
                or status != "assigned"
                or item["previous_revision"] is not None
                or item["previous_status"] is not None
                or item["previous_state_digest"] is not None
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "first instance revision must be assigned revision one"
                )
        else:
            if (
                item["revision"] != int(head["head_revision"]) + 1
                or item["previous_revision"] != int(head["head_revision"])
                or item["previous_status"] != str(head["status"])
                or item["previous_state_digest"] != str(head["head_state_digest"])
                or status
                not in _POLICY_CANARY_INSTANCE_TRANSITIONS.get(
                    str(head["status"]), frozenset()
                )
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "instance revision is not the exact next legal CAS transition"
                )
        terminal = status in _POLICY_CANARY_INSTANCE_TERMINAL_STATUSES
        if (
            terminal
            and (
                item["terminal_from_status"] != item["previous_status"]
                or item["terminal_at_epoch_ns"] is None
            )
        ) or (
            not terminal
            and (
                item["terminal_from_status"] is not None
                or item["terminal_at_epoch_ns"] is not None
            )
        ):
            raise PolicyCandidateAuthorityError(
                "instance terminal evidence is not exact"
            )
        if status in {"sealing", "sealed"}:
            if (
                item["sealed_at_epoch_ns"] is None
                or item["sealed_at_epoch_ns"] < item["created_at_epoch_ns"]
            ):
                raise PolicyCandidateAuthorityError(
                    "instance sealing timestamp is missing or out of order"
                )
            checkpoint_head = conn.execute(
                "SELECT canary_id, instance_id, boot_id, "
                "checkpoint_sequence, checkpoint_envelope_digest, "
                "checkpoint_payload_digest, observation_root_digest, "
                "request_sequence_end, observation_sequence_end, sealed, "
                "sealed_at_epoch_ns, updated_at_epoch_ns "
                "FROM policy_canary_checkpoint_heads "
                "WHERE canary_id = ? AND instance_id = ? AND boot_id = ?",
                identity,
            ).fetchone()
            if (
                checkpoint_head is None
                or item["checkpoint_sequence"]
                != int(checkpoint_head["checkpoint_sequence"])
                or item["checkpoint_envelope_digest"]
                != checkpoint_head["checkpoint_envelope_digest"]
                or item["checkpoint_payload_digest"]
                != checkpoint_head["checkpoint_payload_digest"]
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "instance seal does not bind the exact checkpoint head"
                )
            if status == "sealing":
                sealed = conn.execute(
                    "UPDATE policy_canary_checkpoint_heads SET sealed = 1, "
                    "sealed_at_epoch_ns = ?, updated_at_epoch_ns = ? "
                    "WHERE canary_id = ? AND instance_id = ? AND boot_id = ? "
                    "AND sealed = 0 AND checkpoint_sequence = ? "
                    "AND checkpoint_envelope_digest = ? "
                    "AND checkpoint_payload_digest = ?",
                    (
                        item["sealed_at_epoch_ns"],
                        item["created_at_epoch_ns"],
                        *identity,
                        item["checkpoint_sequence"],
                        item["checkpoint_envelope_digest"],
                        item["checkpoint_payload_digest"],
                    ),
                )
                if sealed.rowcount != 1:
                    raise PolicyCandidateAuthorityConflictError(
                        "checkpoint head was already sealed or changed"
                    )
            elif not bool(checkpoint_head["sealed"]):
                raise PolicyCandidateAuthorityConflictError(
                    "sealed instance requires a sealed checkpoint head"
                )
        transition_digest = _stage_policy_authority_transition(
            conn,
            event_type=event_type,
            entity_kind="canary_instance",
            entity_id=entity_id,
            entity_revision=item["revision"],
            state_digest=item["state_digest"],
            previous_state_digest=item["previous_state_digest"],
            actor_id=actor_id,
            evidence={
                "status": status,
                "loadReceiptPayloadDigest": item["load_receipt_payload_digest"],
                "checkpointPayloadDigest": item["checkpoint_payload_digest"],
            },
            created_at_epoch_ns=item["created_at_epoch_ns"],
        )
        revision = {
            **item,
            "transition_digest": transition_digest,
            "transition_entity_kind": "canary_instance",
            "transition_entity_id": entity_id,
            "transition_event_type": event_type,
        }
        _insert_immutable_candidate_row(
            conn,
            table="policy_canary_instance_revisions",
            columns=tuple(revision),
            values=revision,
            key_columns=("canary_id", "instance_id", "boot_id", "revision"),
        )
        if head is None:
            conn.execute(
                "INSERT INTO policy_canary_instance_heads "
                "(canary_id, instance_id, boot_id, head_revision, "
                "head_state_digest, status, updated_at_epoch_ns) "
                "VALUES (?, ?, ?, ?, ?, ?, ?)",
                (*identity, item["revision"], item["state_digest"], status,
                 item["created_at_epoch_ns"]),
            )
        else:
            updated = conn.execute(
                "UPDATE policy_canary_instance_heads SET head_revision = ?, "
                "head_state_digest = ?, status = ?, updated_at_epoch_ns = ? "
                "WHERE canary_id = ? AND instance_id = ? AND boot_id = ? "
                "AND head_revision = ? AND head_state_digest = ? AND status = ?",
                (
                    item["revision"], item["state_digest"], status,
                    item["created_at_epoch_ns"], *identity,
                    head["head_revision"], head["head_state_digest"],
                    head["status"],
                ),
            )
            if updated.rowcount != 1:
                raise PolicyCandidateAuthorityConflictError(
                    "instance head changed during CAS transition"
                )
    return dict(revision)


def _policy_canary_checkpoint_snapshot_values(
    *,
    aggregate: Mapping[str, Any],
    sequence_end: int,
    observation_window: Mapping[str, Any],
    first_ingress_sequence: int,
    first_observation_envelope_digest: str,
    last_observation_envelope_digest: str,
    first_observed_at_epoch_ns: int,
    last_observed_at_epoch_ns: int,
    verified_evidence_bytes: int,
    verification_work_units: int,
    lane_gaps: int,
    observation_root: str,
    ingress_root: str,
    active_root: str,
    custody_evidence_root: str,
    custody_verification_root: str,
    principal_root: str,
    route_root: str,
) -> dict[str, Any]:
    direct_counters = _policy_authority_direct_cumulative_counters(
        aggregate
    )
    canonical_values: dict[str, tuple[str, str]] = {}
    for label, field, value in (
        ("checkpoint aggregate counters", "aggregate_counters", direct_counters),
        (
            "checkpoint semantic matrix",
            "semantic_matrix",
            aggregate["semanticMatrix"],
        ),
        (
            "checkpoint expansion cells",
            "expansion_cells",
            direct_counters["expansionCells"],
        ),
        (
            "checkpoint route coverage",
            "response_route_coverage",
            direct_counters["responseRouteCoverage"],
        ),
        (
            "checkpoint latency histograms",
            "latency_histograms",
            direct_counters["latencyHistograms"],
        ),
        (
            "checkpoint drop counters",
            "drop_counters",
            direct_counters["drops"],
        ),
        (
            "checkpoint error counters",
            "error_counters",
            direct_counters["errors"],
        ),
    ):
        canonical_values[field] = _candidate_authority_canonical_value(
            label, value
        )
    indeterminate_count = sum(
        count
        for cell, count in aggregate["semanticMatrix"].items()
        if "indeterminate" in cell
    )
    values = {
        "observation_count": sequence_end,
        "assignment_window_started_at_epoch_ns": int(
            observation_window["startsAtUnixNanos"]
        ),
        "assignment_window_ended_at_epoch_ns": int(
            observation_window["endsAtUnixNanos"]
        ),
        "assignment_seal_deadline_epoch_ns": int(
            observation_window["sealDeadlineUnixNanos"]
        ),
        "first_observation_envelope_digest":
            first_observation_envelope_digest,
        "last_observation_envelope_digest":
            last_observation_envelope_digest,
        "first_observed_at_epoch_ns": first_observed_at_epoch_ns,
        "last_observed_at_epoch_ns": last_observed_at_epoch_ns,
        "ingress_count": sequence_end,
        "verified_evidence_bytes": verified_evidence_bytes,
        "verification_work_units": verification_work_units,
        "ingress_sequence_start": first_ingress_sequence,
        "ingress_sequence_end": first_ingress_sequence + sequence_end - 1,
        "observation_sequence_end": sequence_end,
        "cumulative_observation_root_digest": observation_root,
        "cumulative_ingress_root_digest": ingress_root,
        "cumulative_active_decision_root_digest": active_root,
        "cumulative_custody_evidence_root_digest":
            custody_evidence_root,
        "cumulative_custody_verification_root_digest":
            custody_verification_root,
        "cumulative_principal_authority_root_digest": principal_root,
        "cumulative_route_authority_root_digest": route_root,
        "aggregate_counters_json":
            canonical_values["aggregate_counters"][0],
        "aggregate_counters_digest":
            canonical_values["aggregate_counters"][1],
        "semantic_matrix_json": canonical_values["semantic_matrix"][0],
        "semantic_matrix_digest": canonical_values["semantic_matrix"][1],
        "expansion_cells_json": canonical_values["expansion_cells"][0],
        "expansion_cells_digest":
            canonical_values["expansion_cells"][1],
        "response_route_coverage_json":
            canonical_values["response_route_coverage"][0],
        "response_route_coverage_digest":
            canonical_values["response_route_coverage"][1],
        "latency_histograms_json":
            canonical_values["latency_histograms"][0],
        "latency_histograms_digest":
            canonical_values["latency_histograms"][1],
        "drop_counters_json": canonical_values["drop_counters"][0],
        "drop_counters_digest": canonical_values["drop_counters"][1],
        "error_counters_json": canonical_values["error_counters"][0],
        "error_counters_digest": canonical_values["error_counters"][1],
        "excluded_count": int(aggregate["totals"]["excluded"]),
        "gap_count": lane_gaps,
        "indeterminate_count": indeterminate_count,
        "response_divergence_count": int(
            aggregate["responseClasses"][
                "comparable-validation-divergence"
            ]
        ),
        "response_validator_unavailable_count": int(
            aggregate["totals"]["responseValidatorUnavailable"]
        ),
        "observed_request_count": sequence_end,
        "evaluated_request_count": int(aggregate["totals"]["evaluated"]),
        "dropped_request_count": int(aggregate["totals"]["dropped"]),
        "evaluation_error_count": int(aggregate["totals"]["errors"]),
        "excluded_request_count": int(aggregate["totals"]["excluded"]),
        "active_permit_count": sum(
            count
            for cell, count in aggregate["semanticMatrix"].items()
            if cell.startswith("permit:")
        ),
        "active_deny_count": sum(
            count
            for cell, count in aggregate["semanticMatrix"].items()
            if cell.startswith("deny:")
        ),
        "active_conditional_count": sum(
            count
            for cell, count in aggregate["semanticMatrix"].items()
            if cell.startswith("conditional:")
        ),
        "active_indeterminate_count": sum(
            count
            for cell, count in aggregate["semanticMatrix"].items()
            if cell.startswith("indeterminate:")
        ),
        "candidate_permit_count": sum(
            count
            for cell, count in aggregate["semanticMatrix"].items()
            if cell.endswith(":permit")
        ),
        "candidate_deny_count": sum(
            count
            for cell, count in aggregate["semanticMatrix"].items()
            if cell.endswith(":deny")
        ),
        "candidate_conditional_count": sum(
            count
            for cell, count in aggregate["semanticMatrix"].items()
            if cell.endswith(":conditional")
        ),
        "candidate_indeterminate_count": sum(
            count
            for cell, count in aggregate["semanticMatrix"].items()
            if cell.endswith(":indeterminate")
        ),
    }
    contract_material = {
        key: values[key]
        for key in (
            "observation_count",
            "first_observation_envelope_digest",
            "last_observation_envelope_digest",
            "first_observed_at_epoch_ns",
            "last_observed_at_epoch_ns",
            "ingress_count",
            "verified_evidence_bytes",
            "verification_work_units",
            "ingress_sequence_start",
            "ingress_sequence_end",
            "observation_sequence_end",
            "cumulative_observation_root_digest",
            "cumulative_ingress_root_digest",
            "cumulative_active_decision_root_digest",
            "cumulative_custody_evidence_root_digest",
            "cumulative_custody_verification_root_digest",
            "cumulative_principal_authority_root_digest",
            "cumulative_route_authority_root_digest",
            "aggregate_counters_digest",
            "semantic_matrix_digest",
            "expansion_cells_digest",
            "response_route_coverage_digest",
            "latency_histograms_digest",
            "drop_counters_digest",
            "error_counters_digest",
            "excluded_count",
            "gap_count",
            "indeterminate_count",
            "response_divergence_count",
            "response_validator_unavailable_count",
        )
    }
    values["aggregate_contract_digest"] = _policy_authority_domain_digest(
        b"serverware.policyShadowCheckpointAggregate/v1",
        dumps(contract_material).encode("ascii"),
    )
    return values


def _recompute_policy_canary_checkpoint_aggregate(
    conn: Any,
    *,
    canary_id: str,
    instance_id: str,
    boot_id: str,
    sequence_end: int,
    checkpoint_assertions: Mapping[int, Mapping[str, Any]] | None = None,
    historical: bool = False,
) -> dict[str, Any]:
    sequence_end = _candidate_authority_int(
        "checkpoint observation sequence end",
        sequence_end,
        minimum=1,
        maximum=_POLICY_AUTHORITY_MAX_OBSERVATIONS_PER_MEMBER,
    )
    assertions = dict(checkpoint_assertions or {})
    if any(
        not isinstance(boundary, int)
        or isinstance(boundary, bool)
        or boundary < 1
        or boundary > sequence_end
        for boundary in assertions
    ):
        raise PolicyCandidateAuthorityConflictError(
            "checkpoint assertion boundaries are outside the sealed prefix"
        )
    verified_assertion_boundaries: set[int] = set()
    contracts = conn.execute(
        "SELECT assignment.assignment_payload_digest, "
        "assignment.assignment_revision, "
        "assignment.expected_snapshots_json, "
        "assignment.expected_snapshots_digest, "
        "assignment.response_obligations_json, "
        "assignment.response_obligations_json_digest, "
        "assignment.response_obligations_digest, "
        "assignment.observation_window_json, "
        "assignment.observation_window_digest, "
        "compiler.analysis_envelope_digest, "
        "compiler.analysis_payload_digest, compiler.analysis_mode, "
        "compiler.route_authority_root_digest, "
        "compiler.operation_authority_root_digest, "
        "compiler.expansion_cells_json, compiler.expansion_cells_digest, "
        "compiler.pilot_restrictions_json, "
        "compiler.pilot_restrictions_digest "
        "FROM policy_canary_assignments AS assignment "
        "JOIN policy_compiler_authority_analyses AS compiler "
        "ON compiler.assignment_envelope_digest = "
        "assignment.assignment_envelope_digest "
        "AND compiler.assignment_payload_digest = "
        "assignment.assignment_payload_digest "
        "WHERE assignment.canary_id = ? "
        "ORDER BY compiler.analysis_envelope_digest LIMIT 2",
        (canary_id,),
    ).fetchall()
    if len(contracts) != 1:
        raise PolicyCandidateAuthorityConflictError(
            "checkpoint does not resolve one exact compiler contract"
        )
    contract = contracts[0]
    for json_field, digest_field in (
        ("expected_snapshots_json", "expected_snapshots_digest"),
        (
            "response_obligations_json",
            "response_obligations_json_digest",
        ),
        ("observation_window_json", "observation_window_digest"),
        ("expansion_cells_json", "expansion_cells_digest"),
        ("pilot_restrictions_json", "pilot_restrictions_digest"),
    ):
        _candidate_authority_json(
            f"checkpoint {json_field}",
            contract[json_field],
            contract[digest_field],
            maximum=_POLICY_AUTHORITY_MAX_CANONICAL_AGGREGATE_BYTES,
        )
    snapshots = loads(contract["expected_snapshots_json"], None)
    _candidate_authority_strict_object(
        "checkpoint policy snapshots",
        snapshots,
        frozenset({"active", "candidate", "requestFactsSchemaSha256"}),
    )
    observation_window = _candidate_authority_strict_object(
        "checkpoint observation window",
        loads(contract["observation_window_json"], None),
        frozenset(
            {
                "startsAtUnixNanos",
                "endsAtUnixNanos",
                "sealDeadlineUnixNanos",
                "minimumDurationNanos",
                "firstIngressSequence",
                "samplingBasisPoints",
                "requestCommitmentKeyId",
                "requestCommitmentKeyEpoch",
                "maximumEvidenceAgeNanos",
                "maximumHeartbeatGapNanos",
            }
        ),
    )
    first_ingress_sequence = _candidate_authority_int(
        "checkpoint first ingress sequence",
        observation_window["firstIngressSequence"],
        minimum=1,
    )
    obligations = loads(contract["response_obligations_json"], None)
    if not isinstance(obligations, list):
        raise PolicyCandidateAuthorityConflictError(
            "checkpoint response obligations are not a list"
        )
    obligation_by_route = {
        obligation["routeSha256"]: obligation for obligation in obligations
    }
    compiler_entries = loads(contract["expansion_cells_json"], None)
    if not isinstance(compiler_entries, list):
        raise PolicyCandidateAuthorityConflictError(
            "checkpoint compiler expansion authority is not a list"
        )
    authorized_cells: dict[str, dict[str, Any]] = {}
    previous_compiler_digest = ""
    for compiler_index, raw_entry in enumerate(compiler_entries):
        cell = _policy_authority_semantic_expansion_cell(
            f"checkpoint compiler expansion {compiler_index}",
            raw_entry,
        )
        digest = cell["cellSha256"]
        if (
            digest <= previous_compiler_digest
            or cell["routeAuthorityRootSha256"]
            != contract["route_authority_root_digest"]
            or cell["operationAuthorityRootSha256"]
            != contract["operation_authority_root_digest"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint compiler expansion authority is not exact"
            )
        previous_compiler_digest = digest
        authorized_cells[digest] = cell
    lane_gaps = 0
    lane_bytes = 0
    lane_specs = (
        (
            "policy_canary_ingress_observations",
            "ingress_sequence",
            ("ingress_envelope_json",),
            first_ingress_sequence,
            first_ingress_sequence + sequence_end - 1,
        ),
        (
            "policy_canary_active_decisions",
            "ingress_sequence",
            ("active_decision_envelope_json",),
            first_ingress_sequence,
            first_ingress_sequence + sequence_end - 1,
        ),
        (
            "policy_canary_shadow_observations",
            "observation_sequence",
            ("shadow_observation_envelope_json",),
            1,
            sequence_end,
        ),
    )
    for table, sequence_column, envelope_columns, start, end in lane_specs:
        envelope_bytes_expression = " + ".join(
            (
                f"COALESCE(octet_length({column}), 0)"
                if isinstance(conn, PostgresMetadataConnection)
                else f"COALESCE(length(CAST({column} AS BLOB)), 0)"
            )
            for column in envelope_columns
        )
        lane = conn.execute(
            f"SELECT COUNT(*) AS row_count, "
            f"MIN({sequence_column}) AS first_sequence, "
            f"MAX({sequence_column}) AS last_sequence, "
            f"COALESCE(SUM({envelope_bytes_expression}), 0) "
            "AS envelope_bytes "
            f"FROM {table} WHERE canary_id = ? AND instance_id = ? "
            f"AND boot_id = ? AND {sequence_column} >= ? "
            f"AND {sequence_column} <= ?",
            (canary_id, instance_id, boot_id, start, end),
        ).fetchone()
        row_count = int(lane["row_count"])
        first_sequence = (
            int(lane["first_sequence"])
            if lane["first_sequence"] is not None
            else start
        )
        last_sequence = (
            int(lane["last_sequence"])
            if lane["last_sequence"] is not None
            else start - 1
        )
        span = max(0, last_sequence - first_sequence + 1)
        lane_gaps += span - row_count
        lane_bytes += int(lane["envelope_bytes"])
        if (
            row_count != sequence_end
            or first_sequence != start
            or last_sequence != end
        ):
            raise PolicyCandidateAuthorityConflictError(
                "independently signed evidence lane is not an exact "
                "contiguous assigned range"
            )
    if (
        lane_gaps != 0
        or lane_bytes > _POLICY_AUTHORITY_MAX_VERIFIED_EVIDENCE_BYTES
        or sequence_end
        * _POLICY_AUTHORITY_VERIFICATION_WORK_UNITS_PER_OBSERVATION
        > _POLICY_AUTHORITY_MAX_VERIFICATION_WORK_UNITS
    ):
        raise PolicyCandidateAuthorityConflictError(
            "evidence lanes exceed predecode byte/work limits or contain gaps"
        )
    custody_rows = conn.execute(
        "SELECT "
        + _policy_authority_projection(
            _POLICY_CANARY_CUSTODY_EVIDENCE_COLUMNS
        )
        + " FROM policy_canary_custody_evidence "
        "WHERE canary_id = ? AND instance_id = ? AND boot_id = ? "
        "AND ingress_sequence >= ? AND ingress_sequence <= ? "
        "ORDER BY ingress_sequence LIMIT ?",
        (
            canary_id,
            instance_id,
            boot_id,
            first_ingress_sequence,
            first_ingress_sequence + sequence_end - 1,
            sequence_end + 1,
        ),
    ).fetchall()
    if len(custody_rows) > sequence_end:
        raise PolicyCandidateAuthorityConflictError(
            "custody evidence exceeds the bounded checkpoint prefix"
        )
    custody_by_ingress = {
        int(row["ingress_sequence"]): dict(row) for row in custody_rows
    }
    if len(custody_by_ingress) != len(custody_rows):
        raise PolicyCandidateAuthorityConflictError(
            "custody evidence reuses an ingress sequence"
        )
    runtime_lane_records: dict[str, dict[int, dict[str, Any]]] = {}
    for (
        lane_name,
        table,
        columns,
        sequence_column,
        start,
        end,
    ) in (
        (
            "ingress",
            "policy_canary_ingress_observations",
            _POLICY_CANARY_INGRESS_READ_COLUMNS,
            "ingress_sequence",
            first_ingress_sequence,
            first_ingress_sequence + sequence_end - 1,
        ),
        (
            "active",
            "policy_canary_active_decisions",
            _POLICY_CANARY_ACTIVE_DECISION_READ_COLUMNS,
            "ingress_sequence",
            first_ingress_sequence,
            first_ingress_sequence + sequence_end - 1,
        ),
        (
            "shadow",
            "policy_canary_shadow_observations",
            _POLICY_CANARY_SHADOW_OBSERVATION_READ_COLUMNS,
            "observation_sequence",
            1,
            sequence_end,
        ),
    ):
        lane_rows = conn.execute(
            "SELECT "
            + _policy_authority_projection(columns)
            + f" FROM {table} WHERE canary_id = ? AND instance_id = ? "
            f"AND boot_id = ? AND {sequence_column} >= ? "
            f"AND {sequence_column} <= ? "
            f"ORDER BY {sequence_column} LIMIT ?",
            (
                canary_id,
                instance_id,
                boot_id,
                start,
                end,
                sequence_end + 1,
            ),
        ).fetchall()
        keyed_rows = {
            int(row[sequence_column]): dict(row) for row in lane_rows
        }
        if (
            len(lane_rows) != sequence_end
            or len(keyed_rows) != len(lane_rows)
            or set(keyed_rows) != set(range(start, end + 1))
        ):
            raise PolicyCandidateAuthorityConflictError(
                f"{lane_name} evidence projection is not the exact "
                "bounded checkpoint prefix"
            )
        runtime_lane_records[lane_name] = keyed_rows
    rows = conn.execute(
        "SELECT shadow.observation_sequence, "
        "shadow.previous_observation_envelope_digest, "
        "shadow.shadow_observation_envelope_digest, "
        "shadow.shadow_observation_payload_digest, "
        "shadow.shadow_observation_envelope_json, "
        "shadow.shadow_observation_payload_json, "
        "shadow.observation_status, shadow.active_outcome, "
        "shadow.candidate_outcome, "
        "shadow.compiler_analysis_envelope_digest, "
        "shadow.compiler_analysis_payload_digest, "
        "shadow.authority_binding_json, shadow.authority_binding_digest, "
        "shadow.route_id, shadow.operation_class, "
        "shadow.request_authority_class, shadow.expansion_cells_json, "
        "shadow.expansion_cells_digest, shadow.pilot_membership_json, "
        "shadow.pilot_membership_digest, "
        "shadow.candidate_dispatch_commitment_digest, "
        "shadow.response_obligation_json, "
        "shadow.response_obligation_digest, "
        "shadow.response_obligation_route_id, "
        "shadow.response_obligation_root_digest, "
        "shadow.response_comparison_json, "
        "shadow.response_comparison_digest, "
        "shadow.response_comparison_class, shadow.response_capture_mode, "
        "shadow.latency_samples_json, "
        "shadow.latency_samples_digest, shadow.drop_reason, "
        "shadow.error_reason, ingress.ingress_sequence, "
        "ingress.ingress_envelope_digest, ingress.ingress_payload_digest, "
        "ingress.ingress_envelope_json, ingress.observed_at_epoch_ns, "
        "ingress.sampling_decision, ingress.accounting_outcome, "
        "ingress.request_commitment_digest, "
        "ingress.unavailable_marker_digest, "
        "ingress.custody_generation_id_digest, "
        "ingress.custody_request_binding_digest, "
        "ingress.custody_request_commitment_digest, "
        "ingress.custody_opening_spill_receipt_digest, "
        "ingress.custody_evidence_envelope_digest, "
        "ingress.custody_evidence_payload_digest, "
        "ingress.custody_verification_receipt_digest, "
        "ingress.assignment_envelope_digest, "
        "ingress.assignment_payload_digest, "
        "ingress.assignment_revision, ingress.fleet_id, "
        "ingress.membership_revision, ingress.member_ordinal, "
        "active.active_decision_envelope_digest, "
        "active.active_decision_payload_digest, active.decision_status, "
        "active.active_decision_envelope_json, "
        "active.active_decision_payload_json, "
        "active.generation_id_digest, active.captured_at_epoch_ns, "
        "active.decision_at_epoch_ns, active.active_evaluation_digest, "
        "active.active_unavailable_reason, "
        "active.active_unavailable_marker_digest, "
        "active.active_outcome AS independently_active_outcome, "
        "active.final_active_outcome, active.returned_http_status, "
        "active.upstream_dispatch_authorized, "
        "active.active_dispatch_commitment_digest "
        ", active.custody_evidence_envelope_digest AS "
        "active_custody_evidence_envelope_digest, "
        "active.custody_verification_receipt_digest AS "
        "active_custody_verification_receipt_digest, "
        "shadow.custody_evidence_envelope_digest AS "
        "shadow_custody_evidence_envelope_digest, "
        "shadow.custody_verification_receipt_digest AS "
        "shadow_custody_verification_receipt_digest "
        "FROM policy_canary_shadow_observations AS shadow "
        "JOIN policy_canary_ingress_observations AS ingress "
        "ON ingress.canary_id = shadow.canary_id "
        "AND ingress.instance_id = shadow.instance_id "
        "AND ingress.boot_id = shadow.boot_id "
        "AND ingress.ingress_sequence = shadow.ingress_sequence "
        "AND ingress.ingress_envelope_digest = "
        "shadow.ingress_envelope_digest "
        "AND ingress.ingress_payload_digest = shadow.ingress_payload_digest "
        "JOIN policy_canary_active_decisions AS active "
        "ON active.canary_id = shadow.canary_id "
        "AND active.instance_id = shadow.instance_id "
        "AND active.boot_id = shadow.boot_id "
        "AND active.ingress_sequence = shadow.ingress_sequence "
        "AND active.active_decision_envelope_digest = "
        "shadow.active_decision_envelope_digest "
        "AND active.active_decision_payload_digest = "
        "shadow.active_decision_payload_digest "
        "WHERE shadow.canary_id = ? AND shadow.instance_id = ? "
        "AND shadow.boot_id = ? AND shadow.observation_sequence <= ? "
        "ORDER BY shadow.observation_sequence LIMIT ?",
        (
            canary_id,
            instance_id,
            boot_id,
            sequence_end,
            sequence_end + 1,
        ),
    )
    return _fold_policy_canary_checkpoint_originals(
        conn, sequence_end=sequence_end, assertions=assertions, historical=historical,
        contract=contract, snapshots=snapshots, observation_window=observation_window,
        first_ingress_sequence=first_ingress_sequence, obligation_by_route=obligation_by_route,
        authorized_cells=authorized_cells, lane_gaps=lane_gaps,
        custody_by_ingress=custody_by_ingress, runtime_lane_records=runtime_lane_records, rows=rows,
    )


def _fold_policy_canary_checkpoint_originals(
    conn: Any, *, sequence_end: int, assertions: Mapping[int, Mapping[str, Any]], historical: bool,
    contract: Mapping[str, Any], snapshots: Mapping[str, Any], observation_window: Mapping[str, Any],
    first_ingress_sequence: int, obligation_by_route: Mapping[str, Any], authorized_cells: Mapping[str, Any],
    lane_gaps: int, custody_by_ingress: Mapping[int, Any], runtime_lane_records: Mapping[str, Any],
    rows: Any, _controlled_state: Any | None = None,
) -> dict[str, Any]:
    # Both producers supply original rows. This fold retains the same exact
    # signature, prefix, pilot, response, latency and Merkle checks. A controlled
    # caller has no connection and cannot route these reads into runtime SQL.
    from serverware import authority_transition_policy_canary_reads as controlled
    controlled.owner(_controlled_state, conn)
    runtime_verifier = _reverify_policy_runtime_row if _controlled_state is None else _controlled_state.reverify_runtime_row
    custody_verifier = _reverify_policy_canary_custody_evidence if _controlled_state is None else _controlled_state.reverify_custody_row
    verified_assertion_boundaries: set[int] = set()
    aggregate = _empty_policy_authority_aggregate()
    aggregate["gaps"] = lane_gaps
    observation_levels: list[bytes | None] = []
    ingress_levels: list[bytes | None] = []
    active_levels: list[bytes | None] = []
    custody_evidence_levels: list[bytes | None] = []
    custody_verification_levels: list[bytes | None] = []
    principal_levels: list[bytes | None] = []
    route_levels: list[bytes | None] = []
    previous_envelope: str | None = None
    previous_observed_at: int | None = None
    first_row: Any | None = None
    last_row: Any | None = None
    row_count = 0
    verified_evidence_bytes = 0
    verification_work_units = 0
    for expected_sequence, row in enumerate(rows, start=1):
        row_count = expected_sequence
        if first_row is None:
            first_row = row
        last_row = row
        sequence = int(row["observation_sequence"])
        expected_ingress_sequence = (
            first_ingress_sequence + expected_sequence - 1
        )
        observed_at = int(row["observed_at_epoch_ns"])
        ingress_record = runtime_lane_records["ingress"].get(
            expected_ingress_sequence
        )
        active_record = runtime_lane_records["active"].get(
            expected_ingress_sequence
        )
        shadow_record = runtime_lane_records["shadow"].get(sequence)
        if (
            sequence != expected_sequence
            or int(row["ingress_sequence"]) != expected_ingress_sequence
            or ingress_record is None
            or active_record is None
            or shadow_record is None
            or ingress_record["ingress_envelope_digest"]
            != row["ingress_envelope_digest"]
            or active_record["active_decision_envelope_digest"]
            != row["active_decision_envelope_digest"]
            or shadow_record["shadow_observation_envelope_digest"]
            != row["shadow_observation_envelope_digest"]
            or (
                previous_observed_at is not None
                and observed_at < previous_observed_at
            )
            or row["previous_observation_envelope_digest"]
            != previous_envelope
            or row["observation_status"] != row["accounting_outcome"]
            or row["active_outcome"] != row["independently_active_outcome"]
            or (
                row["observation_status"] == "evaluated"
            ) != (row["decision_status"] == "evaluated")
            or row["compiler_analysis_envelope_digest"]
            != contract["analysis_envelope_digest"]
            or row["compiler_analysis_payload_digest"]
            != contract["analysis_payload_digest"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint evidence prefix is not exact and contiguous"
            )
        previous_observed_at = observed_at
        ingress_wire = _policy_shadow_direct_envelope_components(
            "checkpoint ingress evidence",
            loads(row["ingress_envelope_json"], None),
        )
        if (
            ingress_wire["envelope_digest"]
            != row["ingress_envelope_digest"]
            or ingress_wire["payload_digest"] != row["ingress_payload_digest"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint ingress wire digest is not exact"
            )
        runtime_verifier(
            conn,
            evidence_kind="ingress_observation",
            item=ingress_record,
            current_prefix="ingress",
            historical=historical,
        )
        ingress_facts = _policy_shadow_ingress_facts_state(
            "checkpoint ingress evidence",
            ingress_wire["payload"],
            assignment_payload_digest=contract[
                "assignment_payload_digest"
            ],
            assignment_revision=int(contract["assignment_revision"]),
            ingress_sequence=int(row["ingress_sequence"]),
            observed_at_epoch_ns=observed_at,
            observation_window=observation_window,
        )
        if (
            row["request_commitment_digest"]
            != ingress_facts["request_commitment_digest"]
            or row["unavailable_marker_digest"]
            != ingress_facts["unavailable_marker_digest"]
            and ingress_facts["unavailable_marker_digest"] is not None
            or (
                ingress_facts["sampling_decision"] is not None
                and row["sampling_decision"]
                != ingress_facts["sampling_decision"]
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint ingress commitment projection is not exact"
            )
        if ingress_facts["state"] == "captured":
            custody = custody_by_ingress.get(
                int(row["ingress_sequence"])
            )
            if (
                row["custody_generation_id_digest"]
                != row["generation_id_digest"]
                or row["custody_request_binding_digest"] is None
                or row["custody_request_commitment_digest"]
                != row["request_commitment_digest"]
                or row["custody_opening_spill_receipt_digest"] is None
                or custody is None
                or row["custody_evidence_envelope_digest"]
                != custody["custody_evidence_envelope_digest"]
                or row["custody_evidence_payload_digest"]
                != custody["custody_evidence_payload_digest"]
                or row["custody_verification_receipt_digest"]
                != custody["verification_receipt_digest"]
                or row["active_custody_evidence_envelope_digest"]
                != custody["custody_evidence_envelope_digest"]
                or row["active_custody_verification_receipt_digest"]
                != custody["verification_receipt_digest"]
                or row["shadow_custody_evidence_envelope_digest"]
                != custody["custody_evidence_envelope_digest"]
                or row["shadow_custody_verification_receipt_digest"]
                != custody["verification_receipt_digest"]
                or custody["generation_id_digest"]
                != row["generation_id_digest"]
                or custody["request_binding_digest"]
                != row["custody_request_binding_digest"]
                or custody["request_commitment_digest"]
                != row["request_commitment_digest"]
                or custody["opening_spill_receipt_digest"]
                != row["custody_opening_spill_receipt_digest"]
                or custody["sampling_decision"]
                != row["sampling_decision"]
                or int(custody["trusted_time_epoch_ns"])
                != int(row["observed_at_epoch_ns"])
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "checkpoint ingress does not bind exact verified custody"
                )
            custody_verifier(
                conn, custody, require_current_head=False
            )
            custody_evidence_digest = str(
                custody["custody_evidence_envelope_digest"]
            )
            custody_verification_digest = str(
                custody["verification_receipt_digest"]
            )
        elif any(
            row[field] is not None
            for field in (
                "custody_generation_id_digest",
                "custody_request_binding_digest",
                "custody_request_commitment_digest",
                "custody_opening_spill_receipt_digest",
                "custody_evidence_envelope_digest",
                "custody_evidence_payload_digest",
                "custody_verification_receipt_digest",
                "active_custody_evidence_envelope_digest",
                "active_custody_verification_receipt_digest",
                "shadow_custody_evidence_envelope_digest",
                "shadow_custody_verification_receipt_digest",
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "unavailable checkpoint ingress carries custody authority"
            )
        else:
            if int(row["ingress_sequence"]) in custody_by_ingress:
                raise PolicyCandidateAuthorityConflictError(
                    "unavailable ingress has an unreferenced custody object"
                )
            custody_evidence_digest = _policy_authority_domain_digest(
                b"serverware.policyShadowCustodyUnavailableEvidence/v1",
                str(row["ingress_envelope_digest"]).encode("ascii"),
                str(row["unavailable_marker_digest"]).encode("ascii"),
            )
            custody_verification_digest = (
                _policy_authority_domain_digest(
                    b"serverware.policyShadowCustodyUnavailableReceipt/v1",
                    str(row["ingress_envelope_digest"]).encode("ascii"),
                    str(row["unavailable_marker_digest"]).encode("ascii"),
                )
            )
        active_wire = _policy_shadow_direct_envelope_components(
            "checkpoint active decision",
            loads(row["active_decision_envelope_json"], None),
        )
        active_payload = active_wire["payload"]
        active_result = active_payload["result"]
        if (
            active_wire["envelope_digest"]
            != row["active_decision_envelope_digest"]
            or active_wire["payload_digest"]
            != row["active_decision_payload_digest"]
            or active_wire["payload_json"]
            != row["active_decision_payload_json"]
            or active_payload["generationId"]
            != row["generation_id_digest"]
            or active_payload["capturedAtUnixNanos"]
            != row["captured_at_epoch_ns"]
            or active_payload["decisionAtUnixNanos"]
            != row["decision_at_epoch_ns"]
            or not isinstance(active_result, dict)
        ):
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint active-decision wire is not exact"
            )
        runtime_verifier(
            conn,
            evidence_kind="active_decision",
            item=active_record,
            current_prefix="active_decision",
            historical=historical,
        )
        if active_result.get("status") == "finalized":
            pure_evaluation = active_result.get("pureActiveEvaluation")
            effect_resolution = active_result.get("effectResolution")
            active_result_exact = (
                set(active_result)
                == {"status", "pureActiveEvaluation", "effectResolution"}
                and isinstance(pure_evaluation, dict)
                and isinstance(effect_resolution, dict)
                and row["decision_status"] == "evaluated"
                and pure_evaluation.get("outcome")
                == row["independently_active_outcome"]
                and _candidate_authority_sha256(
                    dumps(pure_evaluation).encode("ascii")
                ) == row["active_evaluation_digest"]
                and pure_evaluation.get("dispatchCommitmentSha256")
                == row["active_dispatch_commitment_digest"]
                and effect_resolution.get("finalOutcome")
                == row["final_active_outcome"]
                and effect_resolution.get("returnedHttpStatus")
                == row["returned_http_status"]
                and int(bool(
                    effect_resolution.get("upstreamDispatchAuthorized")
                )) == int(row["upstream_dispatch_authorized"])
            )
        elif active_result.get("status") == "unavailable":
            active_result_exact = (
                set(active_result)
                == {"status", "reason", "unavailableMarkerSha256"}
                and row["decision_status"] == "unavailable"
                and active_result["reason"]
                == row["active_unavailable_reason"]
                and active_result["unavailableMarkerSha256"]
                == row["active_unavailable_marker_digest"]
            )
        else:
            active_result_exact = False
        if not active_result_exact:
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint active-decision projection differs from signed result"
            )
        shadow_wire = _policy_shadow_direct_envelope_components(
            "checkpoint shadow observation",
            loads(row["shadow_observation_envelope_json"], None),
        )
        shadow_payload = shadow_wire["payload"]
        shadow_result = shadow_payload["result"]
        nested_ingress = _policy_shadow_direct_envelope_components(
            "checkpoint nested ingress",
            shadow_payload["ingressEvidence"],
        )
        nested_active = _policy_shadow_direct_envelope_components(
            "checkpoint nested active decision",
            shadow_payload["activeDecision"],
        )
        if (
            shadow_wire["envelope_digest"]
            != row["shadow_observation_envelope_digest"]
            or shadow_wire["payload_digest"]
            != row["shadow_observation_payload_digest"]
            or shadow_wire["payload_json"]
            != row["shadow_observation_payload_json"]
            or nested_ingress["envelope_json"]
            != ingress_wire["envelope_json"]
            or nested_active["envelope_json"]
            != active_wire["envelope_json"]
            or not isinstance(shadow_result, dict)
            or shadow_result.get("status") != row["observation_status"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint shadow wire does not embed the exact lane evidence"
            )
        runtime_verifier(
            conn,
            evidence_kind="shadow_observation",
            item=shadow_record,
            current_prefix="shadow_observation",
            historical=historical,
        )
        if row["observation_status"] == "evaluated":
            direct_expansion = _candidate_authority_strict_object(
                "checkpoint direct expansion",
                shadow_result["derivedExpansion"],
                frozenset({"cells", "cellsRootSha256"}),
            )
            shadow_result_exact = (
                set(shadow_result)
                == {
                    "status",
                    "pureActiveEvaluation",
                    "finalActiveEnforcement",
                    "candidateEvaluation",
                    "authorityBinding",
                    "derivedExpansion",
                    "pilotMembership",
                    "responseObligation",
                    "responseComparison",
                    "latencySamples",
                }
                and dumps(shadow_result["authorityBinding"])
                == row["authority_binding_json"]
                and dumps(direct_expansion["cells"])
                == row["expansion_cells_json"]
                and dumps(shadow_result["pilotMembership"])
                == row["pilot_membership_json"]
                and dumps(shadow_result["responseObligation"])
                == row["response_obligation_json"]
                and dumps(shadow_result["responseComparison"])
                == row["response_comparison_json"]
                and dumps(shadow_result["latencySamples"])
                == row["latency_samples_json"]
                and shadow_result["pureActiveEvaluation"]["outcome"]
                == row["active_outcome"]
                and shadow_result["candidateEvaluation"]["outcome"]
                == row["candidate_outcome"]
            )
        elif row["observation_status"] in {"dropped", "error"}:
            shadow_result_exact = (
                set(shadow_result)
                == {
                    "status",
                    "reason",
                    "unavailableMarkerSha256",
                    "latencySamples",
                }
                and shadow_result["reason"]
                == row[
                    "drop_reason"
                    if row["observation_status"] == "dropped"
                    else "error_reason"
                ]
                and dumps(shadow_result["latencySamples"])
                == row["latency_samples_json"]
            )
        elif row["observation_status"] == "excluded":
            shadow_result_exact = (
                shadow_result
                == {
                    "status": "excluded",
                    "reason": "deterministic-assignment-sampling",
                }
            )
        else:
            shadow_result_exact = shadow_result == {
                "status": "transport-excluded"
            }
        if not shadow_result_exact:
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint shadow projection differs from signed result"
            )
        row_evidence_bytes = sum(
            len(str(row[field]).encode("utf-8"))
            for field in (
                "ingress_envelope_json",
                "active_decision_envelope_json",
                "shadow_observation_envelope_json",
            )
            if row[field] is not None
        )
        custody_row = custody_by_ingress.get(int(row["ingress_sequence"]))
        if custody_row is not None:
            row_evidence_bytes += len(
                str(
                    custody_row["custody_evidence_envelope_json"]
                ).encode("utf-8")
            )
        verified_evidence_bytes += row_evidence_bytes
        verification_work_units += (
            _POLICY_AUTHORITY_VERIFICATION_WORK_UNITS_PER_OBSERVATION
        )
        if (
            verified_evidence_bytes
            > _POLICY_AUTHORITY_MAX_VERIFIED_EVIDENCE_BYTES
            or verification_work_units
            > _POLICY_AUTHORITY_MAX_VERIFICATION_WORK_UNITS
        ):
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint verified evidence exceeds its signed budget"
            )
        previous_envelope = str(
            row["shadow_observation_envelope_digest"]
        )
        _policy_shadow_merkle_accumulate(
            observation_levels,
            sequence=sequence,
            digest=row["shadow_observation_envelope_digest"],
        )
        _policy_shadow_merkle_accumulate(
            ingress_levels,
            sequence=int(row["ingress_sequence"]),
            digest=row["ingress_envelope_digest"],
        )
        _policy_shadow_merkle_accumulate(
            active_levels,
            sequence=sequence,
            digest=row["active_decision_envelope_digest"],
        )
        _policy_shadow_merkle_accumulate(
            custody_evidence_levels,
            sequence=sequence,
            digest=custody_evidence_digest,
        )
        _policy_shadow_merkle_accumulate(
            custody_verification_levels,
            sequence=sequence,
            digest=custody_verification_digest,
        )
        status = str(row["observation_status"])
        totals_key = {
            "evaluated": "evaluated",
            "dropped": "dropped",
            "error": "errors",
            "excluded": "excluded",
            "transport-excluded": "excluded",
        }[status]
        _policy_authority_increment(aggregate["totals"], totals_key)
        _policy_authority_increment(
            aggregate["totals"], "ingressAdmitted"
        )
        if ingress_facts["state"] == "unavailable":
            _policy_authority_increment(
                aggregate["totals"], "unavailableEvidence"
            )
        matrix_key = f"{row['active_outcome']}:{row['candidate_outcome']}"
        if status == "evaluated":
            _policy_authority_increment(
                aggregate["semanticMatrix"], matrix_key
            )
            if row["active_outcome"] == "indeterminate":
                _policy_authority_increment(
                    aggregate["totals"], "activeIndeterminate"
                )
            if row["candidate_outcome"] == "indeterminate":
                _policy_authority_increment(
                    aggregate["totals"], "candidateIndeterminate"
                )
            transition_total = {
                ("deny", "permit"): "activeDenyCandidatePermit",
                ("deny", "conditional"):
                    "activeDenyCandidateConditional",
                ("conditional", "permit"):
                    "activeConditionalCandidatePermit",
                ("indeterminate", "permit"):
                    "activeIndeterminateCandidatePermit",
                ("indeterminate", "conditional"):
                    "activeIndeterminateCandidateConditional",
            }.get((row["active_outcome"], row["candidate_outcome"]))
            if transition_total is not None:
                _policy_authority_increment(
                    aggregate["totals"], transition_total
                )
        for json_field, digest_field in (
            ("authority_binding_json", "authority_binding_digest"),
            ("expansion_cells_json", "expansion_cells_digest"),
            ("pilot_membership_json", "pilot_membership_digest"),
            ("response_obligation_json", "response_obligation_digest"),
            ("response_comparison_json", "response_comparison_digest"),
        ):
            _candidate_authority_json(
                f"persisted {json_field}",
                row[json_field],
                row[digest_field],
                maximum=_POLICY_AUTHORITY_MAX_CANONICAL_AGGREGATE_BYTES,
            )
        authority_value = loads(row["authority_binding_json"], None)
        authority_binding = (
            None
            if authority_value is None
            else _policy_authority_observed_binding(
                "persisted authority binding", authority_value
            )
        )
        if authority_binding is not None:
            _policy_shadow_merkle_accumulate(
                principal_levels,
                sequence=sequence,
                digest=authority_binding["principalSha256"],
            )
            _policy_shadow_merkle_accumulate(
                route_levels,
                sequence=sequence,
                digest=authority_binding["routeSha256"],
            )
        observed_cells = _policy_authority_semantic_expansion_cells(
            "persisted expansion cells",
            loads(row["expansion_cells_json"], None),
            maximum=128,
            allow_empty=True,
        )
        if status == "evaluated" and shadow_result["derivedExpansion"][
            "cellsRootSha256"
        ] != _policy_shadow_merkle_root(
            [
                (index, cell["cellSha256"])
                for index, cell in enumerate(observed_cells, start=1)
            ]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "signed derived expansion root does not match its cells"
            )
        _policy_authority_pilot_membership(
            "persisted pilot membership",
            loads(row["pilot_membership_json"], None),
            authority_binding=authority_binding,
            expansion_cells=observed_cells,
        )
        response_obligation = _policy_authority_response_obligation(
            "persisted response obligation",
            loads(row["response_obligation_json"], None),
        )
        evaluated = status == "evaluated"
        if evaluated and authority_binding is None:
            raise PolicyCandidateAuthorityConflictError(
                "evaluated authority has no exact signed policy-shadow binding"
            )
        if (
            evaluated
            and row["active_outcome"] == "indeterminate"
            and not observed_cells
        ):
            _policy_authority_increment(
                aggregate["totals"], "unapprovedActiveIndeterminate"
            )
        if (
            evaluated != (authority_binding is not None)
            or (
                authority_binding is not None
                and (
                    row["route_id"]
                    != authority_binding["routeSha256"]
                    or row["operation_class"]
                    != authority_binding["operation"]
                    or row["request_authority_class"]
                    != authority_binding["requestAuthorityClass"]
                )
            )
            or (
                response_obligation is None
                and (
                    row["response_obligation_route_id"] is not None
                    or row["response_obligation_root_digest"] is not None
                )
            )
            or (
                response_obligation is not None
                and (
                    row["response_obligation_route_id"]
                    != response_obligation["routeSha256"]
                    or row["response_obligation_root_digest"]
                    != response_obligation["obligationRootSha256"]
                )
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "persisted shadow materialization is not canonical evidence"
            )
        assigned_obligation = (
            None
            if authority_binding is None
            else obligation_by_route.get(authority_binding["routeSha256"])
        )
        if (
            assigned_obligation is None
            and response_obligation is not None
        ) or (
            assigned_obligation is not None
            and (
                response_obligation is None
                or response_obligation["obligationRootSha256"]
                != assigned_obligation["obligationRootSha256"]
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "persisted response obligation is not assignment-exact"
            )
        if any(
            cell["routeSha256"] != authority_binding["routeSha256"]
            or cell["operation"] != authority_binding["operation"]
            or cell["compiledSemanticProfileSha256"]
            != authority_binding["compiledSemanticProfileSha256"]
            or cell["requestAuthorityClass"]
            != authority_binding["requestAuthorityClass"]
            or cell["activeOutcome"] != row["active_outcome"]
            or cell["candidateOutcome"] != row["candidate_outcome"]
            for cell in observed_cells
        ):
            raise PolicyCandidateAuthorityConflictError(
                "persisted expansion cells do not bind observed semantics"
            )
        expected_observed_cells = (
            []
            if authority_binding is None
            else [
                authorized_cells[digest]
                for digest in sorted(authorized_cells)
                if authorized_cells[digest]["routeSha256"]
                == authority_binding["routeSha256"]
                and authorized_cells[digest]["operation"]
                == authority_binding["operation"]
                and authorized_cells[digest][
                    "compiledSemanticProfileSha256"
                ]
                == authority_binding["compiledSemanticProfileSha256"]
                and authorized_cells[digest][
                    "requestAuthorityClass"
                ]
                == authority_binding["requestAuthorityClass"]
                and authorized_cells[digest]["activeOutcome"]
                == row["active_outcome"]
                and authorized_cells[digest]["candidateOutcome"]
                == row["candidate_outcome"]
            ]
        )
        if observed_cells != expected_observed_cells:
            raise PolicyCandidateAuthorityConflictError(
                "persisted expansion set is not compiler-derived exactly"
            )
        if contract["analysis_mode"] == "no-expansion":
            if observed_cells or authorized_cells:
                raise PolicyCandidateAuthorityConflictError(
                    "NoExpansion checkpoint contains expansion authority"
                )
        elif contract["analysis_mode"] != "approved-expansion":
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint compiler mode is invalid"
            )
        response_value = loads(row["response_comparison_json"], None)
        if evaluated:
            if row["candidate_dispatch_commitment_digest"] is None:
                raise PolicyCandidateAuthorityConflictError(
                    "evaluated response has no candidate dispatch commitment"
                )
            response_comparison = _policy_authority_response_comparison(
                "persisted response comparison",
                response_value,
                obligation=response_obligation,
                active_snapshot_digest=
                    snapshots["active"]["compiledSnapshotSha256"],
                candidate_snapshot_digest=
                    snapshots["candidate"]["compiledSnapshotSha256"],
                final_active_outcome=row["final_active_outcome"],
                upstream_dispatch_authorized=int(
                    row["upstream_dispatch_authorized"]
                ),
                active_dispatch_commitment_digest=
                    row["active_dispatch_commitment_digest"],
                candidate_dispatch_commitment_digest=
                    row["candidate_dispatch_commitment_digest"],
                candidate_outcome=row["candidate_outcome"],
            )
            response_class = response_comparison["classification"]
            response_capture_mode = response_comparison["captureMode"]
            if (
                row["response_comparison_class"] != response_class
                or row["response_capture_mode"] != response_capture_mode
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "persisted response class is not recomputed evidence"
                )
            _policy_authority_increment(
                aggregate["responseClasses"], response_class
            )
            _policy_authority_increment(
                aggregate["responseCaptureModes"], response_capture_mode
            )
            if response_class.startswith("comparable-"):
                _policy_authority_increment(
                    aggregate["totals"], "comparableResponses"
                )
            elif response_class in {
                "not-comparable-candidate-not-dispatchable",
                "not-comparable-dispatch-commitment-mismatch",
                "not-comparable-active-response-unavailable",
                "not-comparable-candidate-validator-unavailable",
            }:
                _policy_authority_increment(
                    aggregate["totals"], "responseNoncomparable"
                )
            if response_class == "comparable-validation-divergence":
                _policy_authority_increment(
                    aggregate["totals"],
                    "responseValidationDivergence",
                )
            if (
                response_class
                == "not-comparable-candidate-validator-unavailable"
            ):
                _policy_authority_increment(
                    aggregate["totals"],
                    "responseValidatorUnavailable",
                )
        else:
            response_class = None
            response_capture_mode = None
            if (
                response_value is not None
                or row["candidate_dispatch_commitment_digest"] is not None
                or row["response_comparison_class"] is not None
                or row["response_capture_mode"] is not None
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "failure observation carries response comparison authority"
                )
        if observed_cells:
            _policy_authority_increment(
                aggregate["totals"], "authorityExpansionObservations"
            )
            if (
                authority_binding["requestAuthorityClass"] == "write"
                or any(
                    cell["requestAuthorityClass"] == "write"
                    for cell in observed_cells
                )
            ):
                _policy_authority_increment(
                    aggregate["totals"],
                    "authorityExpansionWriteObservations",
                )
        for cell in observed_cells:
            expansion_digest = cell["cellSha256"]
            authorized = authorized_cells.get(expansion_digest)
            if authorized is None or authorized != cell:
                raise PolicyCandidateAuthorityConflictError(
                    "persisted expansion has no exact compiler cell"
                )
            current = aggregate["expansionCells"].get(expansion_digest)
            if current is None:
                aggregate["expansionCells"][expansion_digest] = {
                    "cellSha256": cell["cellSha256"],
                    "authorityExpansion": cell["authorityExpansion"],
                    "routeSha256": cell["routeSha256"],
                    "operation": cell["operation"],
                    "compiledSemanticProfileSha256":
                        cell["compiledSemanticProfileSha256"],
                    "requestAuthorityClass":
                        cell["requestAuthorityClass"],
                    "activeOutcome": cell["activeOutcome"],
                    "candidateOutcome": cell["candidateOutcome"],
                    "requestCount": 1,
                    "writeRequestCount": (
                        1
                        if cell["requestAuthorityClass"] == "write"
                        else 0
                    ),
                    "responseCount": (
                        1
                        if response_class is not None
                        and response_class.startswith("comparable-")
                        else 0
                    ),
                    "writeResponseCount": (
                        1
                        if cell["requestAuthorityClass"] == "write"
                        and response_class is not None
                        and response_class.startswith("comparable-")
                        else 0
                    ),
                }
            else:
                exact_cell_projection = {
                    "cellSha256": cell["cellSha256"],
                    "authorityExpansion": cell["authorityExpansion"],
                    "routeSha256": cell["routeSha256"],
                    "operation": cell["operation"],
                    "compiledSemanticProfileSha256":
                        cell["compiledSemanticProfileSha256"],
                    "requestAuthorityClass":
                        cell["requestAuthorityClass"],
                    "activeOutcome": cell["activeOutcome"],
                    "candidateOutcome": cell["candidateOutcome"],
                }
                if any(
                    current[field] != value
                    for field, value in exact_cell_projection.items()
                ):
                    raise PolicyCandidateAuthorityConflictError(
                        "expansion cell digest resolves to different semantics"
                    )
                current["requestCount"] += 1
                if cell["requestAuthorityClass"] == "write":
                    current["writeRequestCount"] += 1
                if (
                    response_class is not None
                    and response_class.startswith("comparable-")
                ):
                    current["responseCount"] += 1
                    if cell["requestAuthorityClass"] == "write":
                        current["writeResponseCount"] += 1
            current_count = aggregate["expansionCells"][
                expansion_digest
            ]["requestCount"]
            if (
                current_count > authorized["maximumRequests"]
                or (
                    cell["requestAuthorityClass"] == "write"
                    and current_count
                    > authorized["maximumWriteRequests"]
                )
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "checkpoint expansion exceeds its exact compiler limits"
                )
        if response_obligation is not None:
            route_id = response_obligation["routeSha256"]
            coverage = aggregate["responseRouteCoverage"].setdefault(
                route_id,
                {
                    "routeSha256": route_id,
                    "obligationRootSha256":
                        response_obligation["obligationRootSha256"],
                    "comparableResponses": 0,
                    "validationDivergences": 0,
                    "validatorUnavailable": 0,
                    "noncomparable": 0,
                },
            )
            exact_profile = {
                "routeSha256": route_id,
                "obligationRootSha256":
                    response_obligation["obligationRootSha256"],
            }
            if any(
                coverage[field] != value
                for field, value in exact_profile.items()
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "route obligation profile changed inside one checkpoint"
                )
            if response_class in {
                "comparable-identical",
                "comparable-validation-match",
            }:
                coverage["comparableResponses"] += 1
            elif response_class == "comparable-validation-divergence":
                coverage["comparableResponses"] += 1
                coverage["validationDivergences"] += 1
            elif (
                response_class
                == "not-comparable-candidate-validator-unavailable"
            ):
                coverage["validatorUnavailable"] += 1
            elif response_class not in {
                "not-applicable-active-not-dispatched",
                "not-applicable-both-deny",
            }:
                coverage["noncomparable"] += 1
        latency_json = str(row["latency_samples_json"])
        latency_digest = str(row["latency_samples_digest"])
        _candidate_authority_json(
            "persisted latency samples", latency_json, latency_digest
        )
        latency_wire = _candidate_authority_strict_object(
            "persisted latency samples",
            loads(latency_json, None),
            frozenset(_POLICY_AUTHORITY_LATENCY_SAMPLE_FIELDS.values()),
        )
        latency = {
            series: latency_wire[field]
            for series, field
            in _POLICY_AUTHORITY_LATENCY_SAMPLE_FIELDS.items()
        }
        for series in _POLICY_AUTHORITY_LATENCY_SERIES:
            if latency[series] is not None:
                latency[series] = _candidate_authority_int(
                    f"{series} latency", latency[series]
                )
        if (
            evaluated
            and (
                any(
                    latency[series] is None
                    for series in (
                        "factsCapture",
                        "activeEvaluation",
                        "candidateEvaluation",
                        "shadowTotal",
                    )
                )
                or any(
                    sample is not None
                    and sample > latency["shadowTotal"]
                    for sample in latency.values()
                )
            )
        ) or (
            status == "excluded"
            and any(sample is not None for sample in latency.values())
        ) or (
            status in {"dropped", "error"}
            and (
                (
                    latency["shadowTotal"] is None
                    and any(
                        sample is not None
                        for series, sample in latency.items()
                        if series != "shadowTotal"
                    )
                )
                or (
                    latency["shadowTotal"] is not None
                    and any(
                        sample is not None
                        and sample > latency["shadowTotal"]
                        for sample in latency.values()
                    )
                )
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "persisted latency availability is not evidence-exact"
            )
        for series in _POLICY_AUTHORITY_LATENCY_SERIES:
            sample = latency[series]
            if sample is None:
                continue
            bucket = _policy_authority_latency_bucket_index(sample)
            aggregate["latencyHistograms"][series]["buckets"][bucket] += 1
            aggregate["latencyHistograms"][series]["total"] += 1
        if row["drop_reason"] is not None:
            _policy_authority_increment(
                aggregate["dropReasons"], str(row["drop_reason"])
            )
        if row["error_reason"] is not None:
            _policy_authority_increment(
                aggregate["errorReasons"], str(row["error_reason"])
            )
        assertion = assertions.get(sequence)
        if assertion is not None:
            checkpoint = assertion["checkpoint"]
            stored_aggregate = assertion["aggregate"]
            boundary_values = _policy_canary_checkpoint_snapshot_values(
                aggregate=aggregate,
                sequence_end=sequence,
                observation_window=observation_window,
                first_ingress_sequence=first_ingress_sequence,
                first_observation_envelope_digest=str(
                    first_row["shadow_observation_envelope_digest"]
                ),
                last_observation_envelope_digest=str(
                    row["shadow_observation_envelope_digest"]
                ),
                first_observed_at_epoch_ns=int(
                    first_row["observed_at_epoch_ns"]
                ),
                last_observed_at_epoch_ns=observed_at,
                verified_evidence_bytes=verified_evidence_bytes,
                verification_work_units=verification_work_units,
                lane_gaps=lane_gaps,
                observation_root=
                    _policy_shadow_merkle_accumulator_root(
                        observation_levels
                    ),
                ingress_root=_policy_shadow_merkle_accumulator_root(
                    ingress_levels
                ),
                active_root=_policy_shadow_merkle_accumulator_root(
                    active_levels
                ),
                custody_evidence_root=
                    _policy_shadow_merkle_accumulator_root(
                        custody_evidence_levels
                    ),
                custody_verification_root=
                    _policy_shadow_merkle_accumulator_root(
                        custody_verification_levels
                    ),
                principal_root=_policy_shadow_merkle_accumulator_root(
                    principal_levels
                ),
                route_root=_policy_shadow_merkle_accumulator_root(
                    route_levels
                ),
            )
            checkpoint_fields = (
                "observed_request_count",
                "evaluated_request_count",
                "dropped_request_count",
                "evaluation_error_count",
                "excluded_request_count",
                "active_permit_count",
                "active_deny_count",
                "active_conditional_count",
                "active_indeterminate_count",
                "candidate_permit_count",
                "candidate_deny_count",
                "candidate_conditional_count",
                "candidate_indeterminate_count",
                "first_observation_envelope_digest",
                "last_observation_envelope_digest",
                "first_observed_at_epoch_ns",
                "last_observed_at_epoch_ns",
                "ingress_count",
                "verified_evidence_bytes",
                "verification_work_units",
            )
            if (
                int(checkpoint["request_sequence_start"])
                != boundary_values["ingress_sequence_start"]
                or int(checkpoint["request_sequence_end"])
                != boundary_values["ingress_sequence_end"]
                or int(checkpoint["observation_sequence_end"])
                != boundary_values["observation_sequence_end"]
                or checkpoint["observation_root_digest"]
                != boundary_values[
                    "cumulative_observation_root_digest"
                ]
                or checkpoint["ingress_root_digest"]
                != boundary_values["cumulative_ingress_root_digest"]
                or checkpoint["active_decision_root_digest"]
                != boundary_values[
                    "cumulative_active_decision_root_digest"
                ]
                or checkpoint["custody_evidence_root_digest"]
                != boundary_values[
                    "cumulative_custody_evidence_root_digest"
                ]
                or checkpoint["custody_verification_root_digest"]
                != boundary_values[
                    "cumulative_custody_verification_root_digest"
                ]
                or checkpoint["principal_authority_root_digest"]
                != boundary_values[
                    "cumulative_principal_authority_root_digest"
                ]
                or checkpoint["route_authority_root_digest"]
                != boundary_values[
                    "cumulative_route_authority_root_digest"
                ]
                or any(
                    checkpoint[field] != boundary_values[field]
                    for field in checkpoint_fields
                )
                or any(
                    stored_aggregate[field] != boundary_values[field]
                    for field in
                    _POLICY_CANARY_CHECKPOINT_AGGREGATE_COLUMNS
                )
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "checkpoint assertion is not its exact streaming prefix"
                )
            verified_assertion_boundaries.add(sequence)
    if row_count != sequence_end or first_row is None or last_row is None:
        raise PolicyCandidateAuthorityConflictError(
            "checkpoint streaming pass did not consume the exact prefix"
        )
    if verified_assertion_boundaries != set(assertions):
        raise PolicyCandidateAuthorityConflictError(
            "checkpoint assertion set is not the exact streamed boundary set"
        )
    pilot = loads(contract["pilot_restrictions_json"], None)
    total_expansions = int(
        aggregate["totals"]["authorityExpansionObservations"]
    )
    write_expansions = int(
        aggregate["totals"]["authorityExpansionWriteObservations"]
    )
    if contract["analysis_mode"] == "no-expansion":
        pilot_total_limit = 0
        pilot_write_limit = 0
        pilot_exact = pilot == {"mode": "not-applicable"}
    else:
        pilot_exact_object = _candidate_authority_strict_object(
            "checkpoint constrained pilot restrictions",
            pilot,
            frozenset(
                {
                    "mode",
                    "principalSetRootSha256",
                    "routeSetRootSha256",
                    "maximumRequests",
                    "maximumDurationNanos",
                    "maximumWriteRequests",
                    "cells",
                }
            ),
        )
        pilot_total_limit = _candidate_authority_int(
            "checkpoint pilot total limit",
            pilot_exact_object["maximumRequests"],
            minimum=1,
        )
        pilot_write_limit = _candidate_authority_int(
            "checkpoint pilot write limit",
            pilot_exact_object["maximumWriteRequests"],
        )
        pilot_exact = (
            pilot_exact_object["mode"] == "constrained"
            and pilot_exact_object["cells"]
            == [authorized_cells[key] for key in sorted(authorized_cells)]
        )
    if (
        not pilot_exact
        or total_expansions > pilot_total_limit
        or write_expansions > pilot_write_limit
        or (
            contract["analysis_mode"] == "no-expansion"
            and (
                total_expansions != 0
                or any(
                    count
                    for cell, count in aggregate[
                        "semanticMatrix"
                    ].items()
                    if tuple(cell.split(":", 1))
                    in _POLICY_AUTHORITY_EXPANDING_TRANSITIONS
                )
            )
        )
    ):
        raise PolicyCandidateAuthorityConflictError(
            "checkpoint expansion totals exceed signed pilot authority"
        )
    observation_root = _policy_shadow_merkle_accumulator_root(
        observation_levels
    )
    ingress_root = _policy_shadow_merkle_accumulator_root(ingress_levels)
    active_root = _policy_shadow_merkle_accumulator_root(active_levels)
    custody_evidence_root = _policy_shadow_merkle_accumulator_root(
        custody_evidence_levels
    )
    custody_verification_root = _policy_shadow_merkle_accumulator_root(
        custody_verification_levels
    )
    principal_root = _policy_shadow_merkle_accumulator_root(
        principal_levels
    )
    route_root = _policy_shadow_merkle_accumulator_root(route_levels)
    return _policy_canary_checkpoint_snapshot_values(
        aggregate=aggregate,
        sequence_end=sequence_end,
        observation_window=observation_window,
        first_ingress_sequence=first_ingress_sequence,
        first_observation_envelope_digest=str(
            first_row["shadow_observation_envelope_digest"]
        ),
        last_observation_envelope_digest=str(
            last_row["shadow_observation_envelope_digest"]
        ),
        first_observed_at_epoch_ns=int(
            first_row["observed_at_epoch_ns"]
        ),
        last_observed_at_epoch_ns=int(
            last_row["observed_at_epoch_ns"]
        ),
        verified_evidence_bytes=verified_evidence_bytes,
        verification_work_units=verification_work_units,
        lane_gaps=lane_gaps,
        observation_root=observation_root,
        ingress_root=ingress_root,
        active_root=active_root,
        custody_evidence_root=custody_evidence_root,
        custody_verification_root=custody_verification_root,
        principal_root=principal_root,
        route_root=route_root,
    )


