def _verify_policy_checkpoint_heartbeat_contract(
    conn: Any,
    *,
    item: Mapping[str, Any],
    context: Mapping[str, Any],
    heartbeat_wires: list[Any],
    _controlled_state: Any | None = None,
) -> dict[str, Any]:
    from serverware import authority_transition_policy_canary_reads as controlled
    controlled.owner(_controlled_state, conn)
    checkpoint_payload = loads(item["checkpoint_payload_json"], None)
    cumulative_range = _candidate_authority_strict_object(
        "checkpoint cumulative range",
        checkpoint_payload["cumulativeRange"],
        frozenset(
            {
                "firstObservationSequence",
                "lastObservationSequence",
                "firstObservationSha256",
                "lastObservationSha256",
                "firstIngressSequence",
                "lastIngressSequence",
                "firstObservedAtUnixNanos",
                "lastObservedAtUnixNanos",
                "observationCount",
                "ingressCount",
                "verifiedEvidenceBytes",
                "verificationWorkUnits",
                "cumulativeObservationRootSha256",
                "cumulativeIngressRootSha256",
                "cumulativeActiveDecisionRootSha256",
                "cumulativePrincipalAuthorityRootSha256",
                "cumulativeRouteAuthorityRootSha256",
            }
        ),
    )
    expected_range = {
        "firstObservationSequence": item["observation_sequence_start"],
        "lastObservationSequence": item["observation_sequence_end"],
        "firstObservationSha256":
            item["first_observation_envelope_digest"],
        "lastObservationSha256":
            item["last_observation_envelope_digest"],
        "firstIngressSequence": item["request_sequence_start"],
        "lastIngressSequence": item["request_sequence_end"],
        "firstObservedAtUnixNanos":
            item["first_observed_at_epoch_ns"],
        "lastObservedAtUnixNanos": item["last_observed_at_epoch_ns"],
        "observationCount": item["observed_request_count"],
        "ingressCount": item["ingress_count"],
        "verifiedEvidenceBytes": item["verified_evidence_bytes"],
        "verificationWorkUnits": item["verification_work_units"],
        "cumulativeObservationRootSha256":
            item["observation_root_digest"],
        "cumulativeIngressRootSha256": item["ingress_root_digest"],
        "cumulativeActiveDecisionRootSha256":
            item["active_decision_root_digest"],
        "cumulativePrincipalAuthorityRootSha256":
            item["principal_authority_root_digest"],
        "cumulativeRouteAuthorityRootSha256":
            item["route_authority_root_digest"],
    }
    if cumulative_range != expected_range:
        raise PolicyCandidateAuthorityConflictError(
            "checkpoint direct cumulative range differs from stored projection"
        )
    if (
        checkpoint_payload["cumulativeCounters"]
        != loads(item["aggregate_counters_json"], None)
    ):
        raise PolicyCandidateAuthorityConflictError(
            "checkpoint signed cumulative counters differ from stored aggregate"
        )
    heartbeat_range = _candidate_authority_strict_object(
        "checkpoint cumulative heartbeat range",
        checkpoint_payload["cumulativeHeartbeats"],
        frozenset(
            {
                "firstHeartbeatSequence",
                "lastHeartbeatSequence",
                "heartbeatCount",
                "firstHeartbeatAtUnixNanos",
                "lastHeartbeatAtUnixNanos",
                "maximumObservedGapNanos",
                "cumulativeHeartbeatRootSha256",
            }
        ),
    )
    window = loads(context["observation_window_json"], None)
    load_payload = loads(context["load_receipt_payload_json"], None)
    runtime_identity = checkpoint_payload["runtimeIdentity"]
    generation = checkpoint_payload["generation"]
    if (
        runtime_identity != load_payload["runtimeIdentity"]
        or checkpoint_payload["assignmentSha256"]
        != item["assignment_envelope_digest"]
        or checkpoint_payload["assignmentPayloadSha256"]
        != item["assignment_payload_digest"]
        or checkpoint_payload["assignmentRevision"]
        != item["assignment_revision"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "checkpoint runtime, assignment, or load identity drifted"
        )
    maximum_gap = _candidate_authority_int(
        "maximumHeartbeatGapNanos",
        window["maximumHeartbeatGapNanos"],
        minimum=1,
    )
    ingress_range_start_sequence = _candidate_authority_int(
        "heartbeat generation ingressRangeStartSequence",
        _policy_shadow_payload_path(
            checkpoint_payload,
            ("generation", "ingressRangeStartSequence"),
        ),
        minimum=1,
    )
    ingress_range_predecessor_head_digest = (
        _candidate_authority_digest(
            "heartbeat generation ingressRangePredecessorHeadSha256",
            _policy_shadow_payload_path(
                checkpoint_payload,
                (
                    "generation",
                    "ingressRangePredecessorHeadSha256",
                ),
            ),
        )
    )
    if ingress_range_start_sequence != _candidate_authority_int(
        "heartbeat assignment firstIngressSequence",
        window["firstIngressSequence"],
        minimum=1,
    ):
        raise PolicyCandidateAuthorityConflictError(
            "heartbeat ingress range start differs from its assignment"
        )
    coverage_start = max(
        int(context["loaded_at_epoch_ns"]),
        int(window["startsAtUnixNanos"]),
    )
    cumulative_ingress_rows = iter(
        controlled.joined_observations(_controlled_state, item, item["observation_sequence_end"])
        if _controlled_state is not None else
        conn.execute(
            "SELECT shadow.observation_sequence, "
            "ingress.ingress_sequence, ingress.ingress_envelope_digest, "
            "ingress.observed_at_epoch_ns "
            "FROM policy_canary_shadow_observations AS shadow "
            "JOIN policy_canary_ingress_observations AS ingress "
            "ON ingress.canary_id = shadow.canary_id "
            "AND ingress.instance_id = shadow.instance_id "
            "AND ingress.boot_id = shadow.boot_id "
            "AND ingress.ingress_sequence = shadow.ingress_sequence "
            "AND ingress.ingress_envelope_digest = "
            "shadow.ingress_envelope_digest "
            "AND ingress.ingress_payload_digest = "
            "shadow.ingress_payload_digest "
            "WHERE shadow.canary_id = ? AND shadow.instance_id = ? "
            "AND shadow.boot_id = ? "
            "AND shadow.observation_sequence <= ? "
            "ORDER BY shadow.observation_sequence LIMIT ?",
            (
                item["canary_id"],
                item["instance_id"],
                item["boot_id"],
                item["observation_sequence_end"],
                int(item["observation_sequence_end"]) + 1,
            ),
        )
    )
    pending_ingress = next(cumulative_ingress_rows, None)
    expected_observation_sequence = 0
    expected_ingress: tuple[int, str] | None = None
    previous_digest = generation["generationId"]
    previous_time = coverage_start
    previous_ingress_sequence: int | None = None
    maximum_observed_gap = 0
    heartbeat_leaves: list[tuple[int, str]] = []
    for sequence, wire in enumerate(heartbeat_wires, start=1):
        components = _policy_shadow_direct_envelope_components(
            f"checkpoint heartbeat {sequence}", wire
        )
        payload = _candidate_authority_strict_object(
            f"checkpoint heartbeat {sequence} payload",
            components["payload"],
            _POLICY_SHADOW_DIRECT_PAYLOAD_FIELDS["heartbeat"],
        )
        observed_at = _candidate_authority_int(
            "heartbeat observedAtUnixNanos",
            payload["observedAtUnixNanos"],
        )
        while (
            pending_ingress is not None
            and int(pending_ingress["observed_at_epoch_ns"])
            <= observed_at
        ):
            expected_observation_sequence += 1
            if (
                int(pending_ingress["observation_sequence"])
                != expected_observation_sequence
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "heartbeat cumulative ingress projection is not contiguous"
                )
            expected_ingress = (
                _candidate_authority_int(
                    "heartbeat expected ingress sequence",
                    pending_ingress["ingress_sequence"],
                    minimum=ingress_range_start_sequence,
                ),
                _candidate_authority_digest(
                    "heartbeat expected ingress evidence digest",
                    pending_ingress["ingress_envelope_digest"],
                ),
            )
            pending_ingress = next(cumulative_ingress_rows, None)
        expected_ingress_state = (
            "observed" if expected_ingress is not None else "no-ingress"
        )
        ingress_state = _candidate_authority_text(
            "heartbeat ingressState",
            payload["ingressState"],
            maximum=32,
        )
        payload_ingress_range_start = _candidate_authority_int(
            "heartbeat ingressRangeStartSequence",
            payload["ingressRangeStartSequence"],
            minimum=1,
        )
        payload_ingress_range_predecessor = _candidate_authority_digest(
            "heartbeat ingressRangePredecessorHeadSha256",
            payload["ingressRangePredecessorHeadSha256"],
        )
        last_ingress_sequence = payload["lastIngressSequence"]
        if last_ingress_sequence is not None:
            last_ingress_sequence = _candidate_authority_int(
                "heartbeat lastIngressSequence",
                last_ingress_sequence,
                minimum=1,
            )
        last_ingress_evidence_digest = payload[
            "lastIngressEvidenceSha256"
        ]
        if last_ingress_evidence_digest is not None:
            last_ingress_evidence_digest = _candidate_authority_digest(
                "heartbeat lastIngressEvidenceSha256",
                last_ingress_evidence_digest,
            )
        if (
            ingress_state not in {"no-ingress", "observed"}
            or (
                ingress_state == "no-ingress"
                and (
                    last_ingress_sequence is not None
                    or last_ingress_evidence_digest is not None
                )
            )
            or (
                ingress_state == "observed"
                and (
                    last_ingress_sequence is None
                    or last_ingress_evidence_digest is None
                    or last_ingress_sequence
                    < payload_ingress_range_start
                )
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "heartbeat ingress state is not the exact Rust tagged shape"
            )
        controlled.runtime_values(
            _controlled_state, conn, evidence_kind="heartbeat",
            assignment_envelope_digest=item[
                "assignment_envelope_digest"
            ],
            member_ordinal=item["member_ordinal"],
            canary_id=item["canary_id"],
            fleet_id=item["fleet_id"],
            membership_revision=item["membership_revision"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
            envelope_json=components["envelope_json"],
            envelope_digest=components["envelope_digest"],
            payload_json=components["payload_json"],
            payload_digest=components["payload_digest"],
            signature_algorithm=components["signature_algorithm"],
            signing_key_id=components["signing_key_id"],
            signature=components["signature"],
            signature_digest=components["signature_digest"],
            record_binding={
                **payload,
                "ingress_state": expected_ingress_state,
                "ingress_range_start_sequence":
                    ingress_range_start_sequence,
                "ingress_range_predecessor_head_digest":
                    ingress_range_predecessor_head_digest,
                "last_ingress_evidence_digest":
                    (
                        expected_ingress[1]
                        if expected_ingress is not None
                        else None
                    ),
            },
        )
        gap = observed_at - previous_time
        if (
            payload["assignmentSha256"]
            != item["assignment_envelope_digest"]
            or payload["assignmentPayloadSha256"]
            != item["assignment_payload_digest"]
            or payload["assignmentRevision"] != item["assignment_revision"]
            or payload["runtimeIdentity"] != runtime_identity
            or payload["generationId"] != generation["generationId"]
            or payload["heartbeatSequence"] != sequence
            or payload["previousHeartbeatSha256"] != previous_digest
            or ingress_state != expected_ingress_state
            or payload_ingress_range_start
            != ingress_range_start_sequence
            or payload_ingress_range_predecessor
            != ingress_range_predecessor_head_digest
            or last_ingress_sequence
            != (
                expected_ingress[0]
                if expected_ingress is not None
                else None
            )
            or last_ingress_evidence_digest
            != (
                expected_ingress[1]
                if expected_ingress is not None
                else None
            )
            or (
                last_ingress_sequence is not None
                and previous_ingress_sequence is not None
                and last_ingress_sequence < previous_ingress_sequence
            )
            or gap < 0
            or gap > maximum_gap
        ):
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint heartbeat continuity or assignment binding failed"
            )
        maximum_observed_gap = max(maximum_observed_gap, gap)
        previous_time = observed_at
        previous_ingress_sequence = last_ingress_sequence
        previous_digest = components["envelope_digest"]
        heartbeat_leaves.append((sequence, previous_digest))

    seal = checkpoint_payload["seal"]
    if not isinstance(seal, dict) or seal.get("state") not in {
        "open",
        "sealed",
    }:
        raise PolicyCandidateAuthorityError(
            "checkpoint seal is not the exact Rust tagged shape"
        )
    if seal["state"] == "open":
        if set(seal) != {"state"}:
            raise PolicyCandidateAuthorityError(
                "open checkpoint seal has unknown fields"
            )
        coverage_close = checkpoint_payload["createdAtUnixNanos"]
        if coverage_close >= window["sealDeadlineUnixNanos"]:
            raise PolicyCandidateAuthorityConflictError(
                "open checkpoint passed the assignment seal deadline"
            )
        seal_result = {
            "sealed": 0,
            "window_closure_envelope_digest": None,
            "seal_root_digest": None,
            "sealed_at_epoch_ns": None,
        }
    else:
        seal = _candidate_authority_strict_object(
            "sealed checkpoint",
            seal,
            frozenset(
                {
                    "state",
                    "sealedAtUnixNanos",
                    "windowClosureSha256",
                    "windowClosure",
                    "sealRootSha256",
                }
            ),
        )
        closure = _policy_shadow_direct_envelope_components(
            "checkpoint window closure", seal["windowClosure"]
        )
        closure_payload = closure["payload"]
        controlled.runtime_values(
            _controlled_state, conn, evidence_kind="window_closure",
            assignment_envelope_digest=item[
                "assignment_envelope_digest"
            ],
            member_ordinal=item["member_ordinal"],
            canary_id=item["canary_id"],
            fleet_id=item["fleet_id"],
            membership_revision=item["membership_revision"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
            envelope_json=closure["envelope_json"],
            envelope_digest=closure["envelope_digest"],
            payload_json=closure["payload_json"],
            payload_digest=closure["payload_digest"],
            signature_algorithm=closure["signature_algorithm"],
            signing_key_id=closure["signing_key_id"],
            signature=closure["signature"],
            signature_digest=closure["signature_digest"],
            record_binding=closure_payload,
        )
        coverage_close = int(window["endsAtUnixNanos"])
        if (
            seal["windowClosureSha256"] != closure["envelope_digest"]
            or seal["sealedAtUnixNanos"] != coverage_close
            or closure_payload["assignmentSha256"]
            != item["assignment_envelope_digest"]
            or closure_payload["assignmentPayloadSha256"]
            != item["assignment_payload_digest"]
            or closure_payload["assignmentRevision"]
            != item["assignment_revision"]
            or closure_payload["runtimeIdentity"] != runtime_identity
            or closure_payload["windowEndsAtUnixNanos"]
            != coverage_close
            or closure_payload["closedAtUnixNanos"] != coverage_close
            or closure_payload["lastIngressSequence"]
            != item["request_sequence_end"]
            or closure_payload["lastHeartbeatSequence"]
            != len(heartbeat_wires)
        ):
            raise PolicyCandidateAuthorityConflictError(
                "window closure is not exact at the assigned trusted-time end"
            )
        expected_heartbeat_root = _policy_shadow_merkle_root(
            heartbeat_leaves
        )
        if (
            closure_payload["cumulativeHeartbeatRootSha256"]
            != expected_heartbeat_root
        ):
            raise PolicyCandidateAuthorityConflictError(
                "window closure heartbeat root is not exact"
            )
        expected_seal_root = _policy_authority_domain_digest(
            b"serverware.policyShadowCheckpointSeal/v1",
            *(
                _candidate_authority_digest_bytes("checkpoint seal", digest)
                for digest in (
                    item["observation_root_digest"],
                    item["ingress_root_digest"],
                    item["active_decision_root_digest"],
                    item["principal_authority_root_digest"],
                    item["route_authority_root_digest"],
                    expected_heartbeat_root,
                    closure["envelope_digest"],
                )
            ),
            coverage_close.to_bytes(8, "big", signed=True),
        )
        if seal["sealRootSha256"] != expected_seal_root:
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint seal root is not the Rust contract digest"
            )
        seal_result = {
            "sealed": 1,
            "window_closure_envelope_digest":
                closure["envelope_digest"],
            "seal_root_digest": expected_seal_root,
            "sealed_at_epoch_ns": coverage_close,
        }
    close_gap = coverage_close - previous_time
    maximum_observed_gap = max(maximum_observed_gap, close_gap)
    heartbeat_root = _policy_shadow_merkle_root(heartbeat_leaves)
    if (
        close_gap < 0
        or close_gap > maximum_gap
        or heartbeat_range["firstHeartbeatSequence"] != 1
        or heartbeat_range["lastHeartbeatSequence"]
        != len(heartbeat_wires)
        or heartbeat_range["heartbeatCount"] != len(heartbeat_wires)
        or heartbeat_range["firstHeartbeatAtUnixNanos"]
        != heartbeat_wires[0]["payload"]["observedAtUnixNanos"]
        or heartbeat_range["lastHeartbeatAtUnixNanos"] != previous_time
        or heartbeat_range["maximumObservedGapNanos"]
        != maximum_observed_gap
        or heartbeat_range["cumulativeHeartbeatRootSha256"]
        != heartbeat_root
    ):
        raise PolicyCandidateAuthorityConflictError(
            "checkpoint cumulative heartbeat coverage is not exact"
        )
    return {
        **seal_result,
        "heartbeat_count": len(heartbeat_wires),
        "last_heartbeat_sequence": len(heartbeat_wires),
        "last_heartbeat_at_epoch_ns": previous_time,
        "maximum_heartbeat_gap_ns": maximum_observed_gap,
        "heartbeat_root_digest": heartbeat_root,
    }


def stage_policy_canary_checkpoint(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
    _controlled_state: Any | None = None,
) -> dict[str, Any]:
    from serverware import authority_transition_policy_canary_reads as controlled
    controlled.owner(_controlled_state, _connection)
    item = _candidate_authority_record(
        "canary checkpoint", record, _POLICY_CANARY_CHECKPOINT_FIELDS
    )
    actor_id = _candidate_authority_text(
        "actor_id", item.pop("actor_id"), maximum=1024
    )
    for field, value in tuple(item.items()):
        if field.endswith("_digest") or field.endswith("_hash"):
            item[field] = _candidate_authority_digest(field, value)
    _candidate_authority_json(
        "checkpoint_envelope_json",
        item["checkpoint_envelope_json"],
        item["checkpoint_envelope_digest"],
    )
    _candidate_authority_json(
        "checkpoint_payload_json",
        item["checkpoint_payload_json"],
        item["checkpoint_payload_digest"],
    )
    heartbeat_evidence_json, heartbeat_evidence_digest = (
        _candidate_authority_json(
            "heartbeat_evidence_json",
            item["heartbeat_evidence_json"],
            item["heartbeat_evidence_digest"],
            maximum=8 * 1024 * 1024,
        )
    )
    heartbeat_wires = loads(heartbeat_evidence_json, None)
    if (
        not isinstance(heartbeat_wires, list)
        or not heartbeat_wires
        or len(heartbeat_wires)
        > _POLICY_AUTHORITY_MAX_OBSERVATIONS_PER_MEMBER
        or heartbeat_evidence_digest != item["heartbeat_evidence_digest"]
    ):
        raise PolicyCandidateAuthorityError(
            "checkpoint heartbeat evidence is empty or exceeds its bound"
        )
    _candidate_authority_signature_fields(item)
    for field in (
        "checkpoint_sequence",
        "assignment_revision",
        "membership_revision",
        "member_ordinal",
        "request_sequence_start",
        "request_sequence_end",
        "observation_sequence_start",
        "observation_sequence_end",
        "observed_request_count",
        "ingress_count",
        "verified_evidence_bytes",
        "verification_work_units",
    ):
        item[field] = _candidate_authority_int(field, item[field], minimum=1)
    for field in (
        "previous_request_sequence_end",
        "previous_observation_sequence_end",
        "evaluated_request_count",
        "dropped_request_count",
        "evaluation_error_count",
        "excluded_request_count",
        "active_permit_count",
        "active_deny_count",
        "active_conditional_count",
        "active_indeterminate_count",
        "candidate_permit_count",
        "candidate_deny_count",
        "candidate_conditional_count",
        "candidate_indeterminate_count",
        "first_observed_at_epoch_ns",
        "last_observed_at_epoch_ns",
        "window_started_at_epoch_ns",
        "window_ended_at_epoch_ns",
        "excluded_count",
        "gap_count",
        "indeterminate_count",
        "response_divergence_count",
        "response_validator_unavailable_count",
    ):
        item[field] = _candidate_authority_int(field, item[field])
    if item["predecessor_checkpoint_sequence"] is not None:
        item["predecessor_checkpoint_sequence"] = _candidate_authority_int(
            "predecessor_checkpoint_sequence",
            item["predecessor_checkpoint_sequence"],
            minimum=1,
        )
    if (
        item["observation_sequence_start"] != 1
        or item["request_sequence_end"] < item["request_sequence_start"]
        or item["observation_sequence_end"] < 1
        or item["observed_request_count"]
        != item["request_sequence_end"] - item["request_sequence_start"] + 1
        or item["observed_request_count"] != item["observation_sequence_end"]
        or item["ingress_count"] != item["observed_request_count"]
        or item["verified_evidence_bytes"]
        > _POLICY_AUTHORITY_MAX_VERIFIED_EVIDENCE_BYTES
        or item["verification_work_units"]
        != (
            item["observed_request_count"]
            * _POLICY_AUTHORITY_VERIFICATION_WORK_UNITS_PER_OBSERVATION
        )
        or item["verification_work_units"]
        > _POLICY_AUTHORITY_MAX_VERIFICATION_WORK_UNITS
        or item["last_observed_at_epoch_ns"]
        < item["first_observed_at_epoch_ns"]
        or item["observed_request_count"]
        != item["evaluated_request_count"]
        + item["dropped_request_count"]
        + item["evaluation_error_count"]
        + item["excluded_request_count"]
        or item["evaluated_request_count"]
        != item["active_permit_count"]
        + item["active_deny_count"]
        + item["active_conditional_count"]
        + item["active_indeterminate_count"]
        or item["evaluated_request_count"]
        != item["candidate_permit_count"]
        + item["candidate_deny_count"]
        + item["candidate_conditional_count"]
        + item["candidate_indeterminate_count"]
        or item["window_ended_at_epoch_ns"] < item["window_started_at_epoch_ns"]
    ):
        raise PolicyCandidateAuthorityError(
            "checkpoint sequence span or counters are inconsistent"
        )
    for field in (
        "aggregate_counters_json",
        "semantic_matrix_json",
        "expansion_cells_json",
        "response_route_coverage_json",
        "latency_histograms_json",
        "drop_counters_json",
        "error_counters_json",
    ):
        _candidate_authority_json(
            field,
            item[field],
            item[field.removesuffix("_json") + "_digest"],
            maximum=_POLICY_AUTHORITY_MAX_CANONICAL_AGGREGATE_BYTES,
        )
    identity = (item["canary_id"], item["instance_id"], item["boot_id"])
    for field in ("canary_id", "member_id", "instance_id", "boot_id"):
        _candidate_authority_text(field, item[field], maximum=256)

    connection_scope = (contextlib.nullcontext(None) if _controlled_state is not None else
        connect() if _connection is None else contextlib.nullcontext(_connection))
    with connection_scope as conn:
        if _controlled_state is None:
            _lock_policy_candidate_authority(conn)
        context = _controlled_state.runtime_context(item) if _controlled_state is not None else _policy_canary_runtime_context(
            conn,
            canary_id=item["canary_id"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
        )
        _require_policy_runtime_context(
            item,
            context,
            (
                "fleet_id",
                "membership_revision",
                "membership_root_digest",
                "member_ordinal",
                "member_id",
                "assignment_envelope_digest",
                "assignment_payload_digest",
                "assignment_revision",
                "load_receipt_envelope_digest",
                "load_receipt_payload_digest",
                "policy_identity_digest",
                "runtime_identity_digest",
            ),
        )
        instance = controlled.instance(_controlled_state, item) if _controlled_state is not None else conn.execute(
            "SELECT instance.assignment_envelope_digest, "
            "instance.assignment_payload_digest, "
            "instance.artifact_envelope_digest, "
            "instance.artifact_payload_digest, "
            "instance.candidate_policy_hash, instance.compiler_digest, "
            "instance.compiler_config_digest, "
            "instance.policy_schema_digest, "
            "instance.semantic_model_digest, "
            "instance.evaluator_abi_digest, "
            "instance.policy_bundle_digest, instance.runtime_digest, "
            "instance.boot_public_key_digest, "
            "instance.boot_signing_key_id, "
            "receipt.load_receipt_envelope_digest, "
            "receipt.load_receipt_payload_digest "
            "FROM policy_canary_instances AS instance "
            "JOIN policy_canary_load_receipts AS receipt "
            "ON receipt.canary_id = instance.canary_id "
            "AND receipt.instance_id = instance.instance_id "
            "AND receipt.boot_id = instance.boot_id "
            "WHERE instance.canary_id = ? AND instance.instance_id = ? "
            "AND instance.boot_id = ?",
            identity,
        ).fetchone()
        exact_instance = {
            "assignment_envelope_digest": "assignment_envelope_digest",
            "assignment_payload_digest": "assignment_payload_digest",
            "load_receipt_envelope_digest": "load_receipt_envelope_digest",
            "load_receipt_payload_digest": "load_receipt_payload_digest",
            "artifact_envelope_digest": "artifact_envelope_digest",
            "artifact_payload_digest": "artifact_payload_digest",
            "candidate_policy_hash": "candidate_policy_hash",
            "compiler_digest": "compiler_digest",
            "compiler_config_digest": "compiler_config_digest",
            "policy_schema_digest": "policy_schema_digest",
            "semantic_model_digest": "semantic_model_digest",
            "evaluator_abi_digest": "evaluator_abi_digest",
            "policy_bundle_digest": "policy_bundle_digest",
            "runtime_digest": "runtime_digest",
            "boot_public_key_digest": "boot_public_key_digest",
            "boot_signing_key_id": "boot_signing_key_id",
        }
        if instance is None or any(
            instance[column] != item[field]
            for field, column in exact_instance.items()
        ):
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint does not bind the exact assigned evaluator instance"
            )
        heartbeat_contract = _verify_policy_checkpoint_heartbeat_contract(
            conn,
            item=item,
            context=context,
            heartbeat_wires=heartbeat_wires,
            _controlled_state=_controlled_state,
        )
        observation_window = loads(
            context["observation_window_json"], None
        )
        expected_window_end = (
            heartbeat_contract["sealed_at_epoch_ns"]
            if heartbeat_contract["sealed"]
            else loads(item["checkpoint_payload_json"], None)[
                "createdAtUnixNanos"
            ]
        )
        if (
            item["window_started_at_epoch_ns"]
            != observation_window["startsAtUnixNanos"]
            or item["window_ended_at_epoch_ns"]
            != expected_window_end
        ):
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint window projection does not match signed window state"
            )
        recomputed = controlled.recompute(
            _controlled_state, conn,
            canary_id=item["canary_id"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
            sequence_end=item["observation_sequence_end"],
        )
        aggregate_exact = (
            "observed_request_count",
            "evaluated_request_count",
            "dropped_request_count",
            "evaluation_error_count",
            "excluded_request_count",
            "active_permit_count",
            "active_deny_count",
            "active_conditional_count",
            "active_indeterminate_count",
            "candidate_permit_count",
            "candidate_deny_count",
            "candidate_conditional_count",
            "candidate_indeterminate_count",
            "aggregate_counters_json",
            "aggregate_counters_digest",
            "semantic_matrix_json",
            "semantic_matrix_digest",
            "expansion_cells_json",
            "expansion_cells_digest",
            "response_route_coverage_json",
            "response_route_coverage_digest",
            "latency_histograms_json",
            "latency_histograms_digest",
            "drop_counters_json",
            "drop_counters_digest",
            "error_counters_json",
            "error_counters_digest",
            "excluded_count",
            "gap_count",
            "indeterminate_count",
            "response_divergence_count",
            "response_validator_unavailable_count",
            "aggregate_contract_digest",
        )
        if (
            item["request_sequence_start"]
            != recomputed["ingress_sequence_start"]
            or item["request_sequence_end"]
            != recomputed["ingress_sequence_end"]
            or item["first_observation_envelope_digest"]
            != recomputed["first_observation_envelope_digest"]
            or item["last_observation_envelope_digest"]
            != recomputed["last_observation_envelope_digest"]
            or item["first_observed_at_epoch_ns"]
            != recomputed["first_observed_at_epoch_ns"]
            or item["last_observed_at_epoch_ns"]
            != recomputed["last_observed_at_epoch_ns"]
            or item["ingress_count"] != recomputed["ingress_count"]
            or item["verified_evidence_bytes"]
            != recomputed["verified_evidence_bytes"]
            or item["verification_work_units"]
            != recomputed["verification_work_units"]
            or item["window_started_at_epoch_ns"]
            != recomputed["assignment_window_started_at_epoch_ns"]
            or item["window_ended_at_epoch_ns"]
            < recomputed["last_observed_at_epoch_ns"]
            or item["window_ended_at_epoch_ns"]
            > recomputed["assignment_seal_deadline_epoch_ns"]
            or item["observation_sequence_end"]
            != recomputed["observation_sequence_end"]
            or item["observation_root_digest"]
            != recomputed["cumulative_observation_root_digest"]
            or item["ingress_root_digest"]
            != recomputed["cumulative_ingress_root_digest"]
            or item["active_decision_root_digest"]
            != recomputed["cumulative_active_decision_root_digest"]
            or item["custody_evidence_root_digest"]
            != recomputed["cumulative_custody_evidence_root_digest"]
            or item["custody_verification_root_digest"]
            != recomputed["cumulative_custody_verification_root_digest"]
            or item["principal_authority_root_digest"]
            != recomputed["cumulative_principal_authority_root_digest"]
            or item["route_authority_root_digest"]
            != recomputed["cumulative_route_authority_root_digest"]
            or any(item[field] != recomputed[field] for field in aggregate_exact)
        ):
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint signed aggregate is not the recomputed evidence prefix"
            )
        verified = controlled.runtime_values(
            _controlled_state, conn, evidence_kind="checkpoint",
            assignment_envelope_digest=item["assignment_envelope_digest"],
            member_ordinal=item["member_ordinal"],
            canary_id=item["canary_id"],
            fleet_id=item["fleet_id"],
            membership_revision=item["membership_revision"],
            instance_id=item["instance_id"],
            boot_id=item["boot_id"],
            envelope_json=item["checkpoint_envelope_json"],
            envelope_digest=item["checkpoint_envelope_digest"],
            payload_json=item["checkpoint_payload_json"],
            payload_digest=item["checkpoint_payload_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                {**item, "actor_id": actor_id},
                current_prefix="checkpoint",
            ),
        )
        controlled.apply_values(item, verified)
        if (
            item["window_ended_at_epoch_ns"]
            != int(verified["issued_at_epoch_ns"])
            or int(verified["issued_at_epoch_ns"])
            > recomputed["assignment_seal_deadline_epoch_ns"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint time is outside its signed observation window"
            )
        instance_head = (_controlled_state.one("policy_canary_instance_heads", optional=True,
            canary_id=item["canary_id"], instance_id=item["instance_id"], boot_id=item["boot_id"])) if _controlled_state is not None else conn.execute(
            "SELECT canary_id, instance_id, boot_id, head_revision, "
            "head_state_digest, status, updated_at_epoch_ns "
            "FROM policy_canary_instance_heads "
            "WHERE canary_id = ? AND instance_id = ? AND boot_id = ?",
            identity,
        ).fetchone()
        if instance_head is None or str(instance_head["status"]) != "observing":
            raise PolicyCandidateAuthorityConflictError(
                "checkpoint append requires an observing instance head"
            )
        head = (_controlled_state.one("policy_canary_checkpoint_heads", optional=True,
            canary_id=item["canary_id"], instance_id=item["instance_id"], boot_id=item["boot_id"])) if _controlled_state is not None else conn.execute(
            "SELECT canary_id, instance_id, boot_id, "
            "checkpoint_sequence, checkpoint_envelope_digest, "
            "checkpoint_payload_digest, observation_root_digest, "
            "request_sequence_end, observation_sequence_end, sealed, "
            "sealed_at_epoch_ns, updated_at_epoch_ns "
            "FROM policy_canary_checkpoint_heads "
            "WHERE canary_id = ? AND instance_id = ? AND boot_id = ?",
            identity,
        ).fetchone()
        if head is None:
            empty_root = _policy_shadow_merkle_root([])
            if (
                item["checkpoint_sequence"] != 1
                or item["predecessor_checkpoint_sequence"] is not None
                or item["previous_checkpoint_digest"]
                != item["assignment_payload_digest"]
                or item["previous_observation_digest"]
                != item["load_receipt_payload_digest"]
                or item["previous_ingress_root_digest"] != empty_root
                or item["previous_active_decision_root_digest"]
                != empty_root
                or item["request_sequence_start"]
                != recomputed["ingress_sequence_start"]
                or item["previous_request_sequence_end"]
                != item["request_sequence_start"] - 1
                or item["observation_sequence_start"] != 1
                or item["previous_observation_sequence_end"] != 0
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "first checkpoint is not anchored to assignment/load sequence one"
                )
        else:
            if bool(head["sealed"]):
                raise PolicyCandidateAuthorityConflictError(
                    "checkpoint head is sealed"
                )
            previous_checkpoint = controlled.checkpoint(_controlled_state, item, head["checkpoint_sequence"]) if _controlled_state is not None else conn.execute(
                "SELECT "
                + _policy_authority_projection(
                    tuple(
                        field
                        for field in _POLICY_CANARY_CHECKPOINT_FIELDS
                        if field != "actor_id"
                    )
                )
                + " FROM policy_canary_checkpoints "
                "WHERE canary_id = ? AND instance_id = ? AND boot_id = ? "
                "AND checkpoint_sequence = ?",
                (*identity, head["checkpoint_sequence"]),
            ).fetchone()
            cumulative_fields = (
                "observed_request_count",
                "evaluated_request_count",
                "dropped_request_count",
                "evaluation_error_count",
                "excluded_request_count",
                "active_permit_count",
                "active_deny_count",
                "active_conditional_count",
                "active_indeterminate_count",
                "candidate_permit_count",
                "candidate_deny_count",
                "candidate_conditional_count",
                "candidate_indeterminate_count",
            )
            if (
                previous_checkpoint is None
                or item["checkpoint_sequence"]
                != int(head["checkpoint_sequence"]) + 1
                or item["predecessor_checkpoint_sequence"]
                != int(head["checkpoint_sequence"])
                or item["previous_checkpoint_digest"]
                != head["checkpoint_envelope_digest"]
                or item["previous_observation_digest"]
                != head["observation_root_digest"]
                or item["previous_ingress_root_digest"]
                != previous_checkpoint["ingress_root_digest"]
                or item["previous_active_decision_root_digest"]
                != previous_checkpoint["active_decision_root_digest"]
                or item["request_sequence_start"]
                != recomputed["ingress_sequence_start"]
                or item["previous_request_sequence_end"]
                != int(head["request_sequence_end"])
                or item["request_sequence_end"]
                <= int(head["request_sequence_end"])
                or item["observation_sequence_start"] != 1
                or item["previous_observation_sequence_end"]
                != int(head["observation_sequence_end"])
                or item["observation_sequence_end"]
                <= int(head["observation_sequence_end"])
                or item["window_started_at_epoch_ns"]
                != int(previous_checkpoint["window_started_at_epoch_ns"])
                or any(
                    item[field] < int(previous_checkpoint[field])
                    for field in cumulative_fields
                )
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "checkpoint is not the exact contiguous successor"
                )
        transition_digest = controlled.transition(
            _controlled_state, conn, event_type="policy.canary_checkpoint.staged",
            entity_kind="checkpoint",
            entity_id=(
                f"{item['canary_id']}/{item['instance_id']}/"
                f"{item['boot_id']}/{item['checkpoint_sequence']}"
            ),
            entity_revision=item["checkpoint_sequence"],
            state_digest=item["checkpoint_payload_digest"],
            previous_state_digest=item["previous_checkpoint_digest"],
            actor_id=actor_id,
            evidence={
                "checkpointEnvelopeDigest": item["checkpoint_envelope_digest"],
                "checkpointPayloadDigest": item["checkpoint_payload_digest"],
                "observationRootDigest": item["observation_root_digest"],
                "aggregateContractDigest":
                    item["aggregate_contract_digest"],
                "semanticMatrixDigest": item["semantic_matrix_digest"],
                "principalAuthorityRootDigest":
                    item["principal_authority_root_digest"],
                "routeAuthorityRootDigest":
                    item["route_authority_root_digest"],
                "custodyEvidenceRootDigest":
                    item["custody_evidence_root_digest"],
                "custodyVerificationRootDigest":
                    item["custody_verification_root_digest"],
                "verifiedEvidenceBytes": item["verified_evidence_bytes"],
                "verificationWorkUnits": item["verification_work_units"],
                "requestSequenceStart": item["request_sequence_start"],
                "requestSequenceEnd": item["request_sequence_end"],
            },
            created_at_epoch_ns=item["window_ended_at_epoch_ns"],
        )
        checkpoint = {
            **{
                field: value
                for field, value in item.items()
                if field
                not in _POLICY_CANARY_CHECKPOINT_AGGREGATE_INPUT_FIELDS
            },
            "created_transition_digest": transition_digest,
        }
        if _controlled_state is None:
            _insert_immutable_candidate_row(conn, table="policy_canary_checkpoints", columns=tuple(checkpoint), values=checkpoint,
                key_columns=("canary_id", "instance_id", "boot_id", "checkpoint_sequence"))
        else:
            _controlled_state.put("policy_canary_checkpoints", checkpoint)
        aggregate_row = {
            "canary_id": item["canary_id"],
            "instance_id": item["instance_id"],
            "boot_id": item["boot_id"],
            "checkpoint_sequence": item["checkpoint_sequence"],
            "checkpoint_envelope_digest":
                item["checkpoint_envelope_digest"],
            "checkpoint_payload_digest": item["checkpoint_payload_digest"],
            **{
                column: recomputed[column]
                for column in _POLICY_CANARY_CHECKPOINT_AGGREGATE_COLUMNS
            },
            "sealed": heartbeat_contract["sealed"],
            "window_closure_envelope_digest":
                heartbeat_contract[
                    "window_closure_envelope_digest"
                ],
            "seal_root_digest": heartbeat_contract["seal_root_digest"],
            "sealed_at_epoch_ns":
                heartbeat_contract["sealed_at_epoch_ns"],
        }
        if _controlled_state is not None:
            _controlled_state.put("policy_canary_checkpoint_aggregates", aggregate_row)
            _controlled_state.put("policy_canary_checkpoint_heads", {
                **{name: item[name] for name in ("canary_id", "instance_id", "boot_id", "checkpoint_sequence", "checkpoint_envelope_digest",
                    "checkpoint_payload_digest", "observation_root_digest", "request_sequence_end", "observation_sequence_end")},
                "sealed": heartbeat_contract["sealed"], "sealed_at_epoch_ns": heartbeat_contract["sealed_at_epoch_ns"],
                "updated_at_epoch_ns": item["window_ended_at_epoch_ns"]}, replace=True)
            return dict(checkpoint)
        _insert_immutable_candidate_row(
            conn,
            table="policy_canary_checkpoint_aggregates",
            columns=tuple(aggregate_row),
            values=aggregate_row,
            key_columns=(
                "canary_id",
                "instance_id",
                "boot_id",
                "checkpoint_sequence",
            ),
        )
        if head is None:
            conn.execute(
                "INSERT INTO policy_canary_checkpoint_heads "
                "(canary_id, instance_id, boot_id, checkpoint_sequence, "
                "checkpoint_envelope_digest, checkpoint_payload_digest, "
                "observation_root_digest, request_sequence_end, "
                "observation_sequence_end, sealed, sealed_at_epoch_ns, "
                "updated_at_epoch_ns) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    *identity, item["checkpoint_sequence"],
                    item["checkpoint_envelope_digest"],
                    item["checkpoint_payload_digest"],
                    item["observation_root_digest"],
                    item["request_sequence_end"],
                    item["observation_sequence_end"],
                    heartbeat_contract["sealed"],
                    heartbeat_contract["sealed_at_epoch_ns"],
                    item["window_ended_at_epoch_ns"],
                ),
            )
        else:
            updated = conn.execute(
                "UPDATE policy_canary_checkpoint_heads SET "
                "checkpoint_sequence = ?, checkpoint_envelope_digest = ?, "
                "checkpoint_payload_digest = ?, observation_root_digest = ?, "
                "request_sequence_end = ?, observation_sequence_end = ?, "
                "sealed = ?, sealed_at_epoch_ns = ?, "
                "updated_at_epoch_ns = ? WHERE canary_id = ? "
                "AND instance_id = ? AND boot_id = ? AND sealed = 0 "
                "AND checkpoint_sequence = ? AND checkpoint_envelope_digest = ? "
                "AND checkpoint_payload_digest = ?",
                (
                    item["checkpoint_sequence"],
                    item["checkpoint_envelope_digest"],
                    item["checkpoint_payload_digest"],
                    item["observation_root_digest"],
                    item["request_sequence_end"],
                    item["observation_sequence_end"],
                    heartbeat_contract["sealed"],
                    heartbeat_contract["sealed_at_epoch_ns"],
                    item["window_ended_at_epoch_ns"],
                    *identity,
                    head["checkpoint_sequence"],
                    head["checkpoint_envelope_digest"],
                    head["checkpoint_payload_digest"],
                ),
            )
            if updated.rowcount != 1:
                raise PolicyCandidateAuthorityConflictError(
                    "checkpoint head changed during CAS append"
                )
    return dict(checkpoint)


