def stage_policy_compiler_authority_analysis(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
) -> dict[str, Any]:
    item = _candidate_authority_record(
        "compiler authority analysis",
        record,
        _POLICY_COMPILER_AUTHORITY_ANALYSIS_FIELDS,
    )
    actor_id = _candidate_authority_text(
        "compiler analysis actor_id",
        item.pop("actor_id"),
        maximum=1024,
    )
    for field, value in tuple(item.items()):
        if field.endswith("_digest") or field.endswith("_hash"):
            item[field] = _candidate_authority_digest(field, value)
    item["assignment_revision"] = _candidate_authority_int(
        "assignment_revision", item["assignment_revision"], minimum=1
    )
    item["required_approval_quorum"] = _candidate_authority_int(
        "required_approval_quorum",
        item["required_approval_quorum"],
        minimum=1,
        maximum=2,
    )
    _candidate_authority_json(
        "expansion_cells_json",
        item["expansion_cells_json"],
        item["expansion_cells_digest"],
        maximum=_POLICY_AUTHORITY_MAX_CANONICAL_AGGREGATE_BYTES,
    )
    _candidate_authority_json(
        "pilot_restrictions_json",
        item["pilot_restrictions_json"],
        item["pilot_restrictions_digest"],
    )
    expansion_cells = loads(item["expansion_cells_json"], None)
    if (
        not isinstance(expansion_cells, list)
        or len(expansion_cells) > _POLICY_AUTHORITY_MAX_EXPANSION_CELLS
    ):
        raise PolicyCandidateAuthorityError(
            "compiler expansion cells exceed their fixed bound"
        )
    previous_digest = ""
    maximum_compiler_requests = 0
    maximum_compiler_write_requests = 0
    normalized_cells: list[dict[str, Any]] = []
    for index, entry in enumerate(expansion_cells):
        cell = _policy_authority_semantic_expansion_cell(
            f"compiler expansion semantics {index}",
            entry,
        )
        digest = cell["cellSha256"]
        if (
            digest <= previous_digest
            or cell["routeAuthorityRootSha256"]
            != item["route_authority_root_digest"]
            or cell["operationAuthorityRootSha256"]
            != item["operation_authority_root_digest"]
        ):
            raise PolicyCandidateAuthorityError(
                "compiler expansion cell is not canonical and authority-expanding"
            )
        previous_digest = digest
        maximum_compiler_requests += int(cell["maximumRequests"])
        if cell["requestAuthorityClass"] == "write":
            maximum_compiler_write_requests += int(
                cell["maximumWriteRequests"]
            )
        normalized_cells.append(cell)
    pilot = loads(item["pilot_restrictions_json"], None)
    if not isinstance(pilot, dict):
        raise PolicyCandidateAuthorityError(
            "compiler pilot restrictions are not a tagged object"
        )
    if item["analysis_mode"] == "no-expansion":
        if (
            item["approval_mode"] != "none"
            or item["required_approval_quorum"] != 1
            or expansion_cells
            or pilot != {"mode": "not-applicable"}
        ):
            raise PolicyCandidateAuthorityError(
                "no-expansion compiler analysis carries expansion authority"
            )
    elif item["analysis_mode"] == "approved-expansion":
        pilot = _candidate_authority_strict_object(
            "compiler constrained pilot restrictions",
            pilot,
            frozenset(
                {
                    "mode",
                    "principalSetRootSha256",
                    "routeSetRootSha256",
                    "maximumRequests",
                    "maximumDurationNanos",
                    "maximumWriteRequests",
                    "cells",
                }
            ),
        )
        derived_quorum = (
            2
            if item["approval_mode"]
            == "two-person-hardware-webauthn"
            else 1
            if item["approval_mode"]
            == "single-person-hardware-webauthn"
            else 0
        )
        maximum_requests = _candidate_authority_int(
            "pilot maximumRequests",
            pilot["maximumRequests"],
            minimum=1,
        )
        maximum_duration = _candidate_authority_int(
            "pilot maximumDurationNanos",
            pilot["maximumDurationNanos"],
            minimum=1,
        )
        maximum_write_requests = _candidate_authority_int(
            "pilot maximumWriteRequests",
            pilot["maximumWriteRequests"],
        )
        _candidate_authority_digest(
            "pilot principalSetRootSha256",
            pilot["principalSetRootSha256"],
        )
        _candidate_authority_digest(
            "pilot routeSetRootSha256",
            pilot["routeSetRootSha256"],
        )
        if (
            not expansion_cells
            or pilot["mode"] != "constrained"
            or pilot["cells"] != normalized_cells
            or derived_quorum != item["required_approval_quorum"]
            or maximum_duration <= 0
            or maximum_write_requests > maximum_requests
            or maximum_requests
            > maximum_compiler_requests
            or maximum_write_requests
            > maximum_compiler_write_requests
        ):
            raise PolicyCandidateAuthorityError(
                "approved expansion compiler authority is not exact"
            )
    else:
        raise PolicyCandidateAuthorityError(
            "compiler analysis mode is invalid"
        )
    _candidate_authority_json(
        "analysis_envelope_json",
        item["analysis_envelope_json"],
        item["analysis_envelope_digest"],
    )
    _candidate_authority_json(
        "analysis_payload_json",
        item["analysis_payload_json"],
        item["analysis_payload_digest"],
        maximum=4 * 1024 * 1024,
    )
    _candidate_authority_signature_fields(item)
    if actor_id != item["signing_key_id"]:
        raise PolicyCandidateAuthorityError(
            "compiler analysis actor is not its signed authority key"
        )
    with (
        connect()
        if _connection is None
        else contextlib.nullcontext(_connection)
    ) as conn:
        _lock_policy_candidate_authority(conn)
        assignment = conn.execute(
            "SELECT assignment_payload_digest, assignment_revision, "
            "canary_id, artifact_envelope_digest, "
            "artifact_payload_digest, compiler_digest, "
            "compiler_config_digest, policy_schema_digest, "
            "semantic_model_digest, response_obligations_digest, "
            "expected_snapshots_json "
            "FROM policy_canary_assignments "
            "WHERE assignment_envelope_digest = ?",
            (item["assignment_envelope_digest"],),
        ).fetchone()
        exact = (
            "assignment_payload_digest",
            "assignment_revision",
            "canary_id",
            "artifact_envelope_digest",
            "artifact_payload_digest",
            "compiler_digest",
            "compiler_config_digest",
            "policy_schema_digest",
            "semantic_model_digest",
            "response_obligations_digest",
        )
        if assignment is None or any(
            assignment[field] != item[field] for field in exact
        ):
            raise PolicyCandidateAuthorityConflictError(
                "compiler analysis does not bind the exact assignment"
            )
        verified = _verify_policy_authority_evidence(
            conn,
            evidence_kind="compiler_analysis",
            envelope_json=item["analysis_envelope_json"],
            envelope_digest=item["analysis_envelope_digest"],
            payload_json=item["analysis_payload_json"],
            payload_digest=item["analysis_payload_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                item, current_prefix="analysis"
            ),
        )
        _apply_policy_authority_verification(item, verified)
        analysis_payload = loads(item["analysis_payload_json"], None)
        if (
            analysis_payload["expectedLoadedSnapshots"]
            != loads(assignment["expected_snapshots_json"], None)
            or analysis_payload[
                "responseValidationObligationsRootSha256"
            ]
            != assignment["response_obligations_digest"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "compiler analysis does not bind assignment snapshots and "
                "response obligations exactly"
            )
        item["issued_at_epoch_ns"] = verified.values["issued_at_epoch_ns"]
        item["expires_at_epoch_ns"] = verified.values["expires_at_epoch_ns"]
        _insert_immutable_candidate_row(
            conn,
            table="policy_compiler_authority_analyses",
            columns=tuple(item),
            values=item,
            key_columns=("analysis_envelope_digest",),
        )
    return dict(item)


def _policy_authority_current_trust_checkpoint(
    conn: Any,
    *,
    as_of_epoch_ns: int,
) -> dict[str, Any]:
    """Derive the signed readiness trust snapshot from current revocations."""
    as_of_epoch_ns = _candidate_authority_int(
        "trust checkpoint as-of time", as_of_epoch_ns
    )
    leaves: list[tuple[int, str]] = []
    generation = 0
    row_count = 0
    queries = (
        (
            "authority-key",
            "SELECT evidence_kind, signing_key_id, key_revision, "
            "public_key_digest, revocation_sequence, revocation_digest, "
            "revoked_at_epoch_ns FROM policy_authority_trusted_key_revocations "
            "ORDER BY revocation_sequence, evidence_kind, signing_key_id "
            "LIMIT ?",
            _POLICY_AUTHORITY_READ_MAX_ROWS + 1,
        ),
        (
            "runtime-role-key",
            "SELECT assignment_envelope_digest, member_ordinal, canary_id, "
            "fleet_id, membership_revision, membership_root_digest, "
            "member_id, instance_id, boot_id, role, public_key_digest, "
            "attestation_receipt_envelope_digest, "
            "tee_measurement_digest, authorization_digest, "
            "revocation_sequence, revocation_envelope_digest, "
            "revoked_at_epoch_ns FROM policy_runtime_role_key_revocations "
            "ORDER BY revocation_sequence, assignment_envelope_digest, "
            "member_ordinal, role, public_key_digest LIMIT ?",
            _POLICY_AUTHORITY_READ_MAX_ROWS + 1,
        ),
        (
            "rollback-authority",
            "SELECT rollback_authorization_envelope_digest, "
            "rollback_authorization_payload_digest, "
            "revocation_envelope_digest, revocation_payload_digest, "
            "canary_id, candidate_policy_hash, candidate_policy_sequence, "
            "candidate_rollback_epoch, revoked_at_epoch_ns "
            "FROM policy_activation_rollback_authority_revocations "
            "ORDER BY revoked_at_epoch_ns, revocation_envelope_digest LIMIT ?",
            _POLICY_AUTHORITY_READ_MAX_ROWS + 1,
        ),
    )
    for source, statement, limit in queries:
        source_rows = 0
        for row in conn.execute(statement, (limit,)):
            source_rows += 1
            row_count += 1
            if (
                source_rows > _POLICY_AUTHORITY_READ_MAX_ROWS
                or row_count > _POLICY_AUTHORITY_READ_MAX_ROWS
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "trust checkpoint revocation set exceeds its fixed bound"
                )
            material = {
                "source": source,
                "record": dict(row),
            }
            revoked_at = _candidate_authority_int(
                f"{source} revoked_at_epoch_ns",
                material["record"]["revoked_at_epoch_ns"],
            )
            if revoked_at > as_of_epoch_ns:
                raise PolicyCandidateAuthorityConflictError(
                    "readiness trust checkpoint predates a current revocation"
                )
            generation += 1
            leaves.append(
                (
                    generation,
                    _candidate_authority_sha256(
                        dumps(material).encode("ascii")
                    ),
                )
            )
    revocation_root = _policy_shadow_merkle_root(leaves)
    checkpoint = {
        "checkpointId": _policy_authority_domain_digest(
            b"serverware.policyTrustCheckpoint/v1",
            as_of_epoch_ns.to_bytes(8, "big"),
            generation.to_bytes(8, "big"),
            _candidate_authority_digest_bytes(
                "trust checkpoint revocation root", revocation_root
            ),
        ),
        "asOfUnixNanos": as_of_epoch_ns,
        "revocationGeneration": generation,
        "revocationRootSha256": revocation_root,
    }
    return checkpoint


