def stage_policy_canary_readiness(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
    _controlled_state: Any | None = None,
) -> dict[str, Any]:
    from serverware import authority_transition_policy_canary_reads as controlled
    from serverware import authority_transition_policy_canary_current as current
    controlled.owner(_controlled_state, _connection)
    if _controlled_state is None:
        _require_postgres_policy_authority("secure canary readiness")
    item = _candidate_authority_record(
        "canary readiness", record, _POLICY_CANARY_READINESS_FIELDS
    )
    actor_id = _candidate_authority_text(
        "actor_id", item.pop("actor_id"), maximum=1024
    )
    for field, value in tuple(item.items()):
        if (field.endswith("_digest") or field.endswith("_hash")) and value is not None:
            item[field] = _candidate_authority_digest(field, value)
    _candidate_authority_json(
        "readiness_envelope_json",
        item["readiness_envelope_json"],
        item["readiness_envelope_digest"],
    )
    _candidate_authority_json(
        "readiness_payload_json",
        item["readiness_payload_json"],
        item["readiness_payload_digest"],
    )
    _candidate_authority_signature_fields(item)
    for field in (
        "predecessor_canary_revision",
        "designated_ready_revision",
        "candidate_policy_sequence",
        "candidate_rollback_epoch",
        "required_approval_quorum",
        "publication_revision",
        "expected_active_policy_sequence",
        "expected_instance_count",
        "sealed_instance_count",
        "observed_request_count",
    ):
        item[field] = _candidate_authority_int(field, item[field], minimum=1)
    for field in (
        "evaluated_request_count",
        "dropped_request_count",
        "evaluation_error_count",
        "excluded_request_count",
        "expected_active_rollback_epoch",
        "issued_at_epoch_ns",
        "expires_at_epoch_ns",
    ):
        item[field] = _candidate_authority_int(field, item[field])
    if (
        item["sealed_instance_count"] != item["expected_instance_count"]
        or item["observed_request_count"]
        != item["evaluated_request_count"]
        + item["dropped_request_count"]
        + item["evaluation_error_count"]
        + item["excluded_request_count"]
        or item["expires_at_epoch_ns"] <= item["issued_at_epoch_ns"]
        or item["dropped_request_count"] != 0
        or item["evaluation_error_count"] != 0
    ):
        raise PolicyCandidateAuthorityError(
            "readiness coverage, counters, or expiry are inconsistent"
        )

    connection_scope = (contextlib.nullcontext(None) if _controlled_state is not None else
        connect() if _connection is None else contextlib.nullcontext(_connection))
    with connection_scope as conn:
        if _controlled_state is None:
            _lock_policy_candidate_authority(conn)
        verified = controlled.static_values(
            _controlled_state, conn, evidence_kind="readiness",
            envelope_json=item["readiness_envelope_json"],
            envelope_digest=item["readiness_envelope_digest"],
            payload_json=item["readiness_payload_json"],
            payload_digest=item["readiness_payload_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                {**item, "actor_id": actor_id},
                current_prefix="readiness",
            ),
        )
        controlled.apply_values(item, verified)
        readiness_payload = _candidate_authority_strict_object(
            "signed readiness payload",
            loads(item["readiness_payload_json"], None),
            _POLICY_SHADOW_DIRECT_PAYLOAD_FIELDS["readiness"],
        )
        readiness_core = _candidate_authority_strict_object(
            "signed readiness core",
            readiness_payload["readinessCore"],
            frozenset(
                {
                    "coreVersion",
                    "readinessRevision",
                    "assignmentSha256",
                    "assignmentPayloadSha256",
                    "assignmentRevision",
                    "canaryId",
                    "policyIdentity",
                    "trustCheckpoint",
                    "fleetReadiness",
                    "aggregateCounters",
                    "readinessThresholds",
                    "calculatedRates",
                    "policyAuthorityAnalysisSha256",
                    "policyAuthorityAnalysisPayloadSha256",
                    "authorityAnalysis",
                    "pilotRestrictions",
                    "responseValidationObligationsRootSha256",
                    "activationPrecondition",
                    "evidenceRootSha256",
                    "issuedAtUnixNanos",
                    "expiresAtUnixNanos",
                }
            ),
        )
        expected_readiness_core_digest = _policy_authority_domain_digest(
            b"serverware.policyReadinessCore/v2",
            dumps(readiness_core).encode("ascii"),
        )
        if (
            not isinstance(readiness_payload["readinessId"], str)
            or not readiness_payload["readinessId"]
            or len(readiness_payload["readinessId"]) > 1024
            or readiness_payload["readinessRevision"]
            != item["designated_ready_revision"]
            or readiness_core["readinessRevision"]
            != item["designated_ready_revision"]
            or readiness_payload["readinessCoreSha256"]
            != expected_readiness_core_digest
            or item["readiness_core_digest"]
            != expected_readiness_core_digest
            or readiness_core["issuedAtUnixNanos"]
            != item["issued_at_epoch_ns"]
            or readiness_core["expiresAtUnixNanos"]
            != item["expires_at_epoch_ns"]
            or actor_id != item["signing_key_id"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "readiness identity, core digest, time, or actor is not exact"
            )
        canary = ({**_controlled_state.one("policy_canaries", canary_id=item["canary_id"]),
            **_controlled_state.one("policy_canary_heads", canary_id=item["canary_id"])}) if _controlled_state is not None else conn.execute(
            "SELECT canary.canary_id, canary.policy_id, "
            "canary.artifact_envelope_digest, "
            "canary.artifact_payload_digest, "
            "canary.candidate_policy_hash, "
            "canary.candidate_policy_sequence, "
            "canary.candidate_rollback_epoch, "
            "canary.predecessor_policy_hash, canary.compiler_digest, "
            "canary.compiler_config_digest, "
            "canary.policy_schema_digest, "
            "canary.semantic_model_digest, "
            "canary.evaluator_abi_digest, "
            "canary.policy_bundle_digest, canary.runtime_digest, "
            "canary.thresholds_digest, canary.expected_instance_count, "
            "head.head_revision, head.head_state_digest, head.status "
            "FROM policy_canaries AS canary "
            "JOIN policy_canary_heads AS head ON head.canary_id = canary.canary_id "
            "WHERE canary.canary_id = ?",
            (item["canary_id"],),
        ).fetchone()
        exact = {
            "predecessor_canary_revision": "head_revision",
            "predecessor_canary_state_digest": "head_state_digest",
            "artifact_envelope_digest": "artifact_envelope_digest",
            "artifact_payload_digest": "artifact_payload_digest",
            "candidate_policy_hash": "candidate_policy_hash",
            "candidate_policy_sequence": "candidate_policy_sequence",
            "candidate_rollback_epoch": "candidate_rollback_epoch",
            "predecessor_policy_hash": "predecessor_policy_hash",
            "compiler_digest": "compiler_digest",
            "compiler_config_digest": "compiler_config_digest",
            "policy_schema_digest": "policy_schema_digest",
            "semantic_model_digest": "semantic_model_digest",
            "evaluator_abi_digest": "evaluator_abi_digest",
            "policy_bundle_digest": "policy_bundle_digest",
            "runtime_digest": "runtime_digest",
            "thresholds_digest": "thresholds_digest",
            "expected_instance_count": "expected_instance_count",
        }
        if (
            canary is None
            or str(canary["status"]) != "sealing"
            or item["designated_ready_revision"]
            != item["predecessor_canary_revision"] + 1
            or any(canary[column] != item[field] for field, column in exact.items())
        ):
            raise PolicyCandidateAuthorityConflictError(
                "readiness does not bind the exact sealing predecessor head"
            )
        assignment = controlled.assignment(_controlled_state, item["canary_id"]) if _controlled_state is not None else conn.execute(
            "SELECT assignment_envelope_digest, assignment_payload_digest, "
            "assignment_revision, fleet_id, "
            "membership_revision, membership_root_digest, "
            "expected_instance_count, response_obligations_json, "
            "response_obligations_digest, readiness_thresholds_json, "
            "readiness_thresholds_digest, observation_window_json, "
            "assignment_payload_json "
            "FROM policy_canary_assignments "
            "WHERE canary_id = ? AND assignment_envelope_digest = ?",
            (item["canary_id"], item["assignment_envelope_digest"]),
        ).fetchone()
        if (
            assignment is None
            or assignment["assignment_payload_digest"]
            != item["assignment_payload_digest"]
            or int(assignment["expected_instance_count"])
            != item["expected_instance_count"]
            or assignment["readiness_thresholds_digest"]
            != item["thresholds_digest"]
            or assignment["response_obligations_digest"]
            != item["response_obligations_digest"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "readiness does not bind the exact assignment contract"
            )
        compiler = (_controlled_state.one("policy_compiler_authority_analyses", optional=True,
            analysis_envelope_digest=item["compiler_analysis_envelope_digest"])) if _controlled_state is not None else conn.execute(
            "SELECT "
            + _policy_authority_projection(
                tuple(
                    field
                    for field in _POLICY_COMPILER_AUTHORITY_ANALYSIS_FIELDS
                    if field != "actor_id"
                )
            )
            + ", issued_at_epoch_ns, expires_at_epoch_ns "
            "FROM policy_compiler_authority_analyses "
            "WHERE analysis_envelope_digest = ?",
            (item["compiler_analysis_envelope_digest"],),
        ).fetchone()
        compiler_exact = {
            "analysis_payload_digest":
                item["compiler_analysis_payload_digest"],
            "assignment_envelope_digest":
                item["assignment_envelope_digest"],
            "assignment_payload_digest": item["assignment_payload_digest"],
            "assignment_revision": int(assignment["assignment_revision"]),
            "canary_id": item["canary_id"],
            "artifact_envelope_digest": item["artifact_envelope_digest"],
            "artifact_payload_digest": item["artifact_payload_digest"],
            "compiler_digest": item["compiler_digest"],
            "compiler_config_digest": item["compiler_config_digest"],
            "policy_schema_digest": item["policy_schema_digest"],
            "semantic_model_digest": item["semantic_model_digest"],
            "response_obligations_digest":
                item["response_obligations_digest"],
            "analysis_mode": item["authority_analysis_mode"],
            "approval_mode": item["approval_mode"],
            "required_approval_quorum":
                item["required_approval_quorum"],
        }
        now_epoch_ns = _controlled_state.now if _controlled_state is not None else int(
            _metadata_utcnow(conn).timestamp() * 1_000_000_000
        )
        if (
            compiler is None
            or any(
                compiler[field] != value
                for field, value in compiler_exact.items()
            )
            or int(compiler["expires_at_epoch_ns"]) <= now_epoch_ns
        ):
            raise PolicyCandidateAuthorityConflictError(
                "readiness compiler authority is not exact and current"
            )
        controlled.static_row(
            _controlled_state, conn, evidence_kind="compiler_analysis",
            item={
                field: compiler[field]
                for field in _POLICY_COMPILER_AUTHORITY_ANALYSIS_FIELDS
                if field != "actor_id"
            },
            current_prefix="analysis",
        )
        sealed = _policy_canary_sealed_evidence(
            conn,
            canary_id=item["canary_id"],
            expected_instance_count=item["expected_instance_count"],
            _controlled_state=_controlled_state,
        )
        sealed_exact = (
            "sealed_checkpoint_root_digest",
            "sealed_instance_set_digest",
            "observed_request_count",
            "evaluated_request_count",
            "dropped_request_count",
            "evaluation_error_count",
            "excluded_request_count",
            "semantic_matrix_digest",
            "expansion_cells_digest",
            "response_route_coverage_digest",
            "latency_histograms_digest",
            "aggregate_counters_digest",
        )
        if any(item[field] != sealed[field] for field in sealed_exact):
            raise PolicyCandidateAuthorityConflictError(
                "readiness does not bind the recomputed sealed fleet aggregate"
            )
        from serverware.authority_policy_canary_native_opening import assignment_payload as admitted_assignment_payload
        assignment_payload = admitted_assignment_payload(loads(assignment["assignment_payload_json"], None))
        compiler_payload = _candidate_authority_strict_object(
            "readiness compiler payload",
            loads(compiler["analysis_payload_json"], None),
            _POLICY_SHADOW_DIRECT_PAYLOAD_FIELDS["compiler_analysis"],
        )
        thresholds = loads(assignment["readiness_thresholds_json"], None)
        counters = loads(sealed["aggregate_counters_json"], None)
        observed_expansion_list = loads(
            sealed["expansion_cells_json"], None
        )
        if not isinstance(observed_expansion_list, list):
            raise PolicyCandidateAuthorityConflictError(
                "sealed expansion observations are not a direct list"
            )
        observed_expansions = {
            entry["cellSha256"]: entry
            for entry in observed_expansion_list
        }
        if len(observed_expansions) != len(observed_expansion_list):
            raise PolicyCandidateAuthorityConflictError(
                "sealed expansion observations contain duplicate cells"
            )
        semantic_matrix = loads(sealed["semantic_matrix_json"], None)
        expected_matrix_keys = {
            f"{active}:{candidate}"
            for active in _POLICY_AUTHORITY_OUTCOMES
            for candidate in _POLICY_AUTHORITY_OUTCOMES
        }
        if (
            not isinstance(semantic_matrix, dict)
            or set(semantic_matrix) != expected_matrix_keys
        ):
            raise PolicyCandidateAuthorityConflictError(
                "readiness semantic matrix is not the exhaustive 16-cell contract"
            )
        expanding_matrix_count = sum(
            _candidate_authority_int(
                f"readiness semantic matrix {active}:{candidate}",
                semantic_matrix[f"{active}:{candidate}"],
            )
            for active, candidate
            in _POLICY_AUTHORITY_EXPANDING_TRANSITIONS
        )
        authorized_expansions: dict[str, dict[str, Any]] = {}
        previous_compiler_digest = ""
        for compiler_index, raw_entry in enumerate(
            loads(compiler["expansion_cells_json"], None)
        ):
            cell = _policy_authority_semantic_expansion_cell(
                f"readiness compiler expansion {compiler_index}",
                raw_entry,
            )
            digest = cell["cellSha256"]
            if (
                digest <= previous_compiler_digest
                or cell["routeAuthorityRootSha256"]
                != compiler["route_authority_root_digest"]
                or cell["operationAuthorityRootSha256"]
                != compiler["operation_authority_root_digest"]
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "readiness compiler expansion cells are not exact"
                )
            previous_compiler_digest = digest
            authorized_expansions[digest] = cell
        authority_analysis = compiler_payload["authorityAnalysis"]
        pilot = compiler_payload["pilotRestrictions"]
        derived_mode = authority_analysis["mode"]
        derived_approval_mode = (
            authority_analysis.get("approvalMode")
            if derived_mode == "approved-expansion"
            else "none"
        )
        derived_quorum = (
            2
            if derived_approval_mode
            == "two-person-hardware-webauthn"
            else 1
        )
        if (
            derived_mode != item["authority_analysis_mode"]
            or derived_approval_mode != item["approval_mode"]
            or derived_quorum != item["required_approval_quorum"]
            or authority_analysis
            != compiler_payload["authorityAnalysis"]
            or pilot != loads(compiler["pilot_restrictions_json"], None)
        ):
            raise PolicyCandidateAuthorityConflictError(
                "readiness approval contract is not compiler-derived"
            )
        if item["authority_analysis_mode"] == "no-expansion":
            if (
                expanding_matrix_count != 0
                or observed_expansions
                or authorized_expansions
                or item["approval_mode"] != "none"
                or item["required_approval_quorum"] != 1
                or item["expansion_approval_context_digest"] is not None
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "NoExpansion readiness observed or requested expansion"
                )
            expansion_context_digest = None
        else:
            total_expansions = int(
                counters["totals"]["authorityExpansionObservations"]
            )
            write_expansions = int(
                counters["totals"][
                    "authorityExpansionWriteObservations"
                ]
            )
            observed_total = 0
            observed_write_total = 0
            for digest, observed in observed_expansions.items():
                authorized = authorized_expansions.get(digest)
                request_count = _candidate_authority_int(
                    "readiness expansion request count",
                    observed["requestCount"],
                    minimum=1,
                )
                write_request_count = _candidate_authority_int(
                    "readiness expansion write request count",
                    observed["writeRequestCount"],
                )
                response_count = _candidate_authority_int(
                    "readiness expansion response count",
                    observed["responseCount"],
                )
                write_response_count = _candidate_authority_int(
                    "readiness expansion write response count",
                    observed["writeResponseCount"],
                )
                observed_total += request_count
                observed_write_total += write_request_count
                semantic_fields = (
                    "cellSha256",
                    "authorityExpansion",
                    "routeSha256",
                    "operation",
                    "compiledSemanticProfileSha256",
                    "requestAuthorityClass",
                    "activeOutcome",
                    "candidateOutcome",
                )
                if (
                    authorized is None
                    or any(
                        observed[field] != authorized[field]
                        for field in semantic_fields
                    )
                    or request_count
                    > int(authorized["maximumRequests"])
                    or write_request_count
                    > int(authorized["maximumWriteRequests"])
                    or response_count > request_count
                    or write_response_count > write_request_count
                    or write_response_count > response_count
                ):
                    raise PolicyCandidateAuthorityConflictError(
                        "observed expansion exceeds exact compiler cell authority"
                    )
            if (
                not observed_expansions
                or total_expansions != expanding_matrix_count
                or observed_total != total_expansions
                or observed_write_total != write_expansions
                or total_expansions
                > int(pilot["maximumRequests"])
                or write_expansions
                > int(pilot["maximumWriteRequests"])
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "approved expansion exceeds signed pilot authority"
                )
            expansion_context_digest = _policy_authority_domain_digest(
                b"serverware.policyExpansionApprovalContext/v2",
                dumps(
                    {
                        "authorityAnalysis":
                            authority_analysis,
                        "compilerAnalysisEnvelopeDigest":
                            item["compiler_analysis_envelope_digest"],
                        "compilerAnalysisPayloadDigest":
                            item["compiler_analysis_payload_digest"],
                        "expansionCellsDigest":
                            item["expansion_cells_digest"],
                        "pilotRestrictions": pilot,
                        "predecessorCanaryStateDigest":
                            item["predecessor_canary_state_digest"],
                        "designatedReadyRevision":
                            item["designated_ready_revision"],
                        "sealedCheckpointRootDigest":
                            item["sealed_checkpoint_root_digest"],
                    }
                ).encode("ascii"),
            )
            if (
                item["expansion_approval_context_digest"]
                != expansion_context_digest
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "expansion approval context is not exactly derived"
                )
        high_water = _committed_policy_authority_row(conn) if _controlled_state is None else current.committed_policy(_controlled_state)
        if (
            not _policy_row_matches(
                high_water,
                policy_id=str(canary["policy_id"]),
                sequence=item["expected_active_policy_sequence"],
                rollback_epoch=item["expected_active_rollback_epoch"],
                policy_hash=item["predecessor_policy_hash"],
            )
            or item["publication_revision"]
            != item["candidate_policy_sequence"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "readiness publication CAS does not match active high-water"
            )
        trust_checkpoint = _candidate_authority_strict_object(
            "signed readiness trust checkpoint",
            readiness_core["trustCheckpoint"],
            frozenset(
                {
                    "checkpointId",
                    "asOfUnixNanos",
                    "revocationGeneration",
                    "revocationRootSha256",
                }
            ),
        )
        observation_window = loads(
            assignment["observation_window_json"], None
        )
        trust_as_of = _candidate_authority_int(
            "readiness trust checkpoint as-of",
            trust_checkpoint["asOfUnixNanos"],
        )
        if (
            trust_as_of > item["issued_at_epoch_ns"]
            or item["issued_at_epoch_ns"] - trust_as_of
            > int(observation_window["maximumEvidenceAgeNanos"])
        ):
            raise PolicyCandidateAuthorityConflictError(
                "readiness trust checkpoint is not fresh at issuance"
            )
        expected_trust_checkpoint = current.trust_checkpoint(_controlled_state, trust_as_of) if _controlled_state is not None else (
            _policy_authority_current_trust_checkpoint(
                conn,
                as_of_epoch_ns=trust_as_of,
            )
        )
        fleet_readiness = {
            "fleetId": sealed["fleet_id"],
            "membershipRevision": sealed["membership_revision"],
            "membershipRootSha256":
                sealed["membership_root_digest"],
            "expectedMemberCount": item["expected_instance_count"],
            "coveredMemberCount": item["sealed_instance_count"],
            "memberEvidence": sealed["member_evidence"],
            "memberEvidenceRootSha256":
                sealed["member_evidence_root_digest"],
        }
        calculated_rates = {
            "candidateEvaluationP99Nanos":
                sealed["candidate_evaluation_p99_nanos"],
            "shadowTotalP99Nanos":
                sealed["shadow_total_p99_nanos"],
        }
        activation_precondition = {
            "publicationRevision": item["publication_revision"],
            "expectedPredecessorPolicySha256":
                item["predecessor_policy_hash"],
            "expectedPredecessorPolicySequence":
                item["expected_active_policy_sequence"],
            "expectedPredecessorRollbackEpoch":
                item["expected_active_rollback_epoch"],
            "candidatePolicySha256": item["candidate_policy_hash"],
            "candidatePolicySequence": item["candidate_policy_sequence"],
            "candidateRollbackEpoch": item["candidate_rollback_epoch"],
            "activationDeadlineUnixNanos": item["expires_at_epoch_ns"],
        }
        evidence_root = _policy_authority_domain_digest(
            b"serverware.policyReadinessEvidenceRoot/v2",
            _candidate_authority_digest_bytes(
                "readiness assignment payload",
                item["assignment_payload_digest"],
            ),
            _candidate_authority_digest_bytes(
                "readiness member evidence root",
                sealed["member_evidence_root_digest"],
            ),
            dumps(counters).encode("ascii"),
            dumps(thresholds).encode("ascii"),
            _candidate_authority_digest_bytes(
                "readiness compiler analysis",
                item["compiler_analysis_envelope_digest"],
            ),
            _candidate_authority_digest_bytes(
                "readiness response obligations",
                item["response_obligations_digest"],
            ),
            dumps(expected_trust_checkpoint).encode("ascii"),
        )
        expected_readiness_core = {
            "coreVersion": "serverware.policyReadinessCore/v2",
            "readinessRevision": item["designated_ready_revision"],
            "assignmentSha256": item["assignment_envelope_digest"],
            "assignmentPayloadSha256": item["assignment_payload_digest"],
            "assignmentRevision": int(assignment["assignment_revision"]),
            "canaryId": item["canary_id"],
            "policyIdentity": assignment_payload["policyIdentity"],
            "trustCheckpoint": expected_trust_checkpoint,
            "fleetReadiness": fleet_readiness,
            "aggregateCounters": counters,
            "readinessThresholds": thresholds,
            "calculatedRates": calculated_rates,
            "policyAuthorityAnalysisSha256":
                item["compiler_analysis_envelope_digest"],
            "policyAuthorityAnalysisPayloadSha256":
                item["compiler_analysis_payload_digest"],
            "authorityAnalysis": authority_analysis,
            "pilotRestrictions": pilot,
            "responseValidationObligationsRootSha256":
                item["response_obligations_digest"],
            "activationPrecondition": activation_precondition,
            "evidenceRootSha256": evidence_root,
            "issuedAtUnixNanos": item["issued_at_epoch_ns"],
            "expiresAtUnixNanos": item["expires_at_epoch_ns"],
        }
        expected_core_digest = _policy_authority_domain_digest(
            b"serverware.policyReadinessCore/v2",
            dumps(expected_readiness_core).encode("ascii"),
        )
        if (
            readiness_core != expected_readiness_core
            or compiler_payload["policyIdentity"]
            != assignment_payload["policyIdentity"]
            or expected_core_digest != expected_readiness_core_digest
        ):
            raise PolicyCandidateAuthorityConflictError(
                "signed readiness core is not the exhaustive derived record"
            )
        activation_context = {
            "approvalMode": item["approval_mode"],
            "authorityAnalysisMode": item["authority_analysis_mode"],
            "candidatePolicyHash": item["candidate_policy_hash"],
            "candidatePolicySequence": item["candidate_policy_sequence"],
            "candidateRollbackEpoch": item["candidate_rollback_epoch"],
            "expectedActivePolicySequence":
                item["expected_active_policy_sequence"],
            "expectedActiveRollbackEpoch":
                item["expected_active_rollback_epoch"],
            "expansionApprovalContextDigest": expansion_context_digest,
            "predecessorPolicyHash": item["predecessor_policy_hash"],
            "publicationRevision": item["publication_revision"],
            "readinessCoreDigest": expected_core_digest,
            "requiredApprovalQuorum": item["required_approval_quorum"],
        }
        expected_activation_context = _policy_authority_domain_digest(
            b"serverware.policyActivationContext/v2",
            dumps(activation_context).encode("ascii"),
        )
        if (
            item["readiness_core_digest"] != expected_core_digest
            or item["activation_context_digest"]
            != expected_activation_context
        ):
            raise PolicyCandidateAuthorityConflictError(
                "readiness core or activation context is not derived exactly"
            )
        transition_digest = controlled.transition(
            _controlled_state, conn, event_type="policy.canary_readiness.staged",
            entity_kind="readiness",
            entity_id=item["readiness_payload_digest"],
            entity_revision=item["designated_ready_revision"],
            state_digest=item["readiness_payload_digest"],
            previous_state_digest=item[
                "predecessor_canary_state_digest"
            ],
            actor_id=actor_id,
            evidence={
                "canaryId": item["canary_id"],
                "compilerAnalysisPayloadDigest":
                    item["compiler_analysis_payload_digest"],
                "readinessCoreDigest": item["readiness_core_digest"],
                "activationContextDigest":
                    item["activation_context_digest"],
                "approvalMode": item["approval_mode"],
                "requiredApprovalQuorum":
                    item["required_approval_quorum"],
                "readinessEnvelopeDigest": item["readiness_envelope_digest"],
                "sealedCheckpointRootDigest":
                    item["sealed_checkpoint_root_digest"],
                "sealedInstanceSetDigest": item["sealed_instance_set_digest"],
            },
            created_at_epoch_ns=item["issued_at_epoch_ns"],
        )
        readiness = {
            **item,
            "status": "ready",
            "created_transition_digest": transition_digest,
        }
        if _controlled_state is not None:
            _controlled_state.put("policy_canary_readiness", readiness)
            return dict(readiness)
        _insert_immutable_candidate_row(
            conn,
            table="policy_canary_readiness",
            columns=tuple(readiness),
            values=readiness,
            key_columns=("readiness_envelope_digest",),
        )
    return dict(readiness)


def _candidate_authority_iso(label: str, value: Any) -> str:
    text = _candidate_authority_text(label, value, maximum=64)
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError as exc:
        raise PolicyCandidateAuthorityError(
            f"{label} must be an ISO-8601 timestamp"
        ) from exc
    if parsed.tzinfo is None or parsed.utcoffset() != timedelta(0):
        raise PolicyCandidateAuthorityError(
            f"{label} must be an explicit UTC timestamp"
        )
    if parsed.isoformat() != text:
        raise PolicyCandidateAuthorityError(
            f"{label} must use the canonical datetime representation"
        )
    return text


def _policy_canary_sealed_evidence(
    conn: Any,
    *,
    canary_id: str,
    expected_instance_count: int,
    preverified_member_aggregates: (
        Mapping[tuple[str, str], Mapping[str, Any]] | None
    ) = None,
    _controlled_state: Any | None = None,
) -> dict[str, Any]:
    from serverware import authority_transition_policy_canary_reads as controlled
    controlled.owner(_controlled_state, conn)
    if _controlled_state is not None and preverified_member_aggregates is not None:
        raise PolicyCandidateAuthorityConflictError("controlled readiness cannot accept preverified aggregate DTOs")
    runtime_verifier = _reverify_policy_runtime_row if _controlled_state is None else _controlled_state.reverify_runtime_row
    if expected_instance_count > _POLICY_AUTHORITY_READ_MAX_ROWS:
        raise PolicyCandidateAuthorityConflictError(
            "canary fleet exceeds the fixed evidence bound"
        )
    contract = controlled.assignment(_controlled_state, canary_id) if _controlled_state is not None else conn.execute(
        "SELECT expected_instance_count, readiness_thresholds_json, "
        "readiness_thresholds_digest, observation_window_json, "
        "observation_window_digest, response_obligations_json, "
        "response_obligations_json_digest "
        "FROM policy_canary_assignments WHERE canary_id = ?",
        (canary_id,),
    ).fetchone()
    if (
        contract is None
        or int(contract["expected_instance_count"])
        != expected_instance_count
    ):
        raise PolicyCandidateAuthorityConflictError(
            "sealed fleet does not resolve its exact assignment contract"
        )
    for json_field, digest_field in (
        ("readiness_thresholds_json", "readiness_thresholds_digest"),
        ("observation_window_json", "observation_window_digest"),
        (
            "response_obligations_json",
            "response_obligations_json_digest",
        ),
    ):
        _candidate_authority_json(
            f"sealed fleet {json_field}",
            contract[json_field],
            contract[digest_field],
            maximum=_POLICY_AUTHORITY_MAX_CANONICAL_AGGREGATE_BYTES,
        )
    thresholds = _candidate_authority_strict_object(
        "sealed fleet readiness thresholds",
        loads(contract["readiness_thresholds_json"], None),
        frozenset(
            {
                "minimumIngressRequests",
                "minimumEvaluatedObservations",
                "minimumComparableResponses",
                "minimumIngressRequestsPerMember",
                "minimumEvaluatedObservationsPerMember",
                "minimumComparableResponsesPerMember",
                "maximumCandidateEvaluationP99Nanos",
                "maximumShadowTotalP99Nanos",
            }
        ),
    )
    observation_window = _candidate_authority_strict_object(
        "sealed fleet observation window",
        loads(contract["observation_window_json"], None),
        frozenset(
            {
                "startsAtUnixNanos",
                "endsAtUnixNanos",
                "sealDeadlineUnixNanos",
                "minimumDurationNanos",
                "firstIngressSequence",
                "samplingBasisPoints",
                "requestCommitmentKeyId",
                "requestCommitmentKeyEpoch",
                "maximumEvidenceAgeNanos",
                "maximumHeartbeatGapNanos",
            }
        ),
    )
    obligations = loads(contract["response_obligations_json"], None)
    if not isinstance(obligations, list):
        raise PolicyCandidateAuthorityConflictError(
            "sealed fleet response obligations are not an exact list"
        )
    now_epoch_ns = _controlled_state.now if _controlled_state is not None else int(
        _metadata_utcnow(conn).timestamp() * 1_000_000_000
    )
    rows = controlled.sealed_rows(_controlled_state, canary_id) if _controlled_state is not None else conn.execute(
        "SELECT instance.fleet_id, instance.membership_revision, "
        "instance.member_ordinal, instance.member_id, "
        "instance.instance_id, instance.boot_id, "
        "instance.membership_root_digest, "
        "instance.attestation_verifier_receipt_digest, "
        "instance_head.head_revision, instance_head.head_state_digest, "
        "instance_head.status, checkpoint_head.checkpoint_sequence, "
        "checkpoint_head.checkpoint_envelope_digest, "
        "checkpoint_head.checkpoint_payload_digest, "
        "checkpoint_head.observation_root_digest, "
        "checkpoint_head.sealed, final.ingress_root_digest, "
        "final.active_decision_root_digest, "
        "final.observed_request_count, final.evaluated_request_count, "
        "final.dropped_request_count, final.evaluation_error_count, "
        "final.excluded_request_count, final.active_indeterminate_count, "
        "final.candidate_indeterminate_count, "
        "final.request_sequence_start, final.request_sequence_end, "
        "final.first_observation_envelope_digest, "
        "final.last_observation_envelope_digest, "
        "final.first_observed_at_epoch_ns, "
        "final.last_observed_at_epoch_ns, final.ingress_count, "
        "final.verified_evidence_bytes, final.verification_work_units, "
        "final.principal_authority_root_digest, "
        "final.route_authority_root_digest, "
        "final.window_started_at_epoch_ns, "
        "final.window_ended_at_epoch_ns, "
        "aggregate.aggregate_counters_json, "
        "aggregate.aggregate_counters_digest, "
        "aggregate.semantic_matrix_json, aggregate.semantic_matrix_digest, "
        "aggregate.expansion_cells_json, "
        "aggregate.expansion_cells_digest, "
        "aggregate.response_route_coverage_json, "
        "aggregate.response_route_coverage_digest, "
        "aggregate.latency_histograms_json, "
        "aggregate.latency_histograms_digest, "
        "aggregate.drop_counters_json, aggregate.drop_counters_digest, "
        "aggregate.error_counters_json, aggregate.error_counters_digest, "
        "aggregate.excluded_count, aggregate.gap_count, "
        "aggregate.indeterminate_count, "
        "aggregate.response_divergence_count, "
        "aggregate.response_validator_unavailable_count, "
        "aggregate.aggregate_contract_digest, "
        "aggregate.sealed AS aggregate_sealed, "
        "aggregate.window_closure_envelope_digest, "
        "aggregate.seal_root_digest, aggregate.sealed_at_epoch_ns, "
        "final.checkpoint_payload_json, final.heartbeat_evidence_json "
        "FROM policy_canary_instances AS instance "
        "JOIN policy_canary_instance_heads AS instance_head "
        "ON instance_head.canary_id = instance.canary_id "
        "AND instance_head.instance_id = instance.instance_id "
        "AND instance_head.boot_id = instance.boot_id "
        "JOIN policy_canary_checkpoint_heads AS checkpoint_head "
        "ON checkpoint_head.canary_id = instance.canary_id "
        "AND checkpoint_head.instance_id = instance.instance_id "
        "AND checkpoint_head.boot_id = instance.boot_id "
        "JOIN policy_canary_checkpoints AS final "
        "ON final.canary_id = checkpoint_head.canary_id "
        "AND final.instance_id = checkpoint_head.instance_id "
        "AND final.boot_id = checkpoint_head.boot_id "
        "AND final.checkpoint_sequence = checkpoint_head.checkpoint_sequence "
        "AND final.checkpoint_envelope_digest = "
        "checkpoint_head.checkpoint_envelope_digest "
        "AND final.checkpoint_payload_digest = "
        "checkpoint_head.checkpoint_payload_digest "
        "JOIN policy_canary_checkpoint_aggregates AS aggregate "
        "ON aggregate.canary_id = final.canary_id "
        "AND aggregate.instance_id = final.instance_id "
        "AND aggregate.boot_id = final.boot_id "
        "AND aggregate.checkpoint_sequence = final.checkpoint_sequence "
        "AND aggregate.checkpoint_envelope_digest = "
        "final.checkpoint_envelope_digest "
        "AND aggregate.checkpoint_payload_digest = "
        "final.checkpoint_payload_digest "
        "WHERE instance.canary_id = ? "
        "ORDER BY instance.member_ordinal LIMIT ?",
        (canary_id, expected_instance_count + 1),
    ).fetchall()
    if (
        len(rows) != expected_instance_count
        or any(
            row["status"] != "sealed"
            or not bool(row["sealed"])
            or not bool(row["aggregate_sealed"])
            or int(row["member_ordinal"]) != index
            for index, row in enumerate(rows, start=1)
        )
    ):
        raise PolicyCandidateAuthorityConflictError(
            "canary fleet is not the exact complete sealed assignment"
        )
    merged = _empty_policy_authority_aggregate()
    member_evidence: list[dict[str, Any]] = []
    consumed_preverified_members: set[tuple[str, str]] = set()
    for row in rows:
        checkpoint_record = (controlled.checkpoint(_controlled_state, {**row, "canary_id": canary_id}, row["checkpoint_sequence"])) if _controlled_state is not None else conn.execute(
            "SELECT "
            + _policy_authority_projection(
                tuple(
                    field
                    for field in _POLICY_CANARY_CHECKPOINT_FIELDS
                    if field != "actor_id"
                )
            )
            + " FROM policy_canary_checkpoints WHERE canary_id = ? "
            "AND instance_id = ? AND boot_id = ? "
            "AND checkpoint_sequence = ?",
            (
                canary_id,
                row["instance_id"],
                row["boot_id"],
                row["checkpoint_sequence"],
            ),
        ).fetchone()
        if checkpoint_record is None:
            raise PolicyCandidateAuthorityConflictError(
                "sealed checkpoint record is missing"
            )
        member_key = (str(row["instance_id"]), str(row["boot_id"]))
        if preverified_member_aggregates is None:
            recomputed = controlled.recompute(
                _controlled_state, conn,
                canary_id=canary_id,
                instance_id=member_key[0],
                boot_id=member_key[1],
                sequence_end=int(row["observed_request_count"]),
            )
        else:
            recomputed = preverified_member_aggregates.get(member_key)
            if recomputed is None or member_key in consumed_preverified_members:
                raise PolicyCandidateAuthorityConflictError(
                    "sealed fleet lacks one exact preverified member aggregate"
                )
            consumed_preverified_members.add(member_key)
        checkpoint_item = dict(checkpoint_record)
        checkpoint_item.update(
            {
                field: recomputed[field]
                for field in
                _POLICY_CANARY_CHECKPOINT_AGGREGATE_INPUT_FIELDS
            }
        )
        runtime_context = (_controlled_state.runtime_context({**row, "canary_id": canary_id})) if _controlled_state is not None else _policy_canary_runtime_context(
            conn,
            canary_id=canary_id,
            instance_id=str(row["instance_id"]),
            boot_id=str(row["boot_id"]),
        )
        heartbeat_contract = _verify_policy_checkpoint_heartbeat_contract(
            conn,
            item=checkpoint_item,
            context=runtime_context,
            heartbeat_wires=loads(
                checkpoint_record["heartbeat_evidence_json"], None
            ),
            _controlled_state=_controlled_state,
        )
        runtime_verifier(
            conn,
            evidence_kind="checkpoint",
            item=checkpoint_item,
            current_prefix="checkpoint",
        )
        recomputed_exact = (
            "observed_request_count",
            "evaluated_request_count",
            "dropped_request_count",
            "evaluation_error_count",
            "excluded_request_count",
            "active_indeterminate_count",
            "candidate_indeterminate_count",
            "first_observation_envelope_digest",
            "last_observation_envelope_digest",
            "first_observed_at_epoch_ns",
            "last_observed_at_epoch_ns",
            "ingress_count",
            "verified_evidence_bytes",
            "verification_work_units",
            "aggregate_counters_json",
            "aggregate_counters_digest",
            "semantic_matrix_json",
            "semantic_matrix_digest",
            "expansion_cells_json",
            "expansion_cells_digest",
            "response_route_coverage_json",
            "response_route_coverage_digest",
            "latency_histograms_json",
            "latency_histograms_digest",
            "drop_counters_json",
            "drop_counters_digest",
            "error_counters_json",
            "error_counters_digest",
            "excluded_count",
            "gap_count",
            "indeterminate_count",
            "response_divergence_count",
            "response_validator_unavailable_count",
            "aggregate_contract_digest",
        )
        if (
            int(row["request_sequence_start"])
            != recomputed["ingress_sequence_start"]
            or int(row["request_sequence_end"])
            != recomputed["ingress_sequence_end"]
            or int(row["window_started_at_epoch_ns"])
            != recomputed["assignment_window_started_at_epoch_ns"]
            or int(row["window_ended_at_epoch_ns"])
            < recomputed["last_observed_at_epoch_ns"]
            or int(row["window_ended_at_epoch_ns"])
            > recomputed["assignment_seal_deadline_epoch_ns"]
            or row["observation_root_digest"]
            != recomputed["cumulative_observation_root_digest"]
            or row["ingress_root_digest"]
            != recomputed["cumulative_ingress_root_digest"]
            or row["active_decision_root_digest"]
            != recomputed["cumulative_active_decision_root_digest"]
            or row["principal_authority_root_digest"]
            != recomputed["cumulative_principal_authority_root_digest"]
            or row["route_authority_root_digest"]
            != recomputed["cumulative_route_authority_root_digest"]
            or int(row["aggregate_sealed"]) != 1
            or row["window_closure_envelope_digest"]
            != heartbeat_contract["window_closure_envelope_digest"]
            or row["seal_root_digest"]
            != heartbeat_contract["seal_root_digest"]
            or int(row["sealed_at_epoch_ns"])
            != heartbeat_contract["sealed_at_epoch_ns"]
            or any(row[field] != recomputed[field] for field in recomputed_exact)
        ):
            raise PolicyCandidateAuthorityConflictError(
                "sealed member aggregate is not its recomputed signed prefix"
            )
        json_pairs = (
            ("aggregate_counters_json", "aggregate_counters_digest"),
            ("semantic_matrix_json", "semantic_matrix_digest"),
            ("expansion_cells_json", "expansion_cells_digest"),
            (
                "response_route_coverage_json",
                "response_route_coverage_digest",
            ),
            ("latency_histograms_json", "latency_histograms_digest"),
            ("drop_counters_json", "drop_counters_digest"),
            ("error_counters_json", "error_counters_digest"),
        )
        for json_field, digest_field in json_pairs:
            _candidate_authority_json(
                f"sealed {json_field}",
                row[json_field],
                row[digest_field],
                maximum=_POLICY_AUTHORITY_MAX_CANONICAL_AGGREGATE_BYTES,
            )
        counters = loads(row["aggregate_counters_json"], None)
        _candidate_authority_strict_object(
            "sealed aggregate counters",
            counters,
            frozenset(
                {
                    "totals",
                    "outcomes",
                    "comparability",
                    "drops",
                    "errors",
                    "latencyHistograms",
                    "expansionCells",
                    "responseRouteCoverage",
                }
            ),
        )
        expected_outcome_fields = set(
            _POLICY_AUTHORITY_OUTCOME_COUNTER_FIELDS.values()
        ) | {"total"}
        expected_comparability_fields = set(
            _POLICY_AUTHORITY_COMPARABILITY_COUNTER_FIELDS.values()
        ) | {"total"}
        if (
            set(counters["totals"]) != set(merged["totals"])
            or set(counters["outcomes"]) != expected_outcome_fields
            or set(counters["comparability"])
            != expected_comparability_fields
        ):
            raise PolicyCandidateAuthorityConflictError(
                "sealed aggregate counter classes are not exhaustive"
            )
        for key in merged["totals"]:
            merged["totals"][key] += _candidate_authority_int(
                f"sealed total {key}", counters["totals"][key]
            )
        for classification, field in (
            _POLICY_AUTHORITY_COMPARABILITY_COUNTER_FIELDS.items()
        ):
            merged["responseClasses"][classification] += (
                _candidate_authority_int(
                    f"sealed response class {classification}",
                    counters["comparability"][field],
                )
            )
        matrix = loads(row["semantic_matrix_json"], None)
        if not isinstance(matrix, dict) or set(matrix) != set(
            merged["semanticMatrix"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "sealed semantic matrix is not the complete 16-cell matrix"
            )
        if (
            int(counters["outcomes"]["total"])
            != sum(int(value) for value in matrix.values())
            or any(
                int(counters["outcomes"][field]) != int(matrix[cell])
                for cell, field
                in _POLICY_AUTHORITY_OUTCOME_COUNTER_FIELDS.items()
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "sealed direct outcome counters differ from the matrix"
            )
        for key in merged["semanticMatrix"]:
            merged["semanticMatrix"][key] += _candidate_authority_int(
                f"sealed semantic cell {key}", matrix[key]
            )
        expansion_cells = loads(row["expansion_cells_json"], None)
        if (
            not isinstance(expansion_cells, list)
            or expansion_cells != counters["expansionCells"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "sealed expansion cells are not a list"
            )
        previous_expansion_digest = ""
        for entry in expansion_cells:
            entry = _candidate_authority_strict_object(
                "sealed expansion aggregate",
                entry,
                frozenset(
                    {
                        "cellSha256",
                        "authorityExpansion",
                        "routeSha256",
                        "operation",
                        "compiledSemanticProfileSha256",
                        "requestAuthorityClass",
                        "activeOutcome",
                        "candidateOutcome",
                        "requestCount",
                        "writeRequestCount",
                        "responseCount",
                        "writeResponseCount",
                    }
                ),
            )
            digest = _candidate_authority_digest(
                "sealed expansion digest", entry["cellSha256"]
            )
            for digest_field in (
                "routeSha256",
                "compiledSemanticProfileSha256",
            ):
                _candidate_authority_digest(
                    f"sealed expansion {digest_field}",
                    entry[digest_field],
                )
            request_count = _candidate_authority_int(
                "sealed expansion request count",
                entry["requestCount"],
                minimum=1,
            )
            write_request_count = _candidate_authority_int(
                "sealed expansion write request count",
                entry["writeRequestCount"],
            )
            response_count = _candidate_authority_int(
                "sealed expansion response count",
                entry["responseCount"],
            )
            write_response_count = _candidate_authority_int(
                "sealed expansion write response count",
                entry["writeResponseCount"],
            )
            if (
                digest <= previous_expansion_digest
                or entry["authorityExpansion"]
                not in _POLICY_AUTHORITY_EXPANSION_KINDS
                or entry["operation"] not in _POLICY_AUTHORITY_OPERATIONS
                or entry["requestAuthorityClass"] not in {"read", "write"}
                or entry["activeOutcome"]
                not in _POLICY_AUTHORITY_OUTCOMES
                or entry["candidateOutcome"]
                not in _POLICY_AUTHORITY_OUTCOMES
                or (
                    entry["activeOutcome"],
                    entry["candidateOutcome"],
                ) not in _POLICY_AUTHORITY_EXPANDING_TRANSITIONS
                or write_request_count > request_count
                or response_count > request_count
                or write_response_count > write_request_count
                or write_response_count > response_count
                or (
                    entry["requestAuthorityClass"] == "read"
                    and (
                        write_request_count != 0
                        or write_response_count != 0
                    )
                )
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "sealed expansion cell is not an exact canonical expansion"
                )
            previous_expansion_digest = digest
            current = merged["expansionCells"].get(digest)
            if current is None:
                merged["expansionCells"][digest] = dict(entry)
            elif any(
                current[field] != entry[field]
                for field in (
                    "cellSha256",
                    "authorityExpansion",
                    "routeSha256",
                    "operation",
                    "compiledSemanticProfileSha256",
                    "requestAuthorityClass",
                    "activeOutcome",
                    "candidateOutcome",
                )
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "sealed expansion digest has divergent semantics"
                )
            else:
                current["requestCount"] += request_count
                current["writeRequestCount"] += write_request_count
                current["responseCount"] += response_count
                current["writeResponseCount"] += write_response_count
        coverage = loads(row["response_route_coverage_json"], None)
        if (
            not isinstance(coverage, list)
            or coverage != counters["responseRouteCoverage"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "sealed route coverage is not a list"
            )
        previous_route_id = ""
        for entry in coverage:
            entry = _candidate_authority_strict_object(
                "sealed route coverage",
                entry,
                frozenset(
                    {
                        "routeSha256",
                        "obligationRootSha256",
                        "comparableResponses",
                        "validationDivergences",
                        "validatorUnavailable",
                        "noncomparable",
                    }
                ),
            )
            route_id = _candidate_authority_digest(
                "sealed response route", entry["routeSha256"]
            )
            obligation_root = _candidate_authority_digest(
                "sealed response obligation root",
                entry["obligationRootSha256"],
            )
            comparable_count = _candidate_authority_int(
                "sealed comparable count", entry["comparableResponses"]
            )
            divergence_count = _candidate_authority_int(
                "sealed divergence count", entry["validationDivergences"]
            )
            unavailable_count = _candidate_authority_int(
                "sealed validator unavailable count",
                entry["validatorUnavailable"],
            )
            noncomparable_count = _candidate_authority_int(
                "sealed noncomparable count", entry["noncomparable"]
            )
            if (
                route_id <= previous_route_id
                or divergence_count > comparable_count
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "sealed route coverage totals or ordering are not exact"
                )
            previous_route_id = route_id
            current = merged["responseRouteCoverage"].setdefault(
                route_id,
                {
                    "routeSha256": route_id,
                    "obligationRootSha256": obligation_root,
                    "comparableResponses": 0,
                    "validationDivergences": 0,
                    "validatorUnavailable": 0,
                    "noncomparable": 0,
                },
            )
            if current["obligationRootSha256"] != obligation_root:
                raise PolicyCandidateAuthorityConflictError(
                    "sealed route obligation profiles diverge across members"
                )
            current["comparableResponses"] += comparable_count
            current["validationDivergences"] += divergence_count
            current["validatorUnavailable"] += unavailable_count
            current["noncomparable"] += noncomparable_count
        histograms = loads(row["latency_histograms_json"], None)
        if (
            not isinstance(histograms, dict)
            or set(histograms) != set(_POLICY_AUTHORITY_LATENCY_SERIES)
            or histograms != counters["latencyHistograms"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "sealed latency histogram series are not exhaustive"
            )
        for series in _POLICY_AUTHORITY_LATENCY_SERIES:
            histogram = _candidate_authority_strict_object(
                f"sealed {series} histogram",
                histograms[series],
                frozenset(_POLICY_AUTHORITY_LATENCY_COUNTER_FIELDS)
                | frozenset({"total"}),
            )
            parsed_counts = [
                _candidate_authority_int(
                    f"sealed {series} {field}", histogram[field]
                )
                for field in _POLICY_AUTHORITY_LATENCY_COUNTER_FIELDS
            ]
            histogram_total = _candidate_authority_int(
                f"sealed {series} total", histogram["total"]
            )
            if histogram_total != sum(parsed_counts):
                raise PolicyCandidateAuthorityConflictError(
                    "sealed latency histogram total is not its bucket sum"
                )
            for index, count in enumerate(parsed_counts):
                merged["latencyHistograms"][series]["buckets"][index] += (
                    count
                )
            merged["latencyHistograms"][series]["total"] += (
                histogram_total
            )
        row_failure_totals: dict[str, int] = {}
        for json_field, target, field_map in (
            (
                "drop_counters_json",
                "dropReasons",
                _POLICY_AUTHORITY_DROP_COUNTER_FIELDS,
            ),
            (
                "error_counters_json",
                "errorReasons",
                _POLICY_AUTHORITY_ERROR_COUNTER_FIELDS,
            ),
        ):
            counters_by_reason = loads(row[json_field], None)
            if (
                not isinstance(counters_by_reason, dict)
                or set(counters_by_reason)
                != set(field_map.values()) | {"total"}
                or counters_by_reason != counters[
                    "drops" if target == "dropReasons" else "errors"
                ]
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "sealed failure counters are not exhaustive"
                )
            row_failure_totals[target] = 0
            for reason, direct_field in field_map.items():
                parsed_count = _candidate_authority_int(
                    f"sealed failure count {reason}",
                    counters_by_reason[direct_field],
                )
                row_failure_totals[target] += parsed_count
                merged[target][reason] += parsed_count
            if row_failure_totals[target] != int(
                counters_by_reason["total"]
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "sealed failure total is not its exact reason sum"
                )
        row_observed = sum(
            int(counters["totals"][key])
            for key in ("evaluated", "dropped", "errors", "excluded")
        )
        row_matrix_total = sum(int(value) for value in matrix.values())
        row_response_total = int(counters["comparability"]["total"])
        row_indeterminate = sum(
            int(count)
            for cell, count in matrix.items()
            if "indeterminate" in cell
        )
        row_active_indeterminate = sum(
            int(count)
            for cell, count in matrix.items()
            if cell.startswith("indeterminate:")
        )
        row_candidate_indeterminate = sum(
            int(count)
            for cell, count in matrix.items()
            if cell.endswith(":indeterminate")
        )
        row_validator_unavailable = int(
            counters["comparability"][
                "notComparableCandidateValidatorUnavailable"
            ]
        )
        row_comparable = sum(
            int(counters["comparability"][field])
            for field in (
                "comparableIdentical",
                "comparableValidationMatch",
                "comparableValidationDivergence",
            )
        )
        row_noncomparable = sum(
            int(counters["comparability"][field])
            for field in (
                "notComparableCandidateNotDispatchable",
                "notComparableDispatchCommitmentMismatch",
                "notComparableActiveResponseUnavailable",
                "notComparableCandidateValidatorUnavailable",
            )
        )
        if (
            row_matrix_total != int(counters["totals"]["evaluated"])
            or row_response_total != int(counters["totals"]["evaluated"])
            or int(counters["totals"]["comparableResponses"])
            != row_comparable
            or int(counters["totals"]["responseNoncomparable"])
            != row_noncomparable
            or int(
                counters["totals"]["responseValidationDivergence"]
            )
            != int(
                counters["comparability"][
                    "comparableValidationDivergence"
                ]
            )
            or int(counters["totals"]["responseValidatorUnavailable"])
            != int(
                counters["comparability"][
                    "notComparableCandidateValidatorUnavailable"
                ]
            )
            or int(
                counters["totals"]["authorityExpansionObservations"]
            )
            > int(counters["totals"]["evaluated"])
            or int(
                counters["totals"][
                    "authorityExpansionWriteObservations"
                ]
            )
            > int(
                counters["totals"]["authorityExpansionObservations"]
            )
            or int(counters["totals"]["ingressAdmitted"]) != row_observed
            or row_failure_totals["dropReasons"]
            != int(counters["totals"]["dropped"])
            or row_failure_totals["errorReasons"]
            != int(counters["totals"]["errors"])
            or any(
                int(histograms[series]["total"]) > row_observed
                for series in _POLICY_AUTHORITY_LATENCY_SERIES
            )
            or int(row["observed_request_count"]) != row_observed
            or int(row["evaluated_request_count"]) != row_matrix_total
            or int(row["dropped_request_count"])
            != int(counters["totals"]["dropped"])
            or int(row["evaluation_error_count"])
            != int(counters["totals"]["errors"])
            or int(row["excluded_request_count"])
            != int(counters["totals"]["excluded"])
            or int(row["excluded_count"])
            != int(counters["totals"]["excluded"])
            or int(row["indeterminate_count"]) != row_indeterminate
            or int(row["active_indeterminate_count"])
            != row_active_indeterminate
            or int(row["candidate_indeterminate_count"])
            != row_candidate_indeterminate
            or int(row["response_divergence_count"])
            != int(
                counters["comparability"][
                    "comparableValidationDivergence"
                ]
            )
            or int(row["response_validator_unavailable_count"])
            != row_validator_unavailable
        ):
            raise PolicyCandidateAuthorityConflictError(
                "sealed aggregate marginals diverge from semantic authority"
            )
        checkpoint_payload = loads(
            row["checkpoint_payload_json"], None
        )
        heartbeat_range = checkpoint_payload["cumulativeHeartbeats"]
        if not isinstance(heartbeat_range, dict):
            raise PolicyCandidateAuthorityConflictError(
                "sealed member heartbeat range is not exact"
            )
        member_comparable = int(
            counters["totals"]["comparableResponses"]
        )
        candidate_p99 = _policy_authority_latency_p99(
            "sealed member candidate evaluation",
            histograms["candidateEvaluation"],
        )
        shadow_p99 = _policy_authority_latency_p99(
            "sealed member shadow total",
            histograms["shadowTotal"],
        )
        member_routes = {
            entry["routeSha256"]: entry for entry in coverage
        }
        if len(member_routes) != len(coverage):
            raise PolicyCandidateAuthorityConflictError(
                "sealed member route coverage contains duplicates"
            )
        for obligation in obligations:
            route_coverage = member_routes.get(obligation["routeSha256"])
            if (
                route_coverage is None
                or route_coverage["obligationRootSha256"]
                != obligation["obligationRootSha256"]
                or int(route_coverage["comparableResponses"])
                < int(obligation["minimumComparableResponses"])
                or int(route_coverage["validationDivergences"]) != 0
                or int(route_coverage["validatorUnavailable"]) != 0
                or int(route_coverage["noncomparable"]) != 0
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "sealed member does not satisfy every route obligation"
                )
        maximum_heartbeat_gap = int(
            observation_window["maximumHeartbeatGapNanos"]
        )
        if (
            int(row["observed_request_count"])
            < int(thresholds["minimumIngressRequestsPerMember"])
            or int(row["evaluated_request_count"])
            < int(thresholds["minimumEvaluatedObservationsPerMember"])
            or member_comparable
            < int(thresholds["minimumComparableResponsesPerMember"])
            or candidate_p99 is None
            or candidate_p99
            > int(thresholds["maximumCandidateEvaluationP99Nanos"])
            or shadow_p99 is None
            or shadow_p99
            > int(thresholds["maximumShadowTotalP99Nanos"])
            or int(counters["totals"]["dropped"]) != 0
            or int(counters["totals"]["errors"]) != 0
            or int(counters["totals"]["unavailableEvidence"]) != 0
            or int(counters["totals"]["activeIndeterminate"]) != 0
            or int(
                counters["totals"]["unapprovedActiveIndeterminate"]
            ) != 0
            or int(counters["totals"]["candidateIndeterminate"]) != 0
            or int(counters["totals"]["responseValidationDivergence"])
            != 0
            or int(counters["totals"]["responseValidatorUnavailable"])
            != 0
            or int(counters["totals"]["responseNoncomparable"]) != 0
            or int(row["gap_count"]) != 0
            or int(heartbeat_range["heartbeatCount"]) < 1
            or int(heartbeat_range["maximumObservedGapNanos"])
            > maximum_heartbeat_gap
            or int(heartbeat_range["lastHeartbeatAtUnixNanos"])
            > int(observation_window["endsAtUnixNanos"])
            or int(observation_window["endsAtUnixNanos"])
            - int(heartbeat_range["lastHeartbeatAtUnixNanos"])
            > maximum_heartbeat_gap
            or int(row["window_started_at_epoch_ns"])
            != int(observation_window["startsAtUnixNanos"])
            or int(row["window_ended_at_epoch_ns"])
            != int(observation_window["endsAtUnixNanos"])
            or int(row["sealed_at_epoch_ns"])
            != int(observation_window["endsAtUnixNanos"])
            or now_epoch_ns
            > int(observation_window["sealDeadlineUnixNanos"])
            or now_epoch_ns - int(row["last_observed_at_epoch_ns"])
            > int(observation_window["maximumEvidenceAgeNanos"])
        ):
            raise PolicyCandidateAuthorityConflictError(
                "sealed member fails its independent readiness obligations"
            )
        load_payload = loads(
            runtime_context["load_receipt_payload_json"], None
        )
        generation = checkpoint_payload["generation"]
        member_evidence.append(
            {
                "instanceId": str(row["instance_id"]),
                "spiffeId":
                    load_payload["runtimeIdentity"]["spiffeId"],
                "bootIdSha256":
                    load_payload["runtimeIdentity"]["bootIdSha256"],
                "generationId": generation["generationId"],
                "generationEpoch": generation["generationEpoch"],
                "generationTombstoneEpoch":
                    generation["generationTombstoneEpoch"],
                "loadReceiptSha256":
                    runtime_context["load_receipt_envelope_digest"],
                "loadReceiptPayloadSha256":
                    runtime_context["load_receipt_payload_digest"],
                "finalCheckpointSha256":
                    str(row["checkpoint_envelope_digest"]),
                "finalCheckpointPayloadSha256":
                    str(row["checkpoint_payload_digest"]),
                "finalCheckpointSequence":
                    int(row["checkpoint_sequence"]),
                "lastObservationSequence":
                    int(row["observed_request_count"]),
                "lastIngressSequence":
                    int(row["request_sequence_end"]),
                "observationCount":
                    int(row["observed_request_count"]),
                "ingressCount": int(row["ingress_count"]),
                "evaluatedObservationCount":
                    int(row["evaluated_request_count"]),
                "comparableResponseCount": member_comparable,
                "heartbeatCount":
                    int(heartbeat_range["heartbeatCount"]),
                "lastHeartbeatSequence":
                    int(heartbeat_range["lastHeartbeatSequence"]),
                "lastHeartbeatAtUnixNanos":
                    int(heartbeat_range["lastHeartbeatAtUnixNanos"]),
                "maximumObservedHeartbeatGapNanos":
                    int(heartbeat_range["maximumObservedGapNanos"]),
                "cumulativeObservationRootSha256":
                    str(row["observation_root_digest"]),
                "cumulativeIngressRootSha256":
                    str(row["ingress_root_digest"]),
                "cumulativeActiveDecisionRootSha256":
                    str(row["active_decision_root_digest"]),
                "cumulativePrincipalAuthorityRootSha256":
                    str(row["principal_authority_root_digest"]),
                "cumulativeRouteAuthorityRootSha256":
                    str(row["route_authority_root_digest"]),
                "cumulativeHeartbeatRootSha256":
                    str(heartbeat_range["cumulativeHeartbeatRootSha256"]),
                "sealRootSha256": str(row["seal_root_digest"]),
                "sealedAtUnixNanos": int(row["sealed_at_epoch_ns"]),
            }
        )
        merged["gaps"] += int(row["gap_count"])
    if (
        preverified_member_aggregates is not None
        and consumed_preverified_members
        != set(preverified_member_aggregates)
    ):
        raise PolicyCandidateAuthorityConflictError(
            "preverified member aggregate set differs from the signed fleet"
        )
    observed_total = sum(
        int(merged["totals"][key])
        for key in ("evaluated", "dropped", "errors", "excluded")
    )
    evaluated_total = int(merged["totals"]["evaluated"])
    semantic_total = sum(
        int(value) for value in merged["semanticMatrix"].values()
    )
    response_total = sum(
        int(value) for value in merged["responseClasses"].values()
    )
    expansion_observation_total = int(
        merged["totals"]["authorityExpansionObservations"]
    )
    expansion_write_observation_total = int(
        merged["totals"]["authorityExpansionWriteObservations"]
    )
    if (
        semantic_total != evaluated_total
        or response_total != evaluated_total
        or int(merged["totals"]["comparableResponses"])
        != sum(
            int(count)
            for classification, count in merged["responseClasses"].items()
            if classification.startswith("comparable-")
        )
        or int(merged["totals"]["responseNoncomparable"])
        != sum(
            int(count)
            for classification, count in merged["responseClasses"].items()
            if classification.startswith("not-comparable-")
        )
        or int(merged["totals"]["responseValidationDivergence"])
        != int(
            merged["responseClasses"][
                "comparable-validation-divergence"
            ]
        )
        or int(merged["totals"]["responseValidatorUnavailable"])
        != int(
            merged["responseClasses"][
                "not-comparable-candidate-validator-unavailable"
            ]
        )
        or expansion_observation_total > evaluated_total
        or expansion_write_observation_total
        > expansion_observation_total
        or bool(merged["expansionCells"])
        != (expansion_observation_total > 0)
        or any(
            int(entry["requestCount"]) > expansion_observation_total
            or int(entry["writeRequestCount"])
            > expansion_write_observation_total
            or int(entry["responseCount"])
            > int(entry["requestCount"])
            or int(entry["writeResponseCount"])
            > int(entry["writeRequestCount"])
            for entry in merged["expansionCells"].values()
        )
        or sum(merged["dropReasons"].values())
        != int(merged["totals"]["dropped"])
        or sum(merged["errorReasons"].values())
        != int(merged["totals"]["errors"])
        or any(
            int(merged["latencyHistograms"][series]["total"])
            > observed_total
            or sum(merged["latencyHistograms"][series]["buckets"])
            != int(merged["latencyHistograms"][series]["total"])
            for series in _POLICY_AUTHORITY_LATENCY_SERIES
        )
        or any(
            int(route["validationDivergences"])
            > int(route["comparableResponses"])
            for route in merged["responseRouteCoverage"].values()
        )
    ):
        raise PolicyCandidateAuthorityConflictError(
            "sealed fleet aggregate is not internally complete"
        )
    fleet_candidate_histogram = {
        **{
            field: merged["latencyHistograms"]["candidateEvaluation"][
                "buckets"
            ][index]
            for index, field
            in enumerate(_POLICY_AUTHORITY_LATENCY_COUNTER_FIELDS)
        },
        "total":
            merged["latencyHistograms"]["candidateEvaluation"]["total"],
    }
    fleet_shadow_histogram = {
        **{
            field: merged["latencyHistograms"]["shadowTotal"][
                "buckets"
            ][index]
            for index, field
            in enumerate(_POLICY_AUTHORITY_LATENCY_COUNTER_FIELDS)
        },
        "total": merged["latencyHistograms"]["shadowTotal"]["total"],
    }
    fleet_candidate_p99 = _policy_authority_latency_p99(
        "sealed fleet candidate evaluation", fleet_candidate_histogram
    )
    fleet_shadow_p99 = _policy_authority_latency_p99(
        "sealed fleet shadow total", fleet_shadow_histogram
    )
    if (
        observed_total < int(thresholds["minimumIngressRequests"])
        or evaluated_total
        < int(thresholds["minimumEvaluatedObservations"])
        or int(merged["totals"]["comparableResponses"])
        < int(thresholds["minimumComparableResponses"])
        or fleet_candidate_p99 is None
        or fleet_candidate_p99
        > int(thresholds["maximumCandidateEvaluationP99Nanos"])
        or fleet_shadow_p99 is None
        or fleet_shadow_p99
        > int(thresholds["maximumShadowTotalP99Nanos"])
    ):
        raise PolicyCandidateAuthorityConflictError(
            "sealed fleet fails its signed aggregate thresholds"
        )
    for obligation in obligations:
        route = merged["responseRouteCoverage"].get(
            obligation["routeSha256"]
        )
        if (
            route is None
            or route["obligationRootSha256"]
            != obligation["obligationRootSha256"]
            or int(route["comparableResponses"])
            < int(obligation["minimumComparableResponses"])
            or int(route["validationDivergences"]) != 0
            or int(route["validatorUnavailable"]) != 0
            or int(route["noncomparable"]) != 0
        ):
            raise PolicyCandidateAuthorityConflictError(
                "sealed fleet route coverage is incomplete"
            )
    expansion_cells = [
        dict(merged["expansionCells"][digest])
        for digest in sorted(merged["expansionCells"])
    ]
    route_coverage = [
        dict(merged["responseRouteCoverage"][route_id])
        for route_id in sorted(merged["responseRouteCoverage"])
    ]
    histograms = {
        series: {
            **{
                field: merged["latencyHistograms"][series][
                    "buckets"
                ][index]
                for index, field
                in enumerate(_POLICY_AUTHORITY_LATENCY_COUNTER_FIELDS)
            },
            "total": merged["latencyHistograms"][series]["total"],
        }
        for series in _POLICY_AUTHORITY_LATENCY_SERIES
    }
    direct_counters = _policy_authority_direct_cumulative_counters(merged)
    counters_json, counters_digest = _candidate_authority_canonical_value(
        "fleet aggregate counters", direct_counters
    )
    matrix_json, matrix_digest = _candidate_authority_canonical_value(
        "fleet semantic matrix", merged["semanticMatrix"]
    )
    expansion_json, expansion_digest = _candidate_authority_canonical_value(
        "fleet expansion cells", expansion_cells
    )
    coverage_json, coverage_digest = _candidate_authority_canonical_value(
        "fleet response coverage", route_coverage
    )
    histogram_json, histogram_digest = _candidate_authority_canonical_value(
        "fleet latency histograms", histograms
    )
    drops_json, drops_digest = _candidate_authority_canonical_value(
        "fleet drop counters", direct_counters["drops"]
    )
    errors_json, errors_digest = _candidate_authority_canonical_value(
        "fleet error counters", direct_counters["errors"]
    )
    checkpoint_material = [
        {
            "aggregateContractDigest":
                str(row["aggregate_contract_digest"]),
            "bootId": str(row["boot_id"]),
            "checkpointEnvelopeDigest":
                str(row["checkpoint_envelope_digest"]),
            "checkpointPayloadDigest":
                str(row["checkpoint_payload_digest"]),
            "checkpointSequence": int(row["checkpoint_sequence"]),
            "instanceId": str(row["instance_id"]),
            "memberOrdinal": int(row["member_ordinal"]),
            "observationRootDigest": str(row["observation_root_digest"]),
            "sealRootDigest": str(row["seal_root_digest"]),
        }
        for row in rows
    ]
    instance_material = [
        {
            "attestationVerifierReceiptDigest":
                str(row["attestation_verifier_receipt_digest"]),
            "bootId": str(row["boot_id"]),
            "headRevision": int(row["head_revision"]),
            "headStateDigest": str(row["head_state_digest"]),
            "instanceId": str(row["instance_id"]),
            "memberId": str(row["member_id"]),
            "memberOrdinal": int(row["member_ordinal"]),
            "membershipRootSha256": str(row["membership_root_digest"]),
        }
        for row in rows
    ]
    indeterminate_total = sum(
        int(count)
        for cell, count in merged["semanticMatrix"].items()
        if "indeterminate" in cell
    )
    active_indeterminate_total = sum(
        int(count)
        for cell, count in merged["semanticMatrix"].items()
        if cell.startswith("indeterminate:")
    )
    candidate_indeterminate_total = sum(
        int(count)
        for cell, count in merged["semanticMatrix"].items()
        if cell.endswith(":indeterminate")
    )
    response_divergence_total = int(
        merged["responseClasses"]["comparable-validation-divergence"]
    )
    response_validator_unavailable_total = int(
        merged["totals"]["responseValidatorUnavailable"]
    )
    member_evidence_root = _policy_shadow_merkle_root(
        [
            (
                index,
                _candidate_authority_sha256(
                    dumps(evidence).encode("ascii")
                ),
            )
            for index, evidence
            in enumerate(member_evidence, start=1)
        ]
    )
    result = {
        "sealed_checkpoint_root_digest": _candidate_authority_sha256(
            dumps(checkpoint_material).encode("ascii")
        ),
        "sealed_instance_set_digest": member_evidence_root,
        "observed_request_count": observed_total,
        "evaluated_request_count": evaluated_total,
        "dropped_request_count": int(merged["totals"]["dropped"]),
        "evaluation_error_count": int(merged["totals"]["errors"]),
        "excluded_request_count": int(merged["totals"]["excluded"]),
        "active_indeterminate_count": active_indeterminate_total,
        "candidate_indeterminate_count": candidate_indeterminate_total,
        "aggregate_counters_json": counters_json,
        "aggregate_counters_digest": counters_digest,
        "semantic_matrix_json": matrix_json,
        "semantic_matrix_digest": matrix_digest,
        "expansion_cells_json": expansion_json,
        "expansion_cells_digest": expansion_digest,
        "response_route_coverage_json": coverage_json,
        "response_route_coverage_digest": coverage_digest,
        "latency_histograms_json": histogram_json,
        "latency_histograms_digest": histogram_digest,
        "drop_counters_json": drops_json,
        "drop_counters_digest": drops_digest,
        "error_counters_json": errors_json,
        "error_counters_digest": errors_digest,
        "gap_count": int(merged["gaps"]),
        "indeterminate_count": indeterminate_total,
        "response_divergence_count": response_divergence_total,
        "response_validator_unavailable_count":
            response_validator_unavailable_total,
        "checkpoint_material": checkpoint_material,
        "instance_material": instance_material,
        "member_evidence": member_evidence,
        "member_evidence_root_digest": member_evidence_root,
        "fleet_id": str(rows[0]["fleet_id"]),
        "membership_revision": int(rows[0]["membership_revision"]),
        "membership_root_digest":
            str(rows[0]["membership_root_digest"]),
        "candidate_evaluation_p99_nanos": fleet_candidate_p99,
        "shadow_total_p99_nanos": fleet_shadow_p99,
        "readiness_thresholds": thresholds,
    }
    result["sealed_aggregate_digest"] = _policy_authority_domain_digest(
        b"serverware.policyShadowFleetAggregate/v1",
        dumps(
            {
                "aggregateCountersDigest": counters_digest,
                "errorCountersDigest": errors_digest,
                "expansionCellsDigest": expansion_digest,
                "latencyHistogramsDigest": histogram_digest,
                "responseRouteCoverageDigest": coverage_digest,
                "semanticMatrixDigest": matrix_digest,
                "dropCountersDigest": drops_digest,
                "sealedCheckpointRootDigest":
                    result["sealed_checkpoint_root_digest"],
                "sealedInstanceSetDigest":
                    result["sealed_instance_set_digest"],
            }
        ).encode("ascii"),
    )
    return result


