def _control_plane_approval_row(
    conn: Any,
    approval_id: str,
    *,
    for_update: bool,
) -> Any | None:
    suffix = (
        " FOR UPDATE"
        if for_update and isinstance(conn, PostgresMetadataConnection)
        else ""
    )
    return conn.execute(
        "SELECT "
        + _policy_authority_projection(_CONTROL_PLANE_APPROVAL_COLUMNS)
        + " FROM control_plane_approvals WHERE id = ?"
        + suffix,
        (approval_id,),
    ).fetchone()


def _verify_policy_activation_webauthn_assertion(
    conn: Any,
    *,
    approval: Mapping[str, Any],
    control_plane_approval: Any,
    assertion_json: str,
    verified_at: datetime,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    assertion_json = _candidate_authority_canonical_json(
        "policy activation WebAuthn assertion",
        assertion_json,
    )
    assertion = loads(assertion_json, None)
    allowed_assertion_fields = {
        "id",
        "rawId",
        "type",
        "response",
        "clientExtensionResults",
        "authenticatorAttachment",
    }
    if (
        not isinstance(assertion, dict)
        or not {"id", "type", "response"} <= set(assertion)
        or not set(assertion) <= allowed_assertion_fields
        or assertion["type"] != "public-key"
        or not isinstance(assertion["response"], dict)
    ):
        raise PolicyCandidateAuthorityError(
            "policy activation WebAuthn assertion shape is invalid"
        )
    credential_id = _candidate_authority_text(
        "WebAuthn credential id", assertion["id"], maximum=2048
    )
    if assertion.get("rawId") not in {None, credential_id}:
        raise PolicyCandidateAuthorityError(
            "WebAuthn assertion id and rawId do not match"
        )
    response = assertion["response"]
    if (
        not {"clientDataJSON", "authenticatorData", "signature"} <= set(response)
        or not set(response)
        <= {"clientDataJSON", "authenticatorData", "signature", "userHandle"}
    ):
        raise PolicyCandidateAuthorityError(
            "policy activation WebAuthn response fields are not exact"
        )
    client_data_raw = _candidate_authority_b64url_bounded(
        "clientDataJSON", response["clientDataJSON"], maximum_bytes=64 * 1024
    )
    authenticator_data = _candidate_authority_b64url_bounded(
        "authenticatorData",
        response["authenticatorData"],
        maximum_bytes=4096,
    )
    assertion_signature = _candidate_authority_b64url_bounded(
        "WebAuthn assertion signature",
        response["signature"],
        maximum_bytes=512,
    )
    try:
        client_data = json.loads(client_data_raw)
    except (UnicodeDecodeError, ValueError, TypeError) as exc:
        raise PolicyCandidateAuthorityError(
            "WebAuthn client data is invalid JSON"
        ) from exc
    if (
        not isinstance(client_data, dict)
        or not {"type", "challenge", "origin"} <= set(client_data)
        or not set(client_data)
        <= {"type", "challenge", "origin", "crossOrigin", "tokenBinding"}
        or client_data["type"] != "webauthn.get"
        or client_data["origin"] != WEBAUTHN_ORIGIN
        or client_data.get("crossOrigin") not in {None, False}
    ):
        raise PolicyCandidateAuthorityError(
            "WebAuthn client data type, origin, or cross-origin state is invalid"
        )
    challenge_value = _candidate_authority_text(
        "WebAuthn challenge", client_data["challenge"], maximum=2048
    )
    challenge = conn.execute(
        "SELECT "
        + _policy_authority_projection(_WEBAUTHN_CHALLENGE_COLUMNS)
        + " FROM webauthn_challenges WHERE challenge = ?",
        (challenge_value,),
    ).fetchone()
    now_s = verified_at.isoformat()
    if (
        challenge is None
        or challenge["challenge_type"] != "control-plane-mutation"
        or challenge["user_id"] != control_plane_approval["approved_by"]
        or challenge["used_at"] is None
        or challenge["used_at"] > now_s
        or challenge["expires_at"] <= now_s
        or (
            challenge["approval_request_id"] is not None
            and challenge["approval_request_id"] != control_plane_approval["id"]
        )
    ):
        raise PolicyCandidateAuthorityConflictError(
            "WebAuthn activation challenge is missing, stale, or not consumed"
        )
    activation_challenge_material = {
        "action": _POLICY_CANDIDATE_ACTIVATION_ACTION,
        "activationIntentDigest":
            approval["activation_intent_digest"],
        "approvalMode": approval["approval_mode"],
        "approvalContextDigest": approval["approval_context_digest"],
        "authorityAnalysisMode": approval["authority_analysis_mode"],
        "candidatePolicyHash": approval["candidate_policy_hash"],
        "candidatePolicySequence": approval["candidate_policy_sequence"],
        "candidateRollbackEpoch": approval["candidate_rollback_epoch"],
        "compilerAnalysisPayloadDigest":
            approval["compiler_analysis_payload_digest"],
        "controlPlaneApprovalId": control_plane_approval["id"],
        "expectedActivePolicySequence":
            approval["expected_active_policy_sequence"],
        "expectedActiveRollbackEpoch":
            approval["expected_active_rollback_epoch"],
        "expansionCellsDigest": approval["expansion_cells_digest"],
        "predecessorPolicyHash": approval["predecessor_policy_hash"],
        "publicationRevision": approval["publication_revision"],
        "readinessCoreDigest": approval["readiness_core_digest"],
        "readinessPayloadDigest": approval["readiness_payload_digest"],
        "requesterId": approval["requester_id"],
        "requiredApprovalQuorum": approval["required_member_count"],
        "webauthnChallengeContextDigest":
            approval["webauthn_challenge_context_digest"],
    }
    activation_challenge_digest = _candidate_authority_sha256(
        dumps(activation_challenge_material).encode("ascii")
    )
    expected_challenge_payload = {
        "type": "serverware.policy_candidate_activation",
        "user_id": control_plane_approval["approved_by"],
        "action": _POLICY_CANDIDATE_ACTIVATION_ACTION,
        "resource_id": approval["canary_id"],
        "payload_digest": approval["approval_context_digest"],
        "control_plane_approval_id": control_plane_approval["id"],
        "approval_requester_id": approval["requester_id"],
        "approval_expires_at": control_plane_approval["expires_at"],
        "decision": "approve",
        "readiness_payload_digest": approval["readiness_payload_digest"],
        "readiness_core_digest": approval["readiness_core_digest"],
        "compiler_analysis_payload_digest":
            approval["compiler_analysis_payload_digest"],
        "authority_analysis_mode": approval["authority_analysis_mode"],
        "approval_mode": approval["approval_mode"],
        "required_approval_quorum": approval["required_member_count"],
        "expansion_cells_digest": approval["expansion_cells_digest"],
        "publication_revision": approval["publication_revision"],
        "expected_active_policy_sequence":
            approval["expected_active_policy_sequence"],
        "expected_active_rollback_epoch":
            approval["expected_active_rollback_epoch"],
        "predecessor_policy_hash": approval["predecessor_policy_hash"],
        "webauthn_challenge_context_digest":
            approval["webauthn_challenge_context_digest"],
        "activation_intent_digest":
            approval["activation_intent_digest"],
        "activation_challenge_digest": activation_challenge_digest,
    }
    challenge_payload_json = str(challenge["payload_json"])
    try:
        challenge_payload = loads(challenge_payload_json, None)
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise PolicyCandidateAuthorityError(
            "WebAuthn activation challenge payload is invalid"
        ) from exc
    if (
        challenge_payload_json != dumps(challenge_payload)
        or challenge_payload != expected_challenge_payload
    ):
        raise PolicyCandidateAuthorityConflictError(
            "WebAuthn challenge does not bind the exact activation"
        )

    credential = conn.execute(
        "SELECT "
        + _policy_authority_projection(_WEBAUTHN_CREDENTIAL_COLUMNS)
        + " FROM webauthn_credentials WHERE credential_id = ?",
        (credential_id,),
    ).fetchone()
    trust = conn.execute(
        "SELECT "
        + _policy_authority_projection(
            _WEBAUTHN_TRUST_PUBLICATION_AUTHORITY_COLUMNS
        )
        + " FROM webauthn_trust_publications "
        "WHERE status = 'published' ORDER BY rollback_epoch DESC, "
        "sequence DESC LIMIT 1"
    ).fetchone()
    approver_id = str(control_plane_approval["approved_by"])
    if (
        credential is None
        or credential["user_id"] != approver_id
        or credential["id"]
        != control_plane_approval["approver_webauthn_credential_id"]
        or credential["revoked_at"] is not None
        or credential["attestation_trusted"] != 1
        or credential["authenticator_class"] not in {"yubikey", "hardware"}
        or trust is None
        or credential["attestation_trust_bundle_digest"]
        != trust["bundle_digest"]
        or int(credential["attestation_trust_bundle_sequence"] or 0)
        != int(trust["sequence"])
    ):
        raise PolicyCandidateAuthorityConflictError(
            "WebAuthn credential is not a currently trusted hardware authenticator"
        )
    if len(authenticator_data) < 37:
        raise PolicyCandidateAuthorityError(
            "WebAuthn authenticator data is truncated"
        )
    expected_rp_hash = hashlib.sha256(WEBAUTHN_RP_ID.encode("utf-8")).digest()
    flags = authenticator_data[32]
    sign_count = int.from_bytes(authenticator_data[33:37], "big")
    if (
        not hmac.compare_digest(authenticator_data[:32], expected_rp_hash)
        or flags & 0x01 == 0
        or flags & 0x04 == 0
        or sign_count <= 0
        or sign_count != int(credential["sign_count"])
    ):
        raise PolicyCandidateAuthorityConflictError(
            "WebAuthn RP, UP, UV, or sign-count evidence is invalid"
        )
    try:
        public_key_cose_raw = _candidate_authority_b64url_bounded(
            "WebAuthn credential public key",
            credential["public_key_cose"],
            maximum_bytes=4096,
        )
        cose = cbor2.loads(public_key_cose_raw)
        if (
            not isinstance(cose, dict)
            or cose.get(1) != 2
            or cose.get(3) != -7
            or cose.get(-1) != 1
            or not isinstance(cose.get(-2), bytes)
            or not isinstance(cose.get(-3), bytes)
            or len(cose[-2]) != 32
            or len(cose[-3]) != 32
        ):
            raise ValueError("unsupported COSE key")
        public_key = ec.EllipticCurvePublicKey.from_encoded_point(
            ec.SECP256R1(), b"\x04" + cose[-2] + cose[-3]
        )
        public_key.verify(
            assertion_signature,
            authenticator_data + hashlib.sha256(client_data_raw).digest(),
            ec.ECDSA(hashes.SHA256()),
        )
    except (ValueError, TypeError, cbor2.CBORDecodeError, InvalidSignature) as exc:
        raise PolicyCandidateAuthorityError(
            "WebAuthn activation assertion signature is invalid"
        ) from exc

    approved_at = datetime.fromisoformat(str(control_plane_approval["approved_at"]))
    challenge_created_at = datetime.fromisoformat(
        str(challenge["created_at"])
    )
    challenge_used_at = datetime.fromisoformat(str(challenge["used_at"]))
    if (
        approved_at.tzinfo is None
        or challenge_created_at.tzinfo is None
        or challenge_used_at.tzinfo is None
        or challenge_used_at < challenge_created_at
        or approved_at < challenge_used_at
        or verified_at < approved_at
        or verified_at < challenge_used_at
        or (
            verified_at - challenge_created_at
        ).total_seconds() > _POLICY_ACTIVATION_ASSERTION_MAX_AGE_SECONDS
        or (
            verified_at - challenge_used_at
        ).total_seconds() > _POLICY_ACTIVATION_ASSERTION_MAX_AGE_SECONDS
        or (
            verified_at - approved_at
        ).total_seconds() > _POLICY_ACTIVATION_ASSERTION_MAX_AGE_SECONDS
    ):
        raise PolicyCandidateAuthorityConflictError(
            "WebAuthn activation assertion is not fresh"
        )

    assertion_digest = _candidate_authority_sha256(
        assertion_json.encode("ascii")
    )
    client_data_digest = _candidate_authority_sha256(client_data_raw)
    authenticator_data_digest = _candidate_authority_sha256(authenticator_data)
    assertion_signature_digest = _candidate_authority_sha256(
        assertion_signature
    )
    challenge_payload_digest = _candidate_authority_sha256(
        challenge_payload_json.encode("ascii")
    )
    control_plane_snapshot = {
        "schema": "serverware.controlPlaneApprovalSnapshot/v1",
        "id": control_plane_approval["id"],
        "action": control_plane_approval["action"],
        "resourceId": control_plane_approval["resource_id"],
        "payloadDigest": control_plane_approval["payload_digest"],
        "requesterId": control_plane_approval["requester_id"],
        "requestedAt": control_plane_approval["requested_at"],
        "expiresAt": control_plane_approval["expires_at"],
        "requestJson": control_plane_approval["request_json"],
        "requestJsonDigest": _candidate_authority_sha256(
            str(control_plane_approval["request_json"]).encode("utf-8")
        ),
        "approvalStateAtVerification": "approved",
        "approvedBy": control_plane_approval["approved_by"],
        "approvedAt": control_plane_approval["approved_at"],
        "decisionNote": control_plane_approval["decision_note"],
        "approvalAuthn": control_plane_approval["approval_authn"],
        "approverWebauthnCredentialId":
            control_plane_approval[
                "approver_webauthn_credential_id"
            ],
    }
    (
        control_plane_approval_snapshot_json,
        control_plane_approval_snapshot_digest,
    ) = _candidate_authority_canonical_value(
        "control-plane approval authority snapshot",
        control_plane_snapshot,
        maximum=1024 * 1024,
    )
    challenge_snapshot = {
        "schema": "serverware.webauthnChallengeSnapshot/v1",
        "id": challenge["id"],
        "challenge": challenge["challenge"],
        "challengeType": challenge["challenge_type"],
        "userId": challenge["user_id"],
        "scopeKey": challenge["scope_key"],
        "approvalRequestId": challenge["approval_request_id"],
        "payloadJson": challenge_payload_json,
        "payloadDigest": challenge_payload_digest,
        "expiresAt": challenge["expires_at"],
        "usedAt": challenge["used_at"],
        "createdAt": challenge["created_at"],
    }
    (
        webauthn_challenge_snapshot_json,
        webauthn_challenge_snapshot_digest,
    ) = _candidate_authority_canonical_value(
        "consumed WebAuthn challenge snapshot",
        challenge_snapshot,
        maximum=1024 * 1024,
    )
    credential_authority = {
        "schema": "serverware.webauthnCredentialAuthoritySnapshot/v1",
        "recordId": credential["id"],
        "credentialId": credential["credential_id"],
        "userId": credential["user_id"],
        "publicKeyCose": credential["public_key_cose"],
        "publicKeyCoseSha256":
            _candidate_authority_sha256(public_key_cose_raw),
        "signCount": int(credential["sign_count"]),
        "aaguid": credential["aaguid"],
        "authenticatorClass": credential["authenticator_class"],
        "attestationFormat": credential["attestation_fmt"],
        "attestationTrusted": int(credential["attestation_trusted"]),
        "attestationTrustPath": credential["attestation_trust_path"],
        "attestationLeafSha256": credential["attestation_leaf_sha256"],
        "attestationRootSha256": credential["attestation_root_sha256"],
        "attestationTrustBundleDigest":
            credential["attestation_trust_bundle_digest"],
        "attestationTrustBundleSequence":
            credential["attestation_trust_bundle_sequence"],
        "attestationVerifiedAt":
            credential["attestation_verified_at"],
        "transports": credential["transports"],
        "createdAt": credential["created_at"],
        "revokedAt": credential["revoked_at"],
        "revokedBy": credential["revoked_by"],
        "revocationReason": credential["revocation_reason"],
        "revocationSource": credential["revocation_source"],
    }
    webauthn_credential_version_digest = (
        _policy_authority_domain_digest(
            b"serverware.webauthnCredentialVersion/v1",
            dumps(credential_authority).encode("ascii"),
        )
    )
    credential_snapshot = {
        **credential_authority,
        "credentialVersionDigest":
            webauthn_credential_version_digest,
    }
    (
        webauthn_credential_snapshot_json,
        webauthn_credential_snapshot_digest,
    ) = _candidate_authority_canonical_value(
        "WebAuthn credential authority snapshot",
        credential_snapshot,
        maximum=1024 * 1024,
    )
    trust_snapshot = {
        "schema": "serverware.webauthnTrustPublicationSnapshot/v1",
        **{
            column: trust[column]
            for column in
            _WEBAUTHN_TRUST_PUBLICATION_AUTHORITY_COLUMNS
        },
        "publicationStateAtVerification": "published",
    }
    (
        webauthn_trust_publication_snapshot_json,
        webauthn_trust_publication_snapshot_digest,
    ) = _candidate_authority_canonical_value(
        "WebAuthn trust publication snapshot",
        trust_snapshot,
        maximum=_POLICY_AUTHORITY_MAX_CANONICAL_AGGREGATE_BYTES,
    )
    webauthn_credential_public_key_digest = (
        credential_authority["publicKeyCoseSha256"]
    )
    receipt_material = {
        "activationChallengeDigest": activation_challenge_digest,
        "approvalContextDigest": approval["approval_context_digest"],
        "assertionDigest": assertion_digest,
        "authenticatorDataDigest": authenticator_data_digest,
        "challengeId": challenge["id"],
        "challengeCreatedAt": challenge["created_at"],
        "assertionIssuedAt": challenge["used_at"],
        "approvalApprovedAt": control_plane_approval["approved_at"],
        "clientDataDigest": client_data_digest,
        "controlPlaneApprovalId": control_plane_approval["id"],
        "credentialRecordId": credential["id"],
        "controlPlaneApprovalSnapshotDigest":
            control_plane_approval_snapshot_digest,
        "webauthnChallengeSnapshotDigest":
            webauthn_challenge_snapshot_digest,
        "webauthnCredentialSnapshotDigest":
            webauthn_credential_snapshot_digest,
        "webauthnCredentialVersionDigest":
            webauthn_credential_version_digest,
        "webauthnCredentialPublicKeyDigest":
            webauthn_credential_public_key_digest,
        "webauthnTrustPublicationSnapshotDigest":
            webauthn_trust_publication_snapshot_digest,
        "readinessPayloadDigest": approval["readiness_payload_digest"],
        "signCount": sign_count,
        "trustBundleDigest": trust["bundle_digest"],
        "trustBundleSequence": int(trust["sequence"]),
    }
    assertion_receipt_digest = _candidate_authority_sha256(
        dumps(receipt_material).encode("ascii")
    )
    verified_at_epoch_ns = int(verified_at.timestamp() * 1_000_000_000)
    assertion_row = {
        "assertion_receipt_digest": assertion_receipt_digest,
        "approval_id": approval["approval_id"],
        "control_plane_approval_id": control_plane_approval["id"],
        "approver_id": approver_id,
        "credential_record_id": credential["id"],
        "challenge_id": challenge["id"],
        "readiness_payload_digest": approval["readiness_payload_digest"],
        "activation_intent_digest":
            approval["activation_intent_digest"],
        "approval_context_digest": approval["approval_context_digest"],
        "assertion_digest": assertion_digest,
        "assertion_json": assertion_json,
        "client_data_digest": client_data_digest,
        "authenticator_data_digest": authenticator_data_digest,
        "assertion_signature_digest": assertion_signature_digest,
        "challenge_payload_digest": challenge_payload_digest,
        "rp_id": WEBAUTHN_RP_ID,
        "origin": WEBAUTHN_ORIGIN,
        "client_data_type": "webauthn.get",
        "authenticator_class": credential["authenticator_class"],
        "trust_bundle_digest": trust["bundle_digest"],
        "trust_bundle_sequence": int(trust["sequence"]),
        "sign_count": sign_count,
        "user_present": 1,
        "user_verified": 1,
        "attestation_trusted": 1,
        "control_plane_approval_snapshot_json":
            control_plane_approval_snapshot_json,
        "control_plane_approval_snapshot_digest":
            control_plane_approval_snapshot_digest,
        "webauthn_challenge_snapshot_json":
            webauthn_challenge_snapshot_json,
        "webauthn_challenge_snapshot_digest":
            webauthn_challenge_snapshot_digest,
        "webauthn_credential_snapshot_json":
            webauthn_credential_snapshot_json,
        "webauthn_credential_snapshot_digest":
            webauthn_credential_snapshot_digest,
        "webauthn_credential_version_digest":
            webauthn_credential_version_digest,
        "webauthn_credential_public_key_digest":
            webauthn_credential_public_key_digest,
        "webauthn_trust_publication_snapshot_json":
            webauthn_trust_publication_snapshot_json,
        "webauthn_trust_publication_snapshot_digest":
            webauthn_trust_publication_snapshot_digest,
        "challenge_created_at": challenge["created_at"],
        "challenge_used_at": challenge["used_at"],
        "assertion_issued_at": challenge["used_at"],
        "approval_approved_at": control_plane_approval["approved_at"],
        "assertion_verified_at": verified_at.isoformat(),
        "verified_at_epoch_ns": verified_at_epoch_ns,
    }
    control_plane_request_json = str(control_plane_approval["request_json"])
    control_plane_request_digest = _candidate_authority_sha256(
        control_plane_request_json.encode("utf-8")
    )
    member_evidence = {
        "approvedAt": control_plane_approval["approved_at"],
        "approverId": approver_id,
        "assertionReceiptDigest": assertion_receipt_digest,
        "authenticatorId": credential["id"],
        "controlPlaneApprovalId": control_plane_approval["id"],
        "controlPlaneRequestDigest": control_plane_request_digest,
        "expiresAt": control_plane_approval["expires_at"],
    }
    member_row = {
        "control_plane_approval_id": control_plane_approval["id"],
        "approver_id": approver_id,
        "approver_webauthn_credential_id": credential["id"],
        "approval_evidence_digest": _candidate_authority_sha256(
            dumps(member_evidence).encode("ascii")
        ),
        "control_plane_request_digest": control_plane_request_digest,
        "webauthn_assertion_receipt_digest": assertion_receipt_digest,
        "webauthn_assertion_digest": assertion_digest,
        "webauthn_challenge_id": challenge["id"],
        "readiness_payload_digest": approval["readiness_payload_digest"],
        "activation_intent_digest":
            approval["activation_intent_digest"],
        "approval_context_digest": approval["approval_context_digest"],
        "approved_at": control_plane_approval["approved_at"],
        "expires_at": control_plane_approval["expires_at"],
    }
    return assertion_row, member_row, member_evidence


def _verify_historical_policy_activation_assertion(
    *,
    approval: Mapping[str, Any],
    member: Mapping[str, Any],
    persisted_assertion: Mapping[str, Any],
) -> None:
    snapshots: dict[str, Any] = {}
    for name, json_field, digest_field in (
        (
            "control approval",
            "control_plane_approval_snapshot_json",
            "control_plane_approval_snapshot_digest",
        ),
        (
            "challenge",
            "webauthn_challenge_snapshot_json",
            "webauthn_challenge_snapshot_digest",
        ),
        (
            "credential",
            "webauthn_credential_snapshot_json",
            "webauthn_credential_snapshot_digest",
        ),
        (
            "trust publication",
            "webauthn_trust_publication_snapshot_json",
            "webauthn_trust_publication_snapshot_digest",
        ),
    ):
        canonical, digest = _candidate_authority_json(
            "historical WebAuthn " + name,
            persisted_assertion[json_field],
            persisted_assertion[digest_field],
            maximum=_POLICY_AUTHORITY_MAX_CANONICAL_AGGREGATE_BYTES,
        )
        if digest != persisted_assertion[digest_field]:
            raise PolicyCandidateAuthorityConflictError(
                "historical WebAuthn snapshot digest changed"
            )
        snapshots[name] = loads(canonical, None)
    control = _candidate_authority_strict_object(
        "historical control approval snapshot",
        snapshots["control approval"],
        frozenset(
            {
                "schema",
                "id",
                "action",
                "resourceId",
                "payloadDigest",
                "requesterId",
                "requestedAt",
                "expiresAt",
                "requestJson",
                "requestJsonDigest",
                "approvalStateAtVerification",
                "approvedBy",
                "approvedAt",
                "decisionNote",
                "approvalAuthn",
                "approverWebauthnCredentialId",
            }
        ),
    )
    challenge = _candidate_authority_strict_object(
        "historical challenge snapshot",
        snapshots["challenge"],
        frozenset(
            {
                "schema",
                "id",
                "challenge",
                "challengeType",
                "userId",
                "scopeKey",
                "approvalRequestId",
                "payloadJson",
                "payloadDigest",
                "expiresAt",
                "usedAt",
                "createdAt",
            }
        ),
    )
    credential = _candidate_authority_strict_object(
        "historical credential snapshot",
        snapshots["credential"],
        frozenset(
            {
                "schema",
                "recordId",
                "credentialId",
                "userId",
                "publicKeyCose",
                "publicKeyCoseSha256",
                "signCount",
                "aaguid",
                "authenticatorClass",
                "attestationFormat",
                "attestationTrusted",
                "attestationTrustPath",
                "attestationLeafSha256",
                "attestationRootSha256",
                "attestationTrustBundleDigest",
                "attestationTrustBundleSequence",
                "attestationVerifiedAt",
                "transports",
                "createdAt",
                "revokedAt",
                "revokedBy",
                "revocationReason",
                "revocationSource",
                "credentialVersionDigest",
            }
        ),
    )
    trust_fields = {
        "schema",
        *set(_WEBAUTHN_TRUST_PUBLICATION_AUTHORITY_COLUMNS),
        "publicationStateAtVerification",
    }
    trust = _candidate_authority_strict_object(
        "historical trust publication snapshot",
        snapshots["trust publication"],
        frozenset(trust_fields),
    )
    credential_version_material = {
        key: value
        for key, value in credential.items()
        if key != "credentialVersionDigest"
    }
    public_key_cose_raw = _candidate_authority_b64url_bounded(
        "historical WebAuthn credential public key",
        credential["publicKeyCose"],
        maximum_bytes=4096,
    )
    activation_challenge_material = {
        "action": _POLICY_CANDIDATE_ACTIVATION_ACTION,
        "activationIntentDigest":
            approval["activation_intent_digest"],
        "approvalMode": approval["approval_mode"],
        "approvalContextDigest": approval["approval_context_digest"],
        "authorityAnalysisMode": approval["authority_analysis_mode"],
        "candidatePolicyHash": approval["candidate_policy_hash"],
        "candidatePolicySequence": approval["candidate_policy_sequence"],
        "candidateRollbackEpoch": approval["candidate_rollback_epoch"],
        "compilerAnalysisPayloadDigest":
            approval["compiler_analysis_payload_digest"],
        "controlPlaneApprovalId": member["control_plane_approval_id"],
        "expectedActivePolicySequence":
            approval["expected_active_policy_sequence"],
        "expectedActiveRollbackEpoch":
            approval["expected_active_rollback_epoch"],
        "expansionCellsDigest": approval["expansion_cells_digest"],
        "predecessorPolicyHash": approval["predecessor_policy_hash"],
        "publicationRevision": approval["publication_revision"],
        "readinessCoreDigest": approval["readiness_core_digest"],
        "readinessPayloadDigest": approval["readiness_payload_digest"],
        "requesterId": approval["requester_id"],
        "requiredApprovalQuorum": approval["required_member_count"],
        "webauthnChallengeContextDigest":
            approval["webauthn_challenge_context_digest"],
    }
    activation_challenge_digest = _candidate_authority_sha256(
        dumps(activation_challenge_material).encode("ascii")
    )
    expected_challenge_payload = {
        "type": "serverware.policy_candidate_activation",
        "user_id": member["approver_id"],
        "action": _POLICY_CANDIDATE_ACTIVATION_ACTION,
        "resource_id": approval["canary_id"],
        "payload_digest": approval["approval_context_digest"],
        "control_plane_approval_id":
            member["control_plane_approval_id"],
        "approval_requester_id": approval["requester_id"],
        "approval_expires_at": control["expiresAt"],
        "decision": "approve",
        "readiness_payload_digest":
            approval["readiness_payload_digest"],
        "readiness_core_digest": approval["readiness_core_digest"],
        "compiler_analysis_payload_digest":
            approval["compiler_analysis_payload_digest"],
        "authority_analysis_mode": approval["authority_analysis_mode"],
        "approval_mode": approval["approval_mode"],
        "required_approval_quorum": approval["required_member_count"],
        "expansion_cells_digest": approval["expansion_cells_digest"],
        "publication_revision": approval["publication_revision"],
        "expected_active_policy_sequence":
            approval["expected_active_policy_sequence"],
        "expected_active_rollback_epoch":
            approval["expected_active_rollback_epoch"],
        "predecessor_policy_hash": approval["predecessor_policy_hash"],
        "webauthn_challenge_context_digest":
            approval["webauthn_challenge_context_digest"],
        "activation_intent_digest":
            approval["activation_intent_digest"],
        "activation_challenge_digest": activation_challenge_digest,
    }
    challenge_payload = loads(challenge["payloadJson"], None)
    if (
        control["schema"]
        != "serverware.controlPlaneApprovalSnapshot/v1"
        or challenge["schema"]
        != "serverware.webauthnChallengeSnapshot/v1"
        or credential["schema"]
        != "serverware.webauthnCredentialAuthoritySnapshot/v1"
        or trust["schema"]
        != "serverware.webauthnTrustPublicationSnapshot/v1"
        or control["approvalStateAtVerification"] != "approved"
        or trust["publicationStateAtVerification"] != "published"
        or control["id"] != member["control_plane_approval_id"]
        or control["action"] != _POLICY_CANDIDATE_ACTIVATION_ACTION
        or control["resourceId"] != approval["canary_id"]
        or control["payloadDigest"] != approval["approval_context_digest"]
        or control["requesterId"] != approval["requester_id"]
        or control["approvedBy"] != member["approver_id"]
        or control["approverWebauthnCredentialId"]
        != member["approver_webauthn_credential_id"]
        or control["requestJsonDigest"]
        != member["control_plane_request_digest"]
        or challenge["id"] != member["webauthn_challenge_id"]
        or challenge["challengeType"] != "control-plane-mutation"
        or challenge["userId"] != member["approver_id"]
        or challenge["approvalRequestId"]
        not in {None, member["control_plane_approval_id"]}
        or challenge["payloadDigest"]
        != persisted_assertion["challenge_payload_digest"]
        or not isinstance(challenge_payload, dict)
        or dumps(challenge_payload) != challenge["payloadJson"]
        or challenge_payload != expected_challenge_payload
        or _candidate_authority_sha256(
            str(control["requestJson"]).encode("utf-8")
        )
        != control["requestJsonDigest"]
        or credential["recordId"]
        != member["approver_webauthn_credential_id"]
        or credential["userId"] != member["approver_id"]
        or credential["authenticatorClass"] not in {"yubikey", "hardware"}
        or int(credential["attestationTrusted"]) != 1
        or credential["revokedAt"] is not None
        or credential["publicKeyCoseSha256"]
        != persisted_assertion[
            "webauthn_credential_public_key_digest"
        ]
        or _candidate_authority_sha256(public_key_cose_raw)
        != credential["publicKeyCoseSha256"]
        or _policy_authority_domain_digest(
            b"serverware.webauthnCredentialVersion/v1",
            dumps(credential_version_material).encode("ascii"),
        )
        != persisted_assertion["webauthn_credential_version_digest"]
        or credential["credentialVersionDigest"]
        != persisted_assertion["webauthn_credential_version_digest"]
        or credential["attestationTrustBundleDigest"]
        != trust["bundle_digest"]
        or int(credential["attestationTrustBundleSequence"])
        != int(trust["sequence"])
        or persisted_assertion["trust_bundle_digest"]
        != trust["bundle_digest"]
        or int(persisted_assertion["trust_bundle_sequence"])
        != int(trust["sequence"])
    ):
        raise PolicyCandidateAuthorityConflictError(
            "historical WebAuthn authority snapshots are not an exact graph"
        )
    assertion_json, assertion_digest = _candidate_authority_json(
        "historical WebAuthn assertion",
        persisted_assertion["assertion_json"],
        persisted_assertion["assertion_digest"],
    )
    assertion = loads(assertion_json, None)
    response = assertion.get("response") if isinstance(assertion, dict) else None
    if not isinstance(response, dict):
        raise PolicyCandidateAuthorityConflictError(
            "historical WebAuthn assertion response is missing"
        )
    client_data_raw = _candidate_authority_b64url_bounded(
        "historical clientDataJSON",
        response.get("clientDataJSON"),
        maximum_bytes=64 * 1024,
    )
    authenticator_data = _candidate_authority_b64url_bounded(
        "historical authenticatorData",
        response.get("authenticatorData"),
        maximum_bytes=4096,
    )
    assertion_signature = _candidate_authority_b64url_bounded(
        "historical WebAuthn signature",
        response.get("signature"),
        maximum_bytes=512,
    )
    client_data = json.loads(client_data_raw)
    challenge_created_at = datetime.fromisoformat(
        _candidate_authority_iso(
            "historical challenge created at",
            challenge["createdAt"],
        )
    )
    challenge_used_at = datetime.fromisoformat(
        _candidate_authority_iso(
            "historical challenge used at",
            challenge["usedAt"],
        )
    )
    challenge_expires_at = datetime.fromisoformat(
        _candidate_authority_iso(
            "historical challenge expires at",
            challenge["expiresAt"],
        )
    )
    approved_at = datetime.fromisoformat(
        _candidate_authority_iso(
            "historical approval approved at",
            control["approvedAt"],
        )
    )
    approval_expires_at = datetime.fromisoformat(
        _candidate_authority_iso(
            "historical approval expires at",
            control["expiresAt"],
        )
    )
    assertion_verified_at = datetime.fromisoformat(
        _candidate_authority_iso(
            "historical assertion verified at",
            persisted_assertion["assertion_verified_at"],
        )
    )
    flags = authenticator_data[32] if len(authenticator_data) >= 37 else 0
    expected_rp_hash = hashlib.sha256(
        str(persisted_assertion["rp_id"]).encode("utf-8")
    ).digest()
    if (
        assertion_digest != persisted_assertion["assertion_digest"]
        or assertion.get("id") != credential["credentialId"]
        or client_data.get("challenge") != challenge["challenge"]
        or client_data.get("origin") != persisted_assertion["origin"]
        or client_data.get("type") != persisted_assertion["client_data_type"]
        or _candidate_authority_sha256(client_data_raw)
        != persisted_assertion["client_data_digest"]
        or _candidate_authority_sha256(authenticator_data)
        != persisted_assertion["authenticator_data_digest"]
        or _candidate_authority_sha256(assertion_signature)
        != persisted_assertion["assertion_signature_digest"]
        or int.from_bytes(authenticator_data[33:37], "big")
        != int(persisted_assertion["sign_count"])
        or len(authenticator_data) < 37
        or not hmac.compare_digest(
            authenticator_data[:32], expected_rp_hash
        )
        or flags & 0x01 == 0
        or flags & 0x04 == 0
        or int(persisted_assertion["user_present"]) != 1
        or int(persisted_assertion["user_verified"]) != 1
        or int(persisted_assertion["attestation_trusted"]) != 1
        or str(persisted_assertion["rp_id"]) != WEBAUTHN_RP_ID
        or str(persisted_assertion["origin"]) != WEBAUTHN_ORIGIN
        or challenge_created_at > challenge_used_at
        or challenge_used_at > challenge_expires_at
        or challenge_used_at > approved_at
        or approved_at > approval_expires_at
        or approved_at > assertion_verified_at
        or challenge_used_at > assertion_verified_at
        or persisted_assertion["challenge_created_at"]
        != challenge["createdAt"]
        or persisted_assertion["challenge_used_at"]
        != challenge["usedAt"]
        or persisted_assertion["assertion_issued_at"]
        != challenge["usedAt"]
        or persisted_assertion["approval_approved_at"]
        != control["approvedAt"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "historical WebAuthn assertion bytes do not match the receipt"
        )
    try:
        cose = cbor2.loads(public_key_cose_raw)
        if (
            not isinstance(cose, dict)
            or cose.get(1) != 2
            or cose.get(3) != -7
            or cose.get(-1) != 1
            or not isinstance(cose.get(-2), bytes)
            or not isinstance(cose.get(-3), bytes)
            or len(cose[-2]) != 32
            or len(cose[-3]) != 32
        ):
            raise ValueError("unsupported historical COSE key")
        public_key = ec.EllipticCurvePublicKey.from_encoded_point(
            ec.SECP256R1(), b"\x04" + cose[-2] + cose[-3]
        )
        public_key.verify(
            assertion_signature,
            authenticator_data + hashlib.sha256(client_data_raw).digest(),
            ec.ECDSA(hashes.SHA256()),
        )
    except (
        KeyError,
        TypeError,
        ValueError,
        cbor2.CBORDecodeError,
        InvalidSignature,
    ) as exc:
        raise PolicyCandidateAuthorityConflictError(
            "historical WebAuthn assertion signature is invalid"
        ) from exc
    receipt_material = {
        "activationChallengeDigest": activation_challenge_digest,
        "approvalContextDigest": approval["approval_context_digest"],
        "assertionDigest": assertion_digest,
        "authenticatorDataDigest":
            persisted_assertion["authenticator_data_digest"],
        "challengeId": challenge["id"],
        "challengeCreatedAt": challenge["createdAt"],
        "assertionIssuedAt": challenge["usedAt"],
        "approvalApprovedAt": control["approvedAt"],
        "clientDataDigest": persisted_assertion["client_data_digest"],
        "controlPlaneApprovalId": control["id"],
        "credentialRecordId": credential["recordId"],
        "controlPlaneApprovalSnapshotDigest":
            persisted_assertion[
                "control_plane_approval_snapshot_digest"
            ],
        "webauthnChallengeSnapshotDigest":
            persisted_assertion["webauthn_challenge_snapshot_digest"],
        "webauthnCredentialSnapshotDigest":
            persisted_assertion["webauthn_credential_snapshot_digest"],
        "webauthnCredentialVersionDigest":
            persisted_assertion["webauthn_credential_version_digest"],
        "webauthnCredentialPublicKeyDigest":
            persisted_assertion[
                "webauthn_credential_public_key_digest"
            ],
        "webauthnTrustPublicationSnapshotDigest":
            persisted_assertion[
                "webauthn_trust_publication_snapshot_digest"
            ],
        "readinessPayloadDigest": approval["readiness_payload_digest"],
        "signCount": int(persisted_assertion["sign_count"]),
        "trustBundleDigest": trust["bundle_digest"],
        "trustBundleSequence": int(trust["sequence"]),
    }
    if _candidate_authority_sha256(
        dumps(receipt_material).encode("ascii")
    ) != persisted_assertion["assertion_receipt_digest"]:
        raise PolicyCandidateAuthorityConflictError(
            "historical WebAuthn assertion receipt digest is not exact"
        )


def _revalidate_policy_activation_assertion_ledger(
    conn: Any,
    *,
    approval: Mapping[str, Any],
    member: Mapping[str, Any],
    control_plane_approval: Any,
    verified_at: datetime,
    historical: bool = False,
) -> tuple[dict[str, Any], dict[str, Any]]:
    persisted_assertion = conn.execute(
        "SELECT "
        + _policy_authority_projection(
            _POLICY_ACTIVATION_WEBAUTHN_ASSERTION_COLUMNS
        )
        + " FROM policy_activation_webauthn_assertions "
        "WHERE assertion_receipt_digest = ? AND approval_id = ? "
        "AND control_plane_approval_id = ? AND approver_id = ? "
        "AND credential_record_id = ? AND challenge_id = ? "
        "AND assertion_digest = ? AND readiness_payload_digest = ? "
        "AND activation_intent_digest = ? "
        "AND approval_context_digest = ?",
        (
            member["webauthn_assertion_receipt_digest"],
            approval["approval_id"],
            member["control_plane_approval_id"],
            member["approver_id"],
            member["approver_webauthn_credential_id"],
            member["webauthn_challenge_id"],
            member["webauthn_assertion_digest"],
            approval["readiness_payload_digest"],
            approval["activation_intent_digest"],
            approval["approval_context_digest"],
        ),
    ).fetchone()
    persisted_member = conn.execute(
        "SELECT "
        + _policy_authority_projection(
            _POLICY_ACTIVATION_APPROVAL_MEMBER_COLUMNS
        )
        + " FROM policy_activation_approval_members "
        "WHERE approval_id = ? AND member_ordinal = ? "
        "AND control_plane_approval_id = ? AND approver_id = ? "
        "AND approver_webauthn_credential_id = ? "
        "AND webauthn_assertion_receipt_digest = ? "
        "AND webauthn_assertion_digest = ? AND webauthn_challenge_id = ? "
        "AND readiness_payload_digest = ? "
        "AND activation_intent_digest = ? "
        "AND approval_context_digest = ?",
        (
            approval["approval_id"],
            member["member_ordinal"],
            member["control_plane_approval_id"],
            member["approver_id"],
            member["approver_webauthn_credential_id"],
            member["webauthn_assertion_receipt_digest"],
            member["webauthn_assertion_digest"],
            member["webauthn_challenge_id"],
            approval["readiness_payload_digest"],
            approval["activation_intent_digest"],
            approval["approval_context_digest"],
        ),
    ).fetchone()
    if persisted_assertion is None or persisted_member is None:
        raise PolicyCandidateAuthorityConflictError(
            "activation approval is not backed by exact immutable assertion evidence"
        )
    if historical:
        _verify_historical_policy_activation_assertion(
            approval=approval,
            member=persisted_member,
            persisted_assertion=persisted_assertion,
        )
        return dict(persisted_assertion), dict(persisted_member)
    assertion_clocks: dict[str, datetime] = {}
    for field in (
        "challenge_created_at",
        "challenge_used_at",
        "assertion_issued_at",
        "approval_approved_at",
        "assertion_verified_at",
    ):
        canonical = _candidate_authority_iso(
            f"persisted assertion {field}",
            persisted_assertion[field],
        )
        assertion_clocks[field] = datetime.fromisoformat(canonical)
    original_verified_at = assertion_clocks["assertion_verified_at"]
    if (
        assertion_clocks["challenge_used_at"]
        != assertion_clocks["assertion_issued_at"]
        or persisted_assertion["approval_approved_at"]
        != control_plane_approval["approved_at"]
        or assertion_clocks["challenge_created_at"]
        > assertion_clocks["challenge_used_at"]
        or assertion_clocks["challenge_used_at"]
        > assertion_clocks["approval_approved_at"]
        or assertion_clocks["approval_approved_at"] > original_verified_at
        or original_verified_at > verified_at
        or any(
            (verified_at - assertion_clocks[field]).total_seconds()
            > _POLICY_ACTIVATION_ASSERTION_MAX_AGE_SECONDS
            for field in assertion_clocks
        )
    ):
        raise PolicyCandidateAuthorityConflictError(
            "persisted assertion issuance, approval, or verification is stale"
        )

    current_assertion, current_member, _ = (
        _verify_policy_activation_webauthn_assertion(
            conn,
            approval=approval,
            control_plane_approval=control_plane_approval,
            assertion_json=str(persisted_assertion["assertion_json"]),
            verified_at=verified_at,
        )
    )
    stable_assertion_fields = tuple(
        field
        for field in current_assertion
        if field not in {"assertion_verified_at", "verified_at_epoch_ns"}
    )
    if any(
        persisted_assertion[field] != current_assertion[field]
        for field in stable_assertion_fields
    ):
        raise PolicyCandidateAuthorityConflictError(
            "persisted WebAuthn assertion no longer verifies to the same evidence"
        )
    expected_member = {
        "approval_id": approval["approval_id"],
        "member_ordinal": member["member_ordinal"],
        **current_member,
    }
    if any(
        persisted_member[field] != value
        for field, value in expected_member.items()
    ):
        raise PolicyCandidateAuthorityConflictError(
            "persisted approval member no longer binds current assertion authority"
        )
    return dict(persisted_assertion), dict(persisted_member)


def stage_policy_activation_approval(
    record: Mapping[str, Any],
    members: list[Mapping[str, Any]],
    *,
    _connection: Any | None = None,
) -> dict[str, Any]:
    item = _candidate_authority_record(
        "activation approval", record, _POLICY_ACTIVATION_APPROVAL_FIELDS
    )
    for field, value in tuple(item.items()):
        if field.endswith("_digest") or field.endswith("_hash"):
            item[field] = _candidate_authority_digest(field, value)
    item["candidate_policy_sequence"] = _candidate_authority_int(
        "candidate_policy_sequence",
        item["candidate_policy_sequence"],
        minimum=1,
    )
    item["candidate_rollback_epoch"] = _candidate_authority_int(
        "candidate_rollback_epoch",
        item["candidate_rollback_epoch"],
        minimum=1,
    )
    item["required_member_count"] = _candidate_authority_int(
        "required_member_count", item["required_member_count"], minimum=1,
        maximum=2,
    )
    for field, minimum in (
        ("publication_revision", 1),
        ("expected_active_policy_sequence", 1),
        ("expected_active_rollback_epoch", 0),
    ):
        item[field] = _candidate_authority_int(
            field, item[field], minimum=minimum
        )
    item["use_limit"] = _candidate_authority_int(
        "use_limit", item["use_limit"], minimum=1, maximum=1
    )
    if item["approval_id"] != item["aggregate_evidence_digest"]:
        raise PolicyCandidateAuthorityError(
            "aggregate approval ID must equal its evidence digest"
        )
    _candidate_authority_json(
        "approval_context_json",
        item["approval_context_json"],
        item["approval_context_digest"],
    )
    _candidate_authority_json(
        "aggregate_evidence_json",
        item["aggregate_evidence_json"],
        item["aggregate_evidence_digest"],
    )
    item["approved_at"] = _candidate_authority_iso(
        "approved_at", item["approved_at"]
    )
    item["expires_at"] = _candidate_authority_iso(
        "expires_at", item["expires_at"]
    )
    if item["approved_at"] >= item["expires_at"]:
        raise PolicyCandidateAuthorityError(
            "aggregate approval expiry must follow approval time"
        )
    for field in ("canary_id", "requester_id"):
        _candidate_authority_text(field, item[field], maximum=1024)
    if not isinstance(members, list) or len(members) != item["required_member_count"]:
        raise PolicyCandidateAuthorityError(
            "aggregate approval member count is not exact"
        )
    member_rows = [
        _candidate_authority_record(
            "activation approval member",
            member,
            _POLICY_ACTIVATION_APPROVAL_MEMBER_FIELDS,
        )
        for member in members
    ]
    member_rows.sort(key=lambda member: member["member_ordinal"])
    if [member["member_ordinal"] for member in member_rows] != list(
        range(1, len(member_rows) + 1)
    ):
        raise PolicyCandidateAuthorityError(
            "aggregate approval member ordinals are not contiguous"
        )
    context = loads(item["approval_context_json"], None)
    expected_context = {
        "apiVersion": "serverware.policyActivationApprovalContext/v1",
        "action": _POLICY_CANDIDATE_ACTIVATION_ACTION,
        "activationIntentDigest":
            item["activation_intent_digest"],
        "approvalMode": item["approval_mode"],
        "authorityAnalysisMode": item["authority_analysis_mode"],
        "canaryId": item["canary_id"],
        "compilerAnalysisPayloadDigest":
            item["compiler_analysis_payload_digest"],
        "expectedActivePolicySequence":
            item["expected_active_policy_sequence"],
        "expectedActiveRollbackEpoch":
            item["expected_active_rollback_epoch"],
        "expiresAt": item["expires_at"],
        "expansionCellsDigest": item["expansion_cells_digest"],
        "policyHash": item["candidate_policy_hash"],
        "policySequence": item["candidate_policy_sequence"],
        "predecessorPolicyHash": item["predecessor_policy_hash"],
        "publicationRevision": item["publication_revision"],
        "readinessCoreDigest": item["readiness_core_digest"],
        "readinessPayloadDigest": item["readiness_payload_digest"],
        "requesterId": item["requester_id"],
        "requiredApprovalQuorum": item["required_member_count"],
        "rollbackEpoch": item["candidate_rollback_epoch"],
        "useLimit": 1,
        "webauthnChallengeContextDigest":
            item["webauthn_challenge_context_digest"],
    }
    if context != expected_context:
        raise PolicyCandidateAuthorityError(
            "activation approval context is not the exact approved operation"
        )

    connection_scope = (
        connect()
        if _connection is None
        else contextlib.nullcontext(_connection)
    )
    with connection_scope as conn:
        _lock_policy_candidate_authority(conn)
        _lock_webauthn_authority(conn)
        _lock_rbac_authority(conn)
        now = _metadata_utcnow(conn)
        now_s = now.isoformat()
        now_epoch_ns = int(now.timestamp() * 1_000_000_000)
        actor_id = item["requester_id"]
        created_at_epoch_ns = now_epoch_ns
        if (
            item["approved_at"] > now_s
            or item["expires_at"] <= now_s
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation approval is not transaction-time current"
            )
        readiness = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_CANARY_READINESS_READ_COLUMNS
            )
            + " FROM policy_canary_readiness "
            "WHERE readiness_envelope_digest = ?",
            (item["readiness_envelope_digest"],),
        ).fetchone()
        readiness_exact = {
            "readiness_payload_digest": "readiness_payload_digest",
            "readiness_core_digest": "readiness_core_digest",
            "compiler_analysis_payload_digest":
                "compiler_analysis_payload_digest",
            "authority_analysis_mode": "authority_analysis_mode",
            "approval_mode": "approval_mode",
            "expansion_cells_digest": "expansion_cells_digest",
            "publication_revision": "publication_revision",
            "expected_active_policy_sequence":
                "expected_active_policy_sequence",
            "expected_active_rollback_epoch":
                "expected_active_rollback_epoch",
            "canary_id": "canary_id",
            "candidate_policy_hash": "candidate_policy_hash",
            "candidate_policy_sequence": "candidate_policy_sequence",
            "candidate_rollback_epoch": "candidate_rollback_epoch",
            "predecessor_policy_hash": "predecessor_policy_hash",
        }
        if (
            readiness is None
            or any(
                readiness[column] != item[field]
                for field, column in readiness_exact.items()
            )
            or int(readiness["required_approval_quorum"])
            != item["required_member_count"]
            or int(readiness["expires_at_epoch_ns"]) <= now_epoch_ns
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation approval does not bind exact immutable readiness"
            )
        challenge_context = {
            "activationIntentDigest":
                item["activation_intent_digest"],
            "approvalMode": item["approval_mode"],
            "authorityAnalysisMode": item["authority_analysis_mode"],
            "canaryId": item["canary_id"],
            "candidatePolicyHash": item["candidate_policy_hash"],
            "candidatePolicySequence": item["candidate_policy_sequence"],
            "candidateRollbackEpoch": item["candidate_rollback_epoch"],
            "compilerAnalysisPayloadDigest":
                item["compiler_analysis_payload_digest"],
            "expectedActivePolicySequence":
                item["expected_active_policy_sequence"],
            "expectedActiveRollbackEpoch":
                item["expected_active_rollback_epoch"],
            "expansionCellsDigest": item["expansion_cells_digest"],
            "predecessorPolicyHash": item["predecessor_policy_hash"],
            "publicationRevision": item["publication_revision"],
            "readinessCoreDigest": item["readiness_core_digest"],
            "readinessPayloadDigest": item["readiness_payload_digest"],
            "requesterId": item["requester_id"],
            "requiredApprovalQuorum": item["required_member_count"],
        }
        calculated_challenge_context = _policy_authority_domain_digest(
            b"serverware.policyActivationWebAuthnChallenge/v1",
            dumps(challenge_context).encode("ascii"),
        )
        if (
            item["webauthn_challenge_context_digest"]
            != calculated_challenge_context
        ):
            raise PolicyCandidateAuthorityConflictError(
                "WebAuthn challenge context is not server-derived"
            )
        if not _rbac_subject_has_any_role_on_connection(
            conn,
            item["requester_id"],
            set(_POLICY_CANDIDATE_ACTIVATION_REQUESTER_ROLES),
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation requester lacks current fixed policy-publisher authority"
            )
        seen_approvers: set[str] = set()
        seen_authenticators: set[str] = set()
        aggregate_members: list[dict[str, Any]] = []
        assertion_rows: list[dict[str, Any]] = []
        stored_members: list[dict[str, Any]] = []
        for member in member_rows:
            member["member_ordinal"] = _candidate_authority_int(
                "member_ordinal", member["member_ordinal"], minimum=1, maximum=2
            )
            member["control_plane_approval_id"] = _candidate_authority_uuid(
                "control_plane_approval_id",
                member["control_plane_approval_id"],
            )
            assertion_json = _candidate_authority_canonical_json(
                "member assertion_json", member["assertion_json"]
            )
            approval = _control_plane_approval_row(
                conn, member["control_plane_approval_id"], for_update=True
            )
            if approval is None:
                raise PolicyCandidateAuthorityConflictError(
                    "control-plane approval member does not exist"
                )
            request_json = str(approval["request_json"])
            request_digest = "sha256:" + hashlib.sha256(
                request_json.encode("utf-8")
            ).hexdigest()
            expected_request = {
                "apiVersion": "serverware.policyActivationApprovalRequest/v1",
                "approvalContext": context,
                "approvalContextDigest": item["approval_context_digest"],
            }
            try:
                request = loads(request_json, None)
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                raise PolicyCandidateAuthorityError(
                    "control-plane approval request is invalid"
                ) from exc
            if (
                str(approval["status"]) != "approved"
                or approval["action"] != _POLICY_CANDIDATE_ACTIVATION_ACTION
                or approval["resource_id"] != item["canary_id"]
                or approval["payload_digest"] != item["approval_context_digest"]
                or approval["requester_id"] != item["requester_id"]
                or approval["approved_by"] is None
                or approval["approved_by"] == item["requester_id"]
                or approval["approver_webauthn_credential_id"] is None
                or approval["approved_at"] is None
                or approval["approved_at"] > now_s
                or approval["expires_at"] != item["expires_at"]
                or approval["expires_at"] <= now_s
                or approval["consumed_at"] is not None
                or request_json != dumps(request)
                or request != expected_request
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "control-plane approval member evidence is not exact"
                )
            approver_id = str(approval["approved_by"])
            if (
                not _rbac_subject_has_any_role_on_connection(
                    conn,
                    approver_id,
                    set(_POLICY_CANDIDATE_ACTIVATION_APPROVER_ROLES),
                )
                or approver_id in seen_approvers
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "approval principal is duplicated or lacks fixed authority"
                )
            assertion_row, stored_member, evidence = (
                _verify_policy_activation_webauthn_assertion(
                    conn,
                    approval=item,
                    control_plane_approval=approval,
                    assertion_json=assertion_json,
                    verified_at=now,
                )
            )
            authenticator_id = stored_member[
                "approver_webauthn_credential_id"
            ]
            if authenticator_id in seen_authenticators:
                raise PolicyCandidateAuthorityConflictError(
                    "activation approvals reuse a WebAuthn credential"
                )
            seen_approvers.add(approver_id)
            seen_authenticators.add(authenticator_id)
            stored_member["member_ordinal"] = member["member_ordinal"]
            assertion_rows.append(assertion_row)
            stored_members.append(stored_member)
            aggregate_members.append(evidence)
        derived_approved_at = max(
            member["approved_at"] for member in stored_members
        )
        if item["approved_at"] != derived_approved_at:
            raise PolicyCandidateAuthorityError(
                "aggregate approval time must equal the final member approval"
            )
        expected_aggregate = {
            "apiVersion": "serverware.policyActivationApprovalEvidence/v2",
            "activationIntentDigest":
                item["activation_intent_digest"],
            "approvalContextDigest": item["approval_context_digest"],
            "approvalMode": item["approval_mode"],
            "authorityAnalysisMode": item["authority_analysis_mode"],
            "compilerAnalysisPayloadDigest":
                item["compiler_analysis_payload_digest"],
            "expansionCellsDigest": item["expansion_cells_digest"],
            "members": aggregate_members,
            "publicationRevision": item["publication_revision"],
            "readinessCoreDigest": item["readiness_core_digest"],
            "readinessPayloadDigest": item["readiness_payload_digest"],
            "requiredMemberCount": item["required_member_count"],
            "webauthnChallengeContextDigest":
                item["webauthn_challenge_context_digest"],
        }
        expected_aggregate_json = dumps(expected_aggregate)
        expected_aggregate_digest = _candidate_authority_sha256(
            expected_aggregate_json.encode("ascii")
        )
        if (
            item["aggregate_evidence_json"] != expected_aggregate_json
            or item["aggregate_evidence_digest"] != expected_aggregate_digest
            or item["approval_id"] != expected_aggregate_digest
        ):
            raise PolicyCandidateAuthorityError(
                "aggregate approval was not derived from native assertion evidence"
            )
        existing_aggregate = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_ACTIVATION_APPROVAL_COLUMNS
            )
            + " FROM policy_activation_approvals WHERE approval_id = ?",
            (item["approval_id"],),
        ).fetchone()
        if existing_aggregate is not None:
            expected_existing = {
                **item,
                "action": _POLICY_CANDIDATE_ACTIVATION_ACTION,
                "resource_id": item["canary_id"],
                "payload_digest": item["approval_context_digest"],
            }
            if any(
                existing_aggregate[field] != value
                for field, value in expected_existing.items()
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "activation approval identity was reused with different evidence"
                )
            persisted_members: list[dict[str, Any]] = []
            for current_assertion, current_member in zip(
                assertion_rows, stored_members, strict=True
            ):
                persisted_assertion = conn.execute(
                    "SELECT "
                    + _policy_authority_projection(
                        _POLICY_ACTIVATION_WEBAUTHN_ASSERTION_COLUMNS
                    )
                    + " FROM policy_activation_webauthn_assertions "
                    "WHERE assertion_receipt_digest = ?",
                    (current_assertion["assertion_receipt_digest"],),
                ).fetchone()
                persisted_member = conn.execute(
                    "SELECT "
                    + _policy_authority_projection(
                        _POLICY_ACTIVATION_APPROVAL_MEMBER_COLUMNS
                    )
                    + " FROM policy_activation_approval_members "
                    "WHERE approval_id = ? AND member_ordinal = ?",
                    (item["approval_id"], current_member["member_ordinal"]),
                ).fetchone()
                stable_assertion_fields = tuple(
                    field
                    for field in current_assertion
                    if field not in {
                        "assertion_verified_at",
                        "verified_at_epoch_ns",
                    }
                )
                expected_member = {
                    "approval_id": item["approval_id"],
                    **current_member,
                }
                if (
                    persisted_assertion is None
                    or persisted_member is None
                    or any(
                        persisted_assertion[field] != current_assertion[field]
                        for field in stable_assertion_fields
                    )
                    or any(
                        persisted_member[field] != value
                        for field, value in expected_member.items()
                    )
                ):
                    raise PolicyCandidateAuthorityConflictError(
                        "existing activation approval evidence is not exact"
                    )
                persisted_members.append(dict(persisted_member))
            return {
                "approval": dict(existing_aggregate),
                "members": persisted_members,
            }
        transition_digest = _stage_policy_authority_transition(
            conn,
            event_type="policy.activation_approval.staged",
            entity_kind="activation_approval",
            entity_id=item["approval_id"],
            entity_revision=1,
            state_digest=item["aggregate_evidence_digest"],
            previous_state_digest=item["readiness_payload_digest"],
            actor_id=actor_id,
            evidence={
                "approvalContextDigest": item["approval_context_digest"],
                "approvalMode": item["approval_mode"],
                "compilerAnalysisPayloadDigest":
                    item["compiler_analysis_payload_digest"],
                "memberCount": item["required_member_count"],
                "readinessCoreDigest": item["readiness_core_digest"],
                "readinessPayloadDigest": item["readiness_payload_digest"],
                "webauthnChallengeContextDigest":
                    item["webauthn_challenge_context_digest"],
            },
            created_at_epoch_ns=created_at_epoch_ns,
        )
        aggregate = {
            **item,
            "action": _POLICY_CANDIDATE_ACTIVATION_ACTION,
            "resource_id": item["canary_id"],
            "payload_digest": item["approval_context_digest"],
            "created_transition_digest": transition_digest,
        }
        _insert_immutable_candidate_row(
            conn,
            table="policy_activation_approvals",
            columns=tuple(aggregate),
            values=aggregate,
            key_columns=("approval_id",),
        )
        for assertion_row in assertion_rows:
            _insert_immutable_candidate_row(
                conn,
                table="policy_activation_webauthn_assertions",
                columns=tuple(assertion_row),
                values=assertion_row,
                key_columns=("assertion_receipt_digest",),
            )
        for member in stored_members:
            stored_member = {"approval_id": item["approval_id"], **member}
            _insert_immutable_candidate_row(
                conn,
                table="policy_activation_approval_members",
                columns=tuple(stored_member),
                values=stored_member,
                key_columns=("approval_id", "member_ordinal"),
            )
    return {"approval": dict(aggregate), "members": stored_members}


_POLICY_ACTIVATION_ROLLBACK_AUTHORITY_FIELDS = (
    "rollback_authorization_envelope_digest",
    "rollback_authorization_payload_digest",
    "readiness_envelope_digest",
    "readiness_payload_digest",
    "readiness_core_digest",
    "canary_id",
    "artifact_envelope_digest",
    "artifact_payload_digest",
    "candidate_policy_hash",
    "candidate_policy_sequence",
    "candidate_rollback_epoch",
    "predecessor_policy_hash",
    "expected_active_policy_sequence",
    "expected_active_rollback_epoch",
    "publication_revision",
    "approval_context_digest",
    "webauthn_challenge_context_digest",
    "expected_high_water_digest",
    "rollback_authorization_envelope_json",
    "rollback_authorization_payload_json",
    "signature_algorithm",
    "signing_key_id",
    "signature",
    "signature_digest",
    "use_limit",
    "actor_id",
)


def stage_policy_activation_rollback_authority(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
) -> dict[str, Any]:
    item = _candidate_authority_record(
        "activation rollback authority",
        record,
        _POLICY_ACTIVATION_ROLLBACK_AUTHORITY_FIELDS,
    )
    _candidate_authority_text(
        "rollback authority actor_id", item.pop("actor_id"), maximum=1024
    )
    for field, value in tuple(item.items()):
        if field.endswith("_digest") or field.endswith("_hash"):
            item[field] = _candidate_authority_digest(field, value)
    for field, minimum in (
        ("candidate_policy_sequence", 1),
        ("candidate_rollback_epoch", 1),
        ("expected_active_policy_sequence", 1),
        ("expected_active_rollback_epoch", 0),
        ("publication_revision", 1),
    ):
        item[field] = _candidate_authority_int(
            field, item[field], minimum=minimum
        )
    item["use_limit"] = _candidate_authority_int(
        "rollback use_limit", item["use_limit"], minimum=1, maximum=1
    )
    if (
        item["candidate_rollback_epoch"]
        <= item["expected_active_rollback_epoch"]
    ):
        raise PolicyCandidateAuthorityError(
            "rollback authority does not advance the rollback epoch"
        )
    _candidate_authority_json(
        "rollback_authorization_envelope_json",
        item["rollback_authorization_envelope_json"],
        item["rollback_authorization_envelope_digest"],
    )
    _candidate_authority_json(
        "rollback_authorization_payload_json",
        item["rollback_authorization_payload_json"],
        item["rollback_authorization_payload_digest"],
    )
    _candidate_authority_signature_fields(item)
    with (
        connect()
        if _connection is None
        else contextlib.nullcontext(_connection)
    ) as conn:
        _lock_policy_candidate_authority(conn)
        readiness = conn.execute(
            "SELECT readiness.readiness_envelope_digest, "
            "readiness.readiness_payload_digest, "
            "readiness.readiness_core_digest, readiness.canary_id, "
            "readiness.artifact_envelope_digest, "
            "readiness.artifact_payload_digest, "
            "readiness.candidate_policy_hash, "
            "readiness.candidate_policy_sequence, "
            "readiness.candidate_rollback_epoch, "
            "readiness.predecessor_policy_hash, "
            "readiness.expected_active_policy_sequence, "
            "readiness.expected_active_rollback_epoch, "
            "readiness.publication_revision, "
            "readiness.expires_at_epoch_ns, canary.policy_id "
            "FROM policy_canary_readiness AS readiness "
            "JOIN policy_canaries AS canary "
            "ON canary.canary_id = readiness.canary_id "
            "WHERE readiness.readiness_envelope_digest = ?",
            (item["readiness_envelope_digest"],),
        ).fetchone()
        exact = (
            "readiness_envelope_digest",
            "readiness_payload_digest",
            "readiness_core_digest",
            "canary_id",
            "artifact_envelope_digest",
            "artifact_payload_digest",
            "candidate_policy_hash",
            "candidate_policy_sequence",
            "candidate_rollback_epoch",
            "predecessor_policy_hash",
            "expected_active_policy_sequence",
            "expected_active_rollback_epoch",
            "publication_revision",
        )
        now_epoch_ns = int(
            _metadata_utcnow(conn).timestamp() * 1_000_000_000
        )
        high_water = _committed_policy_authority_row(conn)
        if (
            readiness is None
            or any(readiness[field] != item[field] for field in exact)
            or int(readiness["expires_at_epoch_ns"]) <= now_epoch_ns
            or item["expected_high_water_digest"]
            != _policy_candidate_high_water_digest(high_water)
            or not _policy_row_matches(
                high_water,
                policy_id=str(readiness["policy_id"]),
                sequence=item["expected_active_policy_sequence"],
                rollback_epoch=item["expected_active_rollback_epoch"],
                policy_hash=item["predecessor_policy_hash"],
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "rollback authority does not bind current readiness/high-water"
            )
        approval = conn.execute(
            "SELECT approval_context_digest, "
            "webauthn_challenge_context_digest, readiness_core_digest, "
            "readiness_payload_digest, publication_revision, "
            "expected_active_policy_sequence, "
            "expected_active_rollback_epoch, expires_at "
            "FROM policy_activation_approvals "
            "WHERE approval_context_digest = ?",
            (item["approval_context_digest"],),
        ).fetchone()
        now_s = _metadata_utcnow(conn).isoformat()
        if (
            approval is None
            or approval["webauthn_challenge_context_digest"]
            != item["webauthn_challenge_context_digest"]
            or approval["readiness_core_digest"]
            != item["readiness_core_digest"]
            or approval["readiness_payload_digest"]
            != item["readiness_payload_digest"]
            or int(approval["publication_revision"])
            != item["publication_revision"]
            or int(approval["expected_active_policy_sequence"])
            != item["expected_active_policy_sequence"]
            or int(approval["expected_active_rollback_epoch"])
            != item["expected_active_rollback_epoch"]
            or approval["expires_at"] <= now_s
        ):
            raise PolicyCandidateAuthorityConflictError(
                "rollback authority has no exact current hardware approval"
            )
        verified = _verify_policy_authority_evidence(
            conn,
            evidence_kind="rollback_authority",
            envelope_json=item["rollback_authorization_envelope_json"],
            envelope_digest=item[
                "rollback_authorization_envelope_digest"
            ],
            payload_json=item["rollback_authorization_payload_json"],
            payload_digest=item["rollback_authorization_payload_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                item, current_prefix="rollback_authorization"
            ),
        )
        _apply_policy_authority_verification(item, verified)
        item["issued_at_epoch_ns"] = verified.values["issued_at_epoch_ns"]
        item["expires_at_epoch_ns"] = verified.values["expires_at_epoch_ns"]
        _insert_immutable_candidate_row(
            conn,
            table="policy_activation_rollback_authorities",
            columns=tuple(item),
            values=item,
            key_columns=("rollback_authorization_envelope_digest",),
        )
    return dict(item)


