def stage_policy_activation_rollback_authority_revocation(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
) -> dict[str, Any]:
    item = _candidate_authority_record(
        "activation rollback-authority revocation",
        record,
        _POLICY_ACTIVATION_ROLLBACK_AUTHORITY_REVOCATION_FIELDS,
    )
    actor_id = _candidate_authority_text(
        "rollback-authority revocation actor_id",
        item.pop("actor_id"),
        maximum=1024,
    )
    item["revoked_by"] = _candidate_authority_text(
        "rollback-authority revocation revoked_by",
        item["revoked_by"],
        maximum=1024,
    )
    if actor_id != item["revoked_by"]:
        raise PolicyCandidateAuthorityError(
            "rollback-authority revocation actor is not the signed revoker"
        )
    for field, value in tuple(item.items()):
        if field.endswith("_digest") or field.endswith("_hash"):
            item[field] = _candidate_authority_digest(field, value)
    for field, minimum in (
        ("candidate_policy_sequence", 1),
        ("candidate_rollback_epoch", 1),
        ("expected_active_policy_sequence", 1),
        ("expected_active_rollback_epoch", 0),
        ("publication_revision", 1),
        ("revoked_at_epoch_ns", 0),
    ):
        item[field] = _candidate_authority_int(
            field, item[field], minimum=minimum
        )
    if (
        item["candidate_rollback_epoch"]
        <= item["expected_active_rollback_epoch"]
    ):
        raise PolicyCandidateAuthorityError(
            "rollback-authority revocation monotonic context is invalid"
        )
    _candidate_authority_json(
        "revocation_envelope_json",
        item["revocation_envelope_json"],
        item["revocation_envelope_digest"],
    )
    _candidate_authority_json(
        "revocation_payload_json",
        item["revocation_payload_json"],
        item["revocation_payload_digest"],
    )
    _candidate_authority_signature_fields(item)
    connection_scope = (
        connect()
        if _connection is None
        else contextlib.nullcontext(_connection)
    )
    with connection_scope as conn:
        _lock_policy_candidate_authority(conn)
        authority = conn.execute(
            "SELECT rollback_authorization_envelope_digest, "
            "rollback_authorization_payload_digest, "
            "readiness_envelope_digest, readiness_payload_digest, "
            "readiness_core_digest, canary_id, "
            "artifact_envelope_digest, artifact_payload_digest, "
            "candidate_policy_hash, candidate_policy_sequence, "
            "candidate_rollback_epoch, predecessor_policy_hash, "
            "expected_active_policy_sequence, "
            "expected_active_rollback_epoch, publication_revision, "
            "approval_context_digest, "
            "webauthn_challenge_context_digest, "
            "expected_high_water_digest "
            "FROM policy_activation_rollback_authorities "
            "WHERE rollback_authorization_payload_digest = ?",
            (item["rollback_authorization_payload_digest"],),
        ).fetchone()
        exact_fields = (
            "rollback_authorization_envelope_digest",
            "rollback_authorization_payload_digest",
            "readiness_envelope_digest",
            "readiness_payload_digest",
            "readiness_core_digest",
            "canary_id",
            "artifact_envelope_digest",
            "artifact_payload_digest",
            "candidate_policy_hash",
            "candidate_policy_sequence",
            "candidate_rollback_epoch",
            "predecessor_policy_hash",
            "expected_active_policy_sequence",
            "expected_active_rollback_epoch",
            "publication_revision",
            "approval_context_digest",
            "webauthn_challenge_context_digest",
            "expected_high_water_digest",
        )
        consumed = conn.execute(
            "SELECT rollback_authorization_payload_digest "
            "FROM policy_activation_rollback_consumptions "
            "WHERE rollback_authorization_payload_digest = ?",
            (item["rollback_authorization_payload_digest"],),
        ).fetchone()
        if (
            authority is None
            or consumed is not None
            or any(
                authority[field] != item[field]
                for field in exact_fields
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "rollback-authority revocation is not exact or is too late"
            )
        verified = _verify_policy_authority_evidence(
            conn,
            evidence_kind="rollback_authority_revocation",
            envelope_json=item["revocation_envelope_json"],
            envelope_digest=item["revocation_envelope_digest"],
            payload_json=item["revocation_payload_json"],
            payload_digest=item["revocation_payload_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                {**item, "actor_id": actor_id},
                current_prefix="revocation",
            ),
        )
        _apply_policy_authority_verification(item, verified)
        if item["revoked_at_epoch_ns"] != int(
            verified.values["issued_at_epoch_ns"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "rollback-authority revocation time is not its signed issuance"
            )
        transition_digest = _stage_policy_authority_transition(
            conn,
            event_type="policy.rollback_authority.revoked",
            entity_kind="rollback_authority_revocation",
            entity_id=item["rollback_authorization_payload_digest"],
            entity_revision=1,
            state_digest=item["revocation_payload_digest"],
            previous_state_digest=item[
                "rollback_authorization_payload_digest"
            ],
            actor_id=actor_id,
            evidence={
                "canaryId": item["canary_id"],
                "candidatePolicyHash": item["candidate_policy_hash"],
                "expectedHighWaterDigest":
                    item["expected_high_water_digest"],
                "revocationReasonDigest":
                    item["revocation_reason_digest"],
                "rollbackAuthorizationEnvelopeDigest":
                    item["rollback_authorization_envelope_digest"],
            },
            created_at_epoch_ns=item["revoked_at_epoch_ns"],
        )
        stored = {
            **item,
            "created_transition_digest": transition_digest,
        }
        _insert_immutable_candidate_row(
            conn,
            table="policy_activation_rollback_authority_revocations",
            columns=tuple(stored),
            values=stored,
            key_columns=("revocation_envelope_digest",),
        )
    return dict(stored)


_POLICY_ACTIVATION_REVISION_FIELDS = (
    "activation_attempt_id",
    "revision",
    "status",
    "previous_revision",
    "previous_status",
    "previous_state_digest",
    "approval_id",
    "approval_consumption_digest",
    "publication_intent_digest",
    "uncertainty_digest",
    "state_envelope_json",
    "state_payload_json",
    "state_digest",
    "signature_algorithm",
    "signing_key_id",
    "signature",
    "signature_digest",
    "created_at_epoch_ns",
    "approved_at_epoch_ns",
    "published_at_epoch_ns",
    "terminal_from_status",
    "terminal_at_epoch_ns",
    "actor_id",
    "event_type",
)


def append_policy_activation_revision(
    record: Mapping[str, Any],
    *,
    _connection: Any | None = None,
) -> dict[str, Any]:
    item = _candidate_authority_record(
        "activation revision", record, _POLICY_ACTIVATION_REVISION_FIELDS
    )
    actor_id = _candidate_authority_text(
        "actor_id", item.pop("actor_id"), maximum=1024
    )
    event_type = _candidate_authority_text(
        "event_type", item.pop("event_type"), maximum=256
    )
    _candidate_authority_text(
        "activation_attempt_id", item["activation_attempt_id"], maximum=256
    )
    item["revision"] = _candidate_authority_int(
        "revision", item["revision"], minimum=1
    )
    status = _candidate_authority_text("status", item["status"], maximum=32)
    if status not in set(_POLICY_ACTIVATION_TRANSITIONS) | _POLICY_ACTIVATION_TERMINAL_STATUSES:
        raise PolicyCandidateAuthorityError("activation revision status is invalid")
    for field in (
        "previous_state_digest",
        "approval_id",
        "approval_consumption_digest",
        "publication_intent_digest",
        "uncertainty_digest",
    ):
        if item[field] is not None:
            item[field] = _candidate_authority_digest(field, item[field])
    item["state_digest"] = _candidate_authority_digest(
        "state_digest", item["state_digest"]
    )
    _candidate_authority_json(
        "state_payload_json", item["state_payload_json"], item["state_digest"]
    )
    _candidate_authority_canonical_json(
        "state_envelope_json", item["state_envelope_json"]
    )
    _candidate_authority_signature_fields(item)
    for field in (
        "created_at_epoch_ns",
        "approved_at_epoch_ns",
        "published_at_epoch_ns",
        "terminal_at_epoch_ns",
    ):
        if item[field] is not None:
            item[field] = _candidate_authority_int(field, item[field])

    connection_scope = (
        connect() if _connection is None else contextlib.nullcontext(_connection)
    )
    with connection_scope as conn:
        _lock_policy_candidate_authority(conn)
        attempt = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_ACTIVATION_ATTEMPT_FIELDS
            )
            + " FROM policy_activation_attempts "
            "WHERE activation_attempt_id = ?",
            (item["activation_attempt_id"],),
        ).fetchone()
        if attempt is None:
            raise PolicyCandidateAuthorityConflictError(
                "activation revision has no immutable activation attempt"
            )
        state_envelope_digest = _candidate_authority_sha256(
            item["state_envelope_json"].encode("ascii")
        )
        verified = _verify_policy_authority_evidence(
            conn,
            evidence_kind="activation_state",
            envelope_json=item["state_envelope_json"],
            envelope_digest=state_envelope_digest,
            payload_json=item["state_payload_json"],
            payload_digest=item["state_digest"],
            signature_algorithm=item["signature_algorithm"],
            signing_key_id=item["signing_key_id"],
            signature=item["signature"],
            signature_digest=item["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                {**item, "actor_id": actor_id, "event_type": event_type},
                current_prefix="state",
            ),
        )
        _apply_policy_authority_verification(item, verified)
        head = conn.execute(
            "SELECT activation_attempt_id, head_revision, "
            "head_state_digest, status, unresolved_indeterminate, "
            "updated_at_epoch_ns FROM policy_activation_heads "
            "WHERE activation_attempt_id = ?",
            (item["activation_attempt_id"],),
        ).fetchone()
        if head is None:
            if (
                item["revision"] != 1
                or status != "prepared"
                or item["previous_revision"] is not None
                or item["previous_status"] is not None
                or item["previous_state_digest"] is not None
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "first activation revision must be prepared revision one"
                )
        else:
            if (
                item["revision"] != int(head["head_revision"]) + 1
                or item["previous_revision"] != int(head["head_revision"])
                or item["previous_status"] != str(head["status"])
                or item["previous_state_digest"] != str(head["head_state_digest"])
                or status
                not in _POLICY_ACTIVATION_TRANSITIONS.get(
                    str(head["status"]), frozenset()
                )
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "activation revision is not the exact next legal CAS transition"
                )
        terminal = status in _POLICY_ACTIVATION_TERMINAL_STATUSES
        if (
            terminal
            and (
                item["terminal_from_status"] != item["previous_status"]
                or item["terminal_at_epoch_ns"] is None
            )
        ) or (
            not terminal
            and (
                item["terminal_from_status"] is not None
                or item["terminal_at_epoch_ns"] is not None
            )
        ):
            raise PolicyCandidateAuthorityError(
                "activation terminal evidence is not exact"
            )
        if (status == "indeterminate") != (item["uncertainty_digest"] is not None):
            raise PolicyCandidateAuthorityError(
                "activation indeterminate evidence is not exact"
            )
        publication_bound = status in {
            "publishing",
            "committed",
            "verifying",
            "completed",
        }
        if (
            publication_bound
            != (item["publication_intent_digest"] is not None)
            or (
                publication_bound
                and item["publication_intent_digest"]
                != attempt["publication_intent_digest"]
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation revision does not bind the immutable publication intent"
            )
        transition_digest = _stage_policy_authority_transition(
            conn,
            event_type=event_type,
            entity_kind="activation",
            entity_id=item["activation_attempt_id"],
            entity_revision=item["revision"],
            state_digest=item["state_digest"],
            previous_state_digest=item["previous_state_digest"],
            actor_id=actor_id,
            evidence={
                "status": status,
                "approvalId": item["approval_id"],
                "publicationIntentDigest":
                    item["publication_intent_digest"],
                "uncertaintyDigest": item["uncertainty_digest"],
            },
            created_at_epoch_ns=item["created_at_epoch_ns"],
        )
        revision = {
            **item,
            "transition_digest": transition_digest,
            "transition_entity_kind": "activation",
            "transition_event_type": event_type,
        }
        _insert_immutable_candidate_row(
            conn,
            table="policy_activation_revisions",
            columns=tuple(revision),
            values=revision,
            key_columns=("activation_attempt_id", "revision"),
        )
        unresolved = 1 if status == "indeterminate" else 0
        if head is None:
            conn.execute(
                "INSERT INTO policy_activation_heads "
                "(activation_attempt_id, head_revision, head_state_digest, "
                "status, unresolved_indeterminate, updated_at_epoch_ns) "
                "VALUES (?, ?, ?, ?, ?, ?)",
                (
                    item["activation_attempt_id"], item["revision"],
                    item["state_digest"], status, unresolved,
                    item["created_at_epoch_ns"],
                ),
            )
        else:
            updated = conn.execute(
                "UPDATE policy_activation_heads SET head_revision = ?, "
                "head_state_digest = ?, status = ?, "
                "unresolved_indeterminate = ?, updated_at_epoch_ns = ? "
                "WHERE activation_attempt_id = ? AND head_revision = ? "
                "AND head_state_digest = ? AND status = ?",
                (
                    item["revision"], item["state_digest"], status, unresolved,
                    item["created_at_epoch_ns"], item["activation_attempt_id"],
                    head["head_revision"], head["head_state_digest"],
                    head["status"],
                ),
            )
            if updated.rowcount != 1:
                raise PolicyCandidateAuthorityConflictError(
                    "activation head changed during CAS transition"
                )
    return dict(revision)


def _policy_candidate_high_water_digest(row: Any) -> str:
    if row is None:
        raise PolicyCandidateAuthorityConflictError(
            "active policy high-water state is missing"
        )
    material = dumps(
        {
            "policyHash": str(row["policy_hash"]),
            "policyId": str(row["policy_id"]),
            "rollbackEpoch": int(row["rollback_epoch"]),
            "scope": "active",
            "sequence": int(row["sequence"]),
        }
    )
    return "sha256:" + hashlib.sha256(material.encode("utf-8")).hexdigest()


