                    assignment_item["canary_id"],
                    assignment_item["fleet_id"],
                    assignment_item["membership_revision"],
                    assignment_item["membership_root_digest"],
                    member["member_id"],
                    member["instance_id"],
                    member["boot_id"],
                    role["role"],
                    role["public_key_digest"],
                    attestation["envelopeDigest"],
                    member["tee_measurement_digest"],
                    expected_authorization_digest,
