def _policy_activation_finalized_authority_snapshot(
    finalization: Mapping[str, Any],
) -> dict[str, Any]:
    snapshot_json = str(
        finalization["finalized_authority_snapshot_json"]
    )
    expected_digest = _policy_authority_domain_digest(
        b"serverware.policyActivationFinalizedAuthoritySnapshot/v1",
        snapshot_json.encode("ascii"),
    )
    if (
        expected_digest
        != finalization["finalized_authority_snapshot_digest"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "finalized activation authority snapshot digest changed"
        )
    finalization_material = {
        "activationAttemptId": finalization["activation_attempt_id"],
        "finalizedAuthoritySnapshotDigest":
            finalization["finalized_authority_snapshot_digest"],
        "finalizedAtEpochNs":
            int(finalization["finalized_at_epoch_ns"]),
        "highWaterAfterDigest":
            finalization["high_water_after_digest"],
        "inclusionIdentitySetDigest":
            finalization["inclusion_identity_set_digest"],
        "preparationDigest": finalization["preparation_digest"],
        "preparationInputDigest":
            finalization["preparation_input_digest"],
        "publicationReceiptPayloadDigest":
            finalization["publication_receipt_payload_digest"],
    }
    if _policy_authority_domain_digest(
        b"serverware.policyActivationFinalization/v1",
        dumps(finalization_material).encode("ascii"),
    ) != finalization["finalization_digest"]:
        raise PolicyCandidateAuthorityConflictError(
            "finalized activation digest changed"
        )
    snapshot = loads(snapshot_json, None)
    expected_fields = {
        "schema",
        "activation_attempt_id",
        "preparation_digest",
        "publication",
        "high_water",
        "canary_head",
        "activation_head",
    }
    if (
        not isinstance(snapshot, dict)
        or set(snapshot) != expected_fields
        or dumps(snapshot) != snapshot_json
        or snapshot["schema"]
        != "serverware.policyActivationFinalizedAuthoritySnapshot/v1"
        or snapshot["activation_attempt_id"]
        != finalization["activation_attempt_id"]
        or snapshot["preparation_digest"]
        != finalization["preparation_digest"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "finalized activation authority snapshot is not canonical"
        )
    for name, columns in (
        ("publication", _POLICY_ACTIVATION_CHAIN_PUBLICATION_COLUMNS),
        ("high_water", _POLICY_ACTIVATION_CHAIN_HIGH_WATER_COLUMNS),
        ("canary_head", _POLICY_ACTIVATION_CHAIN_CANARY_HEAD_COLUMNS),
        (
            "activation_head",
            _POLICY_ACTIVATION_CHAIN_ACTIVATION_HEAD_COLUMNS,
        ),
    ):
        value = snapshot[name]
        if not isinstance(value, dict) or set(value) != set(columns):
            raise PolicyCandidateAuthorityConflictError(
                "finalized activation authority snapshot fields are not exact"
            )
    return snapshot


def _policy_activation_authority_snapshot(
    conn: Any,
    *,
    approval_id: str,
    rollback_authorization_digest: str | None,
) -> tuple[str, str]:
    trusted_heads = [
        dict(row)
        for row in conn.execute(
            "SELECT evidence_kind, head_key_revision, "
            "head_signing_key_id, head_public_key_digest, "
            "updated_at_epoch_ns "
            "FROM policy_authority_trusted_key_heads "
            "ORDER BY evidence_kind"
        ).fetchall()
    ]
    revocations = [
        dict(row)
        for row in conn.execute(
            "SELECT revocation_sequence, evidence_kind, key_revision, "
            "signing_key_id, public_key_digest, revoked_at_epoch_ns, "
            "revocation_payload_digest "
            "FROM policy_authority_trusted_key_revocations "
            "ORDER BY revocation_sequence LIMIT ?",
            (_POLICY_AUTHORITY_READ_MAX_ROWS + 1,),
        ).fetchall()
    ]
    if len(revocations) > _POLICY_AUTHORITY_READ_MAX_ROWS:
        raise PolicyCandidateAuthorityError(
            "activation trust snapshot exceeds its row bound"
        )
    assertions = [
        dict(row)
        for row in conn.execute(
            "SELECT assertion_receipt_digest, control_plane_approval_id, "
            "approver_id, credential_record_id, challenge_id, "
            "assertion_digest, webauthn_credential_version_digest, "
            "webauthn_credential_public_key_digest, "
            "trust_bundle_digest, trust_bundle_sequence, "
            "webauthn_trust_publication_snapshot_digest, "
            "assertion_verified_at "
            "FROM policy_activation_webauthn_assertions "
            "WHERE approval_id = ? "
            "ORDER BY control_plane_approval_id",
            (approval_id,),
        ).fetchall()
    ]
    rollback = None
    if rollback_authorization_digest is not None:
        rollback = conn.execute(
            "SELECT rollback_authorization_payload_digest, "
            "rollback_authorization_envelope_digest, signing_key_id, "
            "verification_receipt_digest, expires_at_epoch_ns "
            "FROM policy_activation_rollback_authorities "
            "WHERE rollback_authorization_payload_digest = ?",
            (rollback_authorization_digest,),
        ).fetchone()
        if rollback is None:
            raise PolicyCandidateAuthorityConflictError(
                "rollback authority is missing during reservation"
            )
    material = {
        "schema": "serverware.policyActivationAuthoritySnapshot/v1",
        "approvalId": approval_id,
        "approvalAssertions": assertions,
        "rollbackAuthority": None if rollback is None else dict(rollback),
        "trustedKeyHeads": trusted_heads,
        "trustedKeyRevocations": revocations,
    }
    encoded = dumps(material)
    return encoded, _policy_authority_domain_digest(
        b"serverware.policyActivationAuthoritySnapshot/v1",
        encoded.encode("ascii"),
    )


def _policy_activation_transition_submission(
    conn: Any,
    transition_digest: str,
) -> dict[str, Any]:
    row = conn.execute(
        "SELECT transition.transition_digest, transition.outbox_id, "
        "transition.outbox_event_json, "
        "transition.outbox_event_digest, "
        "transition.event_payload_digest, transition.event_type, "
        "transition.entity_kind, transition.entity_id, "
        "transition.entity_revision, transition.state_digest, "
        "transition.previous_state_digest, transition.actor_id, "
        "transition.created_at_epoch_ns, outbox.status AS outbox_status "
        "FROM policy_authority_transition_audits AS transition "
        "JOIN metadata_audit_outbox AS outbox "
        "ON outbox.id = transition.outbox_id "
        "AND outbox.event_digest = transition.outbox_event_digest "
        "WHERE transition.transition_digest = ?",
        (transition_digest,),
    ).fetchone()
    if row is None:
        raise PolicyCandidateAuthorityConflictError(
            "prepared activation transition is missing"
        )
    return dict(row)


def _stage_policy_activation_prepared_transitions(
    conn: Any,
    *,
    attempt: Mapping[str, Any],
    activation_revisions: list[Mapping[str, Any]],
    canary_revisions: list[Mapping[str, Any]],
    receipt: Mapping[str, Any],
    high_water_before_digest: str,
    high_water_after_digest: str,
) -> list[dict[str, Any]]:
    transition_requests: list[tuple[str, Mapping[str, Any], str]] = [
        ("activation_prepared", activation_revisions[0], "activation"),
        ("canary_activating", canary_revisions[0], "canary"),
        ("activation_approved", activation_revisions[1], "activation"),
        ("activation_publishing", activation_revisions[2], "activation"),
        ("activation_committed", activation_revisions[3], "activation"),
        ("canary_active", canary_revisions[1], "canary"),
    ]
    staged: list[dict[str, Any]] = []
    for purpose, revision, entity_kind in transition_requests:
        if entity_kind == "activation":
            evidence = {
                "status": revision["status"],
                "approvalId": revision["approval_id"],
                "publicationIntentDigest":
                    revision["publication_intent_digest"],
                "uncertaintyDigest": revision["uncertainty_digest"],
            }
            entity_id = attempt["activation_attempt_id"]
        else:
            evidence = {
                "status": revision["status"],
                "assignmentPayloadDigest":
                    revision["assignment_payload_digest"],
                "readinessPayloadDigest":
                    revision["readiness_payload_digest"],
            }
            entity_id = attempt["canary_id"]
        transition_digest = _stage_policy_authority_transition(
            conn,
            event_type=revision["event_type"],
            entity_kind=entity_kind,
            entity_id=entity_id,
            entity_revision=revision["revision"],
            state_digest=revision["state_digest"],
            previous_state_digest=revision["previous_state_digest"],
            actor_id=revision["actor_id"],
            evidence=evidence,
            created_at_epoch_ns=revision["created_at_epoch_ns"],
        )
        staged.append(
            {
                "transition_purpose": purpose,
                **_policy_activation_transition_submission(
                    conn, transition_digest
                ),
            }
        )
    receipt_transition = _stage_policy_authority_transition(
        conn,
        event_type="policy.activation_publication.committed",
        entity_kind="publication_receipt",
        entity_id=attempt["activation_attempt_id"],
        entity_revision=1,
        state_digest=receipt["publication_receipt_payload_digest"],
        previous_state_digest=high_water_before_digest,
        actor_id=receipt["publisher_id"],
        evidence={
            "approvalId": attempt["approval_id"],
            "candidatePolicyHash": attempt["candidate_policy_hash"],
            "highWaterAfterDigest": high_water_after_digest,
            "readinessPayloadDigest": attempt["readiness_payload_digest"],
        },
        created_at_epoch_ns=receipt["committed_at_epoch_ns"],
    )
    staged.insert(
        4,
        {
            "transition_purpose": "publication_committed",
            **_policy_activation_transition_submission(
                conn, receipt_transition
            ),
        },
    )
    return staged


def _persist_policy_activation_preparation(
    conn: Any,
    *,
    attempt: Mapping[str, Any],
    approval: Mapping[str, Any],
    members: list[Mapping[str, Any]],
    consumption: Mapping[str, Any],
    activation_revisions: list[Mapping[str, Any]],
    canary_revisions: list[Mapping[str, Any]],
    receipt: Mapping[str, Any],
    readiness: Mapping[str, Any],
    canary_head: Mapping[str, Any],
    high_water_before_digest: str,
    high_water_after_digest: str,
    prepared_at_epoch_ns: int,
) -> dict[str, Any]:
    preparation_input = {
        "schema": "serverware.policyActivationPreparationInput/v1",
        "activation": dict(attempt),
        "approval": dict(approval),
        "approvalMembers": [dict(member) for member in members],
        "approvalConsumption": dict(consumption),
        "activationRevisions": [
            dict(revision) for revision in activation_revisions
        ],
        "canaryRevisions": [
            dict(revision) for revision in canary_revisions
        ],
        "publicationReceipt": dict(receipt),
    }
    preparation_input_json = dumps(preparation_input)
    preparation_input_digest = _policy_authority_domain_digest(
        b"serverware.policyActivationPreparationInput/v1",
        preparation_input_json.encode("ascii"),
    )
    existing = conn.execute(
        "SELECT "
        + _policy_authority_projection(
            _POLICY_ACTIVATION_PREPARATION_COLUMNS
        )
        + " FROM policy_activation_preparations "
        "WHERE activation_attempt_id = ?",
        (attempt["activation_attempt_id"],),
    ).fetchone()
    if existing is not None:
        if (
            existing["preparation_input_digest"]
            != preparation_input_digest
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation preparation idempotency identity was reused"
            )
        submissions = [
            {
                "transition_purpose": row["transition_purpose"],
                **_policy_activation_transition_submission(
                    conn, row["transition_digest"]
                ),
            }
            for row in conn.execute(
                "SELECT transition_purpose, transition_digest "
                "FROM policy_activation_prepared_transitions "
                "WHERE preparation_digest = ? "
                "ORDER BY transition_ordinal",
                (existing["preparation_digest"],),
            ).fetchall()
        ]
        return {
            "ok": True,
            "idempotent": True,
            "activation_attempt_id": attempt["activation_attempt_id"],
            "preparation_digest": existing["preparation_digest"],
            "preparation_input_digest": preparation_input_digest,
            "audit_submissions": submissions,
        }
    _insert_immutable_candidate_row(
        conn,
        table="policy_activation_attempts",
        columns=_POLICY_ACTIVATION_ATTEMPT_FIELDS,
        values=attempt,
        key_columns=("activation_attempt_id",),
    )
    if attempt["activation_mode"] == "authorized_rollback":
        rollback = conn.execute(
            "SELECT rollback_authorization_payload_digest, "
            "rollback_authorization_envelope_digest, "
            "readiness_payload_digest, readiness_core_digest, canary_id, "
            "artifact_envelope_digest, artifact_payload_digest, "
            "candidate_policy_hash, candidate_policy_sequence, "
            "candidate_rollback_epoch, predecessor_policy_hash, "
            "expected_active_policy_sequence, "
            "expected_active_rollback_epoch, publication_revision, "
            "approval_context_digest, "
            "webauthn_challenge_context_digest, "
            "expected_high_water_digest, expires_at_epoch_ns "
            "FROM policy_activation_rollback_authorities "
            "WHERE rollback_authorization_payload_digest = ?",
            (attempt["rollback_authorization_digest"],),
        ).fetchone()
        rollback_revocation = conn.execute(
            "SELECT revocation_payload_digest "
            "FROM policy_activation_rollback_authority_revocations "
            "WHERE rollback_authorization_payload_digest = ?",
            (attempt["rollback_authorization_digest"],),
        ).fetchone()
        rollback_consumption = conn.execute(
            "SELECT consumption_digest "
            "FROM policy_activation_rollback_consumptions "
            "WHERE rollback_authorization_payload_digest = ?",
            (attempt["rollback_authorization_digest"],),
        ).fetchone()
        rollback_exact = {
            "readiness_payload_digest":
                attempt["readiness_payload_digest"],
            "readiness_core_digest": attempt["readiness_core_digest"],
            "canary_id": attempt["canary_id"],
            "artifact_envelope_digest":
                attempt["artifact_envelope_digest"],
            "artifact_payload_digest":
                attempt["artifact_payload_digest"],
            "candidate_policy_hash": attempt["candidate_policy_hash"],
            "candidate_policy_sequence":
                attempt["candidate_policy_sequence"],
            "candidate_rollback_epoch":
                attempt["candidate_rollback_epoch"],
            "predecessor_policy_hash":
                attempt["predecessor_policy_hash"],
            "expected_active_policy_sequence":
                attempt["expected_active_policy_sequence"],
            "expected_active_rollback_epoch":
                attempt["expected_active_rollback_epoch"],
            "publication_revision": attempt["publication_revision"],
            "approval_context_digest":
                attempt["approval_context_digest"],
            "webauthn_challenge_context_digest":
                approval["webauthn_challenge_context_digest"],
            "expected_high_water_digest":
                attempt["expected_high_water_digest"],
        }
        if (
            rollback is None
            or rollback_revocation is not None
            or rollback_consumption is not None
            or any(
                rollback[field] != value
                for field, value in rollback_exact.items()
            )
            or int(rollback["expires_at_epoch_ns"])
            <= prepared_at_epoch_ns
        ):
            raise PolicyCandidateAuthorityConflictError(
                "rollback authority cannot be reserved exactly"
            )
    authority_snapshot_json, authority_snapshot_digest = (
        _policy_activation_authority_snapshot(
            conn,
            approval_id=attempt["approval_id"],
            rollback_authorization_digest=
                attempt["rollback_authorization_digest"],
        )
    )
    staged = _stage_policy_activation_prepared_transitions(
        conn,
        attempt=attempt,
        activation_revisions=activation_revisions,
        canary_revisions=canary_revisions,
        receipt=receipt,
        high_water_before_digest=high_water_before_digest,
        high_water_after_digest=high_water_after_digest,
    )
    manifest = [
        {
            "ordinal": ordinal,
            "purpose": transition["transition_purpose"],
            "transitionDigest": transition["transition_digest"],
            "outboxId": transition["outbox_id"],
            "outboxEventDigest": transition["outbox_event_digest"],
            "eventPayloadDigest": transition["event_payload_digest"],
            "eventType": transition["event_type"],
            "entityKind": transition["entity_kind"],
            "entityId": transition["entity_id"],
            "entityRevision": transition["entity_revision"],
            "stateDigest": transition["state_digest"],
            "previousStateDigest":
                transition["previous_state_digest"],
        }
        for ordinal, transition in enumerate(staged, start=1)
    ]
    transition_manifest_json = dumps(manifest)
    transition_manifest_root_digest = _policy_authority_domain_digest(
        b"serverware.policyActivationTransitionManifest/v1",
        transition_manifest_json.encode("ascii"),
    )
    preparation_material = {
        "activationAttemptId": attempt["activation_attempt_id"],
        "approvalConsumptionDigest": consumption["consumption_digest"],
        "authoritySnapshotDigest": authority_snapshot_digest,
        "expiresAtEpochNs": attempt["expires_at_epoch_ns"],
        "preparationInputDigest": preparation_input_digest,
        "preparedAtEpochNs": prepared_at_epoch_ns,
        "transitionManifestRootDigest":
            transition_manifest_root_digest,
    }
    preparation_digest = _policy_authority_domain_digest(
        b"serverware.policyActivationPreparation/v1",
        dumps(preparation_material).encode("ascii"),
    )
    preparation = {
        "preparation_digest": preparation_digest,
        "activation_attempt_id": attempt["activation_attempt_id"],
        "activation_intent_digest":
            attempt["activation_intent_digest"],
        "publication_intent_digest":
            attempt["publication_intent_digest"],
        "readiness_payload_digest":
            attempt["readiness_payload_digest"],
        "approval_id": attempt["approval_id"],
        "approval_consumption_digest":
            consumption["consumption_digest"],
        "rollback_authorization_digest":
            attempt["rollback_authorization_digest"],
        "expected_high_water_digest":
            attempt["expected_high_water_digest"],
        "predecessor_policy_hash":
            attempt["predecessor_policy_hash"],
        "candidate_policy_hash":
            attempt["candidate_policy_hash"],
        "candidate_policy_sequence":
            attempt["candidate_policy_sequence"],
        "candidate_rollback_epoch":
            attempt["candidate_rollback_epoch"],
        "prepared_canary_revision": int(
            canary_head["head_revision"]
        ),
        "prepared_canary_state_digest":
            canary_head["head_state_digest"],
        "authority_snapshot_json": authority_snapshot_json,
        "authority_snapshot_digest": authority_snapshot_digest,
        "preparation_input_json": preparation_input_json,
        "preparation_input_digest": preparation_input_digest,
        "transition_manifest_json": transition_manifest_json,
        "transition_manifest_root_digest":
            transition_manifest_root_digest,
        "transition_count": len(staged),
        "prepared_at_epoch_ns": prepared_at_epoch_ns,
        "expires_at_epoch_ns": attempt["expires_at_epoch_ns"],
    }
    _insert_immutable_candidate_row(
        conn,
        table="policy_activation_preparations",
        columns=_POLICY_ACTIVATION_PREPARATION_COLUMNS,
        values=preparation,
        key_columns=("preparation_digest",),
    )
    for ordinal, transition in enumerate(staged, start=1):
        prepared_transition = {
            "preparation_digest": preparation_digest,
            "transition_ordinal": ordinal,
            "transition_purpose":
                transition["transition_purpose"],
            "transition_digest": transition["transition_digest"],
            "outbox_id": transition["outbox_id"],
            "outbox_event_digest":
                transition["outbox_event_digest"],
            "event_payload_digest":
                transition["event_payload_digest"],
            "event_type": transition["event_type"],
            "entity_kind": transition["entity_kind"],
            "entity_id": transition["entity_id"],
            "entity_revision": transition["entity_revision"],
            "state_digest": transition["state_digest"],
            "previous_state_digest":
                transition["previous_state_digest"],
        }
        _insert_immutable_candidate_row(
            conn,
            table="policy_activation_prepared_transitions",
            columns=_POLICY_ACTIVATION_PREPARED_TRANSITION_COLUMNS,
            values=prepared_transition,
            key_columns=(
                "preparation_digest", "transition_ordinal"
            ),
        )
    return {
        "ok": True,
        "idempotent": False,
        "activation_attempt_id": attempt["activation_attempt_id"],
        "preparation_digest": preparation_digest,
        "preparation_input_digest": preparation_input_digest,
        "transition_manifest_root_digest":
            transition_manifest_root_digest,
        "audit_submissions": staged,
    }


def activate_policy_candidate(**_: Any) -> dict[str, Any]:
    raise PolicyCandidateAuthorityError(
        "one-shot activation is disabled; use prepare_policy_activation, "
        "record_policy_activation_audit_inclusions, and "
        "finalize_policy_activation"
    )


def _policy_activation_preparation_row(
    conn: Any,
    preparation_digest: str,
) -> Any:
    preparation_digest = _candidate_authority_digest(
        "preparation_digest", preparation_digest
    )
    row = conn.execute(
        "SELECT "
        + _policy_authority_projection(
            _POLICY_ACTIVATION_PREPARATION_COLUMNS
        )
        + " FROM policy_activation_preparations "
        "WHERE preparation_digest = ?",
        (preparation_digest,),
    ).fetchone()
    if row is None:
        raise PolicyCandidateAuthorityConflictError(
            "activation preparation does not exist"
        )
    return row


def _policy_activation_inclusion_identity_set(
    conn: Any,
    *,
    preparation_digest: str,
    require_complete: bool,
) -> tuple[str, str, list[dict[str, Any]]]:
    preparation = _policy_activation_preparation_row(
        conn, preparation_digest
    )
    rows = conn.execute(
        "SELECT prepared.transition_ordinal, "
        "prepared.transition_purpose, prepared.transition_digest, "
        "prepared.outbox_id, prepared.outbox_event_digest, "
        "prepared.event_payload_digest, prepared.event_type, "
        "prepared.entity_kind, prepared.entity_id, "
        "prepared.entity_revision, prepared.state_digest, "
        "prepared.previous_state_digest, "
        "receipt.inclusion_receipt_envelope_digest, "
        "receipt.inclusion_receipt_payload_digest, "
        "receipt.audit_store_identity_digest, "
        "receipt.audit_ledger_namespace, "
        "receipt.audit_signer_public_key_digest, "
        "receipt.audit_event_hash, receipt.audit_sequence, "
        "receipt.previous_audit_event_hash, "
        "receipt.inclusion_root_digest, receipt.signing_key_id, "
        "receipt.signature_digest, "
        "receipt.verification_receipt_digest "
        "FROM policy_activation_prepared_transitions AS prepared "
        "LEFT JOIN policy_authority_audit_inclusion_receipts AS receipt "
        "ON receipt.transition_digest = prepared.transition_digest "
        "AND receipt.outbox_id = prepared.outbox_id "
        "AND receipt.outbox_event_digest = "
        "prepared.outbox_event_digest "
        "WHERE prepared.preparation_digest = ? "
        "ORDER BY prepared.transition_ordinal",
        (preparation_digest,),
    ).fetchall()
    if (
        int(preparation["transition_count"]) != 7
        or len(rows) != 7
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation preparation must contain exactly seven transitions"
        )
    manifest = [
        {
            "ordinal": int(row["transition_ordinal"]),
            "purpose": row["transition_purpose"],
            "transitionDigest": row["transition_digest"],
            "outboxId": row["outbox_id"],
            "outboxEventDigest": row["outbox_event_digest"],
            "eventPayloadDigest": row["event_payload_digest"],
            "eventType": row["event_type"],
            "entityKind": row["entity_kind"],
            "entityId": row["entity_id"],
            "entityRevision": int(row["entity_revision"]),
            "stateDigest": row["state_digest"],
            "previousStateDigest": row["previous_state_digest"],
        }
        for row in rows
    ]
    manifest_json = dumps(manifest)
    if (
        manifest_json != preparation["transition_manifest_json"]
        or _policy_authority_domain_digest(
            b"serverware.policyActivationTransitionManifest/v1",
            manifest_json.encode("ascii"),
        )
        != preparation["transition_manifest_root_digest"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation preparation transition manifest changed"
        )
    identities: list[dict[str, Any]] = []
    for row in rows:
        if row["inclusion_receipt_envelope_digest"] is None:
            if require_complete:
                raise PolicyCandidateAuthorityConflictError(
                    "activation preparation lacks an exact external audit "
                    "inclusion"
                )
            continue
        receipt = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_AUTHORITY_AUDIT_INCLUSION_COLUMNS
            )
            + " FROM policy_authority_audit_inclusion_receipts "
            "WHERE inclusion_receipt_envelope_digest = ?",
            (row["inclusion_receipt_envelope_digest"],),
        ).fetchone()
        if receipt is None:
            raise PolicyCandidateAuthorityConflictError(
                "activation audit inclusion identity is incomplete"
            )
        _reverify_policy_audit_inclusion_receipt(conn, dict(receipt))
        identities.append(
            {
                "ordinal": int(row["transition_ordinal"]),
                "purpose": row["transition_purpose"],
                "transitionDigest": row["transition_digest"],
                "outboxId": row["outbox_id"],
                "outboxEventDigest": row["outbox_event_digest"],
                "inclusionReceiptEnvelopeDigest":
                    row["inclusion_receipt_envelope_digest"],
                "inclusionReceiptPayloadDigest":
                    row["inclusion_receipt_payload_digest"],
                "auditStoreIdentityDigest":
                    row["audit_store_identity_digest"],
                "auditLedgerNamespace":
                    row["audit_ledger_namespace"],
                "auditSignerSpkiDigest":
                    row["audit_signer_public_key_digest"],
                "auditEventHash": row["audit_event_hash"],
                "auditSequence": int(row["audit_sequence"]),
                "previousAuditEventHash":
                    row["previous_audit_event_hash"],
                "inclusionRootDigest":
                    row["inclusion_root_digest"],
                "signingKeyId": row["signing_key_id"],
                "signatureDigest": row["signature_digest"],
                "verificationReceiptDigest":
                    row["verification_receipt_digest"],
            }
        )
    if require_complete:
        sequences = [identity["auditSequence"] for identity in identities]
        if (
            len(identities) != 7
            or any(
                identity["auditStoreIdentityDigest"]
                != _POLICY_AUTHORITY_AUDIT_STORE_IDENTITY_DIGEST
                or identity["auditLedgerNamespace"]
                != _POLICY_AUTHORITY_AUDIT_LEDGER_NAMESPACE
                or identity["auditSignerSpkiDigest"]
                != _POLICY_AUTHORITY_AUDIT_SIGNER_SPKI_DIGEST
                or identity["signingKeyId"]
                != _POLICY_AUTHORITY_AUDIT_SIGNER_SPKI_DIGEST
                for identity in identities
            )
            or sequences
            != list(range(sequences[0], sequences[0] + 7))
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation requires seven ordered receipts from the one "
                "pinned audit store and independent signer"
            )
    material_json = dumps(identities)
    identity_set_digest = _policy_authority_domain_digest(
        b"serverware.policyActivationAuditInclusionSet/v1",
        material_json.encode("ascii"),
    )
    return material_json, identity_set_digest, identities


def record_policy_activation_audit_inclusions(
    *,
    preparation_digest: str,
    inclusion_receipts: list[Mapping[str, Any]],
    authority_verifier_response: Mapping[str, Any] | None = None,
    _connection: Any | None = None,
) -> dict[str, Any]:
    _require_postgres_policy_authority(
        "policy activation audit inclusion"
    )
    if _connection is None:
        return _invoke_policy_authority_owner_contract(
            operation="policy.activation.record-inclusion",
            input_value={
                "preparationDigest": preparation_digest,
                "inclusionReceipts": [
                    dict(receipt) for receipt in inclusion_receipts
                ],
            },
            verifier_response=authority_verifier_response,
        )
    if not isinstance(_connection, PostgresMetadataConnection):
        raise PolicyCandidateAuthorityError(
            "activation inclusion is owner-contract internal"
        )
    if not isinstance(inclusion_receipts, list) or not inclusion_receipts:
        raise PolicyCandidateAuthorityError(
            "activation audit inclusions must be a non-empty list"
        )
    with contextlib.nullcontext(_connection) as conn:
        _lock_policy_candidate_authority(conn)
        preparation = _policy_activation_preparation_row(
            conn, preparation_digest
        )
        if conn.execute(
            "SELECT preparation_digest FROM policy_activation_aborts "
            "WHERE preparation_digest = ?",
            (preparation["preparation_digest"],),
        ).fetchone() is not None:
            raise PolicyCandidateAuthorityConflictError(
                "aborted activation cannot accept audit inclusions"
            )
        required = conn.execute(
            "SELECT transition_ordinal, transition_digest "
            "FROM policy_activation_prepared_transitions "
            "WHERE preparation_digest = ? "
            "ORDER BY transition_ordinal",
            (preparation["preparation_digest"],),
        ).fetchall()
        supplied_by_transition: dict[str, Mapping[str, Any]] = {}
        for receipt in inclusion_receipts:
            transition_digest = _candidate_authority_digest(
                "transition_digest", receipt.get("transition_digest")
            )
            if transition_digest in supplied_by_transition:
                raise PolicyCandidateAuthorityError(
                    "duplicate activation audit inclusion"
                )
            supplied_by_transition[transition_digest] = receipt
        required_digests = {
            str(row["transition_digest"]) for row in required
        }
        if set(supplied_by_transition) - required_digests:
            raise PolicyCandidateAuthorityConflictError(
                "audit inclusion is outside the exact preparation"
            )
        recorded = []
        for row in required:
            supplied = supplied_by_transition.get(
                str(row["transition_digest"])
            )
            if supplied is None:
                continue
            recorded.append(
                record_policy_authority_audit_inclusion(
                    supplied, _connection=conn
                )
            )
        material_json, identity_set_digest, identities = (
            _policy_activation_inclusion_identity_set(
                conn,
                preparation_digest=preparation["preparation_digest"],
                require_complete=False,
            )
        )
    return {
        "ok": True,
        "preparation_digest": preparation_digest,
        "recorded_count": len(recorded),
        "recorded_inclusion_receipts": recorded,
        "inclusion_identity_set_json": material_json,
        "inclusion_identity_set_digest": identity_set_digest,
        "included_transitions": identities,
    }


def _abort_policy_activation_on_connection(
    conn: Any,
    *,
    preparation: Mapping[str, Any],
    reason: str,
    aborted_by: str,
    aborted_at_epoch_ns: int,
) -> dict[str, Any]:
    aborted_by = _candidate_authority_text(
        "aborted_by", aborted_by, maximum=1024
    )
    aborted_at_epoch_ns = _candidate_authority_int(
        "aborted_at_epoch_ns", aborted_at_epoch_ns
    )
    if reason not in {
        "expired",
        "predecessor_conflict",
        "approval_revoked",
        "trust_revoked",
        "operator_cancelled",
    }:
        raise PolicyCandidateAuthorityError(
            "activation abort reason is invalid"
        )
    if (
        reason == "expired"
        and aborted_at_epoch_ns
        < int(preparation["expires_at_epoch_ns"])
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation cannot be tombstoned as expired before its deadline"
        )
    existing = conn.execute(
        "SELECT preparation_digest, activation_attempt_id, abort_reason, "
        "abort_digest, abort_transition_digest, aborted_by, "
        "aborted_at_epoch_ns FROM policy_activation_aborts "
        "WHERE preparation_digest = ?",
        (preparation["preparation_digest"],),
    ).fetchone()
    if existing is not None:
        existing_material = {
            "schema": "serverware.policyActivationAbort/v1",
            "activationAttemptId":
                preparation["activation_attempt_id"],
            "abortedAtEpochNs":
                int(existing["aborted_at_epoch_ns"]),
            "abortedBy": aborted_by,
            "preparationDigest": preparation["preparation_digest"],
            "reason": reason,
        }
        expected_existing_digest = _policy_authority_domain_digest(
            b"serverware.policyActivationAbort/v1",
            dumps(existing_material).encode("ascii"),
        )
        if (
            existing["activation_attempt_id"]
            != preparation["activation_attempt_id"]
            or existing["abort_reason"] != reason
            or existing["aborted_by"] != aborted_by
            or existing["abort_digest"] != expected_existing_digest
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation abort idempotency identity was reused"
            )
        return dict(existing)
    if conn.execute(
        "SELECT preparation_digest FROM policy_activation_finalizations "
        "WHERE preparation_digest = ?",
        (preparation["preparation_digest"],),
    ).fetchone() is not None:
        raise PolicyCandidateAuthorityConflictError(
            "committed activation cannot be aborted"
        )
    abort_material = {
        "schema": "serverware.policyActivationAbort/v1",
        "activationAttemptId": preparation["activation_attempt_id"],
        "abortedAtEpochNs": aborted_at_epoch_ns,
        "abortedBy": aborted_by,
        "preparationDigest": preparation["preparation_digest"],
        "reason": reason,
    }
    abort_digest = _policy_authority_domain_digest(
        b"serverware.policyActivationAbort/v1",
        dumps(abort_material).encode("ascii"),
    )
    transition_digest = _stage_policy_authority_transition(
        conn,
        event_type="policy.activation.aborted",
        entity_kind="activation_abort",
        entity_id=preparation["activation_attempt_id"],
        entity_revision=1,
        state_digest=abort_digest,
        previous_state_digest=preparation["preparation_digest"],
        actor_id=aborted_by,
        evidence={
            "preparationDigest": preparation["preparation_digest"],
            "reason": reason,
        },
        created_at_epoch_ns=aborted_at_epoch_ns,
    )
    abort = {
        "preparation_digest": preparation["preparation_digest"],
        "activation_attempt_id":
            preparation["activation_attempt_id"],
        "abort_reason": reason,
        "abort_digest": abort_digest,
        "abort_transition_digest": transition_digest,
        "aborted_by": aborted_by,
        "aborted_at_epoch_ns": aborted_at_epoch_ns,
    }
    _insert_immutable_candidate_row(
        conn,
        table="policy_activation_aborts",
        columns=tuple(abort),
        values=abort,
        key_columns=("preparation_digest",),
    )
    return abort


def abort_policy_activation(
    *,
    preparation_digest: str,
    reason: str = "operator_cancelled",
    aborted_by: str,
    authority_verifier_response: Mapping[str, Any] | None = None,
    _connection: Any | None = None,
) -> dict[str, Any]:
    _require_postgres_policy_authority("policy activation abort")
    if _connection is None:
        return _invoke_policy_authority_owner_contract(
            operation="policy.activation.abort",
            input_value={
                "preparationDigest": preparation_digest,
                "reason": reason,
                "abortedBy": aborted_by,
            },
            verifier_response=authority_verifier_response,
        )
    if not isinstance(_connection, PostgresMetadataConnection):
        raise PolicyCandidateAuthorityError(
            "activation abort is owner-contract internal"
        )
    with contextlib.nullcontext(_connection) as conn:
        _lock_policy_candidate_authority(conn)
        preparation = _policy_activation_preparation_row(
            conn, preparation_digest
        )
        now = _metadata_utcnow(conn)
        abort = _abort_policy_activation_on_connection(
            conn,
            preparation=preparation,
            reason=reason,
            aborted_by=aborted_by,
            aborted_at_epoch_ns=int(
                now.timestamp() * 1_000_000_000
            ),
        )
        submission = _policy_activation_transition_submission(
            conn, abort["abort_transition_digest"]
        )
    return {
        "ok": True,
        "status": "aborted",
        **abort,
        "audit_submission": submission,
    }


def finalize_policy_activation(
    *,
    preparation_digest: str,
    inclusion_receipt_envelope_digests: list[str],
    authority_verifier_response: Mapping[str, Any] | None = None,
    _connection: Any | None = None,
) -> dict[str, Any]:
    _require_postgres_policy_authority("policy activation finalization")
    if _connection is None:
        return _invoke_policy_authority_owner_contract(
            operation="policy.activation.finalize",
            input_value={
                "preparationDigest": preparation_digest,
                "inclusionReceiptEnvelopeDigests":
                    list(inclusion_receipt_envelope_digests),
            },
            verifier_response=authority_verifier_response,
        )
    if not isinstance(_connection, PostgresMetadataConnection):
        raise PolicyCandidateAuthorityError(
            "activation finalization is owner-contract internal"
        )
    if (
        not isinstance(inclusion_receipt_envelope_digests, list)
        or not inclusion_receipt_envelope_digests
    ):
        raise PolicyCandidateAuthorityError(
            "finalization requires the exact ordered inclusion identities"
        )
    supplied_inclusions = [
        _candidate_authority_digest(
            "inclusion_receipt_envelope_digest", value
        )
        for value in inclusion_receipt_envelope_digests
    ]
    if len(set(supplied_inclusions)) != len(supplied_inclusions):
        raise PolicyCandidateAuthorityError(
            "finalization inclusion identities are duplicated"
        )
    with contextlib.nullcontext(_connection) as conn:
        _lock_policy_candidate_authority(conn)
        _lock_policy_high_water(conn)
        _lock_webauthn_authority(conn)
        _lock_rbac_authority(conn)
        preparation = _policy_activation_preparation_row(
            conn, preparation_digest
        )
        existing_abort = conn.execute(
            "SELECT abort_reason, abort_digest, abort_transition_digest "
            "FROM policy_activation_aborts "
            "WHERE preparation_digest = ?",
            (preparation["preparation_digest"],),
        ).fetchone()
        if existing_abort is not None:
            return {
                "ok": False,
                "idempotent": True,
                "status": "aborted",
                "preparation_digest": preparation["preparation_digest"],
                **dict(existing_abort),
            }
        existing_finalization = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_ACTIVATION_FINALIZATION_COLUMNS
            )
            + " "
            "FROM policy_activation_finalizations "
            "WHERE preparation_digest = ?",
            (preparation["preparation_digest"],),
        ).fetchone()
        if existing_finalization is not None:
            stored_inclusion_identities = loads(
                str(
                    existing_finalization[
                        "inclusion_identity_set_json"
                    ]
                ),
                None,
            )
            if (
                existing_finalization[
                    "preparation_input_digest"
                ] != preparation["preparation_input_digest"]
                or not isinstance(stored_inclusion_identities, list)
                or supplied_inclusions
                != [
                    identity.get(
                        "inclusionReceiptEnvelopeDigest"
                    )
                    for identity in stored_inclusion_identities
                    if isinstance(identity, dict)
                ]
                or _policy_authority_domain_digest(
                    b"serverware.policyActivationAuditInclusionSet/v1",
                    str(
                        existing_finalization[
                            "inclusion_identity_set_json"
                        ]
                    ).encode("ascii"),
                )
                != existing_finalization[
                    "inclusion_identity_set_digest"
                ]
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "finalization idempotency identity was reused"
                )
            _policy_activation_finalized_authority_snapshot(
                existing_finalization
            )
            frozen_export = conn.execute(
                "SELECT preparation_digest "
                "FROM policy_activation_finalized_exports "
                "WHERE activation_attempt_id = ?",
                (preparation["activation_attempt_id"],),
            ).fetchone()
            if (
                frozen_export is None
                or frozen_export["preparation_digest"]
                != preparation["preparation_digest"]
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "committed activation lacks its immutable finalized "
                    "export snapshot"
                )
            return {
                "ok": True,
                "idempotent": True,
                "status": "committed",
                **dict(existing_finalization),
            }
        preparation_input_json = str(
            preparation["preparation_input_json"]
        )
        if _policy_authority_domain_digest(
            b"serverware.policyActivationPreparationInput/v1",
            preparation_input_json.encode("ascii"),
        ) != preparation["preparation_input_digest"]:
            raise PolicyCandidateAuthorityConflictError(
                "stored activation preparation input changed"
            )
        preparation_input = loads(preparation_input_json, None)
        if (
            not isinstance(preparation_input, dict)
            or dumps(preparation_input) != preparation_input_json
            or preparation_input.get("schema")
            != "serverware.policyActivationPreparationInput/v1"
        ):
            raise PolicyCandidateAuthorityConflictError(
                "stored activation preparation input is not canonical"
            )
        attempt = _candidate_authority_record(
            "activation attempt",
            preparation_input.get("activation"),
            _POLICY_ACTIVATION_ATTEMPT_FIELDS,
        )
        approval = preparation_input.get("approval")
        members = preparation_input.get("approvalMembers")
        consumption = _candidate_authority_record(
            "activation approval consumption",
            preparation_input.get("approvalConsumption"),
            _POLICY_ACTIVATION_CONSUMPTION_FIELDS,
        )
        activation_revisions = preparation_input.get(
            "activationRevisions"
        )
        canary_revisions = preparation_input.get("canaryRevisions")
        receipt = _candidate_authority_record(
            "activation publication receipt",
            preparation_input.get("publicationReceipt"),
            _POLICY_ACTIVATION_PUBLICATION_RECEIPT_FIELDS,
        )
        if (
            not isinstance(approval, Mapping)
            or not isinstance(members, list)
            or not isinstance(activation_revisions, list)
            or not isinstance(canary_revisions, list)
        ):
            raise PolicyCandidateAuthorityConflictError(
                "stored activation preparation evidence is incomplete"
            )
        now = _metadata_utcnow(conn)
        now_s = now.isoformat()
        now_epoch_ns = int(now.timestamp() * 1_000_000_000)
        if now_epoch_ns >= int(preparation["expires_at_epoch_ns"]):
            abort = _abort_policy_activation_on_connection(
                conn,
                preparation=preparation,
                reason="expired",
                aborted_by=attempt["requested_by"],
                aborted_at_epoch_ns=now_epoch_ns,
            )
            return {
                "ok": False,
                "idempotent": False,
                "status": "aborted",
                **abort,
            }
        (
            inclusion_identity_set_json,
            inclusion_identity_set_digest,
            inclusion_identities,
        ) = _policy_activation_inclusion_identity_set(
            conn,
            preparation_digest=preparation["preparation_digest"],
            require_complete=True,
        )
        stored_inclusion_digests = [
            identity["inclusionReceiptEnvelopeDigest"]
            for identity in inclusion_identities
        ]
        if supplied_inclusions != stored_inclusion_digests:
            raise PolicyCandidateAuthorityConflictError(
                "finalization inclusion identities are not the exact "
                "ordered preparation set"
            )
        current = _committed_policy_authority_row(conn)
        canary_head = conn.execute(
            "SELECT canary_id, head_revision, head_state_digest, status, "
            "updated_at_epoch_ns FROM policy_canary_heads "
            "WHERE canary_id = ?",
            (attempt["canary_id"],),
        ).fetchone()
        if (
            not _policy_row_matches(
                current,
                policy_id=receipt["policy_id"],
                sequence=attempt["expected_active_policy_sequence"],
                rollback_epoch=
                    attempt["expected_active_rollback_epoch"],
                policy_hash=attempt["predecessor_policy_hash"],
            )
            or _policy_candidate_high_water_digest(current)
            != preparation["expected_high_water_digest"]
            or canary_head is None
            or canary_head["status"] != "ready"
            or int(canary_head["head_revision"])
            != int(preparation["prepared_canary_revision"])
            or canary_head["head_state_digest"]
            != preparation["prepared_canary_state_digest"]
        ):
            abort = _abort_policy_activation_on_connection(
                conn,
                preparation=preparation,
                reason="predecessor_conflict",
                aborted_by=attempt["requested_by"],
                aborted_at_epoch_ns=now_epoch_ns,
            )
            return {
                "ok": False,
                "idempotent": False,
                "status": "aborted",
                **abort,
            }
        authority_snapshot_json, authority_snapshot_digest = (
            _policy_activation_authority_snapshot(
                conn,
                approval_id=attempt["approval_id"],
                rollback_authorization_digest=
                    attempt["rollback_authorization_digest"],
            )
        )
        if (
            authority_snapshot_digest
            != preparation["authority_snapshot_digest"]
            or authority_snapshot_json
            != preparation["authority_snapshot_json"]
        ):
            abort = _abort_policy_activation_on_connection(
                conn,
                preparation=preparation,
                reason="trust_revoked",
                aborted_by=attempt["requested_by"],
                aborted_at_epoch_ns=now_epoch_ns,
            )
            return {
                "ok": False,
                "idempotent": False,
                "status": "aborted",
                **abort,
            }
        readiness = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_CANARY_READINESS_READ_COLUMNS,
                alias="readiness",
            )
            + ", canary.policy_id, "
            "canary.minimum_evaluation_count "
            "FROM policy_canary_readiness AS readiness "
            "JOIN policy_canaries AS canary "
            "ON canary.canary_id = readiness.canary_id "
            "WHERE readiness.readiness_envelope_digest = ?",
            (attempt["readiness_envelope_digest"],),
        ).fetchone()
        if (
            readiness is None
            or int(readiness["expires_at_epoch_ns"]) <= now_epoch_ns
        ):
            abort = _abort_policy_activation_on_connection(
                conn,
                preparation=preparation,
                reason="expired",
                aborted_by=attempt["requested_by"],
                aborted_at_epoch_ns=now_epoch_ns,
            )
            return {
                "ok": False,
                "idempotent": False,
                "status": "aborted",
                **abort,
            }
        high_water_before_digest = _policy_candidate_high_water_digest(
            current
        )
        high_water_after_digest = _policy_candidate_high_water_digest(
            {
                "policy_id": receipt["policy_id"],
                "sequence": attempt["candidate_policy_sequence"],
                "rollback_epoch": attempt["candidate_rollback_epoch"],
                "policy_hash": attempt["candidate_policy_hash"],
            }
        )
        _validate_policy_activation_equality_map(
            attempt=attempt,
            approval=approval,
            consumption=consumption,
            activation_revisions=activation_revisions,
            canary_revisions=canary_revisions,
            receipt=receipt,
            readiness=readiness,
            policy_id=receipt["policy_id"],
            high_water_before_digest=high_water_before_digest,
            high_water_after_digest=high_water_after_digest,
        )
        try:
            _reverify_policy_activation_chain(
                conn,
                attempt=attempt,
                approval=approval,
                approval_members=members,
                activation_revisions=activation_revisions,
                canary_revisions=canary_revisions,
                receipt=receipt,
                readiness=readiness,
            )
        except PolicyCandidateAuthorityError:
            abort = _abort_policy_activation_on_connection(
                conn,
                preparation=preparation,
                reason="trust_revoked",
                aborted_by=attempt["requested_by"],
                aborted_at_epoch_ns=now_epoch_ns,
            )
            return {
                "ok": False,
                "idempotent": False,
                "status": "aborted",
                **abort,
            }
        staged_approval = stage_policy_activation_approval(
            approval, members, _connection=conn
        )
        members = staged_approval["members"]
        consumed_approvers: set[str] = set()
        consumed_credentials: set[str] = set()
        current_approvals: list[Any] = []
        for member in members:
            approval_row = _control_plane_approval_row(
                conn,
                member["control_plane_approval_id"],
                for_update=True,
            )
            approver_id = member["approver_id"]
            credential_id = member[
                "approver_webauthn_credential_id"
            ]
            if (
                approval_row is None
                or approval_row["status"] != "approved"
                or approval_row["expires_at"] <= now_s
                or approval_row["requester_id"]
                != attempt["requested_by"]
                or approval_row["approved_by"] != approver_id
                or approval_row[
                    "approver_webauthn_credential_id"
                ] != credential_id
                or approver_id == attempt["requested_by"]
                or approver_id in consumed_approvers
                or credential_id in consumed_credentials
            ):
                abort = _abort_policy_activation_on_connection(
                    conn,
                    preparation=preparation,
                    reason="approval_revoked",
                    aborted_by=attempt["requested_by"],
                    aborted_at_epoch_ns=now_epoch_ns,
                )
                return {
                    "ok": False,
                    "idempotent": False,
                    "status": "aborted",
                    **abort,
                }
            if not _rbac_subject_has_any_role_on_connection(
                conn,
                attempt["requested_by"],
                set(_POLICY_CANDIDATE_ACTIVATION_REQUESTER_ROLES),
            ) or not _rbac_subject_has_any_role_on_connection(
                conn,
                approver_id,
                set(_POLICY_CANDIDATE_ACTIVATION_APPROVER_ROLES),
            ):
                abort = _abort_policy_activation_on_connection(
                    conn,
                    preparation=preparation,
                    reason="approval_revoked",
                    aborted_by=attempt["requested_by"],
                    aborted_at_epoch_ns=now_epoch_ns,
                )
                return {
                    "ok": False,
                    "idempotent": False,
                    "status": "aborted",
                    **abort,
                }
            try:
                _revalidate_policy_activation_assertion_ledger(
                    conn,
                    approval=staged_approval["approval"],
                    member=member,
                    control_plane_approval=approval_row,
                    verified_at=now,
                )
            except PolicyCandidateAuthorityError:
                abort = _abort_policy_activation_on_connection(
                    conn,
                    preparation=preparation,
                    reason="approval_revoked",
                    aborted_by=attempt["requested_by"],
                    aborted_at_epoch_ns=now_epoch_ns,
                )
                return {
                    "ok": False,
                    "idempotent": False,
                    "status": "aborted",
                    **abort,
                }
            consumed_approvers.add(approver_id)
            consumed_credentials.add(credential_id)
            current_approvals.append((member, approval_row))

        append_policy_activation_revision(
            activation_revisions[0], _connection=conn
        )
        append_policy_canary_revision(
            canary_revisions[0], _connection=conn
        )
        for member, approval_row in current_approvals:
            updated = conn.execute(
                "UPDATE control_plane_approvals SET status = 'consumed', "
                "consumed_by = ?, consumed_at = ? WHERE id = ? "
                "AND status = 'approved' AND action = ? "
                "AND resource_id = ? AND payload_digest = ? "
                "AND requester_id = ? AND approved_by = ? "
                "AND approver_webauthn_credential_id = ? "
                "AND expires_at > ?",
                (
                    consumption["consumed_by"],
                    consumption["consumed_at"],
                    member["control_plane_approval_id"],
                    _POLICY_CANDIDATE_ACTIVATION_ACTION,
                    attempt["canary_id"],
                    staged_approval["approval"][
                        "approval_context_digest"
                    ],
                    attempt["requested_by"],
                    member["approver_id"],
                    member["approver_webauthn_credential_id"],
                    now_s,
                ),
            )
            if updated.rowcount != 1:
                raise PolicyCandidateAuthorityConflictError(
                    "approval lost finalization consumption CAS"
                )
        _insert_immutable_candidate_row(
            conn,
            table="policy_activation_approval_consumptions",
            columns=_POLICY_ACTIVATION_CONSUMPTION_FIELDS,
            values=consumption,
            key_columns=("approval_id",),
        )
        if attempt["activation_mode"] == "authorized_rollback":
            rollback = conn.execute(
                "SELECT rollback_authorization_envelope_digest, "
                "expires_at_epoch_ns "
                "FROM policy_activation_rollback_authorities "
                "WHERE rollback_authorization_payload_digest = ?",
                (attempt["rollback_authorization_digest"],),
            ).fetchone()
            rollback_revocation = conn.execute(
                "SELECT revocation_payload_digest "
                "FROM policy_activation_rollback_authority_revocations "
                "WHERE rollback_authorization_payload_digest = ?",
                (attempt["rollback_authorization_digest"],),
            ).fetchone()
            if (
                rollback is None
                or rollback_revocation is not None
                or int(rollback["expires_at_epoch_ns"]) <= now_epoch_ns
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "reserved rollback authority is no longer live"
                )
            rollback_consumption_material = {
                "activationAttemptId": attempt["activation_attempt_id"],
                "approvalContextDigest":
                    attempt["approval_context_digest"],
                "consumedAtEpochNs": now_epoch_ns,
                "consumedBy": attempt["requested_by"],
                "expectedHighWaterDigest":
                    attempt["expected_high_water_digest"],
                "publicationRevision": attempt["publication_revision"],
                "readinessPayloadDigest":
                    attempt["readiness_payload_digest"],
                "rollbackAuthorizationPayloadDigest":
                    attempt["rollback_authorization_digest"],
                "webauthnChallengeContextDigest":
                    approval["webauthn_challenge_context_digest"],
            }
            rollback_consumption = {
                "rollback_authorization_payload_digest":
                    attempt["rollback_authorization_digest"],
                "rollback_authorization_envelope_digest":
                    rollback[
                        "rollback_authorization_envelope_digest"
                    ],
                "activation_attempt_id":
                    attempt["activation_attempt_id"],
                "readiness_payload_digest":
                    attempt["readiness_payload_digest"],
                "approval_context_digest":
                    attempt["approval_context_digest"],
                "webauthn_challenge_context_digest":
                    approval["webauthn_challenge_context_digest"],
                "expected_high_water_digest":
                    attempt["expected_high_water_digest"],
                "publication_revision":
                    attempt["publication_revision"],
                "consumed_by": attempt["requested_by"],
                "consumed_at_epoch_ns": now_epoch_ns,
                "consumption_digest":
                    _policy_authority_domain_digest(
                        b"serverware.policyRollbackConsumption/v1",
                        dumps(
                            rollback_consumption_material
                        ).encode("ascii"),
                    ),
            }
            _insert_immutable_candidate_row(
                conn,
                table="policy_activation_rollback_consumptions",
                columns=tuple(rollback_consumption),
                values=rollback_consumption,
                key_columns=(
                    "rollback_authorization_payload_digest",
                ),
            )
        append_policy_activation_revision(
            activation_revisions[1], _connection=conn
        )
        append_policy_activation_revision(
            activation_revisions[2], _connection=conn
        )
        staged_publication = stage_policy_publication(
            policy_id=receipt["policy_id"],
            sequence=attempt["candidate_policy_sequence"],
            rollback_epoch=attempt["candidate_rollback_epoch"],
            policy_hash=attempt["candidate_policy_hash"],
            _connection=conn,
        )
        if (
            staged_publication["previous_policy_hash"]
            != attempt["predecessor_policy_hash"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "publication predecessor changed during finalization"
            )
        advance_policy_high_water(
            policy_id=receipt["policy_id"],
            sequence=attempt["candidate_policy_sequence"],
            rollback_epoch=attempt["candidate_rollback_epoch"],
            policy_hash=attempt["candidate_policy_hash"],
            _connection=conn,
        )
        commit_policy_publication(
            policy_id=receipt["policy_id"],
            sequence=attempt["candidate_policy_sequence"],
            rollback_epoch=attempt["candidate_rollback_epoch"],
            policy_hash=attempt["candidate_policy_hash"],
            previous_policy_hash=attempt["predecessor_policy_hash"],
            _connection=conn,
        )
        committed_high_water = _policy_high_water_row(conn)
        if (
            _policy_candidate_high_water_digest(
                committed_high_water
            ) != high_water_after_digest
        ):
            raise PolicyCandidateAuthorityConflictError(
                "finalized high-water digest is not exact"
            )
        append_policy_activation_revision(
            activation_revisions[3], _connection=conn
        )
        verified_receipt = _verify_policy_authority_evidence(
            conn,
            evidence_kind="publication_receipt",
            envelope_json=receipt[
                "publication_receipt_envelope_json"
            ],
            envelope_digest=receipt[
                "publication_receipt_envelope_digest"
            ],
            payload_json=receipt[
                "publication_receipt_payload_json"
            ],
            payload_digest=receipt[
                "publication_receipt_payload_digest"
            ],
            signature_algorithm=receipt["signature_algorithm"],
            signing_key_id=receipt["signing_key_id"],
            signature=receipt["signature"],
            signature_digest=receipt["signature_digest"],
            record_binding=_candidate_authority_signed_record(
                receipt, current_prefix="publication_receipt"
            ),
        )
        _apply_policy_authority_verification(
            receipt, verified_receipt
        )
        receipt_transition = next(
            identity["transitionDigest"]
            for identity in inclusion_identities
            if identity["purpose"] == "publication_committed"
        )
        stored_receipt = {
            **receipt,
            "created_transition_digest": receipt_transition,
        }
        _insert_immutable_candidate_row(
            conn,
            table="policy_activation_publication_receipts",
            columns=tuple(stored_receipt),
            values=stored_receipt,
            key_columns=(
                "publication_receipt_envelope_digest",
            ),
        )
        append_policy_canary_revision(
            canary_revisions[1], _connection=conn
        )
        final_canary_head = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_ACTIVATION_CHAIN_CANARY_HEAD_COLUMNS
            )
            + " FROM policy_canary_heads WHERE canary_id = ?",
            (attempt["canary_id"],),
        ).fetchone()
        final_activation_head = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_ACTIVATION_CHAIN_ACTIVATION_HEAD_COLUMNS
            )
            + " FROM policy_activation_heads "
            "WHERE activation_attempt_id = ?",
            (attempt["activation_attempt_id"],),
        ).fetchone()
        committed_publication = _policy_publication_row(
            conn, attempt["candidate_policy_hash"]
        )
        if (
            committed_high_water is None
            or final_canary_head is None
            or final_activation_head is None
            or committed_publication is None
            or final_canary_head["status"] != "active"
            or final_activation_head["status"] != "committed"
            or int(
                final_activation_head["unresolved_indeterminate"]
            )
            != 0
            or committed_publication["status"] != "committed"
        ):
            raise PolicyCandidateAuthorityConflictError(
                "finalized activation heads are not exact"
            )
        finalized_authority_snapshot = {
            "schema":
                "serverware.policyActivationFinalizedAuthoritySnapshot/v1",
            "activation_attempt_id":
                attempt["activation_attempt_id"],
            "preparation_digest":
                preparation["preparation_digest"],
            "publication": {
                field: committed_publication[field]
                for field in
                _POLICY_ACTIVATION_CHAIN_PUBLICATION_COLUMNS
            },
            "high_water": {
                field: committed_high_water[field]
                for field in
                _POLICY_ACTIVATION_CHAIN_HIGH_WATER_COLUMNS
            },
            "canary_head": {
                field: final_canary_head[field]
                for field in
                _POLICY_ACTIVATION_CHAIN_CANARY_HEAD_COLUMNS
            },
            "activation_head": {
                field: final_activation_head[field]
                for field in
                _POLICY_ACTIVATION_CHAIN_ACTIVATION_HEAD_COLUMNS
            },
        }
        finalized_authority_snapshot_json = dumps(
            finalized_authority_snapshot
        )
        finalized_authority_snapshot_digest = (
            _policy_authority_domain_digest(
                b"serverware.policyActivationFinalizedAuthoritySnapshot/v1",
                finalized_authority_snapshot_json.encode("ascii"),
            )
        )
        finalization_material = {
            "activationAttemptId": attempt["activation_attempt_id"],
            "finalizedAuthoritySnapshotDigest":
                finalized_authority_snapshot_digest,
            "finalizedAtEpochNs": now_epoch_ns,
            "highWaterAfterDigest": high_water_after_digest,
            "inclusionIdentitySetDigest":
                inclusion_identity_set_digest,
            "preparationDigest": preparation["preparation_digest"],
            "preparationInputDigest":
                preparation["preparation_input_digest"],
            "publicationReceiptPayloadDigest":
                receipt["publication_receipt_payload_digest"],
        }
        finalization_digest = _policy_authority_domain_digest(
            b"serverware.policyActivationFinalization/v1",
            dumps(finalization_material).encode("ascii"),
        )
        finalization = {
            "preparation_digest": preparation["preparation_digest"],
            "activation_attempt_id":
                attempt["activation_attempt_id"],
            "preparation_input_digest":
                preparation["preparation_input_digest"],
            "inclusion_identity_set_json":
                inclusion_identity_set_json,
            "inclusion_identity_set_digest":
                inclusion_identity_set_digest,
            "publication_receipt_payload_digest":
                receipt["publication_receipt_payload_digest"],
            "high_water_after_digest": high_water_after_digest,
            "finalized_authority_snapshot_json":
                finalized_authority_snapshot_json,
            "finalized_authority_snapshot_digest":
                finalized_authority_snapshot_digest,
            "finalization_digest": finalization_digest,
            "finalized_at_epoch_ns": now_epoch_ns,
        }
        _insert_immutable_candidate_row(
            conn,
            table="policy_activation_finalizations",
            columns=tuple(finalization),
            values=finalization,
            key_columns=("preparation_digest",),
        )
        _freeze_policy_activation_export_at_finalization(
            conn,
            activation_attempt_id=attempt["activation_attempt_id"],
            finalized_at_epoch_ns=now_epoch_ns,
        )
    return {
        "ok": True,
        "idempotent": False,
        "status": "committed",
        **finalization,
    }


def _policy_authority_immutable_row(
    row: Any | None,
) -> Mapping[str, Any] | None:
    if row is None:
        return None
    copied = dict(row)
    encoded = dumps(copied).encode("utf-8")
    if len(encoded) > _POLICY_AUTHORITY_READ_MAX_JSON_BYTES:
        raise PolicyCandidateAuthorityError(
            "policy-authority read exceeded its immutable row byte limit"
        )
    return _policy_authority_freeze(copied)


def _policy_authority_freeze(value: Any) -> Any:
    if isinstance(value, Mapping):
        return MappingProxyType(
            {
                key: _policy_authority_freeze(member)
                for key, member in value.items()
            }
        )
    if isinstance(value, list):
        return tuple(_policy_authority_freeze(member) for member in value)
    if isinstance(value, tuple):
        return tuple(_policy_authority_freeze(member) for member in value)
    return value


