def _policy_authority_projection(
    columns: tuple[str, ...],
    *,
    alias: str | None = None,
) -> str:
    if len(set(columns)) != len(columns):
        raise PolicyCandidateAuthorityError(
            "policy-authority read projection contains duplicate columns"
        )
    prefix = (
        _policy_candidate_authority_identifier(alias) + "."
        if alias is not None
        else ""
    )
    return ", ".join(
        prefix + _policy_candidate_authority_identifier(column)
        for column in columns
    )


@contextlib.contextmanager
def _policy_authority_read_snapshot() -> Any:
    with connect() as conn:
        if isinstance(conn, PostgresMetadataConnection):
            conn.raw_connection.commit()
            conn.execute(
                "BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY"
            )
            conn.execute(
                "SET LOCAL lock_timeout = '"
                + _POLICY_AUTHORITY_OWNER_LOCK_TIMEOUT
                + "'"
            )
            conn.execute(
                "SET LOCAL statement_timeout = '"
                + _POLICY_AUTHORITY_OWNER_STATEMENT_TIMEOUT
                + "'"
            )
        elif not conn.in_transaction:
            conn.execute("BEGIN")
        yield conn


def _policy_authority_read_rows(
    rows: list[Any],
    *,
    maximum_rows: int,
    budget: dict[str, int],
) -> list[dict[str, Any]]:
    if len(rows) > maximum_rows:
        raise PolicyCandidateAuthorityError(
            "policy-authority read exceeded its fixed row limit"
        )
    result: list[dict[str, Any]] = []
    for row in rows:
        copied = dict(row)
        budget["rows"] += 1
        budget["bytes"] += len(dumps(copied).encode("utf-8"))
        if (
            budget["rows"]
            > budget.get(
                "maximum_rows", _POLICY_AUTHORITY_READ_MAX_ROWS
            )
            or budget["bytes"] > _POLICY_AUTHORITY_READ_MAX_JSON_BYTES
        ):
            raise PolicyCandidateAuthorityError(
                "policy-authority read exceeded its shared budget"
            )
        result.append(copied)
    return result


def _policy_authority_read_one(
    conn: Any,
    *,
    sql: str,
    params: tuple[Any, ...],
    budget: dict[str, int],
) -> dict[str, Any] | None:
    rows = _policy_authority_read_rows(
        conn.execute(sql + " LIMIT 2", params).fetchall(),
        maximum_rows=1,
        budget=budget,
    )
    return rows[0] if rows else None


def _policy_authority_read_many(
    conn: Any,
    *,
    table: str,
    columns: tuple[str, ...],
    where_sql: str,
    params: tuple[Any, ...],
    order_by: tuple[str, ...],
    maximum_rows: int,
    budget: dict[str, int],
) -> list[dict[str, Any]]:
    if not 1 <= maximum_rows <= _POLICY_AUTHORITY_READ_MAX_ROWS:
        raise PolicyCandidateAuthorityError(
            "policy-authority multi-row bound is invalid"
        )
    sql = (
        "SELECT "
        + _policy_authority_projection(columns)
        + " FROM "
        + _policy_candidate_authority_identifier(table)
        + " WHERE "
        + where_sql
        + " ORDER BY "
        + ", ".join(
            _policy_candidate_authority_identifier(column)
            for column in order_by
        )
        + " LIMIT ?"
    )
    return _policy_authority_read_rows(
        conn.execute(
            sql, params + (maximum_rows + 1,)
        ).fetchall(),
        maximum_rows=maximum_rows,
        budget=budget,
    )


_POLICY_CANARY_EVIDENCE_STAGERS = MappingProxyType(
    {
        "assignment": stage_policy_canary_assignment,
        "canary-revision": append_policy_canary_revision,
        "load-receipt": stage_policy_canary_load_receipt,
        "runtime-attestation-handoff":
            stage_policy_shadow_runtime_attestation_handoff,
        "custody": stage_policy_canary_custody_evidence,
        "ingress": stage_policy_canary_ingress_observation,
        "active-decision": stage_policy_canary_active_decision,
        "shadow-observation": stage_policy_canary_shadow_observation,
        "instance-revision": append_policy_canary_instance_revision,
        "checkpoint": stage_policy_canary_checkpoint,
        "compiler-analysis": stage_policy_compiler_authority_analysis,
        "readiness": stage_policy_canary_readiness,
    }
)


def _policy_canary_evidence_result_summary(
    kind: str,
    result: Mapping[str, Any],
) -> Mapping[str, Any]:
    retained = {
        key: value
        for key, value in result.items()
        if key
        in {
            "canary_id",
            "instance_id",
            "boot_id",
            "status",
            "revision",
            "assignment_envelope_digest",
            "load_receipt_envelope_digest",
            "runtime_attestation_handoff_digest",
            "custody_evidence_envelope_digest",
            "ingress_envelope_digest",
            "active_decision_envelope_digest",
            "shadow_envelope_digest",
            "checkpoint_envelope_digest",
            "analysis_envelope_digest",
            "readiness_envelope_digest",
            "readiness_payload_digest",
            "created_transition_digest",
            "transition_digest",
        }
    }
    return _policy_authority_freeze({"kind": kind, **retained})


def stage_policy_canary_evidence_batch(
    events: list[Mapping[str, Any]],
    *,
    expected_canary_id: str,
    authenticated_instance_id: str,
) -> tuple[Mapping[str, Any], ...]:
    """Atomically admit one bounded ordered batch of signed canary evidence."""
    expected_canary_id = _candidate_authority_text(
        "expected canary_id", expected_canary_id, maximum=256
    )
    authenticated_instance_id = _candidate_authority_text(
        "authenticated instance_id",
        authenticated_instance_id,
        maximum=256,
    )
    if (
        not isinstance(events, list)
        or not 1 <= len(events) <= 128
    ):
        raise PolicyCandidateAuthorityError(
            "policy canary evidence batch must contain 1-128 records"
        )
    normalized: list[tuple[str, dict[str, Any]]] = []
    identities: set[tuple[str, str]] = set()
    for index, event in enumerate(events):
        if (
            not isinstance(event, Mapping)
            or set(event) != {"kind", "record"}
            or event.get("kind") not in _POLICY_CANARY_EVIDENCE_STAGERS
            or not isinstance(event.get("record"), Mapping)
        ):
            raise PolicyCandidateAuthorityError(
                f"policy canary evidence item {index} is not closed"
            )
        kind = str(event["kind"])
        record = dict(event["record"])
        if record.get("canary_id") != expected_canary_id:
            raise PolicyCandidateAuthorityConflictError(
                "policy canary evidence changed its expected canary"
            )
        instance_id = record.get("instance_id")
        if (
            instance_id is not None
            and instance_id != authenticated_instance_id
        ):
            raise PolicyCandidateAuthorityConflictError(
                "policy canary evidence is not from the authenticated instance"
            )
        if (
            kind == "runtime-attestation-handoff"
            and record.get("actor_id") != authenticated_instance_id
        ):
            raise PolicyCandidateAuthorityConflictError(
                "runtime-attestation handoff actor is not authenticated"
            )
        identity_material = dumps(record)
        identity = (
            kind,
            _candidate_authority_sha256(identity_material.encode("ascii")),
        )
        if identity in identities:
            raise PolicyCandidateAuthorityError(
                "policy canary evidence batch contains a duplicate record"
            )
        identities.add(identity)
        normalized.append((kind, record))

    results: list[Mapping[str, Any]] = []
    with connect() as conn:
        _lock_policy_candidate_authority(conn)
        for kind, record in normalized:
            staged = _POLICY_CANARY_EVIDENCE_STAGERS[kind](
                record,
                _connection=conn,
            )
            results.append(
                _policy_canary_evidence_result_summary(kind, staged)
            )
    return tuple(results)


def get_policy_candidate_artifact(
    *,
    candidate_id: str | None = None,
    artifact_envelope_digest: str | None = None,
) -> Mapping[str, Any] | None:
    if (candidate_id is None) == (artifact_envelope_digest is None):
        raise PolicyCandidateAuthorityError(
            "exactly one candidate artifact identifier is required"
        )
    if candidate_id is not None:
        candidate_id = _candidate_authority_text(
            "candidate_id", candidate_id, maximum=256
        )
        sql = (
            "SELECT "
            + _policy_authority_projection(
                _POLICY_CANDIDATE_ARTIFACT_READ_COLUMNS
            )
            + " FROM policy_candidate_artifacts WHERE candidate_id = ?"
        )
        value = candidate_id
    else:
        value = _candidate_authority_digest(
            "artifact_envelope_digest", artifact_envelope_digest
        )
        sql = (
            "SELECT "
            + _policy_authority_projection(
                _POLICY_CANDIDATE_ARTIFACT_READ_COLUMNS
            )
            + " FROM policy_candidate_artifacts "
            "WHERE artifact_envelope_digest = ?"
        )
    budget = {"rows": 0, "bytes": 0}
    with _policy_authority_read_snapshot() as conn:
        row = _policy_authority_read_one(
            conn, sql=sql, params=(value,), budget=budget
        )
    return _policy_authority_immutable_row(row)


