def get_policy_shadow_generation_trust_context(
    *,
    canary_id: str,
    instance_id: str,
    boot_id: str,
    runtime_attestation_handoff_digest: str | None = None,
) -> Mapping[str, Any]:
    identity = tuple(
        _candidate_authority_text(label, value, maximum=256)
        for label, value in (
            ("canary_id", canary_id),
            ("instance_id", instance_id),
            ("boot_id", boot_id),
        )
    )
    expected_handoff_digest = (
        _candidate_authority_digest(
            "runtime_attestation_handoff_digest",
            runtime_attestation_handoff_digest,
        )
        if runtime_attestation_handoff_digest is not None
        else None
    )
    with _policy_authority_read_snapshot() as conn:
        handoff = conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_SHADOW_RUNTIME_ATTESTATION_HANDOFF_COLUMNS
            )
            + " FROM policy_shadow_runtime_attestation_handoffs "
            "WHERE canary_id = ? AND instance_id = ? AND boot_id = ?"
            + (
                " AND runtime_attestation_handoff_digest = ?"
                if expected_handoff_digest is not None
                else ""
            ),
            (
                identity + (expected_handoff_digest,)
                if expected_handoff_digest is not None
                else identity
            ),
        ).fetchone()
        if handoff is None:
            raise PolicyCandidateAuthorityConflictError(
                "durable runtime-attestation handoff is unavailable"
            )
        handoff = dict(handoff)
        verified = _verify_policy_shadow_runtime_attestation_handoff(
            conn,
            handoff_json=handoff["runtime_attestation_handoff_json"],
            canary_id=identity[0],
            instance_id=identity[1],
            boot_id=identity[2],
            candidate_id=handoff["candidate_id"],
            stored=handoff,
            require_current=True,
        )
        context = verified["context"]
        attestation = verified["attestation"]
        shadow_key = verified["shadow_key"]
        key_binding = _policy_shadow_generation_publication_key_binding(
            conn,
            assignment_envelope_digest=
                context["assignment_envelope_digest"],
            member_ordinal=int(context["member_ordinal"]),
            signing_key_id=shadow_key["signing_key_id"],
            verified_public_key_digest=shadow_key["public_key_digest"],
        )
        exact = {
            "runtime_attestation_handoff_digest":
                verified["handoff_digest"],
            "assignment_envelope_digest":
                context["assignment_envelope_digest"],
            "assignment_payload_digest":
                context["assignment_payload_digest"],
            "assignment_revision": context["assignment_revision"],
            "load_receipt_envelope_digest":
                context["load_receipt_envelope_digest"],
            "load_receipt_payload_digest":
                context["load_receipt_payload_digest"],
            "receipt_envelope_digest":
                verified["handoff"]["receiptSha256"],
            "receipt_payload_digest":
                verified["handoff"]["receiptPayloadSha256"],
            "role_authorization_envelope_digest":
                verified["handoff"]["roleAuthorizationSha256"],
            "role_authorization_payload_digest":
                verified["handoff"][
                    "roleAuthorizationPayloadSha256"
                ],
            "attestation_chain_digest":
                verified["handoff"]["chainSha256"],
            "runtime_identity_digest":
                verified["runtime_identity_digest"],
            "runtime_executable_digest":
                verified["role_record"]["runtimeExecutableSha256"],
            "shadow_signing_key_id": shadow_key["signing_key_id"],
            "shadow_signing_key_spki_digest":
                shadow_key["public_key_digest"],
            "shadow_role_key_authorization_digest":
                shadow_key["authorization_digest"],
            "tee_measurement_digest":
                attestation["tee_measurement_digest"],
        }
        if any(handoff[field] != value for field, value in exact.items()):
            raise PolicyCandidateAuthorityConflictError(
                "durable runtime-attestation handoff projection changed"
            )
        result = {
            "runtime_attestation_handoff_digest":
                handoff["runtime_attestation_handoff_digest"],
            "candidate_id": handoff["candidate_id"],
            "assignment_envelope_digest":
                context["assignment_envelope_digest"],
            "assignment_payload_digest":
                context["assignment_payload_digest"],
            "load_receipt_envelope_digest":
                context["load_receipt_envelope_digest"],
            "load_receipt_payload_digest":
                context["load_receipt_payload_digest"],
            "attestation_evidence_digest":
                attestation["tee_evidence_digest"],
            "attestation_mode": handoff["attestation_evidence_type"],
            "attestation_role_authorization_digest":
                handoff["role_authorization_envelope_digest"],
            "runtime_attestation_receipt_payload_digest":
                attestation["attestation_receipt_payload_digest"],
            "runtime_attestation_receipt_envelope_digest":
                attestation["attestation_receipt_envelope_digest"],
            "runtime_attestation_verification_receipt_digest":
                attestation["verification_receipt_digest"],
            "runtime_attestation_json":
                handoff["runtime_attestation_handoff_json"],
            "runtime_attestation_chain_digest":
                handoff["attestation_chain_digest"],
            "runtime_executable_digest":
                handoff["runtime_executable_digest"],
            "runtime_release_digest":
                handoff["runtime_release_digest"],
            "runtime_config_digest":
                handoff["runtime_config_digest"],
            "runtime_policy_digest":
                handoff["runtime_policy_digest"],
            "attestation_policy_digest":
                handoff["attestation_policy_digest"],
            "attestation_trust_checkpoint_digest":
                handoff["attestation_trust_checkpoint_digest"],
            "signing_key_spki_digest":
                key_binding["public_key_digest"],
            "tee_measurement_digest":
                attestation["tee_measurement_digest"],
        }
    frozen = _policy_authority_immutable_row(result)
    if frozen is None:
        raise PolicyCandidateAuthorityError(
            "policy-shadow publication signer trust disappeared"
        )
    return frozen


