def get_policy_shadow_generation_publication_by_request(
    *,
    request_id: str,
    replay_id: str,
    management_handoff_id: str,
    request_payload_digest: str,
) -> Mapping[str, Any] | None:
    request_id = _candidate_authority_text(
        "generation publication request_id",
        request_id,
        maximum=36,
    )
    if re.fullmatch(
        r"[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-"
        r"[89ab][0-9a-f]{3}-[0-9a-f]{12}",
        request_id,
    ) is None:
        raise PolicyCandidateAuthorityError(
            "generation publication request ID is not a lowercase UUIDv4"
        )
    request_payload_digest = _candidate_authority_digest(
        "generation publication request payload digest",
        request_payload_digest,
    )
    replay_id = _candidate_authority_text(
        "generation publication replay ID", replay_id, maximum=256
    )
    management_handoff_id = _candidate_authority_text(
        "generation publication management handoff ID",
        management_handoff_id,
        maximum=256,
    )
    budget = {"rows": 0, "bytes": 0}
    with _policy_authority_read_snapshot() as conn:
        row = _policy_authority_read_one(
            conn,
            sql=(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_SHADOW_GENERATION_PUBLICATION_COLUMNS
                )
                + " FROM policy_shadow_generation_publications "
                "WHERE request_id = ? AND replay_id = ? "
                "AND management_handoff_id = ? "
                "AND request_payload_digest = ?"
            ),
            params=(
                request_id,
                replay_id,
                management_handoff_id,
                request_payload_digest,
            ),
            budget=budget,
        )
        if row is not None:
            _reverify_policy_shadow_generation_publication(conn, dict(row))
    return _policy_authority_immutable_row(row)


