def get_policy_shadow_activation_material(
    *,
    canary_id: str,
    generation_id: str,
) -> Mapping[str, Any] | None:
    """Read one closed, immutable fleet activation input from one snapshot."""
    _require_postgres_policy_authority(
        "secure policy-shadow generation activation read"
    )
    canary_id = _candidate_authority_text(
        "activation canary_id", canary_id, maximum=256
    )
    generation_id = _candidate_authority_digest(
        "activation generation_id", generation_id
    )
    budget = {
        "rows": 0,
        "bytes": 0,
        "maximum_rows": _POLICY_AUTHORITY_READ_MAX_ROWS * 5,
    }
    with _policy_authority_read_snapshot() as conn:
        generation = _policy_authority_read_one(
            conn,
            sql=(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_SHADOW_GENERATION_PUBLICATION_COLUMNS
                )
                + " FROM policy_shadow_generation_publications "
                "WHERE canary_id = ? AND generation_id_digest = ?"
            ),
            params=(canary_id, generation_id),
            budget=budget,
        )
        if generation is None:
            return None
        _reverify_policy_shadow_generation_publication(
            conn, dict(generation)
        )
        assignment = _policy_authority_read_one(
            conn,
            sql=(
                "SELECT assignment_envelope_digest, "
                "assignment_payload_digest, assignment_revision, "
                "assignment_envelope_json, expected_instance_count "
                "FROM policy_canary_assignments WHERE canary_id = ?"
            ),
            params=(canary_id,),
            budget=budget,
        )
        readiness = _policy_authority_read_one(
            conn,
            sql=(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_CANARY_READINESS_READ_COLUMNS
                )
                + " FROM policy_canary_readiness WHERE canary_id = ?"
            ),
            params=(canary_id,),
            budget=budget,
        )
        if assignment is None or readiness is None:
            raise PolicyCandidateAuthorityConflictError(
                "activation assignment or readiness is not durable"
            )
        analysis = _policy_authority_read_one(
            conn,
            sql=(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_COMPILER_ANALYSIS_READ_COLUMNS
                )
                + " FROM policy_compiler_authority_analyses "
                "WHERE analysis_envelope_digest = ?"
            ),
            params=(readiness["compiler_analysis_envelope_digest"],),
            budget=budget,
        )
        expected = int(assignment["expected_instance_count"])
        if (
            analysis is None
            or expected < 1
            or expected > _POLICY_AUTHORITY_READ_MAX_ROWS
            or readiness["status"] != "ready"
            or readiness["assignment_envelope_digest"]
            != assignment["assignment_envelope_digest"]
            or generation["assignment_envelope_digest"]
            != assignment["assignment_envelope_digest"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation authority analysis, readiness, or assignment diverged"
            )
        limit = _POLICY_AUTHORITY_READ_MAX_ROWS + 1
        load_rows = _policy_authority_read_rows(
            conn.execute(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_CANARY_LOAD_RECEIPT_READ_COLUMNS
                )
                + " FROM policy_canary_load_receipts WHERE canary_id = ? "
                "ORDER BY member_ordinal LIMIT ?",
                (canary_id, limit),
            ).fetchall(),
            maximum_rows=_POLICY_AUTHORITY_READ_MAX_ROWS,
            budget=budget,
        )
        handoffs = _policy_authority_read_rows(
            conn.execute(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_SHADOW_RUNTIME_ATTESTATION_HANDOFF_COLUMNS
                )
                + " FROM policy_shadow_runtime_attestation_handoffs "
                "WHERE canary_id = ? ORDER BY instance_id, boot_id LIMIT ?",
                (canary_id, limit),
            ).fetchall(),
            maximum_rows=_POLICY_AUTHORITY_READ_MAX_ROWS,
            budget=budget,
        )
        publications = _policy_authority_read_rows(
            conn.execute(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_SHADOW_GENERATION_PUBLICATION_COLUMNS
                )
                + " FROM policy_shadow_generation_publications "
                "WHERE canary_id = ? ORDER BY member_ordinal LIMIT ?",
                (canary_id, limit),
            ).fetchall(),
            maximum_rows=_POLICY_AUTHORITY_READ_MAX_ROWS,
            budget=budget,
        )
        checkpoints = _policy_authority_read_rows(
            conn.execute(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_CANARY_CHECKPOINT_READ_COLUMNS
                )
                + " FROM policy_canary_checkpoints WHERE canary_id = ? "
                "ORDER BY member_ordinal, checkpoint_sequence LIMIT ?",
                (canary_id, limit),
            ).fetchall(),
            maximum_rows=_POLICY_AUTHORITY_READ_MAX_ROWS,
            budget=budget,
        )
        for publication in publications:
            _reverify_policy_shadow_generation_publication(
                conn, dict(publication)
            )

    def identity(row: Mapping[str, Any]) -> tuple[str, str]:
        return (str(row["instance_id"]), str(row["boot_id"]))

    loads_by_identity = {identity(row): dict(row) for row in load_rows}
    handoffs_by_identity = {identity(row): dict(row) for row in handoffs}
    publications_by_identity = {
        identity(row): dict(row) for row in publications
    }
    checkpoints_by_identity: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for checkpoint in checkpoints:
        checkpoints_by_identity.setdefault(identity(checkpoint), []).append(
            dict(checkpoint)
        )
    identities = tuple(
        sorted(loads_by_identity, key=lambda key: key[0])
    )
    if (
        len(identities) != expected
        or set(identities) != set(handoffs_by_identity)
        or set(identities) != set(publications_by_identity)
        or set(identities) != set(checkpoints_by_identity)
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation member evidence is incomplete or ambiguous"
        )
    members: list[dict[str, Any]] = []
    for member_identity in identities:
        load = loads_by_identity[member_identity]
        handoff = handoffs_by_identity[member_identity]
        publication = publications_by_identity[member_identity]
        chain = checkpoints_by_identity[member_identity]
        if (
            load["assignment_envelope_digest"]
            != assignment["assignment_envelope_digest"]
            or handoff["assignment_envelope_digest"]
            != assignment["assignment_envelope_digest"]
            or publication["assignment_envelope_digest"]
            != assignment["assignment_envelope_digest"]
            or handoff["load_receipt_envelope_digest"]
            != load["load_receipt_envelope_digest"]
            or publication["load_receipt_envelope_digest"]
            != load["load_receipt_envelope_digest"]
            or not chain
            or [int(row["checkpoint_sequence"]) for row in chain]
            != list(range(1, len(chain) + 1))
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation member chain is not exact and contiguous"
            )
        members.append(
            {
                "instance_id": load["instance_id"],
                "boot_id": load["boot_id"],
                "load_receipt": loads(
                    load["load_receipt_envelope_json"], None
                ),
                "runtime_attestation": loads(
                    handoff["runtime_attestation_handoff_json"], None
                ),
                "runtime_attestation_verification": loads(
                    publication[
                        "runtime_attestation_verification_envelope_json"
                    ],
                    None,
                ),
                "checkpoints": [
                    loads(row["checkpoint_envelope_json"], None)
                    for row in chain
                ],
            }
        )
    result = {
        "canary_id": canary_id,
        "candidate_id": generation["candidate_id"],
        "generation_id": generation_id,
        "generation_publication_envelope_digest":
            generation["generation_publication_envelope_digest"],
        "generation_publication_envelope_json":
            generation["generation_publication_envelope_json"],
        "policy_authority_analysis": loads(
            analysis["analysis_envelope_json"], None
        ),
        "readiness": loads(readiness["readiness_envelope_json"], None),
        "readiness_record": dict(readiness),
        "generation_record": dict(generation),
        "members": members,
    }
    frozen = _policy_authority_immutable_row(result)
    if frozen is None:
        raise PolicyCandidateAuthorityError(
            "activation material disappeared after snapshot read"
        )
    return frozen


_POLICY_SHADOW_ACTIVATION_PUBLICATION_FIELDS = frozenset(
    {
        "request_id",
        "replay_id",
        "request_digest",
        "request_json",
        "response_digest",
        "response_json",
        "canary_id",
        "candidate_id",
        "generation_id_digest",
        "generation_publication_envelope_digest",
        "activation_publication_envelope_digest",
        "runtime_attestation_verifier_envelope_digest",
        "decision_gate_binding_digest",
        "decision_gate_binding_json",
        "decision_gate_statement_digest",
        "decision_gate_statement_json",
        "evidence_chain_digest",
        "external_evidence_status",
        "trusted_at_epoch_ns",
        "expires_at_epoch_ns",
        "actor_id",
        "created_at_epoch_ns",
    }
)


def stage_policy_shadow_generation_activation_publication(
    record: Mapping[str, Any],
) -> Mapping[str, Any]:
    """Persist exact verified Rust activation bytes for external verification."""
    item = _candidate_authority_record(
        "policy-shadow generation activation publication",
        record,
        _POLICY_SHADOW_ACTIVATION_PUBLICATION_FIELDS,
    )
    for field in (
        "request_digest",
        "response_digest",
        "generation_id_digest",
        "generation_publication_envelope_digest",
        "activation_publication_envelope_digest",
        "runtime_attestation_verifier_envelope_digest",
        "decision_gate_binding_digest",
        "decision_gate_statement_digest",
        "evidence_chain_digest",
    ):
        item[field] = _candidate_authority_digest(field, item[field])
    for field, maximum in (
        ("request_id", 256),
        ("replay_id", 256),
        ("canary_id", 256),
        ("candidate_id", 256),
        ("actor_id", 1024),
    ):
        item[field] = _candidate_authority_text(field, item[field], maximum=maximum)
    if item["request_id"] == item["replay_id"]:
        raise PolicyCandidateAuthorityError(
            "activation request and replay identities must be independent"
        )
    for field, minimum in (
        ("trusted_at_epoch_ns", 1),
        ("expires_at_epoch_ns", 1),
        ("created_at_epoch_ns", 1),
    ):
        item[field] = _candidate_authority_int(
            field, item[field], minimum=minimum
        )
    if (
        item["external_evidence_status"] not in {
            "awaiting-external-verifier",
            "non-production-trusted-host",
        }
        or item["expires_at_epoch_ns"] <= item["trusted_at_epoch_ns"]
        or item["created_at_epoch_ns"] < item["trusted_at_epoch_ns"]
    ):
        raise PolicyCandidateAuthorityError(
            "activation publication verification state or time is invalid"
        )
    request_json, request_digest = _candidate_authority_json(
        "activation request",
        item["request_json"],
        item["request_digest"],
        maximum=16 * 1024 * 1024,
    )
    response_json, response_digest = _candidate_authority_json(
        "activation response",
        item["response_json"],
        item["response_digest"],
        maximum=16 * 1024 * 1024,
    )
    binding = loads(item["decision_gate_binding_json"], None)
    statement = loads(item["decision_gate_statement_json"], None)
    if not isinstance(binding, dict) or not isinstance(statement, dict):
        raise PolicyCandidateAuthorityError(
            "decision-gate activation evidence is not JSON objects"
        )
    binding_json, _ = _candidate_authority_canonical_value(
        "decision-gate activation binding",
        binding,
        maximum=4 * 1024 * 1024,
    )
    statement_json, _ = _candidate_authority_canonical_value(
        "decision-gate activation statement",
        statement,
        maximum=16 * 1024 * 1024,
    )
    if (
        binding_json != item["decision_gate_binding_json"]
        or statement_json != item["decision_gate_statement_json"]
    ):
        raise PolicyCandidateAuthorityError(
            "decision-gate activation evidence is not canonical JSON"
        )
    if (
        request_digest != item["request_digest"]
        or response_digest != item["response_digest"]
        or _policy_authority_domain_digest(
            b"serverware.policyAuthorityDecisionGatePublicationBinding/v1",
            binding_json.encode("ascii"),
        )
        != item["decision_gate_binding_digest"]
        or _policy_authority_domain_digest(
            b"serverware.policyAuthorityExternalEvidenceStatement/v1",
            statement_json.encode("ascii"),
        )
        != item["decision_gate_statement_digest"]
        or any(statement.get(field) != value for field, value in binding.items())
        or statement.get("schema")
        != "serverware.policyAuthorityDecisionGatePublicationChain/v1"
        or statement.get("evidenceChainDigest")
        != item["evidence_chain_digest"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation publication statement or binding digest is not exact"
        )
    item["request_json"] = request_json
    item["response_json"] = response_json
    item["decision_gate_binding_json"] = binding_json
    item["decision_gate_statement_json"] = statement_json
    with connect() as conn:
        _lock_policy_candidate_authority(conn)
        generation = conn.execute(
            "SELECT candidate_id, canary_id, generation_id_digest, "
            "generation_publication_envelope_digest "
            "FROM policy_shadow_generation_publications "
            "WHERE generation_id_digest = ?",
            (item["generation_id_digest"],),
        ).fetchone()
        if generation is None or any(
            generation[field] != item[field]
            for field in (
                "candidate_id",
                "canary_id",
                "generation_id_digest",
                "generation_publication_envelope_digest",
            )
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation publication changed its durable generation"
            )
        rows = conn.execute(
            "SELECT * FROM policy_shadow_generation_activation_publications "
            "WHERE request_id = ? OR replay_id = ? OR request_digest = ? "
            "OR generation_id_digest = ? OR response_digest = ? LIMIT 2",
            (
                item["request_id"],
                item["replay_id"],
                item["request_digest"],
                item["generation_id_digest"],
                item["response_digest"],
            ),
        ).fetchall()
        if rows:
            if len(rows) != 1 or dict(rows[0]) != item:
                raise PolicyCandidateAuthorityConflictError(
                    "activation replay identity was reused for divergent bytes"
                )
            return _policy_authority_freeze(dict(rows[0]))
        _insert_immutable_candidate_row(
            conn,
            table="policy_shadow_generation_activation_publications",
            columns=tuple(sorted(item)),
            values=item,
            key_columns=("request_id",),
        )
    return _policy_authority_freeze(item)


def get_policy_shadow_generation_activation_publication(
    *, generation_id: str
) -> Mapping[str, Any] | None:
    generation_id = _candidate_authority_digest(
        "activation generation_id", generation_id
    )
    with _policy_authority_read_snapshot() as conn:
        row = conn.execute(
            "SELECT * FROM policy_shadow_generation_activation_publications "
            "WHERE generation_id_digest = ? LIMIT 2",
            (generation_id,),
        ).fetchall()
    if len(row) > 1:
        raise PolicyCandidateAuthorityConflictError(
            "activation generation resolves to multiple publications"
        )
    return _policy_authority_immutable_row(dict(row[0])) if row else None


def get_verified_policy_authority_external_evidence(
    *,
    evidence_digest: str,
    evidence_type: str,
    binding_digest: str,
    statement_digest: str,
) -> Mapping[str, Any] | None:
    """Read an exact receipt admitted by the native external-evidence authority."""
    evidence_digest = _candidate_authority_digest(
        "external evidence receipt digest", evidence_digest
    )
    binding_digest = _candidate_authority_digest(
        "external evidence binding digest", binding_digest
    )
    statement_digest = _candidate_authority_digest(
        "external evidence statement digest", statement_digest
    )
    evidence_type = _candidate_authority_text(
        "external evidence type", evidence_type, maximum=128
    )
    with connect() as conn:
        rows = conn.execute(
            "SELECT * FROM policy_authority_external_evidence_receipts "
            "WHERE evidence_digest = ? LIMIT 2",
            (evidence_digest,),
        ).fetchall()
        database_now_epoch_ns = int(
            _metadata_utcnow(conn).timestamp() * 1_000_000_000
        )
    if not rows:
        return None
    if len(rows) != 1:
        raise PolicyCandidateAuthorityConflictError(
            "external evidence receipt identity is ambiguous"
        )
    row = dict(rows[0])
    statement = loads(row["statement_json"], None)
    statement_json, _ = _candidate_authority_canonical_value(
        "external evidence statement", statement, maximum=4 * 1024 * 1024
    )
    signature = _candidate_authority_text(
        "external evidence signature",
        row["signature_base64url"],
        maximum=4 * 1024 * 1024,
    )
    signature_digest = _policy_authority_domain_digest(
        b"serverware.policyAuthorityExternalEvidenceSignature/v1",
        b"Ed25519",
        signature.encode("ascii"),
    )
    receipt_material = {
        "schema": "serverware.policyAuthorityExternalEvidenceReceipt/v1",
        "bindingDigest": binding_digest,
        "evidenceType": evidence_type,
        "expiresAtEpochNs": row["expires_at_epoch_ns"],
        "signatureAlgorithm": "Ed25519",
        "signatureDigest": signature_digest,
        "sourceRevision": _POLICY_CANDIDATE_AUTHORITY_SOURCE_REVISION,
        "statementDigest": statement_digest,
        "verifiedAtEpochNs": row["verified_at_epoch_ns"],
        "verifierAttestationReceiptDigest":
            row["verifier_attestation_receipt_digest"],
        "verifierIdentityDigest": row["verifier_identity_digest"],
        "verifierMeasurementDigest": row["verifier_measurement_digest"],
    }
    if (
        statement_json != row["statement_json"]
        or row["evidence_type"] != evidence_type
        or row["binding_digest"] != binding_digest
        or row["statement_digest"] != statement_digest
        or row["signature_algorithm"] != "Ed25519"
        or row["signature_digest"] != signature_digest
        or row["status"] != "verified"
        or row["consumed_operation_id"] is not None
        or row["consumed_at_epoch_ns"] is not None
        or row["source_revision"]
            != _POLICY_CANDIDATE_AUTHORITY_SOURCE_REVISION
        or not int(row["verified_at_epoch_ns"])
            <= database_now_epoch_ns
            < int(row["expires_at_epoch_ns"])
        or _policy_authority_domain_digest(
            b"serverware.policyAuthorityExternalEvidenceStatement/v1",
            statement_json.encode("ascii"),
        )
            != statement_digest
        or _policy_authority_domain_digest(
            b"serverware.policyAuthorityExternalEvidenceReceipt/v1",
            dumps(receipt_material).encode("ascii"),
        )
            != evidence_digest
    ):
        raise PolicyCandidateAuthorityConflictError(
            "external evidence receipt is not currently authoritative"
        )
    for field in (
        "verifier_identity_digest",
        "verifier_measurement_digest",
        "verifier_attestation_receipt_digest",
    ):
        _candidate_authority_digest(field, row[field])
    return _policy_authority_freeze(row)


def get_policy_canary_assigned_instance_evidence(
    canary_id: str,
) -> tuple[Mapping[str, Any], ...]:
    _require_postgres_policy_authority(
        "secure assigned instance evidence read"
    )
    canary_id = _candidate_authority_text(
        "canary_id", canary_id, maximum=256
    )
    budget = {
        "rows": 0,
        "bytes": 0,
        "maximum_rows": _POLICY_AUTHORITY_READ_MAX_ROWS * 7,
    }
    with _policy_authority_read_snapshot() as conn:
        canary = _policy_authority_read_one(
            conn,
            sql=(
                "SELECT canary_id, expected_instance_count "
                "FROM policy_canaries WHERE canary_id = ?"
            ),
            params=(canary_id,),
            budget=budget,
        )
        if canary is None:
            return ()
        expected = int(canary["expected_instance_count"])
        if expected > _POLICY_AUTHORITY_READ_MAX_ROWS:
            raise PolicyCandidateAuthorityError(
                "assigned instance set exceeds the fixed read limit"
            )
        limit = _POLICY_AUTHORITY_READ_MAX_ROWS + 1
        instances = _policy_authority_read_rows(
            conn.execute(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_CANARY_INSTANCE_READ_COLUMNS
                )
                + " FROM policy_canary_instances WHERE canary_id = ? "
                "ORDER BY member_ordinal LIMIT ?",
                (canary_id, limit),
            ).fetchall(),
            maximum_rows=_POLICY_AUTHORITY_READ_MAX_ROWS,
            budget=budget,
        )
        load_receipts = _policy_authority_read_rows(
            conn.execute(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_CANARY_LOAD_RECEIPT_READ_COLUMNS
                )
                + " FROM policy_canary_load_receipts WHERE canary_id = ? "
                "ORDER BY member_ordinal LIMIT ?",
                (canary_id, limit),
            ).fetchall(),
            maximum_rows=_POLICY_AUTHORITY_READ_MAX_ROWS,
            budget=budget,
        )
        generation_publications = _policy_authority_read_rows(
            conn.execute(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_SHADOW_GENERATION_PUBLICATION_COLUMNS
                )
                + " FROM policy_shadow_generation_publications "
                "WHERE canary_id = ? "
                "ORDER BY member_ordinal LIMIT ?",
                (canary_id, limit),
            ).fetchall(),
            maximum_rows=_POLICY_AUTHORITY_READ_MAX_ROWS,
            budget=budget,
        )
        for publication in generation_publications:
            _reverify_policy_shadow_generation_publication(
                conn, dict(publication)
            )
        instance_revisions = _policy_authority_read_rows(
            conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_CANARY_INSTANCE_REVISION_READ_COLUMNS,
                alias="revision",
            )
            + " FROM policy_canary_instance_heads AS head "
            "JOIN policy_canary_instance_revisions AS revision "
            "ON revision.canary_id = head.canary_id "
            "AND revision.instance_id = head.instance_id "
            "AND revision.boot_id = head.boot_id "
            "AND revision.revision = head.head_revision "
            "AND revision.state_digest = head.head_state_digest "
            "AND revision.status = head.status "
            "WHERE head.canary_id = ? "
            "ORDER BY head.instance_id, head.boot_id LIMIT ?",
            (canary_id, limit),
            ).fetchall(),
            maximum_rows=_POLICY_AUTHORITY_READ_MAX_ROWS,
            budget=budget,
        )
        checkpoints = _policy_authority_read_rows(
            conn.execute(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_CANARY_CHECKPOINT_READ_COLUMNS,
                alias="checkpoint",
            )
            + ", head.sealed, head.sealed_at_epoch_ns, "
            "head.updated_at_epoch_ns AS head_updated_at_epoch_ns "
            "FROM policy_canary_checkpoint_heads AS head "
            "JOIN policy_canary_checkpoints AS checkpoint "
            "ON checkpoint.canary_id = head.canary_id "
            "AND checkpoint.instance_id = head.instance_id "
            "AND checkpoint.boot_id = head.boot_id "
            "AND checkpoint.checkpoint_sequence = head.checkpoint_sequence "
            "AND checkpoint.checkpoint_envelope_digest = "
            "head.checkpoint_envelope_digest "
            "AND checkpoint.checkpoint_payload_digest = "
            "head.checkpoint_payload_digest "
            "WHERE head.canary_id = ? "
            "ORDER BY head.instance_id, head.boot_id LIMIT ?",
            (canary_id, limit),
            ).fetchall(),
            maximum_rows=_POLICY_AUTHORITY_READ_MAX_ROWS,
            budget=budget,
        )
        checkpoint_aggregates = _policy_authority_read_rows(
            conn.execute(
                "SELECT "
                + _policy_authority_projection(
                    _POLICY_CANARY_CHECKPOINT_AGGREGATE_READ_COLUMNS,
                    alias="aggregate_record",
                )
                + " FROM policy_canary_checkpoint_heads AS head "
                "JOIN policy_canary_checkpoint_aggregates "
                "AS aggregate_record "
                "ON aggregate_record.canary_id = head.canary_id "
                "AND aggregate_record.instance_id = head.instance_id "
                "AND aggregate_record.boot_id = head.boot_id "
                "AND aggregate_record.checkpoint_sequence = "
                "head.checkpoint_sequence "
                "AND aggregate_record.checkpoint_envelope_digest = "
                "head.checkpoint_envelope_digest "
                "AND aggregate_record.checkpoint_payload_digest = "
                "head.checkpoint_payload_digest "
                "WHERE head.canary_id = ? "
                "ORDER BY head.instance_id, head.boot_id LIMIT ?",
                (canary_id, limit),
            ).fetchall(),
            maximum_rows=_POLICY_AUTHORITY_READ_MAX_ROWS,
            budget=budget,
        )
    evidence_sets = (
        instances,
        load_receipts,
        generation_publications,
        instance_revisions,
        checkpoints,
        checkpoint_aggregates,
    )
    if any(len(rows) != expected for rows in evidence_sets):
        raise PolicyCandidateAuthorityConflictError(
            "assigned instance evidence set is incomplete or exceeds its declaration"
        )
    def indexed(rows: list[Any]) -> dict[tuple[str, str, str], dict[str, Any]]:
        return {
            (
                str(row["canary_id"]),
                str(row["instance_id"]),
                str(row["boot_id"]),
            ): dict(row)
            for row in rows
        }

    loads_by_identity = indexed(load_receipts)
    publications_by_identity = indexed(generation_publications)
    revisions_by_identity = indexed(instance_revisions)
    checkpoints_by_identity = indexed(checkpoints)
    aggregates_by_identity = indexed(checkpoint_aggregates)
    result: list[Mapping[str, Any]] = []
    for instance in instances:
        identity = (
            str(instance["canary_id"]),
            str(instance["instance_id"]),
            str(instance["boot_id"]),
        )
        if (
            identity not in loads_by_identity
            or identity not in publications_by_identity
            or identity not in revisions_by_identity
            or identity not in checkpoints_by_identity
            or identity not in aggregates_by_identity
        ):
            raise PolicyCandidateAuthorityConflictError(
                "assigned instance evidence identities are not an exact set"
            )
        evidence = {
            "instance": dict(instance),
            "load_receipt": loads_by_identity[identity],
            "generation_publication":
                publications_by_identity[identity],
            "instance_head_revision": revisions_by_identity[identity],
            "checkpoint_head": checkpoints_by_identity[identity],
            "checkpoint_aggregate": aggregates_by_identity[identity],
        }
        frozen = _policy_authority_immutable_row(evidence)
        if frozen is not None:
            result.append(frozen)
    return tuple(result)


def get_policy_activation_head(
    activation_attempt_id: str,
) -> Mapping[str, Any] | None:
    _require_postgres_policy_authority("policy activation head read")
    activation_attempt_id = _candidate_authority_text(
        "activation_attempt_id", activation_attempt_id, maximum=256
    )
    budget = {"rows": 0, "bytes": 0}
    with _policy_authority_read_snapshot() as conn:
        row = _policy_authority_read_one(
            conn,
            sql=(
            "SELECT "
            + _policy_authority_projection(
                _POLICY_ACTIVATION_REVISION_READ_COLUMNS,
                alias="revision",
            )
            + ", head.unresolved_indeterminate, "
            "head.updated_at_epoch_ns AS head_updated_at_epoch_ns "
            "FROM policy_activation_heads AS head "
            "JOIN policy_activation_revisions AS revision "
            "ON revision.activation_attempt_id = head.activation_attempt_id "
            "AND revision.revision = head.head_revision "
            "AND revision.state_digest = head.head_state_digest "
            "AND revision.status = head.status "
            "WHERE head.activation_attempt_id = ?"
            ),
            params=(activation_attempt_id,),
            budget=budget,
        )
    return _policy_authority_immutable_row(row)


