def get_policy_activation_receipt(
    *,
    activation_attempt_id: str | None = None,
    publication_receipt_payload_digest: str | None = None,
) -> Mapping[str, Any] | None:
    _require_postgres_policy_authority(
        "policy activation receipt read"
    )
    if (
        activation_attempt_id is None
    ) == (publication_receipt_payload_digest is None):
        raise PolicyCandidateAuthorityError(
            "exactly one publication receipt identifier is required"
        )
    if activation_attempt_id is not None:
        value = _candidate_authority_text(
            "activation_attempt_id", activation_attempt_id, maximum=256
        )
        sql = (
            "SELECT "
            + _policy_authority_projection(
                _POLICY_ACTIVATION_RECEIPT_READ_COLUMNS
            )
            + " FROM policy_activation_publication_receipts "
            "WHERE activation_attempt_id = ?"
        )
    else:
        value = _candidate_authority_digest(
            "publication_receipt_payload_digest",
            publication_receipt_payload_digest,
        )
        sql = (
            "SELECT "
            + _policy_authority_projection(
                _POLICY_ACTIVATION_RECEIPT_READ_COLUMNS
            )
            + " FROM policy_activation_publication_receipts "
            "WHERE publication_receipt_payload_digest = ?"
        )
    budget = {"rows": 0, "bytes": 0}
    with _policy_authority_read_snapshot() as conn:
        row = _policy_authority_read_one(
            conn, sql=sql, params=(value,), budget=budget
        )
    return _policy_authority_immutable_row(row)


