def _policy_activation_chain_section_spec(
    section: str,
) -> tuple[Any, ...] | None:
    for spec in _POLICY_ACTIVATION_CHAIN_SECTION_SPECS:
        if spec[0] == section:
            return spec
    if section in _POLICY_ACTIVATION_CHAIN_SPECIAL_SECTIONS:
        return None
    raise PolicyCandidateAuthorityError(
        "activation-chain section is not source-defined"
    )


def _policy_activation_chain_transition_references(
    context: Mapping[str, Any],
) -> tuple[str, tuple[Any, ...]]:
    branches = [
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_candidate_artifacts "
            "WHERE artifact_envelope_digest = ?",
            context["artifact_envelope_digest"],
        ),
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_canary_assignments "
            "WHERE assignment_envelope_digest = ?",
            context["assignment_envelope_digest"],
        ),
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_runtime_role_key_revocations "
            "WHERE assignment_envelope_digest = ?",
            context["assignment_envelope_digest"],
        ),
        (
            "SELECT transition_digest FROM policy_canary_revisions "
            "WHERE canary_id = ?",
            context["canary_id"],
        ),
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_canary_load_receipts WHERE canary_id = ?",
            context["canary_id"],
        ),
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_canary_custody_evidence WHERE canary_id = ?",
            context["canary_id"],
        ),
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_canary_ingress_observations WHERE canary_id = ?",
            context["canary_id"],
        ),
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_canary_active_decisions WHERE canary_id = ?",
            context["canary_id"],
        ),
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_canary_shadow_observations WHERE canary_id = ?",
            context["canary_id"],
        ),
        (
            "SELECT transition_digest "
            "FROM policy_canary_instance_revisions WHERE canary_id = ?",
            context["canary_id"],
        ),
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_canary_checkpoints WHERE canary_id = ?",
            context["canary_id"],
        ),
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_canary_readiness "
            "WHERE readiness_payload_digest = ?",
            context["readiness_payload_digest"],
        ),
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_compiler_authority_analyses "
            "WHERE analysis_payload_digest = ?",
            context["compiler_analysis_payload_digest"],
        ),
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_activation_approvals WHERE approval_id = ?",
            context["approval_id"],
        ),
        (
            "SELECT transition_digest FROM policy_activation_revisions "
            "WHERE activation_attempt_id = ?",
            context["activation_attempt_id"],
        ),
        (
            "SELECT created_transition_digest AS transition_digest "
            "FROM policy_activation_publication_receipts "
            "WHERE activation_attempt_id = ?",
            context["activation_attempt_id"],
        ),
    ]
    rollback_digest = context["rollback_authorization_digest"]
    if rollback_digest is not None:
        branches.append(
            (
                "SELECT created_transition_digest AS transition_digest "
                "FROM policy_activation_rollback_authority_revocations "
                "WHERE rollback_authorization_payload_digest = ?",
                rollback_digest,
            )
        )
    return (
        " UNION ".join(branch for branch, _ in branches),
        tuple(value for _, value in branches),
    )


def _policy_activation_chain_static_verification_references(
    context: Mapping[str, Any],
) -> tuple[str, tuple[Any, ...]]:
    branches = [
        (
            "SELECT verification_receipt_digest "
            "FROM policy_candidate_artifacts "
            "WHERE artifact_envelope_digest = ?",
            context["artifact_envelope_digest"],
        ),
        (
            "SELECT verification_receipt_digest "
            "FROM policy_canary_assignments "
            "WHERE assignment_envelope_digest = ?",
            context["assignment_envelope_digest"],
        ),
        (
            "SELECT verification_receipt_digest "
            "FROM policy_runtime_attestations "
            "WHERE assignment_envelope_digest = ?",
            context["assignment_envelope_digest"],
        ),
        (
            "SELECT verification_receipt_digest "
            "FROM policy_runtime_role_key_revocations "
            "WHERE assignment_envelope_digest = ?",
            context["assignment_envelope_digest"],
        ),
        (
            "SELECT verification_receipt_digest "
            "FROM policy_compiler_authority_analyses "
            "WHERE analysis_payload_digest = ?",
            context["compiler_analysis_payload_digest"],
        ),
        (
            "SELECT verification_receipt_digest "
            "FROM policy_canary_readiness "
            "WHERE readiness_payload_digest = ?",
            context["readiness_payload_digest"],
        ),
        (
            "SELECT verification_receipt_digest "
            "FROM policy_canary_revisions WHERE canary_id = ?",
            context["canary_id"],
        ),
        (
            "SELECT verification_receipt_digest "
            "FROM policy_activation_revisions "
            "WHERE activation_attempt_id = ?",
            context["activation_attempt_id"],
        ),
        (
            "SELECT verification_receipt_digest "
            "FROM policy_activation_publication_receipts "
            "WHERE activation_attempt_id = ?",
            context["activation_attempt_id"],
        ),
    ]
    rollback_digest = context["rollback_authorization_digest"]
    if rollback_digest is not None:
        branches.extend(
            (
                (
                    "SELECT verification_receipt_digest "
                    "FROM policy_activation_rollback_authorities "
                    "WHERE rollback_authorization_payload_digest = ?",
                    rollback_digest,
                ),
                (
                    "SELECT verification_receipt_digest "
                    "FROM policy_activation_rollback_authority_revocations "
                    "WHERE rollback_authorization_payload_digest = ?",
                    rollback_digest,
                ),
            )
        )
    transition_references, transition_params = (
        _policy_activation_chain_transition_references(context)
    )
    return (
        " UNION ".join(branch for branch, _ in branches)
        + " UNION SELECT verification_receipt_digest "
        "FROM policy_authority_audit_inclusion_receipts "
        "WHERE transition_digest IN ("
        + transition_references
        + ")",
        tuple(value for _, value in branches) + transition_params,
    )


def _policy_activation_chain_section_source(
    section: str,
    context: Mapping[str, Any],
) -> tuple[str, str, tuple[Any, ...], tuple[str, ...], tuple[str, ...]]:
    spec = _policy_activation_chain_section_spec(section)
    if spec is not None:
        _, table, columns, filter_column, context_key, order_by = spec
        value = context[context_key]
        if value is None:
            return (
                "FROM "
                + _policy_candidate_authority_identifier(table)
                + " AS item",
                "1 = 0",
                (),
                columns,
                order_by,
            )
        return (
            "FROM "
            + _policy_candidate_authority_identifier(table)
            + " AS item",
            "item."
            + _policy_candidate_authority_identifier(filter_column)
            + " = ?",
            (value,),
            columns,
            order_by,
        )
    if section == "schema_contract":
        return (
            "FROM policy_authority_schema_contracts AS item",
            "item.schema_version = ?",
            (_POLICY_CANDIDATE_AUTHORITY_SCHEMA_VERSION,),
            _POLICY_ACTIVATION_CHAIN_SCHEMA_CONTRACT_COLUMNS,
            ("schema_version",),
        )
    if section == "owner_contract":
        return (
            "FROM policy_authority_owner_contracts AS item",
            "item.contract_id = ?",
            (_POLICY_AUTHORITY_OWNER_CONTRACT_ID,),
            _POLICY_ACTIVATION_CHAIN_OWNER_CONTRACT_COLUMNS,
            ("contract_id",),
        )
    if section == "offline_migration_receipt":
        return (
            "FROM policy_authority_v8_offline_migration_receipts AS item",
            "item.receipt_digest IN ("
            "SELECT contract.offline_migration_receipt_digest "
            "FROM policy_authority_schema_contracts AS contract "
            "WHERE contract.schema_version = ? "
            "AND contract.offline_migration_receipt_digest IS NOT NULL"
            ")",
            (_POLICY_CANDIDATE_AUTHORITY_SCHEMA_VERSION,),
            _POLICY_ACTIVATION_CHAIN_OFFLINE_MIGRATION_RECEIPT_COLUMNS,
            ("contract_id",),
        )
    verification_references, verification_params = (
        _policy_activation_chain_static_verification_references(context)
    )
    if section == "trusted_keys":
        return (
            "FROM policy_authority_trusted_keys AS item",
            "(item.evidence_kind, item.key_revision, "
            "item.signing_key_id) IN ("
            "SELECT verification.evidence_kind, "
            "verification.trusted_key_revision, "
            "verification.signing_key_id "
            "FROM policy_authority_evidence_verifications "
            "AS verification WHERE "
            "verification.verification_receipt_digest IN ("
            + verification_references
            + "))",
            verification_params,
            _POLICY_AUTHORITY_TRUSTED_KEY_COLUMNS,
            ("evidence_kind", "key_revision"),
        )
    if section == "trusted_key_revocations":
        return (
            "FROM policy_authority_trusted_key_revocations AS item",
            "(item.evidence_kind, item.signing_key_id) IN ("
            "SELECT verification.evidence_kind, "
            "verification.signing_key_id "
            "FROM policy_authority_evidence_verifications "
            "AS verification WHERE "
            "verification.verification_receipt_digest IN ("
            + verification_references
            + "))",
            verification_params,
            _POLICY_AUTHORITY_TRUSTED_KEY_REVOCATION_COLUMNS,
            ("revocation_sequence",),
        )
    if section == "authority_evidence_verifications":
        return (
            "FROM policy_authority_evidence_verifications AS item",
            "item.verification_receipt_digest IN ("
            + verification_references
            + ")",
            verification_params,
            _POLICY_AUTHORITY_EVIDENCE_VERIFICATION_COLUMNS,
            ("verification_receipt_digest",),
        )
    if section == "runtime_evidence_verifications":
        return (
            "FROM policy_runtime_evidence_verifications AS item",
            "item.assignment_envelope_digest = ?",
            (context["assignment_envelope_digest"],),
            _POLICY_RUNTIME_EVIDENCE_VERIFICATION_COLUMNS,
            ("verification_receipt_digest",),
        )
    references, reference_params = (
        _policy_activation_chain_transition_references(context)
    )
    if section == "transition_audits":
        return (
            "FROM policy_authority_transition_audits AS item",
            "item.transition_digest IN (" + references + ")",
            reference_params,
            _POLICY_AUTHORITY_TRANSITION_READ_COLUMNS,
            ("transition_digest",),
        )
    if section == "audit_inclusion_receipts":
        return (
            "FROM policy_authority_audit_inclusion_receipts AS item",
            "item.transition_digest IN (" + references + ")",
            reference_params,
            _POLICY_AUTHORITY_AUDIT_INCLUSION_COLUMNS,
            ("audit_sequence",),
        )
    return (
        "FROM metadata_audit_outbox AS item",
        "item.id IN (SELECT transition.outbox_id "
        "FROM policy_authority_transition_audits AS transition "
        "WHERE transition.transition_digest IN ("
        + references
        + "))",
        reference_params,
        _POLICY_AUTHORITY_OUTBOX_READ_COLUMNS,
        ("id",),
    )


def _policy_activation_chain_section_root_genesis(
    *,
    identity_digest: str,
    section: str,
) -> str:
    return _policy_candidate_authority_framed_digest(
        "serverware.policyActivationChainSectionGenesis/v1",
        dumps(
            {
                "identityDigest": identity_digest,
                "section": section,
            }
        ).encode("ascii"),
    )


def _policy_activation_chain_section_root_step(
    *,
    previous_root_digest: str,
    row: Mapping[str, Any],
) -> str:
    return _policy_candidate_authority_framed_digest(
        "serverware.policyActivationChainSectionRow/v1",
        dumps(
            {
                "previousRootDigest": previous_root_digest,
                "row": dict(row),
            }
        ).encode("ascii"),
    )


def _policy_activation_chain_plain(value: Any) -> Any:
    if isinstance(value, Mapping):
        return {
            str(key): _policy_activation_chain_plain(member)
            for key, member in value.items()
        }
    if isinstance(value, (tuple, list)):
        return [
            _policy_activation_chain_plain(member) for member in value
        ]
    return value


def _policy_activation_chain_read_one(
    conn: Any,
    *,
    table: str,
    columns: tuple[str, ...],
    where_sql: str,
    params: tuple[Any, ...],
    budget: dict[str, int],
) -> dict[str, Any] | None:
    return _policy_authority_read_one(
        conn,
        sql=(
            "SELECT "
            + _policy_authority_projection(columns)
            + " FROM "
            + _policy_candidate_authority_identifier(table)
            + " WHERE "
            + where_sql
        ),
        params=params,
        budget=budget,
    )


def _policy_activation_chain_load_context(
    conn: Any,
    activation_attempt_id: str,
) -> dict[str, Any] | None:
    budget = {
        "rows": 0,
        "bytes": 0,
        "maximum_rows": 16,
    }
    attempt = _policy_activation_chain_read_one(
        conn,
        table="policy_activation_attempts",
        columns=_POLICY_ACTIVATION_ATTEMPT_FIELDS,
        where_sql="activation_attempt_id = ?",
        params=(activation_attempt_id,),
        budget=budget,
    )
    if attempt is None:
        return None
    preparation = _policy_activation_chain_read_one(
        conn,
        table="policy_activation_preparations",
        columns=_POLICY_ACTIVATION_PREPARATION_COLUMNS,
        where_sql="activation_attempt_id = ?",
        params=(activation_attempt_id,),
        budget=budget,
    )
    if preparation is None:
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain snapshot has no exact preparation"
        )
    finalization = _policy_activation_chain_read_one(
        conn,
        table="policy_activation_finalizations",
        columns=_POLICY_ACTIVATION_FINALIZATION_COLUMNS,
        where_sql="preparation_digest = ?",
        params=(preparation["preparation_digest"],),
        budget=budget,
    )
    abort = _policy_activation_chain_read_one(
        conn,
        table="policy_activation_aborts",
        columns=_POLICY_ACTIVATION_ABORT_COLUMNS,
        where_sql="preparation_digest = ?",
        params=(preparation["preparation_digest"],),
        budget=budget,
    )
    if finalization is None or abort is not None:
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain snapshot is not an exact committed "
            "two-phase activation"
        )
    readiness = _policy_activation_chain_read_one(
        conn,
        table="policy_canary_readiness",
        columns=_POLICY_CANARY_READINESS_READ_COLUMNS,
        where_sql="readiness_payload_digest = ?",
        params=(attempt["readiness_payload_digest"],),
        budget=budget,
    )
    approval = _policy_activation_chain_read_one(
        conn,
        table="policy_activation_approvals",
        columns=_POLICY_ACTIVATION_APPROVAL_READ_COLUMNS,
        where_sql="approval_id = ?",
        params=(attempt["approval_id"],),
        budget=budget,
    )
    canary = _policy_activation_chain_read_one(
        conn,
        table="policy_canaries",
        columns=_POLICY_CANARY_READ_COLUMNS,
        where_sql="canary_id = ?",
        params=(attempt["canary_id"],),
        budget=budget,
    )
    artifact = _policy_activation_chain_read_one(
        conn,
        table="policy_candidate_artifacts",
        columns=_POLICY_CANDIDATE_ARTIFACT_READ_COLUMNS,
        where_sql="artifact_envelope_digest = ?",
        params=(attempt["artifact_envelope_digest"],),
        budget=budget,
    )
    approval_consumption = _policy_activation_chain_read_one(
        conn,
        table="policy_activation_approval_consumptions",
        columns=_POLICY_ACTIVATION_APPROVAL_CONSUMPTION_READ_COLUMNS,
        where_sql="activation_attempt_id = ?",
        params=(activation_attempt_id,),
        budget=budget,
    )
    receipt = _policy_activation_chain_read_one(
        conn,
        table="policy_activation_publication_receipts",
        columns=_POLICY_ACTIVATION_RECEIPT_READ_COLUMNS,
        where_sql="activation_attempt_id = ?",
        params=(activation_attempt_id,),
        budget=budget,
    )
    if canary is None:
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain snapshot has no exact canary authority"
        )
    finalized_authority = (
        _policy_activation_finalized_authority_snapshot(finalization)
    )
    canary_head = finalized_authority["canary_head"]
    activation_head = finalized_authority["activation_head"]
    high_water = finalized_authority["high_water"]
    publication = finalized_authority["publication"]
    if any(
        row is None
        for row in (
            readiness,
            approval,
            canary,
            artifact,
            approval_consumption,
            receipt,
            preparation,
            finalization,
        )
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain snapshot is missing immutable authority material"
        )
    exact_links = {
        "canary_id": canary["canary_id"],
        "artifact_envelope_digest": artifact["artifact_envelope_digest"],
        "artifact_payload_digest": artifact["artifact_payload_digest"],
        "assignment_envelope_digest":
            readiness["assignment_envelope_digest"],
        "assignment_payload_digest": readiness["assignment_payload_digest"],
        "readiness_payload_digest": readiness["readiness_payload_digest"],
        "approval_id": approval["approval_id"],
        "candidate_policy_hash": canary["candidate_policy_hash"],
    }
    if any(attempt[field] != value for field, value in exact_links.items()):
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain core identities are not an exact graph"
        )
    if (
        _policy_candidate_high_water_digest(high_water)
        != receipt["high_water_after_digest"]
        or high_water["policy_id"] != canary["policy_id"]
        or int(high_water["sequence"])
        != int(attempt["candidate_policy_sequence"])
        or int(high_water["rollback_epoch"])
        != int(attempt["candidate_rollback_epoch"])
        or high_water["policy_hash"] != attempt["candidate_policy_hash"]
        or finalization["activation_attempt_id"]
        != attempt["activation_attempt_id"]
        or finalization["preparation_input_digest"]
        != preparation["preparation_input_digest"]
        or finalization["publication_receipt_payload_digest"]
        != receipt["publication_receipt_payload_digest"]
        or finalization["high_water_after_digest"]
        != receipt["high_water_after_digest"]
        or publication["policy_hash"] != high_water["policy_hash"]
        or publication["policy_id"] != high_water["policy_id"]
        or int(publication["sequence"]) != int(high_water["sequence"])
        or int(publication["rollback_epoch"])
        != int(high_water["rollback_epoch"])
        or publication["status"] != "committed"
        or canary_head["canary_id"] != attempt["canary_id"]
        or canary_head["status"] != "active"
        or activation_head["activation_attempt_id"]
        != attempt["activation_attempt_id"]
        or activation_head["status"] != "committed"
        or int(activation_head["unresolved_indeterminate"]) != 0
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain finalized authority identity is not exact"
        )
    return {
        **dict(attempt),
        "policy_id": canary["policy_id"],
        "attempt": attempt,
        "readiness": {
            **readiness,
            "policy_id": canary["policy_id"],
            "minimum_evaluation_count":
                canary["minimum_evaluation_count"],
        },
        "approval": approval,
        "canary": canary,
        "artifact": artifact,
        "approval_consumption": approval_consumption,
        "receipt": receipt,
        "canary_head": canary_head,
        "activation_head": activation_head,
        "high_water": high_water,
        "preparation": preparation,
        "preparation_digest": preparation["preparation_digest"],
        "finalization": finalization,
    }


def _policy_activation_chain_reverify_context(
    conn: Any,
    context: Mapping[str, Any],
) -> None:
    attempt = context["attempt"]
    readiness = context["readiness"]
    approval = context["approval"]
    receipt = context["receipt"]
    approval_consumption = context["approval_consumption"]
    quorum = _candidate_authority_int(
        "activation-chain approval quorum",
        attempt["required_approval_quorum"],
        minimum=1,
        maximum=2,
    )
    approval_members = conn.execute(
        "SELECT "
        + _policy_authority_projection(
            _POLICY_ACTIVATION_APPROVAL_MEMBER_READ_COLUMNS
        )
        + " FROM policy_activation_approval_members "
        "WHERE approval_id = ? ORDER BY member_ordinal LIMIT ?",
        (attempt["approval_id"], quorum + 1),
    ).fetchall()
    activation_revisions = conn.execute(
        "SELECT "
        + _policy_authority_projection(
            _POLICY_ACTIVATION_REVISION_READ_COLUMNS,
            alias="revision",
        )
        + ", audit.actor_id AS actor_id "
        "FROM policy_activation_revisions AS revision "
        "JOIN policy_authority_transition_audits AS audit "
        "ON audit.transition_digest = revision.transition_digest "
        "WHERE revision.activation_attempt_id = ? "
        "AND revision.revision <= 4 "
        "ORDER BY revision.revision LIMIT 5",
        (attempt["activation_attempt_id"],),
    ).fetchall()
    ready_revision = int(readiness["designated_ready_revision"])
    canary_revisions = conn.execute(
        "SELECT "
        + _policy_authority_projection(
            _POLICY_CANARY_REVISION_READ_COLUMNS,
            alias="revision",
        )
        + ", audit.actor_id AS actor_id "
        "FROM policy_canary_revisions AS revision "
        "JOIN policy_authority_transition_audits AS audit "
        "ON audit.transition_digest = revision.transition_digest "
        "WHERE revision.canary_id = ? AND revision.revision > ? "
        "AND revision.revision <= ? ORDER BY revision.revision LIMIT 3",
        (
            attempt["canary_id"],
            ready_revision,
            ready_revision + 2,
        ),
    ).fetchall()
    if (
        len(approval_members) != quorum
        or [row["status"] for row in activation_revisions]
        != ["prepared", "approved", "publishing", "committed"]
        or [row["status"] for row in canary_revisions]
        != ["activating", "active"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain publication prefix is incomplete or ambiguous"
        )
    before_digest = _policy_candidate_high_water_digest(
        {
            "policy_id": context["canary"]["policy_id"],
            "sequence": attempt["expected_active_policy_sequence"],
            "rollback_epoch": attempt["expected_active_rollback_epoch"],
            "policy_hash": attempt["predecessor_policy_hash"],
        }
    )
    after_digest = _policy_candidate_high_water_digest(
        {
            "policy_id": context["canary"]["policy_id"],
            "sequence": attempt["candidate_policy_sequence"],
            "rollback_epoch": attempt["candidate_rollback_epoch"],
            "policy_hash": attempt["candidate_policy_hash"],
        }
    )
    _validate_policy_activation_equality_map(
        attempt=attempt,
        approval=approval,
        consumption=approval_consumption,
        activation_revisions=[
            dict(row) for row in activation_revisions
        ],
        canary_revisions=[dict(row) for row in canary_revisions],
        receipt=receipt,
        readiness=readiness,
        policy_id=str(context["canary"]["policy_id"]),
        high_water_before_digest=before_digest,
        high_water_after_digest=after_digest,
    )
    _reverify_policy_activation_chain(
        conn,
        attempt=attempt,
        approval=approval,
        approval_members=[dict(row) for row in approval_members],
        activation_revisions=[
            dict(row) for row in activation_revisions
        ],
        canary_revisions=[dict(row) for row in canary_revisions],
        receipt=receipt,
        readiness=readiness,
        lock_approval_principals=False,
        require_unconsumed_rollback=False,
        use_persisted_assertion_verification_time=True,
    )


def _policy_activation_chain_identity(
    context: Mapping[str, Any],
) -> dict[str, Any]:
    attempt = context["attempt"]
    receipt = context["receipt"]
    canary_head = context["canary_head"]
    activation_head = context["activation_head"]
    high_water = context["high_water"]
    return {
        "schema": "serverware.policyActivationChainIdentity/v3",
        "activationAttemptId": attempt["activation_attempt_id"],
        "activationIntentDigest": attempt["activation_intent_digest"],
        "activationRequestPayloadDigest":
            attempt["activation_request_payload_digest"],
        "approvalContextDigest": attempt["approval_context_digest"],
        "approvalId": attempt["approval_id"],
        "artifactEnvelopeDigest": attempt["artifact_envelope_digest"],
        "assignmentEnvelopeDigest":
            attempt["assignment_envelope_digest"],
        "canaryId": attempt["canary_id"],
        "policyId": context["policy_id"],
        "candidatePolicyHash": attempt["candidate_policy_hash"],
        "publicationIntentDigest":
            attempt["publication_intent_digest"],
        "publicationReceiptPayloadDigest":
            receipt["publication_receipt_payload_digest"],
        "readinessPayloadDigest": attempt["readiness_payload_digest"],
        "highWaterBeforeDigest": receipt["high_water_before_digest"],
        "highWaterAfterDigest": receipt["high_water_after_digest"],
        "highWater": {
            field: high_water[field]
            for field in _POLICY_ACTIVATION_CHAIN_HIGH_WATER_COLUMNS
        },
        "canaryHead": {
            field: canary_head[field]
            for field in
            _POLICY_ACTIVATION_CHAIN_CANARY_HEAD_COLUMNS
        },
        "activationHead": {
            field: activation_head[field]
            for field in
            _POLICY_ACTIVATION_CHAIN_ACTIVATION_HEAD_COLUMNS
        },
    }


def _policy_activation_chain_section_manifest(
    conn: Any,
    *,
    context: Mapping[str, Any],
    identity_digest: str,
    section: str,
    shared_budget: dict[str, int],
) -> dict[str, Any]:
    from_sql, where_sql, params, columns, order_by = (
        _policy_activation_chain_section_source(section, context)
    )
    count_row = conn.execute(
        "SELECT COUNT(*) AS row_count "
        + from_sql
        + " WHERE "
        + where_sql,
        params,
    ).fetchone()
    row_count = _candidate_authority_int(
        f"activation-chain {section} row count",
        count_row["row_count"],
        minimum=0,
        maximum=_POLICY_AUTHORITY_STREAM_MAX_WORK_UNITS,
    )
    if (
        shared_budget["rows"] + row_count
        > _POLICY_AUTHORITY_STREAM_MAX_WORK_UNITS
    ):
        raise PolicyCandidateAuthorityError(
            "activation-chain snapshot exceeds its source work bound"
        )
    cursor = conn.execute(
        "SELECT "
        + _policy_authority_projection(columns, alias="item")
        + " "
        + from_sql
        + " WHERE "
        + where_sql
        + " ORDER BY "
        + ", ".join(
            "item." + _policy_candidate_authority_identifier(column)
            for column in order_by
        ),
        params,
    )
    root = _policy_activation_chain_section_root_genesis(
        identity_digest=identity_digest,
        section=section,
    )
    consumed = 0
    section_bytes = 0
    previous_key: tuple[Any, ...] | None = None
    while True:
        rows = cursor.fetchmany(_POLICY_AUTHORITY_STREAM_PAGE_ROWS)
        if not rows:
            break
        for raw_row in rows:
            row = dict(raw_row)
            key = tuple(row[column] for column in order_by)
            encoded = dumps(row).encode("utf-8")
            consumed += 1
            section_bytes += len(encoded)
            shared_budget["rows"] += 1
            shared_budget["bytes"] += len(encoded)
            if (
                any(value is None for value in key)
                or (
                    previous_key is not None
                    and not previous_key < key
                )
                or consumed > row_count
                or shared_budget["rows"]
                > _POLICY_AUTHORITY_STREAM_MAX_WORK_UNITS
                or shared_budget["bytes"]
                > _POLICY_AUTHORITY_READ_MAX_JSON_BYTES * 4
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "activation-chain section order, byte, or work bound "
                    "is not exact"
                )
            root = _policy_activation_chain_section_root_step(
                previous_root_digest=root,
                row=row,
            )
            previous_key = key
    if consumed != row_count:
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain section changed inside its read snapshot"
        )
    return {
        "name": section,
        "rowCount": row_count,
        "canonicalBytes": section_bytes,
        "orderBy": list(order_by),
        "finalRootDigest": root,
    }


def _policy_activation_chain_snapshot_material(
    conn: Any,
    activation_attempt_id: str,
) -> dict[str, Any] | None:
    context = _policy_activation_chain_load_context(
        conn, activation_attempt_id
    )
    if context is None:
        return None
    _policy_activation_chain_reverify_context(conn, context)
    identity = _policy_activation_chain_identity(context)
    identity_digest = _policy_candidate_authority_framed_digest(
        "serverware.policyActivationChainIdentity/v3",
        dumps(identity).encode("ascii"),
    )
    shared_budget = {"rows": 0, "bytes": 0}
    section_names = tuple(
        spec[0] for spec in _POLICY_ACTIVATION_CHAIN_SECTION_SPECS
    ) + _POLICY_ACTIVATION_CHAIN_SPECIAL_SECTIONS
    sections = []
    for section_ordinal, section in enumerate(section_names, start=1):
        section_manifest = _policy_activation_chain_section_manifest(
            conn,
            context=context,
            identity_digest=identity_digest,
            section=section,
            shared_budget=shared_budget,
        )
        sections.append(
            {
                **section_manifest,
                "sectionOrdinal": section_ordinal,
                "terminalRowOrdinal":
                    int(section_manifest["rowCount"]),
            }
        )
    verified_at_epoch_ns = int(
        _metadata_utcnow(conn).timestamp() * 1_000_000_000
    )
    expires_at_epoch_ns = (
        verified_at_epoch_ns + _POLICY_AUTHORITY_EXPORT_TTL_NS
    )
    total_row_count = sum(
        int(section["rowCount"]) for section in sections
    )
    total_canonical_bytes = sum(
        int(section["canonicalBytes"]) for section in sections
    )
    manifest_material = {
        "schema": "serverware.policyActivationChainManifest/v1",
        "identityDigest": identity_digest,
        "sectionCount": len(sections),
        "totalRowCount": total_row_count,
        "totalCanonicalBytes": total_canonical_bytes,
        "terminalSectionOrdinal": len(sections),
        "terminalRowOrdinal": total_row_count,
        "sections": sections,
    }
    manifest_root_digest = _policy_candidate_authority_framed_digest(
        "serverware.policyActivationChainManifest/v1",
        dumps(manifest_material).encode("ascii"),
    )
    export_material = {
        "schema": "serverware.policyActivationChainExport/v1",
        "exportRevision": 1,
        "identityDigest": identity_digest,
        "manifestRootDigest": manifest_root_digest,
        "sectionCount": len(sections),
        "totalRowCount": total_row_count,
        "totalCanonicalBytes": total_canonical_bytes,
        "verifiedAtEpochNs": verified_at_epoch_ns,
        "expiresAtEpochNs": expires_at_epoch_ns,
    }
    export_id = _policy_candidate_authority_framed_digest(
        "serverware.policyActivationChainExport/v1",
        dumps(export_material).encode("ascii"),
    )
    material = {
        "schema": "serverware.policyActivationChainSnapshot/v3",
        "exportId": export_id,
        "exportRevision": 1,
        "identity": identity,
        "identityDigest": identity_digest,
        "manifestRootDigest": manifest_root_digest,
        "sectionCount": len(sections),
        "totalRowCount": total_row_count,
        "totalCanonicalBytes": total_canonical_bytes,
        "terminalSectionOrdinal": len(sections),
        "terminalRowOrdinal": total_row_count,
        "sections": sections,
        "verifiedAtEpochNs": verified_at_epoch_ns,
        "expiresAtEpochNs": expires_at_epoch_ns,
    }
    return {
        **material,
        "snapshotDigest":
            _policy_candidate_authority_framed_digest(
                "serverware.policyActivationChainSnapshot/v3",
                dumps(material).encode("ascii"),
            ),
    }


def _get_policy_activation_chain_unattested_snapshot(
    activation_attempt_id: str,
) -> Mapping[str, Any] | None:
    activation_attempt_id = _candidate_authority_text(
        "activation_attempt_id", activation_attempt_id, maximum=256
    )
    with _policy_authority_read_snapshot() as conn:
        source = _load_policy_activation_finalized_export(
            conn, activation_attempt_id
        )
        export_material = {
            "schema": "serverware.policyActivationChainExport/v1",
            "exportRevision": 1,
            "identityDigest": source["identityDigest"],
            "manifestRootDigest": source["manifestRootDigest"],
            "sectionCount": source["sectionCount"],
            "totalRowCount": source["totalRowCount"],
            "totalCanonicalBytes": source["totalCanonicalBytes"],
            "verifiedAtEpochNs": source["verifiedAtEpochNs"],
            "expiresAtEpochNs": source["expiresAtEpochNs"],
        }
        export_id = _policy_candidate_authority_framed_digest(
            "serverware.policyActivationChainExport/v1",
            dumps(export_material).encode("ascii"),
        )
        material = {
            "schema": "serverware.policyActivationChainSnapshot/v3",
            "exportId": export_id,
            "exportRevision": 1,
            "identity": source["identity"],
            "identityDigest": source["identityDigest"],
            "manifestRootDigest": source["manifestRootDigest"],
            "sectionCount": source["sectionCount"],
            "totalRowCount": source["totalRowCount"],
            "totalCanonicalBytes": source["totalCanonicalBytes"],
            "terminalSectionOrdinal":
                source["terminalSectionOrdinal"],
            "terminalRowOrdinal": source["terminalRowOrdinal"],
            "sections": source["sections"],
            "verifiedAtEpochNs": source["verifiedAtEpochNs"],
            "expiresAtEpochNs": source["expiresAtEpochNs"],
        }
        result = {
            **material,
            "snapshotDigest":
                _policy_candidate_authority_framed_digest(
                    "serverware.policyActivationChainSnapshot/v3",
                    dumps(material).encode("ascii"),
                ),
        }
    return _policy_authority_immutable_row(result)


def _policy_activation_chain_validate_snapshot(
    snapshot: Mapping[str, Any],
) -> dict[str, Any]:
    plain = _policy_activation_chain_plain(snapshot)
    if not isinstance(plain, dict) or set(plain) != {
        "schema",
        "exportId",
        "exportRevision",
        "identity",
        "identityDigest",
        "manifestRootDigest",
        "sectionCount",
        "totalRowCount",
        "totalCanonicalBytes",
        "terminalSectionOrdinal",
        "terminalRowOrdinal",
        "sections",
        "verifiedAtEpochNs",
        "expiresAtEpochNs",
        "snapshotDigest",
    }:
        raise PolicyCandidateAuthorityError(
            "activation-chain snapshot fields are not exact"
        )
    if plain["schema"] != "serverware.policyActivationChainSnapshot/v3":
        raise PolicyCandidateAuthorityError(
            "activation-chain snapshot schema is not supported"
        )
    export_id = _candidate_authority_digest(
        "activation-chain export id", plain["exportId"]
    )
    export_revision = _candidate_authority_int(
        "activation-chain export revision",
        plain["exportRevision"],
        minimum=1,
        maximum=1,
    )
    snapshot_digest = _candidate_authority_digest(
        "activation-chain snapshot digest", plain["snapshotDigest"]
    )
    identity_digest = _candidate_authority_digest(
        "activation-chain identity digest", plain["identityDigest"]
    )
    manifest_root_digest = _candidate_authority_digest(
        "activation-chain manifest root", plain["manifestRootDigest"]
    )
    identity = plain["identity"]
    if not isinstance(identity, dict) or set(identity) != {
        "schema",
        "activationAttemptId",
        "activationIntentDigest",
        "activationRequestPayloadDigest",
        "approvalContextDigest",
        "approvalId",
        "artifactEnvelopeDigest",
        "assignmentEnvelopeDigest",
        "canaryId",
        "policyId",
        "candidatePolicyHash",
        "publicationIntentDigest",
        "publicationReceiptPayloadDigest",
        "readinessPayloadDigest",
        "highWaterBeforeDigest",
        "highWaterAfterDigest",
        "highWater",
        "canaryHead",
        "activationHead",
    }:
        raise PolicyCandidateAuthorityError(
            "activation-chain snapshot identity fields are not exact"
        )
    if (
        identity["schema"]
        != "serverware.policyActivationChainIdentity/v3"
        or _policy_candidate_authority_framed_digest(
            "serverware.policyActivationChainIdentity/v3",
            dumps(identity).encode("ascii"),
        )
        != identity_digest
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain identity digest is not exact"
        )
    for field in (
        "activationIntentDigest",
        "activationRequestPayloadDigest",
        "approvalContextDigest",
        "approvalId",
        "artifactEnvelopeDigest",
        "assignmentEnvelopeDigest",
        "candidatePolicyHash",
        "publicationIntentDigest",
        "publicationReceiptPayloadDigest",
        "readinessPayloadDigest",
        "highWaterBeforeDigest",
        "highWaterAfterDigest",
    ):
        _candidate_authority_digest(
            "activation-chain identity " + field,
            identity[field],
        )
    for field in ("activationAttemptId", "canaryId", "policyId"):
        _candidate_authority_text(
            "activation-chain identity " + field,
            identity[field],
            maximum=256,
        )
    high_water = identity["highWater"]
    if (
        not isinstance(high_water, dict)
        or set(high_water)
        != set(_POLICY_ACTIVATION_CHAIN_HIGH_WATER_COLUMNS)
        or high_water["scope"] != "active"
        or high_water["policy_id"] != identity["policyId"]
        or high_water["policy_hash"] != identity["candidatePolicyHash"]
        or _policy_candidate_high_water_digest(high_water)
        != identity["highWaterAfterDigest"]
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain high-water identity is not exact"
        )
    _candidate_authority_int(
        "activation-chain high-water sequence",
        high_water["sequence"],
        minimum=1,
    )
    _candidate_authority_int(
        "activation-chain high-water rollback epoch",
        high_water["rollback_epoch"],
        minimum=1,
    )
    _candidate_authority_text(
        "activation-chain high-water update time",
        high_water["updated_at"],
        maximum=128,
    )
    for head_name, fields in (
        (
            "canaryHead",
            _POLICY_ACTIVATION_CHAIN_CANARY_HEAD_COLUMNS,
        ),
        (
            "activationHead",
            _POLICY_ACTIVATION_CHAIN_ACTIVATION_HEAD_COLUMNS,
        ),
    ):
        head = identity[head_name]
        if not isinstance(head, dict) or set(head) != set(fields):
            raise PolicyCandidateAuthorityError(
                "activation-chain head identity fields are not exact"
            )
        _candidate_authority_int(
            "activation-chain head revision",
            head["head_revision"],
            minimum=1,
            maximum=_POLICY_AUTHORITY_STREAM_MAX_WORK_UNITS,
        )
        _candidate_authority_digest(
            "activation-chain head state digest",
            head["head_state_digest"],
        )
    section_names = tuple(
        spec[0] for spec in _POLICY_ACTIVATION_CHAIN_SECTION_SPECS
    ) + _POLICY_ACTIVATION_CHAIN_SPECIAL_SECTIONS
    sections = plain["sections"]
    if (
        not isinstance(sections, list)
        or len(sections) != len(section_names)
    ):
        raise PolicyCandidateAuthorityError(
            "activation-chain snapshot section manifest is not exact"
        )
    for expected_ordinal, (expected_name, section) in enumerate(
        zip(section_names, sections, strict=True),
        start=1,
    ):
        if not isinstance(section, dict) or set(section) != {
            "name",
            "sectionOrdinal",
            "rowCount",
            "terminalRowOrdinal",
            "canonicalBytes",
            "orderBy",
            "finalRootDigest",
        }:
            raise PolicyCandidateAuthorityError(
                "activation-chain section fields are not exact"
            )
        spec = _policy_activation_chain_section_spec(expected_name)
        expected_order = (
            spec[5]
            if spec is not None
            else _POLICY_ACTIVATION_CHAIN_SPECIAL_SECTION_ORDERS[
                expected_name
            ]
        )
        if (
            section["name"] != expected_name
            or int(section["sectionOrdinal"]) != expected_ordinal
            or int(section["terminalRowOrdinal"])
            != int(section["rowCount"])
            or section["orderBy"] != list(expected_order)
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation-chain section name or order is not source-defined"
            )
        _candidate_authority_int(
            "activation-chain section row count",
            section["rowCount"],
            minimum=0,
            maximum=_POLICY_AUTHORITY_STREAM_MAX_WORK_UNITS,
        )
        _candidate_authority_int(
            "activation-chain section byte count",
            section["canonicalBytes"],
            minimum=0,
            maximum=_POLICY_AUTHORITY_READ_MAX_JSON_BYTES * 4,
        )
        _candidate_authority_digest(
            "activation-chain section root",
            section["finalRootDigest"],
        )
    section_count = _candidate_authority_int(
        "activation-chain section count",
        plain["sectionCount"],
        minimum=1,
        maximum=len(section_names),
    )
    total_row_count = _candidate_authority_int(
        "activation-chain total row count",
        plain["totalRowCount"],
        minimum=0,
        maximum=_POLICY_AUTHORITY_STREAM_MAX_WORK_UNITS,
    )
    total_canonical_bytes = _candidate_authority_int(
        "activation-chain total canonical bytes",
        plain["totalCanonicalBytes"],
        minimum=0,
        maximum=_POLICY_AUTHORITY_READ_MAX_JSON_BYTES * 4,
    )
    terminal_section_ordinal = _candidate_authority_int(
        "activation-chain terminal section ordinal",
        plain["terminalSectionOrdinal"],
        minimum=1,
        maximum=len(section_names),
    )
    terminal_row_ordinal = _candidate_authority_int(
        "activation-chain terminal row ordinal",
        plain["terminalRowOrdinal"],
        minimum=0,
        maximum=_POLICY_AUTHORITY_STREAM_MAX_WORK_UNITS,
    )
    if (
        section_count != len(section_names)
        or terminal_section_ordinal != section_count
        or terminal_row_ordinal != total_row_count
        or total_row_count
        != sum(int(section["rowCount"]) for section in sections)
        or total_canonical_bytes
        != sum(int(section["canonicalBytes"]) for section in sections)
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain closed manifest counts are not exact"
        )
    verified_at = _candidate_authority_int(
        "activation-chain snapshot verification time",
        plain["verifiedAtEpochNs"],
        minimum=0,
    )
    expires_at = _candidate_authority_int(
        "activation-chain snapshot expiry",
        plain["expiresAtEpochNs"],
        minimum=1,
    )
    if expires_at != verified_at + _POLICY_AUTHORITY_EXPORT_TTL_NS:
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain export expiry is not source-defined"
        )
    manifest_material = {
        "schema": "serverware.policyActivationChainManifest/v1",
        "identityDigest": identity_digest,
        "sectionCount": section_count,
        "totalRowCount": total_row_count,
        "totalCanonicalBytes": total_canonical_bytes,
        "terminalSectionOrdinal": terminal_section_ordinal,
        "terminalRowOrdinal": terminal_row_ordinal,
        "sections": sections,
    }
    if _policy_candidate_authority_framed_digest(
        "serverware.policyActivationChainManifest/v1",
        dumps(manifest_material).encode("ascii"),
    ) != manifest_root_digest:
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain closed manifest root is not exact"
        )
    export_material = {
        "schema": "serverware.policyActivationChainExport/v1",
        "exportRevision": export_revision,
        "identityDigest": identity_digest,
        "manifestRootDigest": manifest_root_digest,
        "sectionCount": section_count,
        "totalRowCount": total_row_count,
        "totalCanonicalBytes": total_canonical_bytes,
        "verifiedAtEpochNs": verified_at,
        "expiresAtEpochNs": expires_at,
    }
    if _policy_candidate_authority_framed_digest(
        "serverware.policyActivationChainExport/v1",
        dumps(export_material).encode("ascii"),
    ) != export_id:
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain immutable export id is not exact"
        )
    material = {
        "schema": plain["schema"],
        "exportId": export_id,
        "exportRevision": export_revision,
        "identity": identity,
        "identityDigest": identity_digest,
        "manifestRootDigest": manifest_root_digest,
        "sectionCount": section_count,
        "totalRowCount": total_row_count,
        "totalCanonicalBytes": total_canonical_bytes,
        "terminalSectionOrdinal": terminal_section_ordinal,
        "terminalRowOrdinal": terminal_row_ordinal,
        "sections": sections,
        "verifiedAtEpochNs": verified_at,
        "expiresAtEpochNs": expires_at,
    }
    if _policy_candidate_authority_framed_digest(
        "serverware.policyActivationChainSnapshot/v3",
        dumps(material).encode("ascii"),
    ) != snapshot_digest:
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain snapshot digest is not exact"
        )
    return plain


def _policy_activation_chain_cursor_digest(
    cursor_material: Mapping[str, Any],
) -> str:
    return _policy_candidate_authority_framed_digest(
        "serverware.policyActivationChainCursor/v2",
        dumps(dict(cursor_material)).encode("ascii"),
    )


def _policy_activation_chain_validate_cursor(
    cursor: Mapping[str, Any],
    *,
    snapshot: Mapping[str, Any],
    section: Mapping[str, Any],
    order_by: tuple[str, ...],
) -> dict[str, Any]:
    plain = _policy_activation_chain_plain(cursor)
    if not isinstance(plain, dict) or set(plain) != {
        "schema",
        "exportId",
        "exportRevision",
        "snapshotDigest",
        "identityDigest",
        "section",
        "sectionRootDigest",
        "pageOrdinal",
        "pageRowLimit",
        "cumulativeRowCount",
        "cumulativeRootDigest",
        "lastKey",
        "predecessorPageRevisionDigest",
        "expiresAtEpochNs",
        "cursorDigest",
    }:
        raise PolicyCandidateAuthorityError(
            "activation-chain cursor fields are not exact"
        )
    cursor_digest = _candidate_authority_digest(
        "activation-chain cursor digest", plain["cursorDigest"]
    )
    material = {
        field: plain[field]
        for field in plain
        if field != "cursorDigest"
    }
    if (
        plain["schema"] != "serverware.policyActivationChainCursor/v2"
        or plain["exportId"] != snapshot["exportId"]
        or plain["exportRevision"] != snapshot["exportRevision"]
        or plain["snapshotDigest"] != snapshot["snapshotDigest"]
        or plain["identityDigest"] != snapshot["identityDigest"]
        or plain["section"] != section["name"]
        or plain["sectionRootDigest"] != section["finalRootDigest"]
        or plain["expiresAtEpochNs"] != snapshot["expiresAtEpochNs"]
        or _policy_activation_chain_cursor_digest(material)
        != cursor_digest
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain cursor is not bound to the exact snapshot section"
        )
    _candidate_authority_int(
        "activation-chain cursor page ordinal",
        plain["pageOrdinal"],
        minimum=2,
        maximum=_POLICY_AUTHORITY_STREAM_MAX_WORK_UNITS,
    )
    _candidate_authority_int(
        "activation-chain cursor page row limit",
        plain["pageRowLimit"],
        minimum=1,
        maximum=_POLICY_AUTHORITY_STREAM_PAGE_ROWS,
    )
    count = _candidate_authority_int(
        "activation-chain cursor cumulative row count",
        plain["cumulativeRowCount"],
        minimum=1,
        maximum=int(section["rowCount"]),
    )
    if count >= int(section["rowCount"]):
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain cursor points beyond a nonterminal page"
        )
    _candidate_authority_digest(
        "activation-chain cursor cumulative root",
        plain["cumulativeRootDigest"],
    )
    _candidate_authority_digest(
        "activation-chain cursor predecessor page revision",
        plain["predecessorPageRevisionDigest"],
    )
    last_key = plain["lastKey"]
    if (
        not isinstance(last_key, list)
        or len(last_key) != len(order_by)
        or any(value is None for value in last_key)
    ):
        raise PolicyCandidateAuthorityError(
            "activation-chain cursor key is not exact"
        )
    _candidate_authority_json_value(
        "activation-chain cursor key", last_key
    )
    return plain


def _policy_activation_chain_resume_predicate(
    order_by: tuple[str, ...],
    last_key: list[Any] | None,
) -> tuple[str, tuple[Any, ...]]:
    if last_key is None:
        return "", ()
    expressions = tuple(
        "item." + _policy_candidate_authority_identifier(column)
        for column in order_by
    )
    if len(expressions) == 1:
        return " AND " + expressions[0] + " > ?", tuple(last_key)
    return (
        " AND ("
        + ", ".join(expressions)
        + ") > ("
        + ", ".join("?" for _ in expressions)
        + ")",
        tuple(last_key),
    )


def _get_policy_activation_chain_unattested_section_page(
    *,
    snapshot: Mapping[str, Any],
    section: str,
    cursor: Mapping[str, Any] | None = None,
    maximum_rows: int = _POLICY_AUTHORITY_STREAM_PAGE_ROWS,
) -> Mapping[str, Any]:
    snapshot_record = _policy_activation_chain_validate_snapshot(snapshot)
    section = _candidate_authority_text(
        "activation-chain section", section, maximum=128
    )
    maximum_rows = _candidate_authority_int(
        "activation-chain page row limit",
        maximum_rows,
        minimum=1,
        maximum=_POLICY_AUTHORITY_STREAM_PAGE_ROWS,
    )
    section_manifest = next(
        (
            item
            for item in snapshot_record["sections"]
            if item["name"] == section
        ),
        None,
    )
    if section_manifest is None:
        raise PolicyCandidateAuthorityError(
            "activation-chain snapshot does not contain the requested section"
        )
    order_by = tuple(section_manifest["orderBy"])
    cursor_record = (
        None
        if cursor is None
        else _policy_activation_chain_validate_cursor(
            cursor,
            snapshot=snapshot_record,
            section=section_manifest,
            order_by=order_by,
        )
    )
    if (
        cursor_record is not None
        and int(cursor_record["pageRowLimit"]) != maximum_rows
    ):
        raise PolicyCandidateAuthorityConflictError(
            "activation-chain continuation changed its fixed page row limit"
        )
    activation_attempt_id = _candidate_authority_text(
        "activation-chain snapshot attempt",
        snapshot_record["identity"]["activationAttemptId"],
        maximum=256,
    )
    with _policy_authority_read_snapshot() as conn:
        now_epoch_ns = int(
            _metadata_utcnow(conn).timestamp() * 1_000_000_000
        )
        if now_epoch_ns >= int(snapshot_record["expiresAtEpochNs"]):
            raise PolicyCandidateAuthorityConflictError(
                "activation-chain immutable export has expired"
            )
        frozen_source = _load_policy_activation_finalized_export(
            conn, activation_attempt_id
        )
        if (
            frozen_source["identity"] != snapshot_record["identity"]
            or frozen_source["identityDigest"]
            != snapshot_record["identityDigest"]
            or frozen_source["manifestRootDigest"]
            != snapshot_record["manifestRootDigest"]
            or frozen_source["sections"]
            != snapshot_record["sections"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation-chain snapshot is outside its immutable "
                "finalized export"
            )
        all_rows = frozen_source["rowsBySection"].get(section)
        if all_rows is None:
            raise PolicyCandidateAuthorityConflictError(
                "activation-chain finalized section is unavailable"
            )
        row_count = len(all_rows)
        if row_count != int(section_manifest["rowCount"]):
            raise PolicyCandidateAuthorityConflictError(
                "activation-chain finalized section count changed"
            )
        previous_count = (
            0
            if cursor_record is None
            else int(cursor_record["cumulativeRowCount"])
        )
        previous_root = (
            _policy_activation_chain_section_root_genesis(
                identity_digest=snapshot_record["identityDigest"],
                section=section,
            )
            if cursor_record is None
            else str(cursor_record["cumulativeRootDigest"])
        )
        last_key = (
            None if cursor_record is None else cursor_record["lastKey"]
        )
        page_ordinal = (
            1
            if cursor_record is None
            else int(cursor_record["pageOrdinal"])
        )
        predecessor_page_revision_digest = (
            None
            if cursor_record is None
            else cursor_record["predecessorPageRevisionDigest"]
        )
        if previous_count:
            previous_row_key = [
                all_rows[previous_count - 1][column]
                for column in order_by
            ]
            if previous_row_key != last_key:
                raise PolicyCandidateAuthorityConflictError(
                    "activation-chain cursor key is outside the frozen "
                    "section ordinal"
                )
        rows: list[dict[str, Any]] = []
        page_bytes = 0
        previous_key = (
            None if last_key is None else tuple(last_key)
        )
        for item in all_rows[
            previous_count:previous_count + maximum_rows
        ]:
            row = dict(item)
            key = tuple(row[column] for column in order_by)
            row_bytes = len(dumps(row).encode("utf-8"))
            if (
                any(value is None for value in key)
                or (
                    previous_key is not None
                    and not previous_key < key
                )
                or row_bytes > _POLICY_AUTHORITY_STREAM_PAGE_BYTES
            ):
                raise PolicyCandidateAuthorityConflictError(
                    "activation-chain frozen row order or size is invalid"
                )
            if (
                rows
                and page_bytes + row_bytes
                > _POLICY_AUTHORITY_STREAM_PAGE_BYTES
            ):
                break
            rows.append(row)
            page_bytes += row_bytes
            previous_key = key
        if page_bytes > _POLICY_AUTHORITY_STREAM_PAGE_BYTES:
            raise PolicyCandidateAuthorityError(
                "activation-chain page exceeds its exact byte bound"
            )
        cumulative_root = previous_root
        for row in rows:
            cumulative_root = _policy_activation_chain_section_root_step(
                previous_root_digest=cumulative_root,
                row=row,
            )
        cumulative_count = previous_count + len(rows)
        if cumulative_count > row_count:
            raise PolicyCandidateAuthorityConflictError(
                "activation-chain page exceeds its section row count"
            )
        has_more = cumulative_count < row_count
        if has_more and not rows:
            raise PolicyCandidateAuthorityConflictError(
                "activation-chain page made no progress before section end"
            )
        if not has_more and (
            cumulative_count != row_count
            or cumulative_root != section_manifest["finalRootDigest"]
        ):
            raise PolicyCandidateAuthorityConflictError(
                "activation-chain page sequence does not close at the "
                "snapshot section root"
            )
        rows_digest = _policy_candidate_authority_framed_digest(
            "serverware.policyActivationChainPageRows/v1",
            dumps(rows).encode("ascii"),
        )
        page_material = {
            "schema": "serverware.policyActivationChainSectionPage/v2",
            "exportId": snapshot_record["exportId"],
            "exportRevision": snapshot_record["exportRevision"],
            "snapshotDigest": snapshot_record["snapshotDigest"],
            "identityDigest": snapshot_record["identityDigest"],
            "manifestRootDigest": snapshot_record["manifestRootDigest"],
            "section": section,
            "sectionRootDigest": section_manifest["finalRootDigest"],
            "sectionRowCount": row_count,
            "pageOrdinal": page_ordinal,
            "pageRowLimit": maximum_rows,
            "predecessorPageRevisionDigest":
                predecessor_page_revision_digest,
            "firstKey": (
                None
                if not rows
                else [rows[0][column] for column in order_by]
            ),
            "lastKey": (
                None
                if not rows
                else [rows[-1][column] for column in order_by]
            ),
            "pageRowCount": len(rows),
            "pageCanonicalBytes": page_bytes,
            "rowsDigest": rows_digest,
            "cumulativeRowCount": cumulative_count,
            "cumulativeRootDigest": cumulative_root,
            "hasMore": has_more,
            "expiresAtEpochNs": snapshot_record["expiresAtEpochNs"],
        }
        page_revision_digest = _policy_candidate_authority_framed_digest(
            "serverware.policyActivationChainPageRevision/v1",
            dumps(page_material).encode("ascii"),
        )
        next_cursor = None
        if has_more:
            cursor_material = {
                "schema": "serverware.policyActivationChainCursor/v2",
                "exportId": snapshot_record["exportId"],
                "exportRevision": snapshot_record["exportRevision"],
                "snapshotDigest": snapshot_record["snapshotDigest"],
                "identityDigest": snapshot_record["identityDigest"],
                "section": section,
                "sectionRootDigest":
                    section_manifest["finalRootDigest"],
                "pageOrdinal": page_ordinal + 1,
                "pageRowLimit": maximum_rows,
                "cumulativeRowCount": cumulative_count,
                "cumulativeRootDigest": cumulative_root,
                "lastKey": page_material["lastKey"],
                "predecessorPageRevisionDigest":
                    page_revision_digest,
                "expiresAtEpochNs":
                    snapshot_record["expiresAtEpochNs"],
            }
            next_cursor = {
                **cursor_material,
                "cursorDigest":
                    _policy_activation_chain_cursor_digest(
                        cursor_material
                    ),
            }
        successor_cursor_digest = (
            None
            if next_cursor is None
            else next_cursor["cursorDigest"]
        )
        delivery_material = {
            **page_material,
            "pageRevisionDigest": page_revision_digest,
            "successorCursorDigest": successor_cursor_digest,
        }
        page_digest = _policy_candidate_authority_framed_digest(
            "serverware.policyActivationChainSectionPage/v2",
            dumps(delivery_material).encode("ascii"),
        )
        result = {
            **delivery_material,
            "pageDigest": page_digest,
            "rows": rows,
            "nextCursor": next_cursor,
        }
    frozen = _policy_authority_immutable_row(result)
    if frozen is None:
        raise PolicyCandidateAuthorityError(
            "activation-chain page unexpectedly disappeared"
        )
    return frozen


